-- Synced units, themes, and subthemes from Supabase reference to D1
CREATE TABLE IF NOT EXISTS custom_units (id TEXT PRIMARY KEY, subject_id TEXT NOT NULL, grade_id TEXT NOT NULL, content TEXT NOT NULL, updated_at TEXT NOT NULL);
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('f0a41476-75fd-401e-bdab-7cde6f7bc367', 'formacion-humana', '6to', '{"id":"f0a41476-75fd-401e-bdab-7cde6f7bc367","name":"Conceptos de unidad","themes":[{"id":"4d57698c-e92b-4aba-9b98-c7c798a20761","name":"El valor del cuerpo humano","subthemes":[{"id":"baa33550-0afc-462f-a677-a78c4b51e8bb","name":"Cuerpo y dignidad humana."},{"id":"30910e5d-cbad-414a-bd2d-5ab011b41c7d","name":"Autoestima y cuidado personal."},{"id":"5d26157e-b291-41bc-b64c-1c23b0de0122","name":"Respeto al propio cuerpo."}]},{"id":"a1386e29-c268-4e8f-9d77-3e5f97e9e22e","name":"Hombre y mujer complementarios: semejanzas y diferencias","subthemes":[{"id":"96d9d0e1-8094-49f1-8e90-53c57f1ef0cf","name":"Igualdad en dignidad y derechos."},{"id":"31ad4a04-04cc-4aaf-b2eb-723b2f713ff4","name":"Diferencias físicas y emocionales (básico)."},{"id":"009d440b-3fab-472e-9b48-4cf4de5c9e4a","name":"Complementariedad y respeto."}]},{"id":"6e6d0b59-63db-45f9-903d-e469f3d308ba","name":"Características del niño y de la niña","subthemes":[{"id":"10712c8f-795f-4425-90d1-a31755feb35b","name":"Identidad y crecimiento."},{"id":"8ef991c3-120f-477f-bf0b-6f222aec6704","name":"Emociones y conducta en la niñez."},{"id":"3f9ddccd-81f0-41b5-aa06-09f18513eac1","name":"Necesidades y cuidados."}]},{"id":"90f895c7-f7c8-4ef9-8341-728d10b84e5d","name":"Situaciones de riesgo en la niñez (maltrato y abuso)","subthemes":[{"id":"8d67cafa-fa6b-4e3b-9ac9-b1a527fa4970","name":"Tipos de maltrato y abuso."},{"id":"0f5ed774-969f-47af-9b45-18c264cef548","name":"Señales de alerta y prevención."},{"id":"e5f63008-c438-4f0a-865f-61b639b95192","name":"Cómo pedir ayuda y a quién acudir."}]},{"id":"6031e466-5792-4ad6-9315-7881df12d034","name":"Deberes y derechos de la niñez","subthemes":[{"id":"18c27661-4a13-4482-9b76-1ff7ba34fda9","name":"Deberes en familia y escuela."},{"id":"66db6c28-deae-47b0-b2f6-596c479d67f2","name":"Responsabilidad y respeto."},{"id":"0cfff63d-8cd0-4fb5-850f-f1944e7f8d03","name":"Derechos fundamentales."}]},{"id":"82890385-e953-4ade-ab89-e5d45ae091fa","name":"Buen trato / Inclusión y discriminación","subthemes":[{"id":"1b0aac1b-ba0c-46aa-ae0a-ecd071209711","name":"Discriminación: causas y consecuencias."},{"id":"d9da0dd4-9bf6-4371-9334-789191d3acc8","name":"Inclusión: aceptar diferencias."},{"id":"e68931a5-f904-4304-8c2c-188e28f95d26","name":"Qué es buen trato."}]},{"id":"b2a540fe-f4fa-4e46-87d1-f9837e20dabf","name":"Bienestar propio y de los demás","subthemes":[{"id":"263d64e5-769f-457d-9100-535cb39195b4","name":"Hábitos saludables."},{"id":"6a9ca9c9-a501-48ea-8fbf-db019fba915a","name":"Cuidado emocional."},{"id":"908ae943-021f-4018-ac58-f360b41defb7","name":"Empatía y solidaridad."}]},{"id":"1c9caa11-203b-4245-b3d7-91fa318b726c","name":"Valor del trabajo humano","subthemes":[{"id":"4383b863-779e-4593-9907-2a4900ec4359","name":"Trabajo y dignidad."},{"id":"fe4ca962-792a-47be-b0c4-8cccdf56f5dd","name":"Trabajo en casa y escuela."},{"id":"bc9fbfe5-5260-48a6-95b7-a9245f260943","name":"Responsabilidad y esfuerzo."}]},{"id":"15d48c6e-e82b-4a93-a2e7-459b9fa9f425","name":"Trabajo infantil: necesidades, riesgos y consecuencias","subthemes":[{"id":"2ed93e0b-e61b-44ac-851b-a61bb47ce7f8","name":"Qué es trabajo infantil."},{"id":"82e19d32-99f2-4a2d-8989-abac6473a305","name":"Riesgos para salud y educación."},{"id":"6aa772d1-4382-43c8-8418-f157710ecaab","name":"Protección y derechos."}]},{"id":"93e3710e-a45a-4723-a445-e0e47fdffb3d","name":"Ciencia, tecnología y vida","subthemes":[{"id":"33a9bedf-d5aa-4983-a565-6f6324fc5f92","name":"Tecnología en la vida diaria."},{"id":"521561ea-7862-4e7c-b0c1-729d2d90623b","name":"Beneficios y riesgos."},{"id":"7e0d6577-a9cb-4867-8e2f-54378bf5fd23","name":"Uso responsable."}]},{"id":"3929909f-6ec8-4aa9-8fd9-20192546e0b3","name":"Aportes de la ciencia y la tecnología","subthemes":[{"id":"07ff81ce-599b-43e2-a436-fa5a82c510e5","name":"Salud y medicina."},{"id":"ee4a0930-595a-4d50-8121-6868c9c62fd6","name":"Comunicación y transporte."},{"id":"f95ca622-b69e-4a79-9e33-dec8eee15ee1","name":"Educación y aprendizaje."}]},{"id":"11b3c3b4-35e1-4d6b-92c1-03c1ea678932","name":"Expresiones del amor de Dios","subthemes":[{"id":"9e3733f2-4d6b-4610-a857-fd6311de3880","name":"Amor en la familia y comunidad."},{"id":"83f25ef5-816e-437e-a3ce-6b81a7ce376d","name":"Ayuda y servicio al prójimo."},{"id":"24efcf79-92ae-41e4-891c-ba0c63a22313","name":"Perdón y respeto."}]},{"id":"a1fdc3ed-9581-4219-8dfc-c58ed9435459","name":"Desarrollo del adolescente","subthemes":[{"id":"da7e8acd-5c06-45c0-871d-a9709b871b3f","name":"Cambios físicos y emocionales."},{"id":"8e3302c0-f3b9-4f83-bb45-1be16bd388ad","name":"Identidad y toma de decisiones."},{"id":"6f9d784d-29b1-4e02-82be-c65e8c5f1d89","name":"Valores y espiritualidad."}]},{"id":"cf19efaf-9ea1-4347-b8a0-665bb862b7d7","name":"La familia como lugar de afecto y cariño","subthemes":[{"id":"a3719e1b-f9ba-43a8-83c1-3a8cfcd17931","name":"Función de la familia."},{"id":"749dadd4-2941-4180-adcd-bab03eb41373","name":"Apoyo y comunicación."},{"id":"7354c887-a7c4-47ec-be65-5a1fed27a6b3","name":"Respeto y unión."}]},{"id":"04000b5d-ca7d-45e0-bd35-91ae82690d4e","name":"Relaciones del adolescente con familia, escuela y entorno","subthemes":[{"id":"b22075f0-c8bd-4363-8dcb-c4cc4f295c45","name":"Convivencia y normas."},{"id":"0c192492-a3c7-44c0-aed9-821549ac1b1d","name":"Amistades y relaciones sanas."},{"id":"9cb98eb9-18bd-46d7-93da-73f949a6116e","name":"Influencia del entorno."}]},{"id":"aeb24589-87a7-4256-ba01-e6dde7edf2c3","name":"Cuidado y protección del entorno natural","subthemes":[{"id":"864ea175-5547-4164-9932-7552c6244a68","name":"Ahorro de agua y energía."},{"id":"9c9e4de4-af27-4ef7-aa20-7f66d74e2c62","name":"Respeto a seres vivos."},{"id":"8666889c-1339-4340-aaa9-6f0d84255165","name":"Conservación y limpieza."}]},{"id":"c2551a7d-bcc7-44ac-b0a7-7a172b6897e1","name":"Soluciones a situaciones que afectan el entorno natural","subthemes":[{"id":"344631af-e962-488b-b6b6-fe72c9da32d6","name":"Acciones comunitarias (siembra, reciclaje)."},{"id":"1a844fb2-c37e-43a7-83a8-4c910e010af4","name":"Acciones comunitarias (siembra, reciclaje)."},{"id":"fd35b73b-364d-42a4-9b91-dd727a3d4bee","name":"Identificación de problemas ambientales."}]},{"id":"bb32eccd-edd5-42b0-96a3-e19c61d41871","name":"Jesús nace y crece en sabiduría y gracia","subthemes":[{"id":"eef450e1-62c7-4bee-953f-84e8e482b1fe","name":"Jesús niño y su familia."},{"id":"255e0f22-461d-4978-94cd-27abcf527759","name":"Valores de obediencia y amor."},{"id":"81cd34ab-c7c8-4f5e-b8e2-d54c18991de7","name":"Nacimiento de Jesús."}]},{"id":"9f63176b-1297-4769-8fdd-ea647e1e522b","name":"Estilo de vida de Jesús","subthemes":[{"id":"78b9c43c-459f-45c0-a794-0389315684f1","name":"Amor al prójimo."},{"id":"4be7ca0f-80f0-4021-bac0-f214273969db","name":"Oración y fe."},{"id":"d8e8a60d-d412-4907-b033-7ebafb30426b","name":"Humildad y servicio."}]},{"id":"378a11b7-d017-4fa5-81b9-4f832b7cd392","name":"Jesús ante el sufrimiento y muerte en la cruz","subthemes":[{"id":"aed3994f-3fa7-47ee-b62a-94292ec9ae08","name":"Sentido del sacrificio."},{"id":"5eefe967-3b1c-4d21-b6e3-9901fe0098a3","name":"Perdón y esperanza."},{"id":"4edf5166-d955-46bd-84fa-e06739ebfa74","name":"Pasión de Jesús."}]},{"id":"eb53de79-9294-4b8a-8827-65e4aa1059aa","name":"La resurrección, triunfo de Jesús","subthemes":[{"id":"7aa7cc19-a3ca-4f18-b64d-33d02fc1f386","name":"Victoria sobre la muerte."},{"id":"73f31cb5-6a76-4806-bb63-7b78c39739a6","name":"Vida nueva y fe cristiana."},{"id":"03174ff8-605a-4287-bc04-440b2af8f49f","name":"Resurrección: significado."}]}],"grade_levels":["6to"],"subjectId":"formacion-humana","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"f0a41476-75fd-401e-bdab-7cde6f7bc367-block-1","themes":["El valor del cuerpo humano","Hombre y mujer complementarios: semejanzas y diferencias","Características del niño y de la niña","Situaciones de riesgo en la niñez (maltrato y abuso)","Deberes y derechos de la niñez","Buen trato / Inclusión y discriminación","Bienestar propio y de los demás","Valor del trabajo humano","Trabajo infantil: necesidades, riesgos y consecuencias","Ciencia, tecnología y vida","Aportes de la ciencia y la tecnología","Expresiones del amor de Dios","Desarrollo del adolescente","La familia como lugar de afecto y cariño","Relaciones del adolescente con familia, escuela y entorno","Cuidado y protección del entorno natural","Soluciones a situaciones que afectan el entorno natural","Jesús nace y crece en sabiduría y gracia","Estilo de vida de Jesús","Jesús ante el sufrimiento y muerte en la cruz","La resurrección, triunfo de Jesús"],"conceptual":"-\tEl valor del cuerpo humano.\n-\tHombre y mujer complementarios: semejanzas y diferencias.\n-\tCaracterísticas del niño y de la niña.\n-\tSituaciones de riesgo en la niñez, maltrato y abuso infantil.\n-\tDeberes y derechos de la niñez. \n-\tBuen trato hacia las personas - Inclusión y discriminación.\n-\tBienestar propio y el de los demás.\n-\tValor del trabajo humano.\n-\tEl trabajo infantil: Necesidades, riesgos y consecuencias. \n-\tCiencia, tecnología y vida.\n-\tAportes de la ciencia y la tecnología\n-\tExpresiones del amor de Dios.\n-\tDesarrollo físico, cognitivo, afectivo, sexual y espiritual del adolescente.\n-\tLa familia como lugar de afecto y cariño.\n-\tRelaciones del adolescente con la familia, la escuela y el entorno.\n-\tCuidado y protección del entorno natural.\n-\tBúsqueda de soluciones a situaciones que afectan el entorno natural.\n-\tJesús nace y crece en sabiduría y gracia.\n-\tEstilo de vida de Jesús.\n-\tJesús ante el sufrimiento y muerte en la cruz.\n-\tLa resurrección, triunfo de Jesús.\n ","procedural":"-\tSocialización acerca de lo valioso que es su cuerpo y el de los demás, mediante la implementación de estrategias, técnicas y recursos diversas.\n-\tExploración acerca de la igualdad y semejanzas entre el hombre y la mujer a partir de los textos bíblicos del Génesis 2, 18-25 y Génesis 1, 26.\n-\tInvestigación acerca de la igualdad del hombre y la mujer según la Declaración Universal de los Derechos Humanos.\n-\tExposición donde se establezca a través de diferentes recursos  (fotografías, láminas, afiches, frases, proclamas, poesías, tecnológicos…) un trato equitativo entre los hombres y las mujeres.\n-\tArgumentación sobre la igualdad y diferencias entre los niños y las niñas a partir de experiencias en su entorno familiar, escolar y social.\n-\tSocialización de situaciones de riesgo, maltrato, abandono, negligencia, abuso físico, emocional y sexual a través del análisis de recursos diversos.\n-\tArgumentación y representación sobre los derechos fundamentales establecidos en la Ley 136- 03 que establece el Código para el Sistema de Protección y los \nDerechos Fundamentales de Niños, Niñas y Adolescentes República Dominicana.\n \n-\tIdentificación y promoción de actitudes inclusivas en el trato a los demás a partir de textos bíblicos y otros documentos.\n-\tDramatización de situaciones en las que se manifiesten situaciones de exclusión por sexo, género, color, raza, clase social, discapacidad, o creencias religiosas en contextos variados.\n-\tOrganización de una celebración en que se agradezca a Dios por los aprendizajes adquiridos con relación al valor de su cuerpo, los derechos fundamentales de la niñez y la adolescencia, sus deberes y el buen trato a los demás.\n-\tDescripción de las tareas que los niños y adolescentes realizan en la casa, en la escuela y en la comunidad.\n-\tInvestigación en su comunidad acerca del trabajo infantil remunerado y los tipos de trabajos que realizan los niños y adolescentes.\n-\tInvestigación acerca de las causas y consecuencias de la explotación laboral infantil.\n-\tDebate sobre el trabajo infantil apoyado en los artículos 34, 37, 40 del Código para la Protección de los Derechos de los Niños. \n-\tRepresentación de los aportes del trabajo humano a la creación de Dios y al bienestar de todos.\n-\tExposición sobre trabajos e instituciones que realizan acciones de cuidado y protección del entorno natural.\n-\tOrganización de una campaña de sensibilización sobre el daño que ocasiona el trabajo y explotación infantil al desarrollo integral de niños, niñas y adolescentes.\n-\tAnálisis de textos bíblicos en los que se valora el trabajo humano: \n-\tGénesis 3,19; Eclesiastés 5,11; Jeremías 22, 13; Mateo 20,1- 15; Efesios 4, 28; 2 \nTesalonicenses 3, 7- 13; Santiago 5, 4.-\n-\tAnálisis de textos bíblicos en los que se valora el trabajo humano: \n-\tGénesis 3,19; Eclesiastés 5,11; Jeremías 22, 13; Mateo 20,1- 15; Efesios 4, 28; 2 \nTesalonicenses 3, 7- 13; Santiago 5, 4.-\n-\tSocialización de los inventos, descubrimientos y facilidades que disfrutan las personas gracias al trabajo realizado desde el campo de la ciencia y la tecnología.\n-\tOrganización de un espacio reflexivo y orante presentando todos los aprendizajes, experiencias y producciones destacando los beneficios del trabajo, las ciencias y las tecnologías al desarrollo humano y espiritual de las personas.\n \n-\tIdentificación en grupos de los valores que posibilitan la buena relación en la familia y con las personas a partir de los siguientes textos bíblicos: Mateo 18, 15-20; Lucas 18, 15-17; Marcos 1, 40-45; 2 Timoteo 2, 22-25; Hechos 10, 23-35.\n-\tConstrucción de un mural donde se muestren situaciones que favorecen y no favorecen las buenas relaciones en el contexto familiar, escolar y social.\n-\tOrganización de una celebración donde se realicen actividades que fomenten las buenas relaciones interpersonales en la familia, la escuela y la comunidad.\n-\tInvestigación sobre instituciones y personas que realizan actividades y acciones a favor y protección del entorno natural.\n-\tRealización de una mesa redonda donde analicen situaciones que dañan al entorno natural y se expongan alternativas para cuidar y proteger al Medioambiente, tomando en cuenta: la contaminación sonora, contaminación y escasez de agua, contaminación de desperdicio sólido, contaminación de gases. \n-\tConstrucción y ejecución de proyectos con acciones dirigidas al cuidado y protección del entorno natural en la familia, la escuela, la comunidad y las redes sociales. \n-\tOrganización de una campaña de sensibilización y concientización sobre la urgencia de cuidar y proteger el entorno natural en la familia, la escuela, la comunidad y las redes sociales.\n-\tDramatización acerca del crecimiento de Jesús de Nazaret destacando los valores espirituales a partir del texto bíblico de Lucas 2, 41-52.\n-\tOrganización de un panel en el que se establezca el estilo de vida de Jesús, su amor y compromiso con el bienestar de las personas a partir de los siguientes textos: \nMateo 4, 18- 22 y Mateo 4, 23- 25.\n \n-\tIdentificación de los momentos clave del sufrimiento en la vida de  Jesús a partir de los textos que siguen: arresto de Jesús y traición de Judas (Marcos 14,43- 51), acusaciones y burlas (Marcos 14, 53- 65), negación de Pedro (Marcos 14, 66- 72), Jesús ante Pilatos (Marcos 15, 1- 15), el camino de la cruz y la crucifixión (Marcos 15, 21- 27).\n-\tElaboración de un mural donde se presenten signos de la pasión, muerte y resurrección de Jesús y los valores que nos enseña. \n-\tOrganización de una celebración con espacios de oración, cantos y reflexión acerca del nacimiento, la vida, la pasión, la muerte y la resurrección de Jesús de Nazaret y presentación de los trabajos elaborados donde se resalten los valores de su persona de Jesús.\n ","attitudinal":"-\tRespeto por las opiniones diferentes a las suyas.\n-\tTrato igualitario hacia sus compañeros y compañeras.\n-\tDisposición a dispensar buen trato a todas las personas.\n-\tReconocimiento de sus deberes y exigencia de sus derechos.\n-\tAgradecimiento a Dios por la existencia de leyes, personas e instituciones que protegen a la niñez. \n-\tDisposición para comunicar situaciones de riesgo que le afectan.\n-\tRechazo al abandono y al abuso infantil.\n-\tAcogida a los niños, adolescentes y a otras personas con discapacidad.\n-\tInterés por cultivar buenas relaciones de amistad.\n-\tReconocimiento del sacrificio que realizan las personas que trabajan.\n-\tDisposición a comunicar a personas adultas cualquier tipo de maltrato, abuso o explotación al que pueda estar siendo sometido.\n "}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:20:36.181Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('6690780f-3ce5-47db-83ed-5f11859596e5', 'sociales', '6to', '{"id":"6690780f-3ce5-47db-83ed-5f11859596e5","name":"Geografía humana","themes":[{"id":"339e38ab-f292-4094-a05a-588d13f85656","name":"Geografía humana","subthemes":[{"id":"140a29eb-4326-4d4b-aabb-a89a42dd4c1b","name":"Relación entre población y territorio."},{"id":"17701d64-c12d-4e9e-a620-723ca19af4f1","name":"Cultura y organización social."},{"id":"e2f59dad-9b32-4944-9586-b9ad7e14828c","name":"Actividades humanas y espacio geográfico."}]},{"id":"a3afb5df-41e1-4c5f-bd32-431c5209993d","name":"Geografía como ciencia y sus ramas","subthemes":[{"id":"4fc1fb3b-d4b4-489e-8e33-99410da58e17","name":"Qué estudia la geografía."},{"id":"9d01db16-50d4-4194-8f4b-e807495bcf6c","name":"Geografía física y humana."},{"id":"a1f1d5ac-d981-4665-a66e-be4e07609f4b","name":"Herramientas geográficas (mapas, globos)."}]},{"id":"1e42e444-4699-4562-92a1-02ff5963c27a","name":"Conceptos básicos","subthemes":[{"id":"d4804a58-99c9-470e-9b5c-c5ccd12b2fbd","name":"Coordenadas geográficas básicas."},{"id":"14ce5482-3cef-4037-82f4-914f147b7f06","name":"Ubicación y orientación."},{"id":"f35b6db1-d72b-4d96-b8be-e25474afd030","name":"Escala y símbolos cartográficos."}]},{"id":"296c5299-9427-47da-b887-2703d4d2999f","name":"El espacio geográfico","subthemes":[{"id":"ded7afe7-e3fa-469e-bb00-0eb8f7e031a6","name":"Elementos naturales y humanos."},{"id":"633b5071-e308-402e-9d18-52976b310cdf","name":"Uso del territorio."},{"id":"1b364f7f-011d-41d1-baf4-d263d49f2c81","name":"Transformación del paisaje."}]},{"id":"c592bfba-31f0-4b5a-b07b-317d087cc224","name":"Aspectos geográficos de los continentes","subthemes":[{"id":"c830c125-dbdf-44f5-a8b5-d1fff7f58528","name":"Ubicación, límites y superficie."},{"id":"b6698f54-ccd5-488b-9a80-64611748cb89","name":"Economía, población y cultura."},{"id":"541d1106-80a6-4835-ac63-4aca52ccee38","name":"Relieve, clima e hidrografía."}]},{"id":"dea556b3-1091-49b0-93c8-ae63bbcad385","name":"Antiguas civilizaciones","subthemes":[{"id":"c82f22c4-ac7e-4a0c-825d-c3817f6bbae4","name":"Primeras civilizaciones del mundo."},{"id":"ec3e26a0-176c-41e8-a9c7-b7bd8cb442b8","name":"Aportes históricos principales."},{"id":"354d57ef-bc6c-4800-a474-48bbf1116776","name":"Organización social y cultural."}]}],"grade_levels":["6to"],"subjectId":"sociales","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"6690780f-3ce5-47db-83ed-5f11859596e5-block-1","themes":["Geografía humana","Geografía como ciencia y sus ramas","Conceptos básicos","El espacio geográfico","Aspectos geográficos de los continentes","Antiguas civilizaciones"],"conceptual":"\"Geografía Humana\"\n \nGeografía como ciencia y sus ramas.\n–\tConceptos básicos. \n–\tEl espacio geográfico.\n–\tAspectos geográficos de los continentes: Ubicación, límites, superficie, relieve, clima, hidrografía, economía, población, cultura.\n–\tAntiguas civilizaciones.\n ","procedural":"Identificación y uso de fuentes confiables de la geografía como ciencia y sus ramas.\n–\tAnálisis de conceptos de geografía, ubicación, relieve, ubicación, cultura civilización.\n–\tSelección de fuentes confiables sobre la geografía como ciencia.\n–\tAnálisis de los conceptos básicos de geografía y su objeto de estudio.\n–\tComparación de las ramas de la geografía física y humana.\n–\tElaboración de cuadros sinópticos de los aspectos geográficos de los continentes: relieve, clima, hidrografía, economía, población, cultura.\n–\tAnálisis de mapas sobre la población de los continentes.\n–\tAnálisis de la ubicación espacial de las antiguas civilizaciones e identifica sus aportes al desarrollo de la humanidad.\nIdentifica en mapamundi, países en donde se ubicaban las civilizaciones antiguas.\n–\tUtilización de lecturas de fuentes seguras y confiables sobre la geografía humana y los continentes, siguiendo procedimientos de análisis.\n–\tPresentación de un resumen sobre los aspectos estudiados de la geografía humana y los aspectos geográficos de los continentes.\n ","attitudinal":"–\tValoración del uso adecuado de fuentes de investigación.\n–\tInterés por respetar la autoría de las informaciones utilizadas.\n–\tInterés por el uso de fuentes confiables de investigación de geografía, historia y ciudadanía.\n–\tValoración de la geografía en el estudio del espacio natural.\n–\tRespeto por las tradiciones culturales.\n–\tValoración del patrimonio de las civilizaciones. \n "}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:20:36.182Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('52e7806c-68ec-43f6-9fb2-3bf5920a0ae0', 'naturales', '6to', '{"id":"52e7806c-68ec-43f6-9fb2-3bf5920a0ae0","name":"Ciencias físicas","themes":[{"id":"7ba880fc-db29-4182-93d9-373a0a73c70a","name":"Materia y sus propiedades","subthemes":[{"id":"9f8e4ead-6911-4c54-bdb1-32794c824039","name":"Características generales: masa, volumen, peso."},{"id":"758165c0-e915-4f97-bdf6-2659f2e339f7","name":"Propiedades de la materia"},{"id":"4fcde916-367b-45a0-b9a4-86b8de1cba3c","name":"Tipos de cambios de estado"},{"id":"75c4dfb0-06ff-483c-91a3-9c7249d04b90","name":"Qué es la materia."},{"id":"4b3946e9-2bd2-49da-a99e-5290fa2c5a4f","name":"Estados de la materia"},{"id":"28a2da9d-9dd7-4c6b-938d-74a7953b8ac2","name":"Dilatación y temperatura"}]},{"id":"228e9a9d-ba0f-47ef-884a-741f0f28764f","name":"Energía y conservación","subthemes":[{"id":"91cb44f8-6403-4e38-ae88-612ad3affe86","name":"Qué es la energía."},{"id":"73aa7e7a-59e0-47a4-8618-5b71db942a5c","name":"Importancia de la energía en la vida diaria."},{"id":"94f9e565-6d58-412d-bbc9-1bc5637705c7","name":"Calor y energía."},{"id":"1fb35fcd-ce93-46d4-a995-8d5f72dc1e9d","name":"Formas de energía (térmica, nuclear y eólica)"},{"id":"165f8f9a-777f-4eb0-b097-6aa1145b5d82","name":"Conservación de la energía"}]},{"id":"7864904e-f78a-427e-b889-52974ac2e12c","name":"Interacción y movimiento","subthemes":[{"id":"d9bdb26d-1191-42be-9c30-f0aa1a0d087a","name":"Modelo molecular simple"},{"id":"24193036-b0bd-4089-9cec-a524fe902c5b","name":"Concepto de presión"},{"id":"0690e5b7-c686-453e-8aec-4833abc9e457","name":"Espacio entre partículas."},{"id":"53f1a331-92d9-49e2-82e2-62f5cf6074d8","name":"Factores que influyen en la presión"},{"id":"45e8a143-7ef3-4073-8b2f-4b5c4848b656","name":"Modelo molecular en los estados de la materia"},{"id":"848ef255-37b0-4510-a186-f301bc79c27e","name":"Ejemplos cotidianos"},{"id":"3e1fcf87-7bad-4185-9bb7-17c4415d843f","name":"Relación entre fuerza y área (Presión)"},{"id":"d727add6-77af-4e20-8a87-f012626c3740","name":"Unidades de presión"}]},{"id":"530084fd-46d6-46b3-a695-39982e3455ce","name":"Sistema y mecanismo","subthemes":[{"id":"3f9122e8-08b3-45ff-9b53-4c07593c4318","name":"Principios de Pascal"},{"id":"ce7788bf-99e5-410a-bcd2-904f9e3b5261","name":"Principios de Arquímedes."},{"id":"ce6db11f-2876-438e-a855-58a416d90016","name":"Mecanismos de acumulación de energía"},{"id":"cc82c61d-04ad-4c6b-be5e-2d30ac007aeb","name":"Máquinas (elementos neumáticos e hidráulicos)."},{"id":"ac8fd5e8-690d-4674-9c4e-0a2ec1a8a37d","name":"Tecnología en la producción nacional"},{"id":"cb148790-8205-44af-b34e-0db91481610e","name":"Empresas en la comunidad"},{"id":"a6ee04ef-331f-4418-947f-1ed1c2ab17bc","name":"Desarrollo sostenible."},{"id":"fd523543-27f1-4e76-962b-96cff6bad5c9","name":"Qué es la tecnología."},{"id":"5651343d-4f65-4834-b635-7d48d65d77d5","name":"Laboratorios nacionales"},{"id":"5c7e40af-fd37-4797-b9aa-d142a801fd2c","name":"Competitividad nacional."},{"id":"3cc3dcf0-a4f5-4919-868e-1e8fcc13c27c","name":"Relación entre tecnología, ciencia y sociedad."},{"id":"ba1b459a-9aa9-447d-b139-496bb8db4c21","name":"Centros de investigación e innovación"},{"id":"05ee34b7-76f8-4f48-9b1c-7b4e3803a5f6","name":"Solución de problemas sociales y ambientales."},{"id":"4dc0b835-1107-4220-a1e3-6055996fa83b","name":"Aplicación de la tecnología en la producción"},{"id":"9689ddb1-bfac-44df-9a01-b8b808978a44","name":"Impacto"}]}],"grade_levels":["6to"],"subjectId":"naturales","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"52e7806c-68ec-43f6-9fb2-3bf5920a0ae0-block-1","themes":["Materia y sus propiedades","Energía y conservación","Interacción y movimiento","Sistema y mecanismo"],"conceptual":"\"Ciencias físicas\"\n \n\"Materia y sus propiedades\"\n \n– Cambios de estado: fusión, solidificación, condensación, licuefacción, evaporación, ebullición, sublimación, cristalización.\n \n– Dilatación y temperatura.\n \n\"Energía y conservación\"\n– Calor y energía.\n– Formas de energía (térmica, nuclear y eólica).\n \n\"Interacción y movimiento\"\n– Modelo molecular simple en sólidos, líquidos y gases.\n– Relación entre fuerza y área (presión).\n \n\"Sistema y mecanismo\"\n– Principios de Pascal y Arquímedes.\n– Mecanismos de acumulación de energía.\n– Máquinas (elementos neumáticos e hidráulicos).\n– Tecnología en la producción nacional (empresas en la comunidad, laboratorios nacionales y centros de investigación-innovación).","procedural":"– Experimento sobre la dilatación de los cuerpos. Procedimiento: observación, formulación de preguntas, utilización de instrumentos, construcción de modelos, reporte en diario de laboratorio.\n \n– Experimentación para relacionar entre densidad, volumen y masa. Procedimiento: formulación de preguntas, mediciones, análisis, utilización de instrumentos, recolección de información, comparación, descripción, dibujos, reporte diario de laboratorio.\n \n– Experimento sobre el principio de Pascal. Procedimiento: exploración, formulación de preguntas, construcción de modelo, recolección de información, comunicación escrita y reporte en diario de laboratorio.\n \n– Experimento sobre el volumen y presión de un gas. Procedimiento: observación, formulación de preguntas, utilización de instrumentos, construcción de modelos, descripción, inferencia, gráficos, reporte en diario de laboratorio.\n \n– Experimento sobre el principio de Arquímedes. Procedimiento: exploración, formulación de preguntas, construcción de modelo, recolección de información, comunicación escrita y reporte en diario de laboratorio.\n \n– Observación de los diferentes estados de la materia. Construcción de modelos moleculares. Procedimiento: experimentación (guiada), utilización de instrumentos, dibujos o esquemas.\n \n– Experimentación con gases. Relación entre presión, volumen y temperatura. Procedimiento: exploración, medición, recolección de información, experimentación (guiada), utilización de instrumentos, reporte en diario de laboratorio.\n \n– Construcción de modelos de elementos neumáticos e hidráulicos de máquinas y sus mecanismos de acumulación de energía.\n \n– Procedimiento: experimentación, dibujos y esquemas, utilización de instrumentos, reporte en diario de laboratorio.\n \n– Experimentación con máquina de vapor. Procedimiento: observación, formulación de preguntas, utilización de instrumentos, descripción, reporte en diario de laboratorio.\n \n– Observación de la tecnología en la producción de empresas locales, laboratorios y centros de investigación, desarrollo e innovación.\n \n– Procedimiento: exploración, formulación de preguntas, recolección de información, comparación, descripción, comunicación oral y escrita.","attitudinal":"– Curiosidad, creatividad y perseverancia en la búsqueda de respuestas y comprensión de su entorno natural.\n \n– Interés por la comunicación de sus ideas.\n \n– Sistematicidad en los procesos de la ciencia.\n \n– Trabajo individual y colaborativo.\n \n– Cuidado de su salud y el medioambiente, y la utilización sostenible de los recursos disponibles.\n \n– Respeto a las ideas y diferencias de las demás personas.\n \n– Criticidad y cuestionamiento en la búsqueda, recepción y producción de información científica tanto oral como escrita."}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:20:36.182Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('303', 'naturales', '2do', '{"id":"303","name":"Ciencias de la Tierra y el Universo","themes":[{"id":"52813d95-2403-4877-bf93-e450e3e9233f","name":"Materiales de los suelos. Rocas, agua","subthemes":[{"id":"12ad9bcc-cac4-4fb2-9124-ccde29b51721","name":"Qué es el suelo y para qué sirve"},{"id":"d4f811fc-96c8-43e8-835c-b1526ad56a59","name":"Tipos de materiales del suelo (tierra, arena, piedras)"},{"id":"cb57a871-c5f2-43a0-86bd-b71a6014c645","name":"Las rocas: tamaño, forma y uso"},{"id":"cad7902f-4a2c-4f4e-8308-a8439a61c6e9","name":"El agua en el suelo y su importancia para los seres vivos"}]},{"id":"c1152998-9ba1-4471-afe8-12d081c8c490","name":"Fenómenos atmosféricos (lluvia, tormentas)","subthemes":[{"id":"26b9fc77-a4c1-49c4-b3ab-0630a1c0d78a","name":"Qué es el clima"},{"id":"07b8a001-bf1a-4a0d-af80-83398e011814","name":"La lluvia y cómo se produce"},{"id":"6f6cf72f-cbe0-4931-999b-a52bf073e8ad","name":"Las tormentas y sus características"},{"id":"44ffeb69-152f-4edf-9631-5887231ab31d","name":"Cuidados ante lluvias y tormentas"}]},{"id":"ef059041-c388-46d5-8b7d-760628d3faa9","name":"Fuentes de energía (agua y aire)","subthemes":[{"id":"8c9c2c0a-37d3-473f-817c-539c10b89704","name":"Qué es la energía"},{"id":"133944b2-5b85-4e9b-828b-d3408502b8e0","name":"El agua como fuente de energía"},{"id":"2086c3ff-748b-452c-84ec-53fc23bcbdc2","name":"El aire y el viento como fuente de energía"},{"id":"c9981e0e-51d8-4072-b6c5-6dfe4fde79cf","name":"Uso responsable del agua y del aire"}]},{"id":"9e8cda74-f67f-4f04-997a-75f7b53b1d8f","name":"Fenómenos naturales (sismos, derrumbes)","subthemes":[{"id":"597aa852-1a69-471b-8662-49dc42537b4d","name":"Qué son los fenómenos naturales"},{"id":"fab779d8-5aba-47f2-83fe-550a5d9a2a34","name":"Los sismos: qué son y cómo ocurren"},{"id":"c50e70f1-8fcf-4346-b479-fa17cc825a49","name":"Los derrumbes y sus causas"},{"id":"9b56a7a4-256b-4b25-8ab2-fbc2b921f2e4","name":"Medidas de prevención y cuidado"}]},{"id":"fe7ccb7a-97f6-4cdb-8404-beac856c8125","name":"Movimiento de la Tierra: el día y la noche","subthemes":[{"id":"85710a51-f8fc-4555-a978-ee061363d811","name":"Qué es la Tierra"},{"id":"a01c6aff-55e0-4a48-ae20-2f2ce6e44e20","name":"Movimiento de la Tierra"},{"id":"0db353c0-4707-4be0-9d6c-e67f3e4f36a4","name":"El día y sus características"},{"id":"d250f322-375c-4014-b33b-7cf58e4b6f38","name":"La noche y sus características"}]},{"id":"1a12ffdb-e241-4ad5-a7c5-66a040d332a9","name":"Estaciones del año","subthemes":[{"id":"ac4f3ba5-a8d3-446d-90d9-e6d71263eea0","name":"Qué son las estaciones del año"},{"id":"88780c63-6679-41ae-8a99-1b3a75ef0793","name":"Características del verano"},{"id":"e531c566-b7ac-41f2-ab9b-46b5c35b7c60","name":"Características del invierno"},{"id":"9383ac9e-3137-42d1-9ad1-14e3d4b551bf","name":"Cambios en la naturaleza según la estación"}]},{"id":"3b5eecaa-3379-47d0-b8c9-e1ff1ac7959c","name":"Ciclo del agua","subthemes":[{"id":"cac80b34-0ca0-4edf-9e59-060b07226069","name":"Qué es el agua y dónde se encuentra"},{"id":"5b647120-7ae1-4aba-886e-41fd97669008","name":"Evaporación del agua"},{"id":"594f7a67-e991-401a-b67c-4f23b431f907","name":"Formación de las nubes y la lluvia"},{"id":"a28ad86d-0ff8-4921-baff-a7f6329e8432","name":"Importancia del ciclo del agua para la vida"}]},{"id":"ba652489-4f58-49fe-b097-9eb26745b2e0","name":"Introducción a la Materia","subthemes":[{"id":"30d16b19-91fe-4233-a737-47b31ccb15af","name":"Definición de materia"},{"id":"a864edc7-600a-49bc-87ac-02916558244a","name":"Propiedades de la materia"},{"id":"af1b1571-6ddb-4174-b54d-6136459483f0","name":"Tipos de materia"},{"id":"8d67658b-76e9-4129-a363-784410cdf637","name":"Ejemplos de materia en la vida diaria"}]},{"id":"40975f82-0ab4-4088-87bb-7665b5d80036","name":"Importancia de la fotosíntesis","subthemes":[{"id":"4ba71e74-5573-43f2-87ac-7e3266588d5f","name":"La sombra fresca de los árboles"},{"id":"15291bb5-6239-4d1b-87de-8b6934c2e053","name":"Frutas y verduras gracias a la luz solar"},{"id":"3053d991-876c-4e69-b2a4-a918c465a6b1","name":"Las plantas como hogar de muchos animales"}]},{"id":"319f6231-9f94-4b1d-996c-5fbf4f7b1b21","name":"Las Hormonas: Los Mensajeros Secretos de Nuestro Cuerpo","subthemes":[{"id":"395f39b5-f918-4dd6-bb72-23fd967f2f3a","name":"¡Mi corazón late rápido! La alarma de emergencia de mi cuerpo (Adrenalina)."}]}],"grade_levels":["2do"],"subjectId":"naturales","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"303-block-1","themes":["Materiales de los suelos. Rocas, agua","Fenómenos atmosféricos (lluvia, tormentas)","Fuentes de energía (agua y aire)","Fenómenos naturales (sismos, derrumbes)","Movimiento de la Tierra: el día y la noche","Estaciones del año","Ciclo del agua","Introducción a la Materia","Importancia de la fotosíntesis","Las Hormonas: Los Mensajeros Secretos de Nuestro Cuerpo"],"conceptual":"Materiales del suelo (rocas, agua, textura, humedad)\nFenómenos atmosféricos: precipitación (lluvia, granizo), temperatura, viento, arcoíris\nFuentes de energía: agua y aire\nFenómenos naturales: sismos, derrumbes\nMovimiento de la Tierra: el día y la noche\nEstaciones del año\nCiclo del agua (precipitación, escorrentía, evaporación)","procedural":"Exploración y formulación de preguntas sobre fenómenos atmosféricos\nDescripción y comparación de estaciones del año\nExperimentación guiada: diferenciación de tipos de suelo (color, vegetación)\nFormulación de preguntas sobre movimientos de la Tierra (sismos, derrumbes)\nObservación y comparación de la posición del Sol\nExploración del ciclo del agua mediante diagramas","attitudinal":"Cuidado del medio ambiente\nSolidaridad y respeto por las diferencias\nInterés por descubrir propiedades de la materia"}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:20:36.182Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('e2e425b4-4e33-41b8-838c-c9794a3d5de4', 'formacion-humana', '4to', '{"id":"e2e425b4-4e33-41b8-838c-c9794a3d5de4","name":"Conceptos de unidad","themes":[{"id":"44e4e6cc-0293-4837-afcc-4b35a5489534","name":"El cuerpo","subthemes":[{"id":"92f8e799-9c41-404c-891d-9675392a113c","name":"Partes del cuerpo humano."},{"id":"a460f875-1e17-4e82-b127-4c72b2c0b570","name":"Funciones del cuerpo."},{"id":"49651522-1f80-4927-8314-e82bc2d26639","name":"Valoración y respeto del propio cuerpo."}]},{"id":"72a47820-cc1e-434f-9aa7-5051bfb8af38","name":"Cambios del cuerpo","subthemes":[{"id":"47b8e6b5-1b4d-4674-b328-d7c982cf1450","name":"Cambios físicos a medida que crecemos."},{"id":"6cdf8775-feda-481d-a1e5-f7b7c37c3c1d","name":"Cambios en los sentimientos y emociones."},{"id":"54da5d0d-bdba-4e18-8523-a399ed2070bc","name":"Aceptación y cuidado de los cambios del cuerpo."}]},{"id":"85b8bf8f-ad98-4175-bb1d-c6700934eb3e","name":"Cuidado y protección del cuerpo – criatura de Dios","subthemes":[{"id":"f2829472-d823-4c95-bb1c-4d3b001f346a","name":"El cuerpo como regalo de Dios."},{"id":"af69f800-4587-4ee4-8467-644e9bb96a04","name":"Hábitos de higiene y cuidado personal."},{"id":"031e6700-bf11-4c79-af42-5b799712dffa","name":"Protección del cuerpo y la salud."}]},{"id":"07a51af1-58ee-40d5-9eff-1b7a0af2fe6c","name":"Importancia y necesidad del trabajo","subthemes":[{"id":"52bd8d2b-7607-4dd4-a88b-8a0271f2d67e","name":"El trabajo como medio para vivir."},{"id":"7c189d2c-79f3-4fb7-87ad-9aae9f3a89be","name":"El trabajo en la familia y la comunidad."},{"id":"540a27a6-e783-478b-8e47-c9e57b3deb66","name":"Valor del esfuerzo y la responsabilidad."}]},{"id":"b8f923a2-7457-49d9-a3f3-2244bce5204e","name":"El trabajo mejora la creación de Dios","subthemes":[{"id":"da93f72e-11c7-4d00-ad6b-9f3cbdf71030","name":"El trabajo humano al servicio del bien común."},{"id":"74517f17-b84d-479f-ad2d-99744c59c88d","name":"Cuidado de la creación mediante el trabajo."},{"id":"79a209ab-4cc2-47be-8898-5a01231a6dd2","name":"Uso responsable de los recursos naturales."}]},{"id":"35ff073a-667d-4558-a12a-cba5c55e4c27","name":"Trabajo científico y tecnológico","subthemes":[{"id":"ee453501-1e84-45e6-8a50-a8f7e042fd8f","name":"Qué es el trabajo científico."},{"id":"a5246c6d-afe1-49b5-add8-3bef2be5476b","name":"Uso de la tecnología para mejorar la vida."},{"id":"42eea8a6-1ecc-467c-a174-241611dc880a","name":"Aportes de la ciencia y la tecnología a la sociedad."}]},{"id":"bee28c4c-2d45-4cd0-9b13-6e75b2a05966","name":"Desarrollo del trabajo humano","subthemes":[{"id":"2c5c14ff-e222-4e1b-8d4c-e7c6a613e4e7","name":"Evolución del trabajo a través del tiempo."},{"id":"08d27801-d65d-442b-a29a-617014826e49","name":"Nuevas formas de trabajo."},{"id":"fd0e9ba4-e815-41d8-8692-44c7718229b4","name":"Importancia del trabajo para el desarrollo humano."}]},{"id":"f5c3bd30-4c18-4bbc-b6c3-9a2d2dbea768","name":"Trabajo tecnológico y creación de Dios","subthemes":[{"id":"aabcc30c-4a7c-450a-bb38-c8f2f0146876","name":"La tecnología al servicio de la creación."},{"id":"c38e7686-8991-4b22-9902-3fbcef306414","name":"Uso responsable de la tecnología."},{"id":"183b18dc-d687-45ca-831c-5d3885af0907","name":"Tecnología para cuidar la vida y la naturaleza."}]},{"id":"d8ac0266-8160-472f-b2d5-59212f975153","name":"Crecimiento físico, afectivo-sexual y espiritual","subthemes":[{"id":"958cd95a-4172-4d8a-b28d-cbac4520a223","name":"Crecimiento físico del cuerpo."},{"id":"9ca7ef24-37d0-43f6-9ef8-5868818a7540","name":"Desarrollo de los sentimientos y afectos."},{"id":"fa063844-c8a7-4c03-9fed-93b4d554d859","name":"Crecimiento espiritual y valores."}]},{"id":"fdd0eca1-6c1f-4d18-8bb4-b0fe91c34f43","name":"La naturaleza, creación de Dios","subthemes":[{"id":"8fb1827c-ab3d-4a21-ab89-61b571985cc4","name":"Elementos de la naturaleza creados por Dios."},{"id":"4253f691-bd13-4643-b921-994477687f87","name":"La naturaleza como regalo de Dios."},{"id":"e2ab81c9-2ed7-4ff4-b6d2-32dd624961c7","name":"Agradecimiento por la creación."}]},{"id":"db9c2f58-b970-425e-bf11-5c453a907d0a","name":"Cuidado y respeto por la naturaleza","subthemes":[{"id":"ca324dbc-44d4-4260-9d7d-d7fda0ae6e33","name":"Acciones para cuidar el medio ambiente."},{"id":"09a189ff-bcd2-4500-8863-eb74b54fc040","name":"Respeto por los seres vivos."},{"id":"9ebb3a73-bf6e-46b7-8414-2fbc9c18835b","name":"Responsabilidad humana con la creación."}]},{"id":"aa02dad2-2aba-4f83-b2c7-fc3220c2411d","name":"El amor de Dios expresado en Jesús de Nazaret","subthemes":[{"id":"18f03278-ce05-449c-8213-ae6263edb9de","name":"Jesús como muestra del amor de Dios."},{"id":"48906e79-6f15-498a-9e27-8a4b66503fbc","name":"Enseñanzas de amor y servicio de Jesús."},{"id":"846eda88-a827-448f-a9e7-963825b8ac8b","name":"Vivir el amor de Dios en la vida diaria."}]},{"id":"c8a4bdae-7e13-43bf-883a-f064d416ec64","name":"Valoración del trabajo","subthemes":[{"id":"8905ece4-4d4f-4091-a9bd-ddafebf73437","name":"Importancia de la responsabilidad en el trabajo"},{"id":"8f7cdaee-b91e-4bf2-a471-e540f90abfde","name":"Autoestima y orgullo por el trabajo realizado"},{"id":"2798570d-86f1-46a2-869d-68834e811bc8","name":"Reconocimiento del esfuerzo y la perseverancia"}]}],"grade_levels":["4to"],"subjectId":"formacion-humana","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"e2e425b4-4e33-41b8-838c-c9794a3d5de4-block-1","themes":["El cuerpo","Cambios del cuerpo","Cuidado y protección del cuerpo – criatura de Dios","Importancia y necesidad del trabajo","El trabajo mejora la creación de Dios","Trabajo científico y tecnológico","Desarrollo del trabajo humano","Trabajo tecnológico y creación de Dios","Crecimiento físico, afectivo-sexual y espiritual","La naturaleza, creación de Dios","Cuidado y respeto por la naturaleza","El amor de Dios expresado en Jesús de Nazaret","Valoración del trabajo"],"conceptual":"-\tEl cuerpo\n-\tCambios del cuerpo\n-\tCuidado y protección del cuerpo - Criatura de Dios.\n-\tImportancia y necesidad del trabajo.\n-\tEl trabajo mejora la creación de Dios.\n-\tTrabajo científico y tecnológico.\n-\tDesarrollo del trabajo humano.\n-\tTrabajo tecnológico y creación de Dios.\n-\tCrecimiento físico, afectivo-sexual y espiritual.\n-\tLa naturaleza, creación de Dios.\n-\tCuidado y respeto por la naturaleza.\n-\tEl amor de Dios expresado en Jesús de Nazaret\n ","procedural":"-\tSocialización de las características y cambios que se generan en el cuerpo de niños y niñas mediante la utilización de recursos diversos.\n-\tDramatización sobre diferentes formas en que se puede cuidar y proteger el cuerpo de niños y niñas.\n-\tIdentificación de citas bíblicas donde se resalta el respeto al cuerpo como creación de Dios.\n-\tPresentación artística donde muestre que su cuerpo es creación de Dios.\n-\tRepresentación en que se destaca el cuerpo como expresión hacia Dios y del amor de Dios hacia las personas.\n-\tRealización de entrevistas sobre el cuidado del cuerpo a padres, profesores y otros profesionales.\n-\tInvestigación de acciones de respeto e irrespeto a su cuerpo.\n-\tSocialización sobre la importancia del cuerpo y todas sus partes como regalo de Dios a partir 1Corintios 12, 12- 26 y otros textos.\n-\tIdentificación en láminas y otros recursos de las maravillas del cuerpo. \n-\tElaboración de pautas sobre cuidado y protección del cuerpo en los diferentes contextos.\n-\tOrganización de celebración de agradecimiento a Dios por el cuerpo, su cuidado y protección a partir de diferentes expresiones artísticas.\n- Presentación donde se muestre que somos criaturas de Dios a partir de citas bíblicas y otras fuentes.\n \n-\tSocialización sobre el trabajo que realizan el padre, la madre y familiares para sustentar a sus familias y su aporte para el desarrollo de la sociedad. \n-\tConstatación del desarrollo de la sociedad por el trabajo realizado a través de los aportes de la ciencia y la tecnología.\n-\tArgumentación de la necesidad del trabajo en la vida de las personas.\n-\tComparación entre trabajos que promueven al ser humano y su dignidad y otros que no lo promueven. \n-\tExploración sobre la obligación y la necesidad del trabajo para la vida en sociedad.\n-\tAnálisis del Salmo 8 y su referencia al ser humano con relación a todo lo creado.\n-\tOrganización y celebración de acción de gracias por los trabajos que realizan las personas en los diferentes ambientes, utilizando el Salmo 8 y las producciones realizadas.\n-\tInvestigación de los beneficios que el ser humano ha logrado a través de su trabajo científico y tecnológico. \n-\tIndagación sobre las características, ventajas y desventajas de los juegos electrónicos y del uso de la tecnología.\n-\tInvestigación sobre instituciones y/o personas que trabajan para mejorar lo que Dios ha creado (medicina, arquitectura, desarrollo de las TIC, las ciencias, las artes, entre otras).\n \n-\tRepresentación de actividades que muestren la responsabilidad y participación de las personas en el cuidado de la creación a través de la ciencia y la tecnología.\n-\tExpresiones diversas de agradecimiento a Dios por los aportes de las ciencias y las tecnologías a su obra creada utilizando diferentes recursos. \n-\tOrganización de campañas escolares sobre el cuidado y la protección de las personas y del medio natural creado por Dios haciendo uso de herramientas tecnológicas.\n ","attitudinal":"-\tRespeto hacia los demás y sus diferencias \n-\tGratitud a Dios por haberlo creado. \n-\tAdmiración por su cuerpo.\n-\tValoración de su cuerpo.\n \n-\tRespeto por el trabajo de las personas adultas.\n-\tAprecio por los beneficios del trabajo.\n-\tResponsabilidad en las tareas propias del hogar y la escuela.\n-\tAgradecimiento a Dios por permitir a las personas colaborar con su creación a través de la ciencia y la tecnología.\n-\tAdmiración por los avances científicos y tecnológicos.\n-\tAprecio por los aportes de la ciencia y la tecnología en el desarrollo de la sociedad.\n "}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:20:36.182Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('302', 'naturales', '2do', '{"id":"302","name":"Ciencias Físicas","themes":[{"id":"fee30b36-70f5-4e4c-b17b-93061644582d","name":"Cambios de estado de la materia (solidificación y fusión)","subthemes":[{"id":"29571f2a-1142-4a60-be64-2aeaf6ba4a0f","name":"Estados de la materia: sólido y líquido"},{"id":"86cc07e5-5a91-4983-a308-d0b5fc3f941c","name":"Cambios de la materia con el calor"},{"id":"9726786a-8f45-4dbc-a9e5-5762efef7879","name":"La fusión: cuando el sólido se derrite"},{"id":"723b2d32-cb11-4941-b35f-2d007fa88da6","name":"La solidificación: cuando el líquido se endurece"},{"id":"cf346a94-9e37-4540-ae10-4dbceceeb433","name":"Ejemplos de cambios de estado en la vida diaria"}]},{"id":"cfa6e870-712e-4f15-8bfe-fd99916156e0","name":"Estructuras arquitectónicas de tránsito permanente (carreteras, puentes, túneles)","subthemes":[{"id":"87f7f9b1-94b8-4667-b3c2-69a529046051","name":"¿Qué son las estructuras de tránsito?"},{"id":"721c1ad9-e506-4083-a59b-c006a0d29931","name":"Carreteras y su importancia"},{"id":"b3ccde4e-e299-4eb7-98d6-65a52082f027","name":"Puentes y túneles"},{"id":"46a16764-2256-42a6-9d48-fec3bfd049b7","name":"Normas de seguridad vial"}]},{"id":"a56ee0b8-2f7e-4ad2-a5fb-73f884984a79","name":"Mezclas en medios líquido y sólido","subthemes":[{"id":"88e0bd05-8b89-4f32-b8c0-1e9fe7012b2f","name":"¿Qué es una mezcla?"},{"id":"9b4be4f9-1cdb-4386-838d-73a9100ada40","name":"Mezclas de sólidos"},{"id":"a2fbe6ce-34ff-4ace-972a-7dd0a05d0d65","name":"Mezclas de líquidos"},{"id":"0a38dc59-e55b-4987-b2d8-ec81aa80075e","name":"Mezclas de sólidos y líquidos"},{"id":"b58ac9ba-7b26-4473-a2ba-039fa177748c","name":"Uso de las mezclas en la vida diaria"}]},{"id":"6399cfa1-a0c1-456e-8983-61b32c223049","name":"Sonido (intensidad, timbre y eco)","subthemes":[{"id":"00a7cac2-5249-4f18-a74d-67b42117ab42","name":"Diferentes sonidos y sus fuentes (timbre)"},{"id":"d691e105-2c74-4410-882c-e41cd87cc6a6","name":"¿Qué es el sonido?"},{"id":"a4ae5967-e43b-49c3-8103-24feaad90c12","name":"El eco y cómo se produce"},{"id":"0add92e6-a971-4405-8496-02fd085afb90","name":"Sonidos fuertes y sonidos suaves (intensidad)"},{"id":"0f9fb1fe-1a58-4d22-8e52-94293743d71e","name":"Importancia del cuidado del oído"}]},{"id":"69641584-cfe1-42a8-9fba-e6921240ce11","name":"Distancia. Tiempo. Rapidez","subthemes":[{"id":"e832fadf-4e49-443f-ad5f-4b90d9462155","name":"¿Qué es el tiempo?"},{"id":"75c79458-11ea-40a7-ba19-010ad7baf326","name":"¿Qué es la distancia?"},{"id":"7bbec311-1ef8-402a-8a6b-9ce8263b665e","name":"Relación entre distancia, tiempo y rapidez"},{"id":"7d2d6ac2-77ff-4d9b-bf06-a420d9a8ef96","name":"Movimientos rápidos y lentos"},{"id":"a147bdc0-7ed8-45c3-95c0-dd38a2c4f9ee","name":"Ejemplos de movimiento en la vida cotidiana"}]},{"id":"a4d90fa9-de6c-49b1-af49-d4d17aad3417","name":"Tecnología de la comunicación","subthemes":[{"id":"31194ec9-e315-42ec-b9e1-7f528c4e2291","name":"¿Qué es la tecnología?"},{"id":"57f20233-b5fc-46d7-aeb8-9375bcbd7111","name":"Medios de comunicación antiguos"},{"id":"4c9ce335-9baa-4b29-9a8b-3cb221d83eb6","name":"Medios de comunicación actuales"},{"id":"e4d196e8-6fe3-42c1-a78e-0f1f44a7de4c","name":"Uso responsable de la tecnología de la comunicación"}]},{"id":"c265fb33-855e-4562-8acf-cd81c1ed97a3","name":"Máquinas (elementos mecánicos)","subthemes":[{"id":"9ff280dc-724a-4121-bc95-df97c7739cb9","name":"¿Qué son las máquinas?"},{"id":"8f9925d5-04af-4e6e-98ae-e55e707baafd","name":"Máquinas simples"},{"id":"57b2c719-c09c-4f90-a225-37e1356234b0","name":"Uso de máquinas en la vida diaria"},{"id":"2d198e6f-fe66-4b81-90db-0f72b86f5a14","name":"Cuidado y uso seguro de las máquinas"}]}],"grade_levels":["2do"],"subjectId":"naturales","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"302-block-1","themes":["Cambios de estado de la materia (solidificación y fusión)","Estructuras arquitectónicas de tránsito permanente (carreteras, puentes, túneles)","Mezclas en medios líquido y sólido","Sonido (intensidad, timbre y eco)","Distancia. Tiempo. Rapidez","Tecnología de la comunicación","Máquinas (elementos mecánicos)"],"conceptual":"Cambios de estado de la materia (solidificación y fusión)\nMezclas en medios líquido y sólido\nSonido: intensidad, timbre y eco\nInteracción y movimiento: Distancia, tiempo, rapidez\nTecnología de la comunicación\nMáquinas: elementos mecánicos\nEstructuras arquitectónicas (carreteras, puentes, túneles)","procedural":"Experimentación guiada: agua <-> hielo\nIndagación sobre mezclas (sólido disuelto en líquido como gelatina; arena, grava)\nUtilización de recursos tecnológicos para ubicación (sector, ciudad, país)\nMedición y comparación de longitudes (regla, estatura) y volúmenes en líquidos\nMedición del tiempo (minutos, horas, días, años, edad)\nExperimentación con objetos en movimiento (trayectoria, distancia, rapidez)\nIndagación y clasificación de sonidos (personas, animales, aparatos)\nConstrucción y utilización de instrumentos musicales o máquinas simples","attitudinal":"Motivación por aprender sobre el entorno\nMedidas de protección frente a objetos o materiales peligrosos\nUtilización sostenible de recursos tecnológicos"}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:20:36.182Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('20c4088b-c415-4ad1-814e-95bed3b4d4ae', 'sociales', '2do', '{"id":"20c4088b-c415-4ad1-814e-95bed3b4d4ae","name":"La comunidad y la familia","themes":[{"id":"6dfac98f-eefd-422d-9597-0e3fdc80be9c","name":"Espacio natural y social de la comunidad","subthemes":[{"id":"56aa3ab7-be84-4330-9435-7590c0d74a6d","name":"Elementos naturales de la comunidad"},{"id":"50e064c9-348f-4035-b660-513fe5e4bf29","name":"Elementos sociales de la comunidad"},{"id":"4c2c49ce-dc99-4402-9323-9a732f062055","name":"Actividades que se realizan en la comunidad"},{"id":"44edd7ca-7ca1-4fab-ac3d-346c6c8df9dd","name":"Relación entre las personas y su entorno comunitario"}]},{"id":"6357f4d3-d15a-470b-b7d1-bd2427f73628","name":"Cuidado del espacio natural de su comunidad","subthemes":[{"id":"02b645dc-3da0-4287-b33f-cb5194bbe23e","name":"Importancia del cuidado del medio ambiente"},{"id":"d7a0699a-b0ab-4da5-b835-6796bb6b43ea","name":"Prácticas para proteger áreas verdes y recursos naturales"},{"id":"017e3782-2f49-4b67-a0b3-4b8a46d11a66","name":"Consecuencias del mal uso de los recursos naturales"},{"id":"73784208-ccfa-4acc-8018-5a1bfc2c8371","name":"Participación de la comunidad en el cuidado ambiental"}]},{"id":"fddcec29-81fc-445e-867e-b3c7b0174df5","name":"Cuidado de espacios públicos","subthemes":[{"id":"9e305289-484f-4058-b747-79249b814f2c","name":"Identificación de los espacios públicos de la comunidad"},{"id":"e8e93868-1761-4ee0-a7bf-521fdadcc702","name":"Normas para el uso adecuado de los espacios públicos"},{"id":"6523ca76-714e-4cd8-8351-e81c4d95f833","name":"Importancia de mantener los espacios públicos limpios"},{"id":"872c6cb6-0e3b-42c1-8a86-5b479eeca0af","name":"Responsabilidad ciudadana en el cuidado colectivo"}]},{"id":"891f3646-75c9-4dd5-873b-f7ce44d38f44","name":"Sucesos y eventos de la historia familiar y comunitaria","subthemes":[{"id":"7e94a683-ad27-4c97-ab1d-f6553ed4bdf5","name":"Hechos importantes de la historia familiar"},{"id":"c3b82619-1dad-4ce6-95a8-a287ea3ff420","name":"Tradiciones y costumbres familiares"},{"id":"86085e7d-e406-4ba7-ac5b-4a755addd565","name":"Eventos relevantes de la comunidad"},{"id":"0e447b95-8d00-4f3a-97ce-414d309a65b2","name":"Importancia de la memoria histórica familiar y comunitaria"}]}],"grade_levels":["2do"],"subjectId":"sociales","week_duration":4,"description":"Test update 2026-01-23T00:40:02.140Z","achievementIndicators":["Test update 2026-01-23T00:40:02.140Z"],"conceptual_content":[{"id":"20c4088b-c415-4ad1-814e-95bed3b4d4ae-block-1","themes":["Espacio natural y social de la comunidad","Cuidado del espacio natural de su comunidad","Cuidado de espacios públicos","Sucesos y eventos de la historia familiar y comunitaria"],"conceptual":"La Comunidad:\n- Espacio natural y social de la comunidad.\n- Cuidado del espacio natural de su comunidad.\n- Cuidado de espacios públicos\nSucesos y eventos de la historia familiar y comunitaria:","procedural":"Identificación del espacio natural y social:\n- Reconocimiento y dibujo de relieves o aspectos del espacio natural en el que está situada su comunidad.\n- Identificación de los productos que consume regularmente, provenientes de actividades productivas de su entorno.\n- Exploración del espacio social cercano a su casa, a su escuela y a su barrio, y reconocimiento de algunos elementos que lo componen.\n- Participación en campañas de cuidado de espacios públicos de su entorno natural y social (baños públicos, parques, balnearios, playas, entre otros).\nIndagación y levantamiento de información sobre procesos históricos de su familia y su comunidad:\n- Escucha narraciones de acontecimientos pasados de la familia y la comunidad.\n- Elaboración de un árbol genealógico de su familia.\n- Recopilación de informaciones sobre las costumbres, gastronomía de su comunidad.\n- Formulación de preguntas para comprender la relación del pasado con el presente familiar con y con el presente de su entorno familiar y comunitario.\n- Producción oral de cuentos sobre su familia, seleccionando los personajes y teniendo en cuenta el inicio, nudo y desenlace.\n- Presentación en cartulina del presupuesto familiar de su familia durante el mes elaborado por sus padres.","attitudinal":"- Contribución y participación en los trabajos de equipo.\n- Respeto y valoración de las instituciones sociales de su comunidad.\n- Establecimiento de lazos de pertenencia a su entorno social y natural.\n- Muestra de comprensión de la importancia de pertenecer a una comunidad y de la necesidad de involucrarse activamente en ella.\n- Valoración de las características que conforman su identidad.\n- Respeto por los símbolos patrios.\n- Reconocimiento del valor histórico de los héroes y heroínas de la Patria.\n- Compromiso con el cumplimiento de deberes y normas establecidas.\n- Respeto por los puntos de vista diferentes al propio.\n- Valoración de los derechos que corresponden a niños y niñas como seres humanos.\n- Respeto por los turnos al participar en conversaciones grupales.\n- Valoración de la importancia de las señales de tránsito y respeto a sus normas para su protección."}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:20:36.182Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('3f101883-80db-4036-85e9-b3b712c8160e', 'sociales', '2do', '{"id":"3f101883-80db-4036-85e9-b3b712c8160e","name":"Eventos históricos que conforman nuestra identidad","themes":[{"id":"240904f9-7984-443b-8b5e-7617a62f2c8e","name":"Primeros pobladores","subthemes":[{"id":"b0cd1bfd-b311-453a-b5eb-fe02395c866a","name":"Quiénes fueron los primeros pobladores"},{"id":"cc9303dd-b3c7-43b0-8268-12021a4bc66b","name":"Forma de vida de los primeros habitante"},{"id":"7d3528f4-5950-4c3f-be25-74a6b74926ae","name":"Actividades económicas de los primeros pobladores"},{"id":"e082ce7a-116a-4f08-923f-c89f8bc28e89","name":"Aportes culturales a nuestra identidad"}]},{"id":"e2867d75-6c7c-46ce-941f-d56ff0127e86","name":"Llegada de los españoles","subthemes":[{"id":"6801d8c7-c89d-40d9-b2ba-d181615be0ca","name":"Motivos de la llegada de los españoles"},{"id":"f30dbc79-2b3a-43f7-8dba-87ae385e8807","name":"Encuentro entre españoles y pobladores originarios"},{"id":"78eed525-58dd-4b60-aa53-49766c1cf971","name":"Cambios sociales y culturales tras la llegada"},{"id":"98e6abfc-5c5d-4389-93d7-0193f1b3a053","name":"Consecuencias de la colonización"}]},{"id":"efdefff0-578c-494a-a6e9-a2a596355a80","name":"Independencia nacional","subthemes":[{"id":"760f2235-bc9c-4609-a0bc-731a4a405398","name":"Concepto de independencia nacional"},{"id":"804c2922-8162-49ac-b490-3330f8d21fbe","name":"Causas de la independencia"},{"id":"d834ab8a-5f64-4b1d-8bc2-1a14bb95f7f5","name":"Fecha y hechos principales de la independencia"},{"id":"e40e549e-8c48-4b62-84e2-63a5bf6c576a","name":"Importancia de la independencia para el país"}]},{"id":"6917a79e-41a4-4c05-8075-9201a8f7e0a1","name":"Padres de la Patria héroes y heroínas","subthemes":[{"id":"37359710-5967-4a2c-b9dc-47a004e3ed52","name":"Quiénes fueron los Padres de la Patria"},{"id":"6993dacb-4152-4f7f-ad43-7f7fe8d60088","name":"Aportes de los héroes y heroínas nacionales"},{"id":"087afbde-262f-4079-b165-a94a74085494","name":"Valores que representaron los héroes nacionales"},{"id":"6d3869c6-fea4-4900-97f2-566641cf6388","name":"Importancia de su legado histórico"}]},{"id":"6f4d1d47-0045-4c71-9930-62ce4cbf53b2","name":"Símbolos patrios sus componentes: la Bandera, el Escudo Nacional, el Himno, y los orígenes de estos.","subthemes":[{"id":"87422ad1-adaf-4eb1-bb68-7c63a2489a38","name":"La Bandera Nacional y su significado"},{"id":"3587ed4a-f817-4ce4-b2f6-d72fb0d8e4af","name":"El Escudo Nacional y sus elementos"},{"id":"7f655596-2356-4a0e-aa75-5f90bcc30d59","name":"El Himno Nacional y su importancia"},{"id":"da49cd9d-00aa-4956-bb84-db82857430c0","name":"Origen y respeto a los símbolos patrios"}]}],"grade_levels":["2do"],"subjectId":"sociales","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"3f101883-80db-4036-85e9-b3b712c8160e-block-1","themes":["Primeros pobladores","Llegada de los españoles","Independencia nacional","Padres de la Patria héroes y heroínas","Símbolos patrios sus componentes: la Bandera, el Escudo Nacional, el Himno, y los orígenes de estos."],"conceptual":"Eventos históricos esenciales que conforman nuestra identidad:\n- Primeros pobladores. - Llegada de los españoles.\n- Independencia nacional. - Padres de la Patria héroes y heroínas.\n- Símbolos patrios sus componentes: la Bandera, el Escudo Nacional, el Himno, y los orígenes de estos.","procedural":"Indagación de procesos históricos de la nación dominicana:\n- Descripción de los modos de vida de los primeros pobladores (taínos): ubicación geográfica, medio natural en que habitaban, roles de hombres y mujeres, principales actividades, vivienda, costumbres, idioma, creencias, alimentación, estas y otros.\n- Comparación entre el modo de vida y expresiones culturales de los primeros pobladores y aspectos culturales que se han mantenido hasta el presente.\n- Exploración a través de diversas fuentes sobre la llegada de los españoles y los africanos.\n- Acontecimientos históricos: Creación de línea de tiempo sobre los acontecimientos históricos: Taínos, españoles y africanos.\nIdentificación a través de diversas fuentes de los eventos más destacados de la Independencia Nacional (Padres de la patria, heroínas y símbolos patrios):\n- Reconocimiento de las hazañas principales de los Padres de la patria y las heroínas.\n- Elaboración de acrósticos sobre héroes y heroínas. - Reconocimiento de las hazañas principales de los Padres de la patria. - Reconocimiento del aporte de las mujeres a los símbolos patrios. - Análisis de los eventos más significativos de la independencia nacional.\n- Identificación y dibujo de la Bandera y el Escudo Nacional. - Reconocimiento e interpretación del Himno Nacional. - Realización de diálogos sobre los padres de patria y heroínas, respetando los turnos de los demás.","attitudinal":"- Contribución y participación en los trabajos de equipo.\n- Respeto y valoración de las instituciones sociales de su comunidad.\n- Establecimiento de lazos de pertenencia a su entorno social y natural.\n- Muestra de comprensión de la importancia de pertenecer a una comunidad y de la necesidad de involucrarse activamente en ella.\n- Valoración de las características que conforman su identidad.\n- Respeto por los símbolos patrios.\n- Reconocimiento del valor histórico de los héroes y heroínas de la Patria.\n- Compromiso con el cumplimiento de deberes y normas establecidas.\n- Respeto por los puntos de vista diferentes al propio.\n- Valoración de los derechos que corresponden a niños y niñas como seres humanos.\n- Respeto por los turnos al participar en conversaciones grupales.\n- Valoración de la importancia de las señales de tránsito y respeto a sus normas para su protección."}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:20:36.182Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('204a4c18-6771-4d6b-b90d-d1a0d5b32bac', 'sociales', '2do', '{"id":"204a4c18-6771-4d6b-b90d-d1a0d5b32bac","name":"Orientación espacial","themes":[{"id":"fc7ceedc-7cbc-4417-b246-5247b10b47df","name":"Puntos cardinales","subthemes":[{"id":"1e8dae18-1c80-481b-9eb0-690629d38e94","name":"Uso de los puntos cardinales para ubicarse en el entorno"},{"id":"703e9f4c-0a16-42f6-9363-664cc23496a7","name":"Relación de los puntos cardinales con el Sol"},{"id":"a9d471a1-a6a3-400a-8d90-5185b24299ea","name":"Aplicación de los puntos cardinales en mapas y planos sencillos"},{"id":"2ab00693-439c-4657-aba3-4331c6b2c0ce","name":"Puntos cardinales (Norte, Sur, Este, Oeste)"}]},{"id":"4e2d8c9c-c88a-40af-8ad1-28b31a25fd30","name":"Hemisferios norte y sur","subthemes":[{"id":"a8ddcb22-ebef-4856-b4d9-30cae009e761","name":"Concepto de hemisferio"},{"id":"25b01d40-df84-4fd9-a77b-79839ff1d22d","name":"Diferencias entre hemisferio norte y hemisferio sur"},{"id":"ba411bf1-b63d-47c0-8ed1-1d5cc8c2e8b2","name":"Ubicación de países en cada hemisferio"},{"id":"0886ffc7-0b31-416f-aa69-c4102e26864d","name":"Importancia de los hemisferios para el clima y las estaciones"}]},{"id":"6b38bd2d-d571-4221-9b92-c92e17d95d4f","name":"Línea de Ecuador","subthemes":[{"id":"f2aef7f4-9f80-494f-9836-d552e793cef3","name":"Concepto y función de la línea del Ecuador"},{"id":"70371fce-a595-46bf-96c6-b402ce67607e","name":"Ubicación de la línea del Ecuador en el mapa mundial"},{"id":"b36d6986-3782-479e-a099-94c5a2a54acb","name":"Relación de la línea del Ecuador con los hemisferios"},{"id":"e585fd5b-f1c8-4309-8fee-376f38c96151","name":"Influencia de la línea del Ecuador en el clima"}]},{"id":"51851b0b-e6c2-45da-a322-53f995cc979b","name":"La República Dominicana la isla de Santo Domingo en el país y el mundo","subthemes":[{"id":"9f16c2e8-8862-4a50-9a35-1c2ca7c046b7","name":"Ubicación geográfica de la República Dominicana"},{"id":"19d20d5b-81ad-4a9b-b446-8d9ba16c7b96","name":"Países vecinos y límites territoriales"},{"id":"c22d33eb-ea2e-4e28-b1ff-0efbb8cc9ec4","name":"La isla de Santo Domingo y su división política"},{"id":"69724e10-c27d-437c-bb76-eb2a44932c50","name":"Importancia de la República Dominicana en el Caribe"}]},{"id":"df21c70d-d9cd-45a0-916d-a09a8617eb97","name":"Viviendo en una isla","subthemes":[{"id":"eafb1aaa-92d9-4d98-a7f3-6a373eef6b6d","name":"La comida típica de una isla"},{"id":"df0400c8-c4e1-4be0-902b-bf8a9d52f3b1","name":"La pesca como actividad común"},{"id":"4eeff474-c71d-4dd8-897b-dc900bfe0321","name":"Cómo es vivir cerca del mar"},{"id":"39329836-e0b0-492f-b352-20a4104426e4","name":"Celebraciones en la playa"}]},{"id":"fae5c049-bc6d-4958-8cb9-43126ff3e47e","name":"¿Qué es una isla?","subthemes":[{"id":"ddd9959c-e846-495a-950d-99a15df92216","name":"Rodeadas de agua"},{"id":"33171a95-a064-461b-a629-8ea6c1a86144","name":"Otras islas cerca de nosotros"},{"id":"10c122c2-9016-45dd-897b-bf272b85bab0","name":"Islas grandes y pequeñas"}]}],"grade_levels":["2do"],"subjectId":"sociales","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"204a4c18-6771-4d6b-b90d-d1a0d5b32bac-block-1","themes":["Puntos cardinales","Hemisferios norte y sur","Línea de Ecuador","La República Dominicana la isla de Santo Domingo en el país y el mundo","Viviendo en una isla","¿Qué es una isla?"],"conceptual":"Orientación espacial:\nPuntos cardinales.\nHemisferios norte y sur. Ecuador.\nLa República Dominicana la isla de Santo Domingo en el país y el mundo.","procedural":"Reconocimiento de los puntos cardinales: Identificación de los puntos cardinales, ubicación de su casa en el barrio o sector y ubicación de la escuela en la comunidad.\nIdentificación en un mapa de la isla de Santo Domingo de: La extensión territorial, límites geográficos de la isla de Santo Domingo, límites fronterizos entre la República Dominicana y la República de Haití.\nUbicación en un mapa del Caribe de: La isla de Santo Domingo, principales formas de relieve. Islas, mar y océano que la rodean, teniendo en cuenta los puntos cardinales.\nIdentificación en el mapa de la República Dominicana: Su comunidad en la ciudad, pueblo, sección o paraje, teniendo en cuenta los puntos cardinales.\nIdentificación en el globo terráqueo de: la línea del Ecuador, los hemisferios y comentar por qué se ha dividido así. Identificación y dibujo en el aula líneas para establecer hemisferios norte, sur, este, oeste\nIdentificar en un globo terráqueo la isla de Santo Domingo y la importancia de su ubicación.","attitudinal":"Contribución y participación en los trabajos de equipo.\nRespeto y valoración de las instituciones sociales de su comunidad.\nEstablecimiento de lazos de pertenencia a su entorno social y natural.\nMuestra de comprensión de la importancia de pertenecer a una comunidad y la necesidad de involucrarse activamente en ella.\nValoración de las características que conforman su identidad.\nRespeto por los símbolos patrios.\nReconocimiento del valor histórico de los héroes y heroínas de la Patria.\nCompromiso con el cumplimiento de deberes y normas establecidas.\nRespeto por los puntos de vista diferentes al propio.\nValoración de los derechos que corresponden a niños y niñas como seres humanos.\nRespeto por los turnos al participar en conversaciones grupales.\nValoración de la importancia de las señales de tránsito y respeto a sus normas para su protección."}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:20:36.182Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('84fb74f9-05eb-4a92-9463-37280f22b19e', 'sociales', '6to', '{"id":"84fb74f9-05eb-4a92-9463-37280f22b19e","name":"Historia general","themes":[{"id":"67cd3134-147b-4cd6-a788-692ee7452885","name":"Patrimonio natural, histórico y cultural del mundo","subthemes":[{"id":"4bbf246f-f491-4d7c-87ab-b2c20c253db3","name":"Patrimonio natural y biodiversidad."},{"id":"314fc8f6-10b9-464e-887e-288751bfc03a","name":"Tradiciones y patrimonio cultural."},{"id":"f790d86a-33d0-4ebc-b16b-b6dd3ad0ba25","name":"Monumentos y sitios históricos."}]},{"id":"6d8d45ad-a4d2-4c46-9c89-d426136b4120","name":"Primeras civilizaciones de Asia y África","subthemes":[{"id":"82abdfc6-a112-4baa-a649-e0a4593086e5","name":"Mesopotamia y Egipto."},{"id":"bfae415b-bbfa-4830-90aa-0e066bae37de","name":"Aportes: escritura, agricultura y ciencia."},{"id":"de787ece-abae-42c4-a33c-e329ba1a0a3f","name":"Organización social y política."}]},{"id":"2ea22eba-e4e9-4891-a9ab-c51c4440f688","name":"Civilizaciones europeas: Grecia y Roma","subthemes":[{"id":"54ded4a3-ed24-4148-a1d1-5f966b70c3b0","name":"Democracia griega y filosofía."},{"id":"04b390d3-f3e8-4815-bc45-0cae0b7e2041","name":"Aportes culturales y arquitectónicos."},{"id":"a70f82c4-bcd0-4524-b2fc-9ef5bf6faa3e","name":"Imperio romano y leyes."}]},{"id":"bcf288f3-1615-48c4-b9ef-25058253ac80","name":"Cristianismo y Edad Media","subthemes":[{"id":"b214afd7-56f8-49dc-8067-22a1010b4091","name":"Origen y expansión del cristianismo."},{"id":"22030677-5a8c-46ed-ad85-519e40de4229","name":"Iglesia y cultura medieval."},{"id":"2f9854d1-ba90-459f-8319-db7807e56157","name":"Sociedad feudal y castillos."}]},{"id":"53fd59d7-7767-4cec-a039-e7d8af1da4fd","name":"Imperios modernos","subthemes":[{"id":"28851324-f77a-4ed1-9709-d3cc239c7906","name":"Expansión europea."},{"id":"a998da41-62f6-472a-9584-29fbde5ec31b","name":"Nuevas rutas marítimas."},{"id":"51ca9e47-0aa9-4042-abbb-811a19f63061","name":"Colonización y comercio."}]},{"id":"4ed25997-8f9b-4982-bd27-15f6c947dd09","name":"Civilizaciones modernas (siglo XVI a la actualidad)","subthemes":[{"id":"4ce37fef-e2ee-4e31-a1a7-14ef9f98da65","name":"Revoluciones políticas y sociales."},{"id":"508bcfd4-091c-4c4b-81b4-29d90dbfbe85","name":"Industrialización y cambios sociales."},{"id":"018e06a1-a554-445c-9127-7086a3cd24ea","name":"Globalización y avances tecnológicos."}]},{"id":"5ae81136-095c-47bc-bd28-663f4f387f3f","name":"Ciencia y desarrollo capitalista (siglo XVI a la actualidad)","subthemes":[{"id":"0a664771-5fdd-4a24-a8bc-4a828ae16f60","name":"Revolución científica."},{"id":"2702a33c-66e4-4873-9b6b-6399f000cf78","name":"Innovaciones tecnológicas modernas."},{"id":"5cace480-b968-487d-bed7-74ffd7061128","name":"Desarrollo industrial y económico."}]}],"grade_levels":["6to"],"subjectId":"sociales","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"84fb74f9-05eb-4a92-9463-37280f22b19e-block-1","themes":["Patrimonio natural, histórico y cultural del mundo","Primeras civilizaciones de Asia y África","Civilizaciones europeas: Grecia y Roma","Cristianismo y Edad Media","Imperios modernos","Civilizaciones modernas (siglo XVI a la actualidad)","Ciencia y desarrollo capitalista (siglo XVI a la actualidad)"],"conceptual":"Historia General\n–\tPatrimonio natural, histórico y cultural del mundo.\n–\tPrimeras civilizaciones de Asia y África.\n–\tCivilizaciones europeas: Grecia y Roma.\n–\tCristianismo y Edad Media.\n–\tImperios Modernos.\n–\tCivilizaciones modernas desde el siglo XVI a la actualidad Imperios modernos.\n–\tCiencia y desarrollo capitalista desde el siglo XVI hasta la actualidad.\n ","procedural":"–\tIdentificación de lecturas de fuentes seguras y confiables en la redacción de un comentario sobre las primeras civilizaciones europeas y de América.\n–\tElección de la estructura del comentario (punto de partida, tesis, argumentos y conclusión).\n–\tIdentificación de fuentes confiables sobre la que realizará el comentario.\n–\tUso de verbos de opinión en primera persona (considero, creo, pienso, opino).\n–\tFormulación de la tesis en referencia al tema seleccionado.\n–\tEstructuración lógica de los argumentos que apoyan la tesis o planteamiento.\n–\tUso de expresiones que indiquen su postura (sin duda, lamentablemente, se debería, es necesario).\n–\tConclusión sobre los aspectos planteados.\n \n–\tElaboración de línea de tiempo para la ubicación de los siglos que corresponden las primeras civilizaciones, la Edad Media y la Edad Moderna.\n–\tElaboración de líneas de tiempo sobre la evolución y desarrollo de las primeras civilizaciones (Mesopotamia, Egipto, India y China, Fenicia y hebrea).\n–\tAnálisis de algunas de las causas del surgimiento de las primeras civilizaciones\n–\tElaboración de líneas de tiempo sobre la evolución y desarrollo de las primeras civilizaciones europeas hasta los imperios modernos.\n–\t-Observación de videos sobre las primeras civilizaciones (Mesopotamia, Egipto, India y China, Fenicia y hebrea).\n–\tSocialización de ideas sobre la diferencia entre: cultura y civilización\n–\tElaboración de murales con ilustraciones de las antiguas civilizaciones.\n–\tLecturas de mapas históricos para ubicar en el tiempo y el espacio las primeras civilizaciones en África y Asia, Europa y América.\n–\tElaboración de un artículo expositivo sobre las civilizaciones modernas del siglo XVI a la actualidad (Utilización de la estructura (introducción, desarrollo y conclusión) el modo de organización causa consecuencia para comprender la información del artículo expositivo). \n–\tIdentificación de las causas y consecuencias del desarrollo de la ciencia y el capitalismo en el siglo XVI.\n–\tElaboración de líneas de tiempo sobre las etapas de la historia.\n \n ","attitudinal":"–\tAprecio del por el legado histórico de las primeras civilizaciones.\n–\tSe interesa por ubicar en mapa los países que actuales donde se ubicaron las civilizaciones antiguas.\n–\tValoración de los aportes de las civilizaciones antiguas y modernas. \n–\tInterés por plantear su punto de vista sobre las civilizaciones antiguas.\n–\tInterés por entender los acontecimientos históricos que dieron origen a las civilizaciones antiguas y modernas.\n "}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:20:36.183Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('5812f33f-c656-401e-b4fd-f757687964a0', 'sociales', '2do', '{"id":"5812f33f-c656-401e-b4fd-f757687964a0","name":"Derechos y deberes de los niños y educación vial","themes":[{"id":"55f0b634-e24f-4e42-b952-bd8114fe50da","name":"Desarrollo de valores","subthemes":[{"id":"c3c75a0d-0f54-41de-8899-a371fb7b051e","name":"Valores fundamentales: respeto, responsabilidad y solidaridad"},{"id":"d8b6f432-1998-47e3-8c77-f27b674ee5e4","name":"Práctica de valores en la familia y la escuela"},{"id":"a64f821e-5c7f-4c53-b6c9-2afa2d4245c5","name":"Importancia de los valores para la convivencia"},{"id":"e754e0ef-9805-4061-8dfd-6d967e6a471f","name":"Resolución pacífica de conflictos"}]},{"id":"1d89b468-3be4-450e-b605-ab4937db5135","name":"Normas y señales de tránsito","subthemes":[{"id":"4b755253-8a76-45ac-9eec-49898cafaa7b","name":"Importancia de las normas de tránsito"},{"id":"64d78b4c-b18c-40bf-b736-3613b30313a0","name":"Señales de tránsito básicas y su significado"},{"id":"3c490775-5c8c-4a75-8e17-ea4ff5849523","name":"Comportamiento seguro como peatón"},{"id":"35145f41-d7ac-4fb9-ac29-93168f6cfe8d","name":"Educación vial para prevenir accidentes"}]},{"id":"a9df0719-59e5-459c-a358-0a86a0cdaf89","name":"Eventos históricos que conforman nuestra identidad","subthemes":[{"id":"1b7bfa6d-18ee-41ae-b1a8-6cf85fba1e9b","name":"Quiénes fueron los primeros pobladores"}]}],"grade_levels":["2do"],"subjectId":"sociales","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"5812f33f-c656-401e-b4fd-f757687964a0-block-1","themes":["Desarrollo de valores","Normas y señales de tránsito","Eventos históricos que conforman nuestra identidad"],"conceptual":"Derechos y deberes del Niño y la Niña:\nDesarrollo de Valores:\nEducación vial: normas y señales de tránsito:","procedural":"Exploración a través de diversas fuentes (conversaciones, narraciones, cuentos) sobre los derechos de los niños y las niñas:\n- Realización de diálogo sobre los derechos humanos.\n- Expresión gráfica de algunos derechos de los niños y las niñas.\n- Identificación de sus deberes para con su familia, escuela y su comunidad.\n- Escucha historias y cuentos infantiles sobre los valores en las relaciones sociales, como: cortesía, cooperación, compasión, amor.\n- Identificación de los valores que se practican en su familia, escuela y comunidad: respeto a la autoridad, cooperación, responsabilidad, justicia y libertad.\n- Realización de Sociodrama para la búsqueda de soluciones pacíficas a los conflictos, tomando en cuenta los deberes y derechos de los niños y las niñas.\nRepresentación gráfica de las señales de tránsito y reconocimiento de su significado:\n- Exploración de las normas de educación vial y cuestionamiento de su cumplimiento.\n- Identificación de las señales de tránsito y su clasificación: informativas, reglamentarias y preventivas.\n- Diferenciación del significado de las formas y los colores en las señales de tránsito.\n- Identificación de las responsabilidades de hombres y mujeres de su comunidad en el cumplimiento de las señales de tránsito.\n- Escucha noticias sobre educación vial, reconociendo el titular, el cuerpo de la noticia, fotos y pie de fotos.","attitudinal":"- Contribución y participación en los trabajos de equipo.\n- Respeto y valoración de las instituciones sociales de su comunidad.\n- Establecimiento de lazos de pertenencia a su entorno social y natural.\n- Muestra de comprensión de la importancia de pertenecer a una comunidad y de la necesidad de involucrarse activamente en ella.\n- Valoración de las características que conforman su identidad.\n- Respeto por los símbolos patrios.\n- Reconocimiento del valor histórico de los héroes y heroínas de la Patria.\n- Compromiso con el cumplimiento de deberes y normas establecidas.\n- Respeto por los puntos de vista diferentes al propio.\n- Valoración de los derechos que corresponden a niños y niñas como seres humanos.\n- Respeto por los turnos al participar en conversaciones grupales.\n- Valoración de la importancia de las señales de tránsito y respeto a sus normas para su protección."}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:20:36.183Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('8df61c3e-2757-4967-a9a0-6b327eda6e42', 'sociales', '1ro', '{"id":"8df61c3e-2757-4967-a9a0-6b327eda6e42","name":"Entorno natural y social","themes":[{"id":"645a59bd-ad71-4b0e-9308-624d320720d9","name":"Características de su entorno","subthemes":[{"id":"bdc2f1ef-e64e-4025-8742-d5cf926ae995","name":"Elementos naturales del entorno (plantas, animales, agua)"},{"id":"f36b14ee-dbf6-4f6e-a55a-3b9f740060e2","name":"Elementos sociales del entorno (personas, casas, escuelas)"},{"id":"a80adc1d-800d-434b-86b1-0ffc37bec8be","name":"Actividades que se realizan en el entorno"},{"id":"a913e859-0ce5-4969-a2d0-e9657b035648","name":"Relación entre las personas y la naturaleza"}]},{"id":"bfefea7d-c4dd-44fa-abdb-2b64430c9319","name":"Cuidado del entorno","subthemes":[{"id":"11ca983d-ef0c-4e6a-9ce4-ef10316785b8","name":"Importancia de cuidar el entorno"},{"id":"186b6397-9445-4a70-89ee-695dd0bb7e30","name":"Acciones para cuidar la naturaleza"},{"id":"48dc7a9a-fdb6-409a-aad9-de5a19b1f1ea","name":"Cuidado de los espacios sociales y públicos"},{"id":"05ba2598-654b-4d42-90ea-ff3528f0d441","name":"Responsabilidad de las personas con su entorno"}]}],"grade_levels":["1ro"],"subjectId":"sociales","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"8df61c3e-2757-4967-a9a0-6b327eda6e42-block-1","themes":["Características de su entorno","Cuidado del entorno"],"conceptual":"\"Entorno natural y social:\"\n-\tCaracterísticas de su entorno.\n-\tCuidado del entorno.","procedural":"\"Reconocimiento del entorno natural y social:\"\n-\tExploración y descripción de los espacios naturales y sociales que le rodean: parques, monumentos, espacios deportivos, clubes, ‘’casas de la cultura’’, plazas dedicadas a personajes históricos, entre otros.\n-\tDiscusión sobre los cambios del entorno natural y social en relación con el tiempo pasado y presente y su impacto en el futuro.\n-\tDistinción de acciones humanas que benefician el Medioambiente y las que lo perjudican.\n-\tDibujo de señales de tránsito de su entorno.","attitudinal":"-\tValoración y respeto de los diferentes ambientes naturales y sociales.\n-\tCuidado de los espacios naturales y sociales.\n-\tPreocupación por conocer algunas señales de tránsito que se utilizan en las escuelas y la calle."}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:20:36.183Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('7443ba43-f983-491b-870a-62216b3abbc5', 'sociales', '1ro', '{"id":"7443ba43-f983-491b-870a-62216b3abbc5","name":"Orientación espacial","themes":[{"id":"bc479191-d734-4949-84b5-15b1038d25d9","name":"La vivienda, la escuela y otros espacios","subthemes":[{"id":"a788a13c-f088-4b2c-9542-753f6011a658","name":"Mi vivienda y sus espacios principales"},{"id":"0a150833-fc02-47ea-b5be-0c3bb663fd69","name":"La escuela y sus áreas importantes"},{"id":"817b325a-63e5-40b7-a6c6-6db6952afeab","name":"Otros espacios de la comunidad"},{"id":"646b1893-081c-465a-b95a-0544401d8626","name":"Uso y cuidado de los espacios que compartimos"}]},{"id":"3cc18a3d-3161-4ddd-a411-3e2370779a29","name":"La isla de Santo Domingo","subthemes":[{"id":"aadb960c-cfdc-491c-84d8-b51a9118ffe3","name":"Qué es una isla"},{"id":"cd40887f-a6a5-4346-8a23-0cdf0bddc475","name":"La isla de Santo Domingo y su nombre"},{"id":"7b3176f0-cc47-4b34-a8f5-5e8f86e22c53","name":"La isla de Santo Domingo y su nombre"},{"id":"405919c8-2711-408b-b41a-67ad5179c9e7","name":"Ubicación de la isla en el Caribe"}]},{"id":"7537689f-47e9-4c6b-9a4f-dad9a7667b15","name":"La República Dominicana y Haití","subthemes":[{"id":"7e85dfe6-7666-446d-aebf-4814c3f9c98a","name":"Países que comparten la isla de Santo Domingo"},{"id":"98be053e-eaa0-4ae1-9994-7d5de0072184","name":"Ubicación de la República Dominicana y Haití"},{"id":"af04cde7-9ff7-4beb-8e9e-d4f25f052fd9","name":"Ubicación de la República Dominicana y Haití"},{"id":"5e29b050-136a-4b24-9143-7e120e841897","name":"Convivencia y respeto entre los pueblos"}]},{"id":"ce2033c0-dfb8-4d74-acab-d0cf0dafe268","name":"¡Nuestras Plantas: La Fábrica de Alimentos de la Comunidad!","subthemes":[{"id":"0bfdabb7-7c4f-43f5-bc60-306e96b11e99","name":"¡Sembrando nuestra comida!: Actividad de sembrar una semilla comestible (frijol, lenteja) y observar su crecimiento."},{"id":"19956436-cbe3-435d-a52d-f6af25f35f42","name":"Un huerto escolar, ¡comida para todos!: Visita o creación de un pequeño huerto escolar y sus beneficios para la comunidad."},{"id":"fb86b0eb-33e4-4c12-a125-f9ceb26e14cd","name":"Del campo a mi mesa: Trazar el origen de algunos alimentos (ej. la yuca que comemos, el arroz)."},{"id":"3b3b92b3-b024-4293-9d90-5e300bc63556","name":"¿Qué comemos de las plantas?: Identificar frutas, verduras y granos que provienen de plantas."}]},{"id":"77bc4faf-5bc2-493a-adb0-88dce848990d","name":"Manos a la Obra: Creando y Experimentando el Ciclo","subthemes":[{"id":"f4c55ee2-0423-4b8f-8450-db4ca1622d87","name":"\"Sonidos del Agua\": Creación de Instrumentos Musicales con Agua para Representar sus Estados."},{"id":"c1026d15-913c-4ce7-90bc-b0127f0b8d0c","name":"\"Danza del Agua\": Coreografía Sencilla para Representar las Fases del Ciclo."},{"id":"3c5d604d-9896-45cf-99a7-4942211d93dd","name":"\"Mural Interactivo del Agua\": Creación de un Gran Mural con Elementos Móviles para Cada Fase."}]}],"grade_levels":["1ro"],"subjectId":"sociales","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"7443ba43-f983-491b-870a-62216b3abbc5-block-1","themes":["La vivienda, la escuela y otros espacios","La isla de Santo Domingo","La República Dominicana y Haití","¡Nuestras Plantas: La Fábrica de Alimentos de la Comunidad!","Manos a la Obra: Creando y Experimentando el Ciclo"],"conceptual":"\"Historia familiar y entorno\"","procedural":"\"Análisis de su historia familiar y su entorno:\"\n-\tIdentificación de los miembros de su familia.\n-\tRepresentación con número de los miembros de su familia.\n-\tNarración sencilla de la historia de su familia. Dónde vivían, qué hacían antes y qué hacen ahora, etc.\n-\tNarración sencilla de la historia de su escuela, como era antes, como es ahora, como te gustaría que fuera.\n-\tNarración sencilla de la historia de su comunidad, cómo era con antelación, cómo es ahora y cómo te gustaría que fuera.","attitudinal":"-\tInterés por conocer sobre su origen familiar.\n-\tValoración de entorno familiar y escolar.\n-\tRespeto por las tradiciones de su comunidad.\n-\tInterés por su historia familiar.\n-\tValoración de los ancestros familiares.\n-\tValoración de acontecimientos históricos sobre su familia y la comunidad."}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:20:36.183Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('823f353a-ab4d-4b2d-ac89-de49c50d8227', 'sociales', '6to', '{"id":"823f353a-ab4d-4b2d-ac89-de49c50d8227","name":"Historia de América","themes":[{"id":"792a6250-9ab8-4145-b869-1b8e0f488f5b","name":"Cambios en el siglo XVIII en Europa y América","subthemes":[{"id":"81de4d3e-4b85-48bb-a76b-3a2eabaa1abc","name":"Ilustración y nuevas ideas políticas."},{"id":"0618ddd8-adc6-4468-be6d-b55a8e182d3b","name":"Reformas económicas y sociales."}]},{"id":"446e0b9d-ce83-43da-842b-3072160c866c","name":"Revoluciones","subthemes":[{"id":"090c7e58-47cc-4684-91d7-5b9005210f47","name":"Revolución Industrial."},{"id":"697d9510-8aa3-4f95-8299-dc9ed13198b8","name":"Revolución Francesa."},{"id":"bc19dd89-1a8f-4cba-9b77-4625d06f0019","name":"Revolución Haitiana."}]},{"id":"c8c7ee9d-acc1-48d5-b68c-8982813a92a1","name":"Reformas","subthemes":[{"id":"b389cda9-c338-414b-a72b-0f207dfbfb09","name":"Cambios políticos y sociales."},{"id":"8c94d4ab-70f9-4615-8ff2-d6589bf2357e","name":"Reformas borbónicas."},{"id":"dd08611a-2753-42a0-8483-f238fcc09308","name":"Nuevas ideas ilustradas."}]},{"id":"b2d0d330-c146-4514-a6db-bf7f2edacd06","name":"Independencia","subthemes":[{"id":"5a1d5d63-b31b-4bd0-aa52-2cd86a48d154","name":"Independencias latinoamericanas."},{"id":"59cede42-6f2c-4482-a8c2-9702d514864a","name":"Independencia de EE.UU."},{"id":"c1a7eaa3-938c-4757-9f6f-1da73e0aaa72","name":"Formación de nuevos Estados."}]}],"grade_levels":["6to"],"subjectId":"sociales","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"823f353a-ab4d-4b2d-ac89-de49c50d8227-block-1","themes":["Cambios en el siglo XVIII en Europa y América","Revoluciones","Reformas","Independencia"],"conceptual":"Historia de América\n–\tCambios en el siglo XVIII en Europa y América:\n–\tRevoluciones, reformas e independencia.\n ","procedural":"–\tExplicación de los procesos históricos relacionados con la expansión de Occidente durante los siglos XVI- XVIII. \n–\tElaboración informe de lecturas y monografías sobre las civilizaciones modernas y su legado.\n–\tAnálisis de los conceptos de revolución, reformas e independencia y su vinculación con las ocurridas en América.\nComparación de textos cortos sobre el capitalismo, liberalismo y socialismo durante los siglos XVI al XX.\n–\tExplicación crítica de los aportes de la ciencia en el Renacimiento y la conquista. \n–\tAnálisis crítico del papel de los Imperios modernos: \nPortugal, España, Francia, Inglaterra, Holanda. Dominación en América, África, Asia y Oceanía en el proceso de conquista.\n–\tAnálisis de los acontecimientos más destacados del siglo XVIII en Europa.\n \n–\tComprensión de la Ilustración, de los personajes relevantes y de las características de los conservadores y los liberales.\n–\tLectura, comentario de texto y discusión sobre las causas de la Independencia de los Estados Unidos de América.\n–\tIdentificación de las causas de la Independencia de los Estados Unidos de América (situación de los colonos, impuestos, monopolización, personajes relevantes de esta, cronología) y sus consecuencias en el Caribe y América.\n–\tExplicación de las causas y consecuencias de las revoluciones burguesas, la revolución de Haití y las revoluciones hispanoamericanas.\n–\tRealización de una historieta sobre los cambios ocurridos en el siglo XVIII en Europa y América: Revoluciones, reformas e independencia (Utilización de la estructura de la historieta (inicio, nudo y desenlace), Inferencia, a partir del contexto, el significado de las palabras que desconoce, uso de las viñetas, las imágenes, los globos con textos y sin textos, de las onomatopeyas, el tamaño de las letras y el color para comprender su contenido.\n \n ","attitudinal":"–\tValoración crítica de las revoluciones políticas burguesas, en particular de la Revolución Francesa y de la Revolución Haitiana, como promotoras de los derechos humanos y el respeto a la dignidad humana de todos los sectores sociales.\n–\tSe interesa por comprender acontecimientos históricos de la expansión de occidente durante los siglos XVI Y XVIII.\n–\tInterés por comprender los acontecimientos históricos sobre las independencias y revoluciones.\n–\tInterés por plantear su punto de vista sobre las revoluciones hispanoamericana. \n "}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:20:36.183Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('d2831537-ad7e-4b4e-8474-b292b37bef8a', 'sociales', '1ro', '{"id":"d2831537-ad7e-4b4e-8474-b292b37bef8a","name":"Fechas patrias, Héroes y heroínas. Símbolos Patrios","themes":[{"id":"9820a2ff-64bf-495a-b609-2be2dc67579d","name":"Fechas patrias","subthemes":[{"id":"15ab61fa-273c-43ed-be9e-48cc3e0a61b1","name":"Qué son las fechas patrias"},{"id":"86372024-907e-4c74-8b9a-0d46ff9de8f4","name":"Principales fechas patrias de la República Dominicana"},{"id":"eded63ea-7362-40ed-8d13-b72aa88ec45a","name":"Cómo celebramos las fechas patrias en la escuela"},{"id":"31f63b2b-0d61-4f74-acb9-733c62177b44","name":"Importancia de recordar las fechas patrias"}]},{"id":"e0423eaf-6b32-4c2b-9d63-a3daa2e10264","name":"Héroes y heroínas","subthemes":[{"id":"fa0231c9-c732-46c5-8043-53dcee4542c0","name":"Quiénes fueron los héroes y heroínas"},{"id":"0591e34a-06fb-4576-a0d9-da0b27f2ae06","name":"Padres de la Patria"},{"id":"3edbc01a-da1a-445e-867a-bcbc96da6936","name":"Valores que representaron los héroes y heroínas"},{"id":"7547dbd9-e016-4f0c-a59c-35f827c3cc3e","name":"Importancia de su legado para el país"}]},{"id":"15eaa022-bcdd-41af-8509-49c23ce8d8b4","name":"Respeto y valoración de los símbolos patrios","subthemes":[{"id":"18ef9288-456d-49d8-b444-6d74cb49069d","name":"Normas de respeto a los símbolos patrios"},{"id":"f62219db-ad85-4345-a0ac-adf21b331b4a","name":"Uso correcto de la Bandera Nacional"},{"id":"4d097371-3004-407d-a3d4-e746fad9668a","name":"Actitud adecuada al entonar el Himno Nacional"},{"id":"d2ec98c0-1839-4cdc-8f19-8748aab60b19","name":"Importancia de cuidar y valorar los símbolos patrios"}]},{"id":"745bf49d-626c-40cc-a8fa-c97c2e42f47a","name":"Símbolos patrios","subthemes":[{"id":"d158adb6-9f42-4a4b-b18e-6b28f1356b01","name":"Qué son los símbolos patrios"},{"id":"8ad8ed78-0267-4daf-acee-8f3d0506dcb3","name":"La Bandera Nacional y su significado"},{"id":"09677121-22e8-47e7-b725-c1489893c6eb","name":"El Escudo Nacional y sus elementos"},{"id":"c495e03a-e7ef-460b-a90f-53789542f3cd","name":"El Himno Nacional y su importancia"}]},{"id":"b8917a6b-0d3a-49b0-98aa-c7bb86a009bd","name":"¿Qué es la independencia?","subthemes":[{"id":"a4ff6c61-2725-4283-a394-d4f91eefa5c8","name":"Nuestro país es libre"},{"id":"a8d7cecc-ac1e-4c99-a884-7a437901c7c4","name":"Celebramos la independencia con orgullo"},{"id":"5a6bf5f8-0007-4069-8491-7e434c9e576d","name":"Nuestros héroes lucharon por la libertad"},{"id":"d875c0e3-6d05-41d6-8068-3ac0f9a8fca3","name":"La bandera es nuestro símbolo"}]}],"grade_levels":["1ro"],"subjectId":"sociales","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"d2831537-ad7e-4b4e-8474-b292b37bef8a-block-1","themes":["Fechas patrias","Héroes y heroínas","Respeto y valoración de los símbolos patrios","Símbolos patrios","¿Qué es la independencia?"],"conceptual":"\"Fechas patrias, Héroes y heroínas.\"\nSímbolos Patrios: Bandera, Escudo e Himno Nacional.","procedural":"\"Identificación de algunas fechas patrias, héroes y heroínas y los símbolos patrios: Bandera, escudo e Himno Nacional:\"\n-\tIdentificación de fechas patrias relevantes.\n-\tIdentificación de héroes y heroínas que aportaron a procesos históricos.\n-\tObservación y Reconocimiento de la estructura de la bandera dominicana.\n-\tExplicación del significado de los colores de la bandera y su evolución histórica.\n-\tExplicación del significado de los componentes del escudo.\n-\tDibujo de la Bandera y escritura de sus colores.\n-\tDominio del Himno Nacional a través de la escucha y entonación del mismo.","attitudinal":"-\tValoración de los símbolos patrios.\n-\tParticipación en actividades de celebración de las fiestas patrias.\n-\tValoración de los aportes de los héroes y heroínas.\n-\tParticipación de actividades donde se dibujen la bandera y el escudo.\n-\tInterés por cantar el Himno Nacional dominicano.\n-\tInterés por conocer las principales fechas patrias."}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:20:36.183Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('cb14e9a7-bf62-4c13-a2e7-a0129b121890', 'sociales', '1ro', '{"id":"cb14e9a7-bf62-4c13-a2e7-a0129b121890","name":"Historia familiar y entorno","themes":[{"id":"4cc61c18-aa1d-43ef-9808-e05d14c618fa","name":"Mi familia y sus integrantes","subthemes":[{"id":"16707945-56d4-419e-8e30-cb2ea6dcf085","name":"Quiénes forman mi familia"},{"id":"5f445b46-8014-4928-a800-204256870d26","name":"Roles y responsabilidades en la familia"},{"id":"8b1749c3-2d56-4afd-a1f8-8f16a4242385","name":"El respeto y el cariño en la familia"},{"id":"ec5ecc89-c53f-4152-bdc5-aa0e0dd51a87","name":"La familia como grupo de apoyo"}]},{"id":"7fc54b11-6826-4879-a254-70c8c0ba0334","name":"Cambios y recuerdos importantes de mi familia","subthemes":[{"id":"4945ee33-b71e-4791-8e39-c40a77c977d7","name":"Momentos importantes de mi familia"},{"id":"a2bb4490-383a-4fce-a992-90220778841c","name":"Cambios que ocurren en la familia con el tiempo"},{"id":"c9b31bb9-919a-4071-92ae-7b8aca76a9a7","name":"Recuerdos familiares significativos"},{"id":"231aa1f4-5ccf-42f5-b2ce-aed0e3ce6755","name":"Importancia de recordar la historia familiar"}]},{"id":"42f1a0fe-0e62-4849-99db-66c2fd902c4e","name":"Mi casa y los lugares que forman mi entorno","subthemes":[{"id":"e3f32e0a-b275-476c-9a5e-7dbb538ebcf1","name":"Mi casa y sus espacios"},{"id":"818fb993-2674-4ba7-bd18-1c6786243d87","name":"Lugares importantes de mi comunidad"},{"id":"f852b5fb-1514-410a-9b65-1c6daec89919","name":"Uso y cuidado de los espacios del entorno"},{"id":"650b92cb-bc70-4639-947c-13449b63b41b","name":"Relación entre mi casa, la escuela y la comunidad"}]},{"id":"b2e5ecfb-e60c-4150-abd9-249960de9960","name":"Tradiciones y costumbres familiares y comunitarias","subthemes":[{"id":"5dbfc4fc-b178-429b-bc39-5ff420734fdb","name":"Tradiciones de mi familia"},{"id":"a780d751-5a39-4fef-9bb6-bf28c101dd74","name":"Costumbres de la comunidad"},{"id":"610f4f04-67a9-409f-bc10-edd14dc33c63","name":"Valor de las tradiciones para la identidad"},{"id":"1d68c4b8-8fbb-4f2e-bc9d-a13873e585bb","name":"Celebraciones familiares y comunitarias"}]}],"grade_levels":["1ro"],"subjectId":"sociales","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"cb14e9a7-bf62-4c13-a2e7-a0129b121890-block-1","themes":["Mi familia y sus integrantes","Cambios y recuerdos importantes de mi familia","Mi casa y los lugares que forman mi entorno","Tradiciones y costumbres familiares y comunitarias"],"conceptual":"\"Historia familiar y entorno\"","procedural":"\"Análisis de su historia familiar y su entorno:\"\n-\tIdentificación de los miembros de su familia.\n-\tRepresentación con número de los miembros de su familia.\n-\tNarración sencilla de la historia de su familia. Dónde vivían, qué hacían antes y qué hacen ahora, etc.\n-\tNarración sencilla de la historia de su escuela, como era antes, como es ahora, como te gustaría que fuera.\n-\tNarración sencilla de la historia de su comunidad, cómo era con antelación, cómo es ahora y cómo te gustaría que fuera.","attitudinal":"-\tInterés por conocer sobre su origen familiar.\n-\tValoración de entorno familiar y escolar.\n-\tRespeto por las tradiciones de su comunidad.\n-\tInterés por su historia familiar.\n-\tValoración de los ancestros familiares.\n-\tValoración de acontecimientos históricos sobre su familia y la comunidad."}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:20:36.183Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('1f63e7e0-565e-446b-b5a9-e5e555ee34b3', 'educacion-artistica', '6to', '{"id":"1f63e7e0-565e-446b-b5a9-e5e555ee34b3","name":"Artes Visuales","themes":[{"id":"508a439e-d87d-442c-af2e-7daf040cb6b7","name":"Instituciones y espacios artísticos","subthemes":[{"id":"91f120ae-2096-4419-ac84-290610714193","name":"Tipos de espacios: teatros, museos y galerías."},{"id":"98a1dc7d-276d-4a95-bed7-0e8c6fb41975","name":"Función cultural y educativa."},{"id":"58c92b6a-3bfe-4079-8879-9a2c466c531b","name":"Escuelas y talleres de arte."}]},{"id":"91ce3e97-99b5-4ed1-8836-c569d7b144d2","name":"Artistas y gestores de arte","subthemes":[{"id":"ea79e33e-cbae-402b-a944-3eec38ab9d96","name":"Roles: pintores, músicos, actores, artesanos."},{"id":"ee19b404-d0e2-454e-ae5a-b202142d0e7a","name":"Gestión y promoción del arte."},{"id":"1c480c6d-feb7-41d0-a9e5-6d646cd43fff","name":"Trabajo creativo y producción artística."}]},{"id":"094ec229-f2ae-409d-b889-e872ab7862ff","name":"Eventos y acontecimientos artísticos","subthemes":[{"id":"5557ef3e-3d6b-4005-9fab-ba1a26f6128e","name":"Eventos artísticos locales y nacionales."},{"id":"05c06b72-eefe-4a7d-959e-f8d45113a205","name":"Presentaciones escénicas y musicales."},{"id":"8e922b65-dfb5-475d-869f-ffba0ca42ee2","name":"Festivales y exposiciones."}]},{"id":"450c880b-f118-4a3e-8b8d-2b5a77e33126","name":"Artes visuales","subthemes":[]},{"id":"098008c3-e4f6-414d-942c-290353aab6e2","name":"Medios audiovisuales (cine, TV, internet)","subthemes":[{"id":"a01b874a-b0be-4a0d-a7e1-3a7462845d74","name":"Recursos: imagen, sonido y edición."},{"id":"687b5a47-212d-4795-8307-75b8662f9475","name":"Funciones del audiovisual."},{"id":"1e68a20e-5414-4ef5-b703-0e81c190dcc3","name":"Tipos de contenido audiovisual."}]},{"id":"bb771857-585d-4836-88c0-d7806d929a43","name":"Lo popular en artes plásticas dominicanas","subthemes":[{"id":"f2c7b854-4b31-46b3-9b8f-2c78ba8ab4cd","name":"Colores y estilos tradicionales."},{"id":"276e5729-e0a5-4b26-96f3-e7f6149bd47c","name":"Temas cotidianos dominicanos."},{"id":"538485fd-17fd-4f86-a0af-8f95a75d16e2","name":"Identidad cultural en el arte."}]},{"id":"142a3710-eb40-4c92-b5a5-c77110f0bf67","name":"Composición visual (línea, punto, imagen, color, espacio)","subthemes":[{"id":"7ec3685d-85a3-4a47-b791-7467f0b370b9","name":"Organización del espacio visual."},{"id":"32ff5f21-c7dd-4676-8a6c-e40aa9083cc9","name":"Uso del color y formas."},{"id":"6af8150b-5cd8-43f7-98d0-bf507a931837","name":"Elementos básicos del lenguaje visual."}]},{"id":"07815719-0425-46b4-bb7d-ce41140906c1","name":"Géneros (ficción, documental, anuncio)","subthemes":[{"id":"7be8c87b-ce45-48e1-825e-1bdc10fd8327","name":"Publicidad: mensaje visual."},{"id":"4f0dc7a8-16b4-4542-8ce3-4b3db4c425b8","name":"Características de ficción."},{"id":"f751acba-c67b-4aef-80b7-9fb890a580c5","name":"Características de ficción."}]},{"id":"3847db33-9d8c-4abd-b16a-933a93911116","name":"Soportes (película, video digital)","subthemes":[{"id":"05ab567c-4c75-4101-be51-2f34cc3478f1","name":"Formatos audiovisuales básicos."},{"id":"1038abfd-51e0-47c8-896a-604ad12fbad4","name":"Uso educativo y artístico."},{"id":"97c25043-0746-42cb-8211-bfd84b84507a","name":"Diferencias entre película y digital."}]}],"grade_levels":["6to"],"subjectId":"educacion-artistica","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"1f63e7e0-565e-446b-b5a9-e5e555ee34b3-block-1","themes":["Instituciones y espacios artísticos","Artistas y gestores de arte","Eventos y acontecimientos artísticos","Artes visuales","Medios audiovisuales (cine, TV, internet)","Lo popular en artes plásticas dominicanas","Composición visual (línea, punto, imagen, color, espacio)","Géneros (ficción, documental, anuncio)","Soportes (película, video digital)"],"conceptual":"-\tInstituciones y espacios artísticos (teatros, museos, galerías, escuelas de arte y artesanía, talleres, entre otros).\n-\tArtistas y gestores de arte (pintores, músicos, actores, bailarines, artesanos, entre otros).\n-\tEventos y acontecimientos relacionados con las artes (visuales, aplicadas, escénicas y musicales) a nivel local, regional y nacional.\n \n\"Artes Visuales\"\n-\tLa composición visual: línea, punto, imagen, color, espacio.\n-\tMedios audiovisuales: cine, televisión, internet. Funciones, recursos y contenidos.\n-\tSoportes: película, video digital.\n-\tGéneros: ficción, documental, anuncio publicitario.\n-\tLo popular en las artes plásticas dominicanas: temáticas relacionadas con el quehacer cotidiano.\n ","procedural":"-\tInvestigaciones sobre las instituciones, personas, acontecimientos e inserciones en lugares históricos y eventos relacionados con las artes (visuales, aplicadas, escénicas y musicales) a nivel local, regional y nacional.\n-\tVisitas presenciales y virtuales a instituciones culturales, lugares históricos, parques, \nmonumentos relacionados con las artes (visuales, aplicadas, escénicas y musicales) a nivel local, regional y nacional.\nArtes Visuales\n-\tDibujo y pintura utilizando la línea, el punto, la imagen, el color y el  espacio como elementos de la composición visual.\n-\tApreciación de distintas expresiones artísticas del cine, la televisión y el internet. Análisis y crítica.\n-\tRealización de video autobiográfico con fotos, videos, testimonios, dibujos, animaciones.\n-\tRealización de obras pictóricas y artesanales inspiradas en las costumbres y tradiciones dominicanas.\n ","attitudinal":"-\tEsmero en la aplicación de efectos artísticos en sus pinturas y dibujos.\n-\tValoración del teatro de títeres como medio de intercambio de ideas.\n-\tValoración del uso correcto de las técnicas vocales en diferentes géneros musicales y escénicos.\n-\tValoración justa al realizar un análisis de expresiones artísticas apreciadas en el cine, la televisión y el Internet.\n-\tDisposición para trabajar en equipo.\n-\tInterés por indagar las manifestaciones folklóricas  dominicanas.\n-\tValoración e identificación con las instituciones, personas, lugares históricos, eventos y acontecimientos relacionados con las artes (visuales, aplicadas, escénicas y musicales) a nivel local, regional y nacional.\n-\tValoración del arte popular dominicano.\n "}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:20:36.183Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('69257d04-b5ab-4247-94da-7b1d26e4e232', 'sociales', '1ro', '{"id":"69257d04-b5ab-4247-94da-7b1d26e4e232","name":"Derechos y necesidades","themes":[{"id":"6f530225-50c2-4289-af80-177860801492","name":"Derechos y necesidades","subthemes":[{"id":"0be25f62-2ada-4b11-b969-5e587e92caad","name":"Qué son los derechos"},{"id":"a0f1e9ed-aa8a-435a-ab6b-ff0e9fba10a5","name":"Derecho a la familia y al cuidado"},{"id":"403b3f90-4f2e-4ae3-a161-b57a3b629317","name":"Derecho a la educación y al juego"},{"id":"c166369f-79e6-4dc7-9c6a-cd1384188146","name":"Derecho a la protección y al respeto"}]},{"id":"bc458554-b118-4e70-9151-53df44c99b38","name":"Necesidades básicas de las personas","subthemes":[{"id":"23abf320-e736-41d2-ac22-6fdaa286f2a3","name":"Alimentación y agua"},{"id":"6588531e-6a2d-4309-b702-4648e38b9037","name":"Vivienda y abrigo"},{"id":"1f4f2473-f37a-48f4-b5df-1df7faab8ed1","name":"Salud y cuidado personal"},{"id":"4c95fce3-8baf-45c4-a478-d7e32e88429d","name":"Descanso y recreación"}]},{"id":"736700ff-e1b6-4290-847a-e0c41ee201fe","name":"Diferencia entre derechos y necesidades","subthemes":[{"id":"93ba939d-32be-4a53-8124-956c3a6a5852","name":"Qué son los derechos y las necesidades"},{"id":"71f6bff5-ec66-4d1f-9803-07bb98840a48","name":"Derechos que protegen nuestras necesidades"},{"id":"178c6e3a-9dfc-4d9c-aba8-d64dd465c659","name":"Ejemplos de derechos y necesidades en la vida diaria"},{"id":"d399310e-9b55-4353-8939-f20e536c1a23","name":"Importancia de respetar derechos y cubrir necesidades"}]},{"id":"2e064345-ccc7-46ce-be42-80bd6b83f176","name":"Responsabilidades para cuidar los derechos","subthemes":[{"id":"5f994571-cb41-467a-aeac-8a3b3c66c49a","name":"Cumplir normas en la familia y la escuela"},{"id":"fd6e03ea-08c8-4559-a017-a9e3d45c6c23","name":"Respetar los derechos de los demás"},{"id":"374e6672-1b6b-418d-bea3-65595e6b659f","name":"Participar de forma responsable en la comunidad"},{"id":"0a3d78a6-0633-40b8-94c7-7d22dcf190c7","name":"Cuidar los espacios y recursos comunes"}]}],"grade_levels":["1ro"],"subjectId":"sociales","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"69257d04-b5ab-4247-94da-7b1d26e4e232-block-1","themes":["Derechos y necesidades","Necesidades básicas de las personas","Diferencia entre derechos y necesidades","Responsabilidades para cuidar los derechos"],"conceptual":"\"Orientación espacial:\"\n-\tLa vivienda, escuela y otros espacios.\n-\tLa isla de Santo Domingo. \n-  La República Dominicana y Haití.","procedural":"\"Orientación y ubicación en el espacio siguiendo directrices:\"\n-\tRealización de dibujos de su vivienda. Escritura del lugar donde se encuentra.\n-\tRepresentación de los espacios de su casa utilizando figuras geométricas. \n-\tExploración guiada mediante mapas sencillos para ubicarse en los diferentes espacios en que se encuentre.\n-\tIdentificación en un mapa, la isla de Santo Domingo y los países que la componen.\n-\tUbicación en un mapa de la isla, la parte que ocupa la República Dominicana.\n-\tOrientación de espacios cercanos a su casa y a la escuela (lejos, dentro, fuera, arriba y abajo).\n-\tObservación y dibujo de los espacios que existen en su comunidad (parques, jardines y patios).\n-\tRepresentación de los espacios de su casa utilizando figuras geométricas.\n-\tUbicación de posiciones en los diferentes espacios de su casa y escuela (derecha, izquierda).\n-\tRealización de juegos grupales para la ubicación de los espacios de su aula (derecha, izquierda):","attitudinal":"-\tInterés por la ubicación de la isla de Santo Domingo y los países que lacomponen.\n-\tParticipación en actividades realizadas en el aula para la ubicación lejos, dentro, fuera, arriba y abajo).\n-\tSe interesa por representar los espacios de su casa y de su comunidad.\n-\tValoración de actividades y actividades individuales y grupales para la ubicación espacial.\n-\tInterés por la ubicación de la República Dominicana en un mapa.\n-\tParticipación en la elaboración de dibujos que representen los espacios de comunidad."}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:20:36.183Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('7caba209-0cce-45e7-b06c-00b04baec039', 'sociales', '1ro', '{"id":"7caba209-0cce-45e7-b06c-00b04baec039","name":"Orientación temporal","themes":[{"id":"9c1c2235-6367-48db-8221-f32d7c4d8dd4","name":"Pasado, presente y futuro","subthemes":[{"id":"351e0722-d34c-4ad6-8934-55a808dfc8d6","name":"Qué pasó antes (pasado)"},{"id":"e0803c35-3ea9-4831-a70f-32c6ec51ff78","name":"Qué pasó antes (pasado)"},{"id":"f5147218-743a-4113-84c9-9709ab52b0d2","name":"Qué pasará después (futuro)"},{"id":"5ed50041-2cbf-4e29-b5b2-2a6e8d7bdb50","name":"Importancia de reconocer el paso del tiempo"}]},{"id":"83defeb2-4fd2-4e06-8645-62d4f0f27e32","name":"Ayer, hoy y mañana","subthemes":[{"id":"a91931de-7cff-4db1-9100-7bb96e6bf581","name":"Significado de ayer, hoy y mañana"},{"id":"cc109847-36d3-45ce-baba-b07b52942309","name":"Actividades que realizamos ayer"},{"id":"7b3563fe-a5c2-4f15-aef3-7a56422d3b5f","name":"Actividades que hacemos hoy"},{"id":"50190969-415e-4ae0-a0a8-e4c784a5b1d2","name":"Actividades que hacemos hoy"}]},{"id":"ccd6d8fb-9324-452e-99fc-58b4b762c3a2","name":"Antes y después","subthemes":[{"id":"3d500c4e-537b-4cce-b4dc-1b0d6936bfa3","name":"Actividades que haremos mañana"},{"id":"8a3059ac-cfa1-46cd-a787-fd2aa57c8c0f","name":"Orden de acciones en la vida diaria"},{"id":"d5eeb46a-efe2-4669-bc49-4954a40e0e3d","name":"Uso de “antes” y “después” en cuentos y relatos"},{"id":"4322c422-d99e-4336-bd73-774cb709e58f","name":"Uso de “antes” y “después” en cuentos y relatos"}]}],"grade_levels":["1ro"],"subjectId":"sociales","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"7caba209-0cce-45e7-b06c-00b04baec039-block-1","themes":["Pasado, presente y futuro","Ayer, hoy y mañana","Antes y después"],"conceptual":"\"Orientación temporal:\"\nPasado, presente, futuro. Ayer, hoy y mañana. Antes y después.","procedural":"\"Orientación en el tiempo:\"\n-\tDescripción oral de las actividades que realiza en la casa, durante la mañana, el día, la tarde y la noche.\n-\tEscritura y lectura de las actividades que realiza en la escuela durante el horario de clases.\n-\tMención de actividades que realiza antes y después de asistir a la escuela.\n-\tReconocimiento y verbalización de acciones de su familia y propias, pasadas (ayer), presentes (hoy) y que va a realizar en el futuro (mañana).\n-\tDramatización y realización de juegos sobre las actividades que realiza presentando el pasado, el presente y el futuro.\n-\tRepresentación gráfica de líneas de tiempo sencillas ayer, hoy y mañana.","attitudinal":"-\tIntegración a actividades que muestren lo que realiza en mañana, en el día, la tarde y la noche.\n-\tValoración del tiempo dedicado a sus tareas en la casa y la escuela pasadas \n(ayer), presentes (hoy) y que va a realizar en el futuro (mañana).\n-\tParticipación en actividades lúdicas que representen los espacios de su familia.\n-\tValoración de tiempo dedicado a sus actividades."}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:20:36.183Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('4e838150-085a-4641-a30e-c72266c0b3a4', 'sociales', '6to', '{"id":"4e838150-085a-4641-a30e-c72266c0b3a4","name":"América en el siglo XX","themes":[{"id":"80d5e5df-0df9-4074-a985-07ce1c56528a","name":"Estados Unidos (siglo XX)","subthemes":[{"id":"fb6bd609-dac0-49cd-9ac8-34b01a5ffae9","name":"Crecimiento económico e industrial."},{"id":"9d3c61a3-3b5c-43ad-8b62-a0ca06eac029","name":"Influencia política y cultural."},{"id":"e64a6ee8-40d4-4a8a-8d19-4f66d3973e1e","name":"Participación en guerras mundiales."}]},{"id":"959fe66b-61f3-49cd-abd5-bf81f76b78dc","name":"Canadá (siglo XX)","subthemes":[{"id":"5ff1aa8f-9d3f-48a6-a314-5c3d0cc83fc0","name":"Desarrollo económico y social."},{"id":"b5e6a0b9-d9ef-404b-8b6b-a44eb2dbaad8","name":"Relaciones con EE.UU. y el mundo."},{"id":"4d07d6ca-d625-479f-81f3-74831c421305","name":"Sistema político y multiculturalidad."}]},{"id":"adc2d520-f485-4261-be11-210f71f500a5","name":"Latinoamérica (siglo XX)","subthemes":[{"id":"501a340d-ed7a-4b1b-b7f0-2f473589e0f1","name":"Dictaduras y democracias."},{"id":"00acf5c0-7822-4c0a-a5da-9efd7e50c192","name":"Desarrollo económico y desigualdad."},{"id":"afa3e70f-5189-4850-9a88-9c8e99f0e81b","name":"Movimientos sociales y reformas."}]},{"id":"23f717ff-e94e-4a3e-bf3b-dd6efbddd4d6","name":"Imperios coloniales e impacto en LATAM (siglo XX)","subthemes":[{"id":"a5878fbe-b7c7-4d16-b318-d7b1827ea27e","name":"Fin del colonialismo tradicional."},{"id":"fbf2c037-6050-41df-b78e-69d6d58ba8fd","name":"Cambios políticos y sociales."},{"id":"6658e949-356e-4a63-ab29-1cc8fbbb7216","name":"Influencia extranjera y economía."}]}],"grade_levels":["6to"],"subjectId":"sociales","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"4e838150-085a-4641-a30e-c72266c0b3a4-block-1","themes":["Estados Unidos (siglo XX)","Canadá (siglo XX)","Latinoamérica (siglo XX)","Imperios coloniales e impacto en LATAM (siglo XX)"],"conceptual":"América en el siglo XX: Estados Unidos, Canadá y \nLatinoamérica\n– Imperios coloniales y su impacto en América durante los siglos XX.\n ","procedural":"–\tAnálisis de la incidencia de los imperios coloniales impacto en América durante los siglos XIX y XX.\n–\tComprensión del papel de los imperios coloniales en América en el siglo XX.\n–\tInterés por comprender la situación política de América en la primera mitad del siglo XIX. \n–\tIdentificación de fuentes confiables y seguras sobre la historia de América.\n ","attitudinal":"–\tReflexión crítica sobre los imperios coloniales que incidieron en Latinoamérica. \n–\tInterés por la situación política de América en el siglo XX.\n–\tValoración de los sectores que resistieron las intervenciones de los Estados Unidos de América.\n "}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:20:36.183Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('e646d657-c3ea-4e1f-b6c5-5b9ff1a8d757', 'sociales', '1ro', '{"id":"e646d657-c3ea-4e1f-b6c5-5b9ff1a8d757","name":"Valores y deberes de las personas","themes":[{"id":"67134c9b-8128-4192-8272-42d9c0730dc3","name":"Responsabilidad en la familia, en la escuela y en la comunidad","subthemes":[{"id":"d90247c3-4ad1-4722-af9d-7e6b5c3ebb22","name":"Qué es la responsabilidad"},{"id":"09ebba6e-1689-4468-a25e-4777373c30b0","name":"Responsabilidades en la escuela"},{"id":"35e68db0-5627-471a-ad52-3a5e4c2be47d","name":"Responsabilidades en la familia"},{"id":"269e1618-edf0-4a0d-98b9-709858b05299","name":"Responsabilidades en la comunidad"}]},{"id":"b5bb120c-1ee7-42a7-9533-662e4d0af25f","name":"Respeto a su persona y a sus iguales","subthemes":[{"id":"09ca9a4b-d61a-40c8-b1fa-fbb2de6369aa","name":"Cuidado y respeto de uno mismo"},{"id":"472222f0-c7c9-46f1-8ad3-465205820635","name":"Respeto a los compañeros y compañeras"},{"id":"123e148d-6dc8-4914-ac37-ed28e950c001","name":"Respeto a los compañeros y compañeras"},{"id":"f5276325-ce56-4dd6-8907-142d6ab9c012","name":"Buen trato y convivencia"}]},{"id":"abca78b3-812f-4765-910d-5d6a063a0b9a","name":"Escucha y diálogo","subthemes":[{"id":"34f3679c-8ba4-4dc3-9b66-36ca8d9770a5","name":"Importancia de escuchar a los demás."},{"id":"fc3a3778-2251-4497-adc2-9c0d623a63c3","name":"Importancia de escuchar a los demás"},{"id":"fb4817ca-9469-46ab-9165-15ff7393b7c8","name":"Expresar ideas con respeto"},{"id":"85c556dc-1c83-474a-bea4-9f42bb0056fe","name":"Resolver conflictos mediante el diálogo"}]},{"id":"5dc4227f-1459-4ae5-ab89-7d666f341642","name":"Relaciones armoniosas","subthemes":[{"id":"2613c91a-11a5-4bc4-b3f9-b84f8bb1833a","name":"Qué son las relaciones armoniosas"},{"id":"64b3715b-ae1e-45a1-be41-589b22342362","name":"Qué son las relaciones armoniosas"},{"id":"14244ab7-87cb-4603-a7b4-d32ad782961b","name":"La amistad y el compañerismo"},{"id":"762abd8b-ea89-4c6f-8771-251360c8917e","name":"Cooperación y trabajo en equipo"}]}],"grade_levels":["1ro"],"subjectId":"sociales","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"e646d657-c3ea-4e1f-b6c5-5b9ff1a8d757-block-1","themes":["Responsabilidad en la familia, en la escuela y en la comunidad","Respeto a su persona y a sus iguales","Escucha y diálogo","Relaciones armoniosas"],"conceptual":"\"Valores y deberes de las personas\"\n-\tResponsabilidad en la familia, en la escuela y en la comunidad.\n-\tRespeto a su persona y a sus iguales.\n-\tEscucha y diálogo.\n-\tRelaciones armoniosas.","procedural":"\"Identificación de los valores, deberes y derechos en la familia, escuela y comunidad y su colaboración con soluciones sencillas a problemáticas de su entorno:\"\n-\tObservación de imágenes, escucha de historias y cuentos infantiles que transmiten valores como: tolerancia, cortesía, amor, respeto, honestidad.\n-\tIdentificación de los deberes que cumplen las niñas y niños en el hogar y en la escuela.\n-\tDescripción y dibujo de las actividades de trabajo y ocio que realizan su familia.\n-\tIntegración en actividades de higiene y limpieza en su hogar y la escuela.\n-\tParticipación en las soluciones de situaciones de su entorno (ahorro de energía al apagar bombillas en su vivienda y la escuela, cuidado del espacio del aula).\n-\tCuidado de su persona y de los demás.\nEscenificación de situaciones donde se asume el diálogo en la solución de conflictos para la convivencia armoniosa.","attitudinal":"-\tValoración de sus derechos y los de sus compañeros/as.\n-\tCumplimiento de las \nresponsabilidades que contribuyen a los entornos donde se desenvuelve.\n-\tInterés por una alimentación sana.\n-\tValoración del diálogo para lograr relaciones armoniosas en su entorno familiar y escolar.\n-\tValoración de las normas de convivencia."}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:20:36.183Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('6a487def-376e-420b-a8df-2ca814ad53ce', 'naturales', '1ro', '{"id":"6a487def-376e-420b-a8df-2ca814ad53ce","name":"Ciencias de la vida","themes":[{"id":"3f36428c-2d48-41d6-baa0-53f4a03a83ed","name":"Los seres vivos y su entorno","subthemes":[{"id":"b650c6f2-28ae-498d-b21b-7144756d4a04","name":"Los seres vivos y su entorno"},{"id":"a6dc277a-dc0a-44e8-b5ba-c0357b0a054b","name":"Seres vivos que nos rodean (plantas, animales y personas)"},{"id":"742fc4d9-dd6f-4d5d-bf02-5e00eb81aee1","name":"Relación de los seres vivos con su entorno"},{"id":"2d3a667a-d851-4373-9bb5-c4d21336c359","name":"Importancia de cuidar a los seres vivos"}]},{"id":"dc640836-2adb-4eb8-94fa-dced758433ef","name":"Componentes bióticos y abióticos","subthemes":[{"id":"de3dd408-b6cf-4740-9778-6b7effddee87","name":"Qué son los componentes bióticos"},{"id":"0059702d-ce82-40e5-bb9c-80cb04e7fbac","name":"Qué son los componentes abióticos"},{"id":"475f5418-21c4-423e-a38d-a9f001b71282","name":"Ejemplos de componentes bióticos y abióticos del entorno"},{"id":"bb887280-f8c7-4e48-ab12-6defc21566e2","name":"Relación entre los componentes bióticos y abióticos"}]},{"id":"13f06f13-10e1-4624-a382-40afa0345c66","name":"Los sentidos: vista, oído, olfato, gusto y tacto","subthemes":[{"id":"63a17ed9-cafe-4289-990e-acc79fad8354","name":"La vista y lo que nos permite observar"},{"id":"8d858cd2-7f75-42fb-afe8-5983f5487151","name":"El oído y los sonidos del entorno"},{"id":"27d6adb0-f154-40ed-b9f6-d46fb3b11aac","name":"El olfato y los olores"},{"id":"56528dee-de9d-4dfb-84e3-f7161b359520","name":"El gusto y el tacto en la vida diaria"}]},{"id":"55aab5c3-1e9a-4a6f-95cb-f7d240c962f3","name":"Energía y conservación","subthemes":[{"id":"198daf57-af63-4835-86af-078f01254f47","name":"Los alimentos"},{"id":"0b3e77f1-76e3-40a3-96e5-cb8136238f1a","name":"Qué son los alimentos"},{"id":"4bb34a9c-ecf4-427b-8858-c888e7ed68c1","name":"Tipos de alimentos (frutas, verduras, carnes, granos)"},{"id":"462726dc-cdaf-4772-940e-eaf68a095740","name":"Alimentos saludables para crecer fuertes"},{"id":"2ad3a1b8-dd43-42de-ab8c-9d601cb9a8b9","name":"Importancia de una alimentación balanceada"}]},{"id":"a150402f-6e64-48c8-a463-9b7c917611c1","name":"Sistema y mecanismo","subthemes":[{"id":"fc10281b-5afe-4f6a-8871-07e98e497a83","name":"Estructura externa del ser humano, animales y plantas"},{"id":"954dc403-f4eb-4161-b556-22aab012cbde","name":"Partes externas del cuerpo humano"},{"id":"728e8866-3974-419e-bf5d-602288459d8e","name":"Partes externas de los animales"},{"id":"6dd78ee3-c308-44d5-ab2c-d9897ffa5134","name":"Partes externas de las plantas"},{"id":"c4b699ad-73bf-4419-9a70-a30b44e2ada5","name":"Función de las partes externas de los seres vivos"},{"id":"6c6a17bf-66d0-4425-ad48-7573bb75966a","name":"Características externas o rasgos físicos de los seres vivos"},{"id":"ff8edf72-1e05-427f-8896-4103590d8976","name":"Semejanzas y diferencias entre los seres vivos"},{"id":"fc6fd453-dbb7-4664-9914-226ab49b9448","name":"Rasgos físicos que identifican a los seres vivos"},{"id":"1218be5f-5aa0-4b13-b15f-6e617f518b1c","name":"Importancia de respetar la diversidad de los seres vivos"}]},{"id":"b266d088-9e5c-48ab-8e8e-389ae71f9cfb","name":"Salud","subthemes":[{"id":"617955d4-920a-4296-a370-ebb5e6b22f42","name":"Enfermedades infecciosas"},{"id":"1320c1a5-1802-4d59-a3f4-a47eee9b7192","name":"Cuidado e higiene personal"},{"id":"c407a7fe-d1c9-416b-b093-299ce264a2a8","name":"Vacunas"}]}],"grade_levels":["1ro"],"subjectId":"naturales","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"6a487def-376e-420b-a8df-2ca814ad53ce-block-1","themes":["Los seres vivos y su entorno","Componentes bióticos y abióticos","Los sentidos: vista, oído, olfato, gusto y tacto","Energía y conservación","Sistema y mecanismo","Salud"],"conceptual":"\"Ciencias de la Vida\"\n\"Materia y sus propiedades\"\n-\tLos seres vivos y su entorno.\n-\tComponentes bióticos y abióticos.\n-\tLos sentidos: vista, oído, olfato, gusto y tacto.\n\"Energía y conservación.\"\n- Los alimentos.\nSistema y mecanismo\n-\tEstructura externa del ser humano, animales y plantas.\n-\tCaracterísticas externas o rasgos físicos de los seres vivos.\n\"Salud\"\n-\tEnfermedades infecciosas.\n-\tCuidado e higiene personal.\n-\tVacunas.","procedural":"-Exploración del entorno y sus componentes (plantas, animales, humanos, aire, suelo, agua, energía solar). Procedimiento: observación, medición, comparación, elaboración de croquis, dibujos, diseño y construcción de modelos, comunicación utilizando distintos medios.\n-\tUtilización de diferentes herramientas (lupas, microscopios, binoculares, computadoras, reglas, cintas métricas) para clasificar y describir (diagramas, dibujos, fotos, notas) los componentes de su entorno.\n-\tExploración del entorno sobre la nutrición de las plantas, los animales y el ser humano. Procedimiento: observación, descripción, organización de la información, comparación, discusión y conclusión.\n-\tObservación e identificación de la estructura externa de las plantas y los animales, utilizando instrumentos y aparatos (regla, cinta métrica, lupa, microscopio, binoculares).\n-\tExperimentación (guiada): respuesta de las plantas ante los estímulos externos (luz, agua, temperatura). Procedimiento: diseño, planificación, observación, medición, registro de información, discusión, conclusión y presentación.\n-\tExperimentación (guiada): germinación de semillas. Procedimiento: observación diaria, dibujo, medición, descripción, análisis, conteo, tabulación, discusión y conclusión.\n-\tDescripción y discusión sobre síntomas de enfermedades infecciosas comunes (gripe, sarampión, varicela, conjuntivitis, viruela, dengue...) por medio de narraciones y dibujos. Inventario sobre control de vacunas recibidas en función de sus edades.\n-\tAnálisis y discusión de los sentidos especiales en algunos animales. Procedimiento: observación, descripción, comparación, comunicación oral o escrita.\n-\tDiscusión sobre la salud de los órganos sensoriales. Utilizando e interpretando diferentes fuentes de información, realizando comentarios, anécdotas y conclusiones.\n-\tDescripción y comunicación de medidas higiénicas para el cuidado y protección de la salud (cepillado de dientes, baño corporal, lavado de manos y los alimentos).\n-\tInferencias de rasgos físicos comunes en plantas, animales y humanos, utilizando distintos recursos.","attitudinal":"-\tManifestación de curiosidad, creatividad, objetividad; comunicación de sus ideas, seguimiento de procedimientos, trabajo individual y colaborativo, cuidado de su salud y el Medioambiente, respeto a las ideas y diferencias de las demás personas, solidaridad y utilización sostenible de los recursos de que dispone.\n-\tDemostración de interés por conocer sobre las propiedades y características de los estados de la materia, por utilizar herramientas y construir máquinas simples y modelar estructuras y aparatos de comunicación.\n-\tMotivación por aprender cosas nuevas de su entorno.\n-\tDemostración de interés por conocer sobre las propiedades y características de los estados de la materia, por utilizar herramientas y construir máquinas simples y modelar estructuras y aparatos de comunicación.\n-\tMotivación por aprender cosas nuevas de su entorno.\n-\tAdopción de medidas de cuidado, protección y prevención respecto a la luz, el ruido, los olores, y sustancias peligrosas, así como otros objetos que puedan afectar sus órganos o salud.\n-\tParticipación con los y las demás en experiencias, observaciones, ideas, inquietudes, aspiraciones y preguntas sobre las propiedades de los objetos y la manifestación de los estados de la materia.\n-\tDemostración de interés por aprender sobre sí mismo y su entorno.\n-\tAdopción de medidas de cuidado, de su entorno, de los recursos disponibles, de su salud y la de las demás personas."}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:20:36.183Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('ed99298a-1443-469e-a00c-0a5a890d240f', 'naturales', '3ro', '{"id":"ed99298a-1443-469e-a00c-0a5a890d240f","name":"Ciencias de la tierra y el universo","themes":[{"id":"c3618df8-0e39-478b-b75b-8c848ed9f601","name":"Materia y sus propiedades","subthemes":[{"id":"06ffb1a1-a02a-4091-9ef9-90c737b2baa8","name":"Rocas (ciclo de las rocas)"}]},{"id":"1f9bae37-91a9-41e9-acea-13dd001d2269","name":"Energía y conservación","subthemes":[{"id":"4e8f4eb0-5203-42b8-86cf-4b5cd170b925","name":"Terremoto, maremoto (tsunami)"}]},{"id":"fc7134ce-f3b8-4e8a-9efd-9ea83ae6df5b","name":"Interacción y movimiento","subthemes":[{"id":"6075c649-158a-4a9c-9929-2cc3ceb9280f","name":"Movimiento de la Tierra (años) y de la Luna (fases)"}]},{"id":"64aa5f6a-91ea-42ae-b056-b41d085f132d","name":"Sistema y mecanismo","subthemes":[{"id":"d6aff3de-7942-48d5-9503-485e2603bbc9","name":"Elementos del Sistema Solar: Sol, Luna, planetas y cometas"},{"id":"ec08cdbe-40ee-4f3b-bfb9-2e5697a5fa54","name":"Clima"},{"id":"3f0a2a5a-adc2-4da3-b53e-7eb0358de788","name":"Tiempo"}]},{"id":"cc092373-19f6-4d64-a4b9-3db3e918b39e","name":"Exploradores de Texturas y Formas: La Materia a Través de Nuestros Sentidos","subthemes":[{"id":"d5629090-8d73-478c-9147-62cd0f6bd78b","name":"Flota o se hunde: La aventura submarina con diferentes materiales en agua."},{"id":"daa24fb8-4c87-4751-99d1-48a9b7e6388c","name":"¿Qué pesa más?: Comparando el peso de diferentes objetos usando una balanza simple."}]},{"id":"4be2b822-f5bb-4085-a95f-71bec2523781","name":"Exploradores Sensoriales de la Materia: Toca, Mira y Descubre","subthemes":[{"id":"dd4604c7-2a15-42e3-b016-a21c5cc2a6b5","name":"¿Flota o Se Hunde?: Diseñando un experimento para clasificar objetos por densidad."}]}],"grade_levels":["3ro"],"subjectId":"naturales","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"ed99298a-1443-469e-a00c-0a5a890d240f-block-1","themes":["Materia y sus propiedades","Energía y conservación","Interacción y movimiento","Sistema y mecanismo","Exploradores de Texturas y Formas: La Materia a Través de Nuestros Sentidos","Exploradores Sensoriales de la Materia: Toca, Mira y Descubre"],"conceptual":"\"Ciencias de la tierra y el universo\"\n \n\"Conceptos\"\n \n\"Materia y sus propiedades\"\n-\tRocas (ciclo de las rocas).\n \n\"Energía y conservación\"\n-\tTerremoto, maremoto (tsunami).\n \n\"Interacción y movimiento\"\n-\tMovimiento de la Tierra (años) y de la Luna (fases).\n \n\"Sistema y mecanismo\"\n-\tElementos del Sistema Solar: Sol, Luna, planetas y cometas.\n-\tClima.\n-\tTiempo.\n ","procedural":"\"Ciencias de la tierra y el universo\"\n \n-\tRecolección, observación y descripción de las características físicas de diferentes rocas, y vinculación de estas con su entorno.\n \n-\tDescripción del movimiento de la corteza terrestre (terremoto y maremoto). Exposición utilizando diferentes herramientas para registro de informaciones (diagramas, gráficos, notas).\n \n-\tObservación, descripción y comparación sobre el movimiento de rotación de la Tierra: el día y la noche. Exposición utilizando distintos medios.\n \n-\tObservación de la Luna y sus fases. Procedimiento: registro de observación, comparación entre las fases, comunicación y organización de su resultado a partir de observación de las fases de la luna durante algunos meses.\n \n-\tAnálisis, descripción y discusión sobre desastres naturales: inundaciones de agua y lodo, derrumbes (deslizamientos), aludes, aluviones, sequías. Relación con experiencias conocidas y exposición por medio de narraciones.\n \n-\tObservación, descripción y comparación sobre la relación entre el Sol, la Tierra y la Luna. Exposición por medio de narraciones y dibujos.\n \n-\tAnálisis y discusión usando diferentes herramientas para exponer las informaciones sobre cómo los océanos y las montañas afectan el clima.\n \n-\tAnálisis, discusión y organización de informaciones sobre el clima en los polos, el ecuador, las montañas y las costas.\n ","attitudinal":"- Participación en la organización y ejecución de actividades colectivas del aula tendientes a adquirir aprendizajes significativos."}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:20:36.183Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('18a01a0b-b09b-434d-9861-c734ce299707', 'educacion-artistica', '4to', '{"id":"18a01a0b-b09b-434d-9861-c734ce299707","name":"Artes Escénicas","themes":[{"id":"12634523-21af-4b37-bb98-545ad4e84a3c","name":"Acciones reales e imaginarias para la representación de cuentos, mitos y leyendas","subthemes":[{"id":"8c55d819-cedb-4b94-9e9e-e7c97264ce3a","name":"Representación de acciones reales del entorno."},{"id":"2e137c9a-8a46-42de-a832-5dc3a97a40a7","name":"Representación de acciones imaginarias y fantásticas."},{"id":"7afe27e5-917a-4d57-b528-2f0bc2cad7f6","name":"Representación de acciones imaginarias y fantásticas."}]},{"id":"16f7d96d-aef1-4f09-8201-48350ff910a4","name":"El tiempo en el movimiento y el gesto corporal","subthemes":[{"id":"997f3fee-9b91-45be-afa3-88fe2bed74d0","name":"Movimientos rápidos y lentos del cuerpo."},{"id":"60742171-29ed-4de1-9316-4995ba91393e","name":"Duración de los gestos y movimientos."},{"id":"e5a824b2-28a7-4668-9e9f-cd417064c989","name":"Coordinación del movimiento con el tiempo."}]},{"id":"978ade3f-9c62-48ba-bd6e-e35a9e49d60f","name":"Recursos asociados al tiempo, al espacio y a las direcciones","subthemes":[{"id":"a0310586-09cf-40b3-a14a-f983b0f871f0","name":"Velocidad, continuidad y energía del movimiento."},{"id":"a6356293-a940-48e4-a89b-3ee460fffb62","name":"Uso del espacio: niveles bajo, medio y alto."},{"id":"c8cdadd5-f3d2-4b15-98d6-e26efcf84d6b","name":"Direcciones del movimiento (arriba/abajo, derecha/izquierda, amplitud)."}]},{"id":"feaef3c6-2d25-4cdf-9d53-dac3cc0da03a","name":"La dramatización de cuentos, poesías y canciones","subthemes":[{"id":"a579f6a1-6177-4325-97ca-5b95640c2658","name":"Creación y caracterización de personajes teatrales."},{"id":"8614950d-6fac-4562-8714-e1004a17df7f","name":"Representación de cuentos mediante el teatro."},{"id":"f9a3388b-5675-4a17-b1d7-ce6bcc182a86","name":"Dramatización de poesías y canciones."}]},{"id":"15ce29ed-f3a8-4898-b5b3-a807009446b5","name":"La representación escénica: textos, personajes tradicionales y pregones","subthemes":[{"id":"2a0274b2-2a69-4e8f-b33e-82283d3c1ea7","name":"Valor cultural de las representaciones escénicas."},{"id":"ff633924-5025-459c-b684-278a6f00b73c","name":"Uso de textos sencillos en la representación escénica."},{"id":"3893d717-f45e-4ee4-b5ab-34bb73c44964","name":"Personajes tradicionales y pregones de la comunidad."}]},{"id":"1f99929a-4cef-4028-822a-b2e72f4554dd","name":"Títeres: figuras animadas para jugar y contar historias","subthemes":[{"id":"2f43ed1a-6081-4ee1-8c0e-41d8aa0c6f34","name":"Creación de títeres con materiales diversos."},{"id":"87cc2ff4-1f1a-475f-a691-4881695d5555","name":"Animación de títeres para representar acciones."},{"id":"43ecb030-2fbe-4d88-9dfe-5c923e006176","name":"Uso de títeres para contar historias sencillas."}]}],"grade_levels":["4to"],"subjectId":"educacion-artistica","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"18a01a0b-b09b-434d-9861-c734ce299707-block-1","themes":["Acciones reales e imaginarias para la representación de cuentos, mitos y leyendas","El tiempo en el movimiento y el gesto corporal","Recursos asociados al tiempo, al espacio y a las direcciones","La dramatización de cuentos, poesías y canciones","La representación escénica: textos, personajes tradicionales y pregones","Títeres: figuras animadas para jugar y contar historias"],"conceptual":"-\tEl realismo y la ficción en diferentes manifestaciones artísticas.\n-\tLa representación de objetos y personajes imaginarios.\n-\tEl pensamiento divergente como generador de creatividad.\n-\tMúsica y danzas tradicionales dominicanas (merengue y mangulina). \nCaracterísticas musicales, coreográficas y visuales fundamentales.\n-\tIdentidad cultural. Patrimonio material e inmaterial. Bienes culturales.\nArtes Visuales\n-\tEl dibujo (Líneas, luces y sombras como elementos    configuradores de la forma).\n-\tEl círculo cromático: combinaciones y tonalidades del color.\n-\tEl color en los lenguajes visuales: colores primarios, secundarios y complementarios.\n-\tLa narración visual con imágenes fijas o en movimiento.\n-\tTransformaciones reales e imaginarias del espacio (plástico-visual y escénico).\n \n-\tLa exposición de artes visuales y sus componentes básicos: espacio expositivo, iluminación, información del catálogo de participantes, ficha técnica de la obra, entre otros.\n-\tComposiciones visuales en objetos y producciones artísticas bidimensionales (pintura, serigrafía, fotografía, grabado, entre otros) y tridimensionales (cerámicas, maderas talladas, higüeros, pilones, entre otros.).\nArtes Escénicas\n-\tEl tiempo en el movimiento y el gesto corporal.\n-\tRecursos asociados al tiempo \n(velocidad, continuidad y energía), al espacio (niveles bajo, medio y alto) y direcciones, (arriba/abajo, derecha/ izquierda, amplitudes).\n-\tTíteres: figuras animadas para jugar y contar historias.\n-\tAcciones reales e imaginarias para la representación de cuentos breves, pequeñas historias, mitos y leyendas de su región o comunidad.\n-\tLa dramatización de cuentos, poesías y canciones. Personajes teatrales.\n-\tLa representación escénica: textos, personajes tradicionales y pregones.","procedural":"-\tExploración en diferentes manifestaciones artísticas, a partir de temas o formas del realismo y la ficción.\nArtes Visuales\n-\tLa fotografía con dispositivos móviles y sus posibilidades comunicativas.\n-\tCaracterísticas de la fotografía, considerando temáticas y tipos de encuadres.\n-\tLos medios audiovisuales y de las TIC como recursos de realización y análisis de producciones \nartísticas, articulando la percepción, la imaginación y la exploración.\n-\tFormas bidimensionales y tridimensionales pertenecientes a diferentes contextos, géneros y estilos. Técnicas y materiales en el lenguaje plástico-visual.\n-\tUtilización de los colores primarios y secundarios en producciones artísticas a partir de temas de la realidad y de la imaginación.\n-\tEl dibujo a lápiz, a carboncillo y a la témpera en la representación de objetos y personajes imaginarios.\n-\tDiseño y creación de objetos y personajes a partir de simbologías o referentes visuales propios de su región, utilizando materiales de su entorno inmediato.\n \n-\tCreación de dibujos para representar objetos, personas o ambientes rurales y urbanos, a partir del reconocimiento de sus  formas, colores u otras características estéticas.\n-\tAnimaciones sencillas creadas a partir del lenguaje audiovisual: guion, realización, montaje y sonido.\n-\tUtilización del círculo cromático para la representación de emociones y sentimientos en la ejecución de sus producciones visuales.\n-\tRealización de exposiciones de artes visuales y aplicadas. El plan de acción, paso a paso.\nArtes Escénicas\n-\tAcciones físicas y gestos expresivos en relación con los objetos, usos y costumbres de su realidad para comunicar sentimientos, emociones e ideas.\n-\tDramatización de cuentos, poesías y canciones. Interpretación de personajes teatrales.\n-\tModificación del espacio (escénico y plástico visual), utilizando elementos, gestos o movimientos a partir de un concepto real o imaginario.\n-\tEjecución de la mangulina y algunas formas danzadas del merengue dominicano.\n-\tManejo de títeres.\n-\tMontaje de piezas o cuentos breves, con títeres, como medio para conocer, interpretar y transformar la realidad.\n-\tMontaje de espectáculos escénicos integrando distintos elementos artísticos. El plan de acción, paso a paso.\n ","attitudinal":"-\tLa naturalidad en la expresión vocal (hablada o cantada) y corporal, individual y colectiva.\n-\tLa creatividad en el uso de diversos tipos de títeres y otras manifestaciones artísticas, valorando su utilidad a la hora de expresarse.\n-\tLa autoestima en la comunicación artística.\n-\tColaboración, solidaridad y respeto en actividades artísticas colectivas.\n-\tDisfrute de costumbres y prácticas artísticas tradicionales.\n-\tValoración de distintas manifestaciones artísticas, realistas o de ficción.\n-\tValoración y disfrute de los bienes culturales de su comunidad \n(materiales e inmateriales) haciendo conciencia sobre la necesidad de su preservación.\n-\tRespeto a las indicaciones de letreros y gráficos que regulan la convivencia y el orden en entornos rurales y urbanos (parques, monumentos, señalización de tránsito, pasos peatonales, rampas, aceras, depósitos clasificados para desechos, alumbrados).\n \n-\tValoración de los elementos técnicos que enriquecen distintas expresiones \nartísticas (iluminación, banda sonora, amplificación, decoración, maquillaje, vestuarios…).\n-\tValoración de los sentidos, la voz y el cuerpo como propiedades únicas e instrumentos de comunicación y percepción. Respeto a las diferencias.\n-\tValoración de las expresiones propias y ajenas, a partir del respeto y tolerancia con los desacuerdos.\n-\tDisposición a la terminación de la obra artística atendiendo a principios estéticos.\n "}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:20:36.183Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('1077216b-f6a1-4941-a78b-da27b1e14e23', 'educacion-artistica', '5to', '{"id":"1077216b-f6a1-4941-a78b-da27b1e14e23","name":"Artes aplicadas","themes":[{"id":"9a841e32-1866-485d-a6e8-7700e0521ab0","name":"Diseño artesanal: papel maché","subthemes":[{"id":"8969b913-20ad-4633-a43e-caaf44fc7c46","name":"Materiales básicos y preparación de la mezcla (papel, pegamento/engrudo)."},{"id":"3d8ddf74-4d5e-418b-85a2-f64ef613d5f2","name":"Técnicas de modelado: capas, secado y resistencia."},{"id":"d9a22d69-5c99-4022-bb34-ec0bc4e7e903","name":"Decoración y acabado: pintura, colores, textura y barniz."}]},{"id":"4eac2820-78b6-4c44-a871-b9612e75c5a6","name":"La máscara","subthemes":[{"id":"5b3b43dc-ebb1-4f54-bc6b-0ef21fd15be3","name":"Diseño de máscaras: forma, expresión, simetría y creatividad."},{"id":"0695d811-8178-471f-8a13-68d656f0345f","name":"Tipos de máscaras: culturales, teatrales y carnavalescas."},{"id":"b8d00bb6-2b48-4d6e-a313-0ddc7ae03384","name":"Máscaras dominicanas: carnaval y significado de personajes tradicionales."}]},{"id":"25b5f995-92ce-4049-b756-59d56fea7857","name":"El reciclaje en las artes","subthemes":[{"id":"2a8cc167-2b75-4e0f-8fda-57f078cc7423","name":"Materiales reciclables en el arte: cartón, botellas, tapitas, telas."},{"id":"30f9b864-e467-40f5-93b2-b16286e85451","name":"Creación de obras con reciclaje: collage, esculturas y manualidades."},{"id":"decc9645-a38e-4835-9f26-ca3aeacd1937","name":"Conciencia ambiental: reutilizar para reducir basura y cuidar el entorno."}]}],"grade_levels":["5to"],"subjectId":"educacion-artistica","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"1077216b-f6a1-4941-a78b-da27b1e14e23-block-1","themes":["Diseño artesanal: papel maché","La máscara","El reciclaje en las artes"],"conceptual":"\"Artes Aplicadas\"\n \n-\tDiseño artesanal: papel maché.\n-\tLa máscara.\n-\tEl reciclaje en las artes.\n ","procedural":"-\tCoordinación, equilibrio y percepción del espacio en la pantomima.\n-\tAplicación de técnicas de manejo de subidas y bajadas de escaleras y manejo de objetos en la pantomima.\n-\tDramatización en teatro de títeres y pantomima: uso de textos con derecho de autor y la adaptación de cuentos, poesías, experiencias personales, sentimientos, recuerdos y canciones.\n-\tUso de máscaras para la representación de personajes.\n-\tInterpretación de formas folklóricas musicales, cantadas, bailadas y teatralizadas como legado cultural dominicano e incorporarlas a producciones artísticas.\n-\tIdentificación de los rasgos de la cultura regional presentes en la obra de artistas escénicos. (incluye lo gastronómico, uso del lenguaje, hábitat, mitos y leyendas).\n-\tEscenificaciones folklóricas y costumbristas (danza, títeres y pantomima): gestualidad y expresión corporal propias.\n ","attitudinal":"-\tValoración y disfrute de las características de las obras pictóricas producidas por artistas nacionales.\n-\tApreciación de instrumentos musicales de uso popular y folklórico (tambora, güira, guitarra, balsié y marimba de cajón).\n-\tValoración de las creaciones de artistas escénicos y su vinculación con las culturas regionales.\n-\tEsmero en la realización de gráficos promoviendo soluciones a problemáticas sociales.\n-\tValoración de la difusión de obras artísticas criollas en montajes, representaciones, exposiciones y muestras artísticas.\n-\tDisfrute de la realización de actividades colectivas que propicien la interacción grupal.\n-\tValoración del trabajo cooperativo en provecho de la armonía grupal en su participación en bandas rítmicas y conjuntos de flauta dulce.\n "}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:20:36.183Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('c8a3bc57-4cda-43d9-a0dc-dbbbd4210b20', 'naturales', '1ro', '{"id":"c8a3bc57-4cda-43d9-a0dc-dbbbd4210b20","name":"Ciencias físicas","themes":[{"id":"acac2f4c-5618-4572-bdd1-d2f90e09dc33","name":"Materia y sus propiedades","subthemes":[{"id":"1e028648-1363-4ea9-ad83-fa097b81281f","name":"Estados de la materia: líquidos, sólidos y gases"},{"id":"39503705-de29-41af-b140-3b7b79ac52e8","name":"Mezclas en medio líquido"},{"id":"0745ff62-e839-4e8b-a4e7-4a9688cb58dd","name":"Características y propiedades"}]},{"id":"345ddde6-3912-4693-ac37-a90851a6ce0d","name":"Interacción y movimiento","subthemes":[{"id":"87eca993-8497-438c-a5cb-a1a4456489a9","name":"Posición: localización y trayectoria"}]},{"id":"e7b60219-bb60-4a38-b250-5a8a60a8fede","name":"Energía y conservación","subthemes":[{"id":"be081b14-a4cd-44af-8aec-bab4c3941d2d","name":"Luz solar"},{"id":"2843e806-fa88-45f6-80e6-9323925876c2","name":"Máquinas simples"},{"id":"d82fbba2-6337-4501-a773-fd5f286f1102","name":"Tecnología de la comunicación (teléfono, tableta, radio y televisión)"},{"id":"5938c14c-1af2-4f2f-b277-ac886cf752ca","name":"Sonido (intensidad y tono). Sistema y mecanismo"},{"id":"979f7ed1-32f5-42a2-9856-5805346dad6a","name":"Estructuras arquitectónicas habitables"}]}],"grade_levels":["1ro"],"subjectId":"naturales","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"c8a3bc57-4cda-43d9-a0dc-dbbbd4210b20-block-1","themes":["Materia y sus propiedades","Interacción y movimiento","Energía y conservación"],"conceptual":"\"Ciencias físicas:\"\n\"Conceptos\"\n\"Materia y sus propiedades\"\n-\tEstados de la materia: líquidos, sólidos y gases. Sus características y propiedades.\n-\tMezclas en medio líquido.\n\"Interacción y movimiento\"\n-\tPosición: localización y trayectoria.\n\"Energía y conservación.\"\n-\tLuz solar.\n-\tSonido (intensidad y tono).\n\"Sistema y mecanismo\" \n- Máquinas simples.\n-\tEstructuras arquitectónicas habitables.\n-\tTecnología de la comunicación (teléfono, tableta, radio y televisión).","procedural":"\"Ciencias físicas\"\n-\tObservación, comparación y comunicación oral de la posición y dirección de su casa, escuela, edificio u otra referencia conocida.\n-\tIndagación sobre el movimiento. Observación, comparación e inferencia del movimiento comunicando a través de dibujos la trayectoria de objetos y seres vivos.\n-\tConstrucción y utilización de máquinas simples: cuña, polea, palanca, tornillo y plano inclinado. Procedimiento: exploración, organización, seguir instrucciones, clasificación, construcción y evaluación de herramientas y modelos registrando y describiendo sus observaciones.\n-\tExperimentación (guiada): Anticipa resultados imaginando soluciones a la luz de las explicaciones sobre objetos materiales y superficies, sus propiedades y características: forma, color, dureza, transparencia, textura y permeabilidad. (Ejemplos: áspero, blando, tenue, vaporoso, denso, sólido, pesado, liviano, translúcido, elástico, líquido, ancho, delgado, liso, rugosa, gaseoso, transparente, rápido, lento, arriba, abajo, curvo, recto, derecha, izquierda). Procedimiento: observación, medición y recolección de información, descripción y comparación, inferencia a partir de preguntas guiadas, diseño de modelos con distintos recursos.\n-\tExperimentación (guiada): Observación y medición de cómo el Sol calienta y da luz. Procedimiento: comparación, elaboración de preguntas, uso de instrumentos (lupa, espejo, foco, …), inferencias de la narración, dibujos y registro en su cuaderno.\n-\tIndagación acerca de los estados de la materia: sólidos, líquidos y gaseosos Procedimiento: exploración, observación, recolección de muestras, descripción oral y puesta en común.\n-\tExperimentación (guiada): Cambios de estado del agua: agua, hielo y vapor de agua. Procedimiento: exploración, observación, medición, registro a través de dibujos o diagramas, inferencias a partir de preguntas guiadas, conclusión y reporte en su cuaderno.\n-\tIndagación acerca de la relación luz y visión, sonido y audición, suave y áspera con el tacto, gusto, sabor, olor (aire) y olfato. Procedimiento: exploración, recolección de información y descripción oral.\n-\tExploración, comparación y medición de la intensidad y tono del sonido en ser humano, animales domésticos e instrumentos musicales observando el cuidado de su órgano auditivo.\n-\tMezclas en medio líquido (leche y agua). Procedimiento: exploración, observación, medición, recolección de muestras, registro a través\nde dibujos o diagramas, inferencias a partir de preguntas guiadas y \nconclusión.\n-\tObservación, comparación, elaboración y presentación de modelos de su casa y edificación del entorno.\n-\tComparación y utilización de teléfono, radio y televisión.","attitudinal":"-\tDemostración de interés por conocer sobre las propiedades y características de los estados de la materia, por utilizar herramientas y construir máquinas simples y modelar estructuras y aparatos de comunicación.\n-\tMotivación por aprender cosas nuevas de su entorno.\n-\tAdopción de medidas de cuidado, protección y prevención respecto a la luz, el ruido, los olores, y sustancias peligrosas, así como otros objetos que puedan afectar sus órganos o salud.\n-\tParticipación con los y las demás en experiencias, observaciones, ideas, inquietudes, aspiraciones y preguntas sobre las propiedades de los objetos y la manifestación de los estados de la materia.\n-\tDemostración de interés por aprender sobre sí mismo y su entorno.\n-\tAdopción de medidas de cuidado, de su entorno, de los recursos disponibles, de su salud y la de las demás personas."}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:20:36.183Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('7c159b99-5cf8-447a-830f-b78ffbdb4e0d', 'educacion-artistica', '6to', '{"id":"7c159b99-5cf8-447a-830f-b78ffbdb4e0d","name":"Artes escénicas","themes":[{"id":"fe67ea3e-8f5b-4d48-9fda-f2133850165a","name":"El títere de boca","subthemes":[{"id":"076bd0ca-8e7e-4ae2-ab6c-179df8ef44d0","name":"Partes y construcción básica."},{"id":"5222eee4-dda2-46ba-8880-f25aaa6a5626","name":"Técnicas de manipulación y voz."},{"id":"6ef98902-a534-42aa-8d7c-cc94d000ddeb","name":"Creación de personajes simples."}]},{"id":"149bb670-5a6a-4ad8-ae91-55583ae961af","name":"El costumbrismo","subthemes":[{"id":"a1b05469-a73f-4d92-b580-368f189c4fcd","name":"Estilo y expresión cultural."},{"id":"35e3b657-b9d2-4a14-90e8-990f29a8400f","name":"Representación de la vida cotidiana."},{"id":"aff24330-c11a-4dc3-8910-26857b5e09f6","name":"Temas tradicionales dominicanos."}]},{"id":"e8d832b5-f8fb-4be9-a41d-a05ac99c861f","name":"Danza popular","subthemes":[{"id":"3ab054c0-ed8d-441b-a712-3bbb8793e884","name":"Ritmos y pasos básicos."},{"id":"c46e4373-2018-4da1-a793-beadba683ebd","name":"Bailes dominicanos tradicionales."},{"id":"ca6bfd61-f70c-4de2-abaa-ccfcd78a3a9b","name":"Expresión corporal y tradición."}]},{"id":"f465ac4c-f924-4f5e-a098-5e6f24b954a1","name":"Teatro popular","subthemes":[{"id":"2d5b8b1c-6cbf-497d-a179-623201943b1a","name":"Improvisación y actuación básica."},{"id":"7c0f6614-7d59-4926-bb80-3becc432b9d7","name":"Personajes y escenas tradicionales."},{"id":"abe5f06c-7991-4e3d-87a3-dfc5128122ac","name":"Elementos escénicos simples."}]},{"id":"42b06038-9247-4f06-a25f-b396db41790b","name":"El carabiné","subthemes":[{"id":"8755918e-915d-4c54-801d-0f95557b284a","name":"Origen del carabiné dominicano."},{"id":"7803bbb7-6fae-4d17-9111-16fd97bd4317","name":"Ritmo y pasos básicos."},{"id":"ea86ffe1-b7bd-4c05-9057-45c9509af6fe","name":"Importancia cultural y folklórica."}]}],"grade_levels":["6to"],"subjectId":"educacion-artistica","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"7c159b99-5cf8-447a-830f-b78ffbdb4e0d-block-1","themes":["El títere de boca","El costumbrismo","Danza popular","Teatro popular","El carabiné"],"conceptual":"Artes Escénicas\n-\tEl títere de boca.\n-\tEl costumbrismo.\n-\tDanza popular. - Teatro popular.\n-\tEl carabiné.","procedural":"Artes Escénicas\n-\tMontaje de secuencias coreográficas del carabiné: dominio de la coordinación, equilibrio y uso del espacio.\n-\tCreación coreográfica de danzas y montajes escénicos, incorporando canciones, obras y juegos populares.\n \n-\tEducación Musical\n-\tRespiración y técnica vocal para el canto coral.\n-\tInventario y clasificación de ritmos folklóricos dominicanos.\n-\tPráctica de géneros musicales, populares y regionales (vocales, corporales e instrumentales).","attitudinal":"-\tDesarrollo de la interacción grupal y fomento de la imaginación creadora en producciones artísticas.\n-\tApertura a la diversidad de expresiones artísticas populares nacionales.\n "}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:20:36.183Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('6ba65299-6748-494b-96d9-fd034bb75a19', 'naturales', '1ro', '{"id":"6ba65299-6748-494b-96d9-fd034bb75a19","name":"Ciencias de la tierra y el universo","themes":[{"id":"2274bb53-bba4-43fb-ab4a-c933a03bd813","name":"Conceptos Materia y sus propiedades","subthemes":[{"id":"e7737afa-38c8-4928-9756-cf29d0fe6a1c","name":"Suelo. Agua. Aire. "}]},{"id":"a47a0ee7-0f44-4770-9ea6-7ca88c99143f","name":"Interacción y movimiento","subthemes":[{"id":"1cbfc116-cfa4-456b-a7a3-4c2fa38b2ceb","name":"Tierra, Sol y Luna. "}]},{"id":"89571ffe-ab1f-47c8-b1db-4d7d1a79f2af","name":"Sistema y mecanismo","subthemes":[{"id":"72b49d0d-6d59-4a7c-8bfc-eb8280cf3ffc","name":"El día y la noche"}]},{"id":"827155a4-d3bb-41d6-aafa-cd054c6a6438","name":"Introducción a la Materia","subthemes":[]}],"grade_levels":["1ro"],"subjectId":"naturales","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"6ba65299-6748-494b-96d9-fd034bb75a19-block-1","themes":["Conceptos Materia y sus propiedades","Interacción y movimiento","Sistema y mecanismo","Introducción a la Materia"],"conceptual":"\"Conceptos\" \n\"Materia y sus propiedades\" \n- Suelo. Agua. Aire.\nI\"nteracción y movimiento\"\n-\tTierra, Sol y Luna.\n\"Sistema y mecanismo\"\n-\tEl día y la noche.","procedural":"\"Ciencias de la tierra y el universo\"\n-\tObservación de diferentes recursos en el planeta Tierra. Indagación sobre el agua, el aire (vientos, lluvia, ríos, mares, lagunas, lagos, nubes, huracanes) y el suelo; comunica sus observaciones por medio de narraciones y dibujos.\n-\tIndagación sobre la Luna, el Sol y las estrellas. Procedimiento: observación, comparación, clasificación, descripción y análisis, y comunica sus resultados de forma oral o escrita.\n-\tExperimentación (guiada): relación entre luz y sombra, su asociación con la Luna, las estrellas y el Sol. Procedimiento: observación, descripción, comparación, inferencia, y la utilización de instrumentos comunicando sus resultados.\n-\tExploración, observación, formulación de preguntas sobre el cielo de día y de noche. Procedimiento: comunicación de sus observaciones a través de diferentes medios y recursos.\n-\tExperimentación (guiada): características de la luz (bombillo, espejos, fuentes, sombra). Procedimiento: observación, descripción, comparación, inferencia, y la utilización de instrumentos comunicando sus resultados por diferentes medios.","attitudinal":""}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:20:36.183Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('cf48a592-9488-4df7-9f92-65d068d66ad3', 'naturales', '3ro', '{"id":"cf48a592-9488-4df7-9f92-65d068d66ad3","name":"Ciencias de la vida","themes":[{"id":"a901e47e-809e-4d52-9cf7-c5145447ef0d","name":"Materia y sus propiedades","subthemes":[{"id":"e9713da0-dadd-4e3c-a18c-5030f0427260","name":"Seres vivos (plantas y animales)"}]},{"id":"9bf528b5-291f-4179-ad97-5a8cf2507d9a","name":"Energía y conservación","subthemes":[{"id":"a4015bca-6d36-4850-8fb9-353741c836f8","name":"Nutrición: nutrientes"},{"id":"8518dc82-13a2-4f51-b1fb-23b998c72880","name":"Cadena alimenticia"}]},{"id":"2ce2bd3d-d6ab-4856-afd1-b15a04c253fe","name":"Interacción y movimiento","subthemes":[{"id":"38fd0c44-95d0-425e-a549-ef30b15592a1","name":"Impulsos nerviosos"}]},{"id":"2b22e3b8-1d43-4c62-afe4-7d03f981f2c6","name":"Sistema y mecanismo","subthemes":[{"id":"a5a73092-8dc2-4978-8557-dcb977ec959a","name":"Sistema excretor, nervioso y reproductor"},{"id":"90f5745c-e518-4ced-963b-0c291ce2f57e","name":"Ciclo de vida"}]},{"id":"ec0f366c-ff6e-4c2b-83b4-13f12c93f5a0","name":"Salud","subthemes":[{"id":"379f7a15-ebf8-4998-a5bf-4cefa2bb6e08","name":"Enfermedades transmitidas por vectores"},{"id":"ca646652-322f-4bb2-bab0-ed0d0913eb4c","name":"Usos medicinales de las plantas"}]}],"grade_levels":["3ro"],"subjectId":"naturales","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"cf48a592-9488-4df7-9f92-65d068d66ad3-block-1","themes":["Materia y sus propiedades","Energía y conservación","Interacción y movimiento","Sistema y mecanismo","Salud"],"conceptual":"\"Ciencias de la Vida\"\n \n\"Conceptos\"\n \n\"Materia y sus propiedades \"\n \n- Seres vivos (plantas y animales).\n \n\"Energía y conservación.\"\n \n- Nutrición: nutrientes.\n-\tCadena alimenticia.\n \n\"Interacción y movimiento\" \n- Impulsos nerviosos.\n \n\"Sistema y mecanismo\"\n-\tSistema excretor, nervioso y reproductor.\n-\tCiclo de vida.\n \n\"Salud\"\n-\tEnfermedades transmitidas por vectores.\n-\tUsos medicinales de las plantas.\n ","procedural":"\"Ciencias de la Vida\"\n \n-\tExploración, identificación y descripción de características y funciones que realizan las plantas, y su relación con otros seres vivos. Comunicación de los resultados, utilizando diversos recursos del medio.\n \n-\tComparación, clasificación y descripción de la forma de alimentación de los seres vivos de su entorno. Elaboración de la cadena de alimentos. Comunicación de los resultados de sus indagaciones.\n \n-\tExperimentación (guiada): las plantas necesitan luz, aire, suelo y agua para producir alimentos. Procedimiento: observación, descripción, comparación, utilización de instrumentos de medida y comunicación de los resultados apoyándose en el uso de diferentes recursos.\n \n-\tIndagación en fuentes variadas, descripción y discusión para explicar sobre las funciones de las plantas como productoras de alimentos. \n \nComunicación de los resultados utilizando diferentes formas y recursos.\n \n-\tExperimentación (guiada): relación entre las semillas y las plantas. Procedimiento: observación, comparación, registro, discusión, análisis y descripción de cada paso del experimento. Comunica sus resultados utilizando diferentes herramientas.\n \n-\tIndagación en diversas fuentes sobre la transmisión del impulso nervioso y su función en los organismos. Procedimiento: discusión, descripción y comunicación de forma oral, escrita o por medio de dibujos.\n \n-\tComparación entre los órganos masculino y femenino, discusión y descripción de las funciones que realizan estos sistemas. Utilización de diferentes herramientas para expresar las informaciones.\n \n-\tIndagación acerca de los tipos de reproducción de los seres vivos.\n \n-\tComunicación a través de diversos medios de sus resultados.\n \n-\tExperimentación (guiada) con plantas y animales del entorno: \nnacimiento, desarrollo y crecimiento. Procedimiento: observación, descripción, comparación, utilización de instrumentos de medida y comunicación de los resultados.\n \n-\tObservación del ciclo de vida de las plantas, los animales y los seres humanos, haciendo comparaciones de las distintas fases. Procedimiento: discusión, descripción y comunicación de resultados.\n \n-\tIndagación, análisis, discusión, descripción y comunicación acerca de síntomas de enfermedades causadas por vectores.\n \n-\tIndagación acerca de plantas utilizadas en la elaboración de medicamentos, comunicando los hallazgos y validando las fuentes de información.\n \n-\tExploración del entorno para conocer plantas medicinales utilizadas para prevenir o curar enfermedades. Comunicación de las observaciones.\n \n ","attitudinal":"-\tDemostración de curiosidad, objetividad, creatividad; interés por la comunicación de sus ideas, seguimiento de procedimientos, el trabajo individual y colaborativo, cuidado de su salud, y el medioambiente; respeto a las ideas y diferencias de las demás personas, y utilización sostenible de los recursos de que dispone.\n \n-\tAdopción de medidas de cuidado y prevención de enfermedades \n(malaria, dengue, cólera, chikungunya, sarampión, varicela, zika, coronavirus, entre otras) y accidentes caseros.\n \n-\tAplicación de medidas higiénicas para prevenir enfermedades de los sistemas excretor, reproductor y nervioso.\n \n-\tAplicación de medidas de cuidado \nal utilizar los recursos naturales y tecnológicos.\n \n-\tAdopción de medidas para la protección de plantas y animales.\n \n-\tValoración del trabajo que realizan docentes y científicos de la República Dominicana.\n-\tAdopción de medidas de cuidado por su salud y el Medioambiente, \n \nRespeto a las ideas y diferencias de las demás personas, solidaridad y utilización sostenible de los recursos de que dispone. Reducción, recurso y reciclaje de materiales.\n \n "}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:20:36.184Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('bfabc49c-9ada-4efb-b770-2160faa768c5', 'naturales', '3ro', '{"id":"bfabc49c-9ada-4efb-b770-2160faa768c5","name":"Ciencias físicas","themes":[{"id":"e9541b69-b4e8-4a07-8bfd-791b8106ba03","name":"Materia y sus propiedades","subthemes":[{"id":"b6919bfa-5689-43f7-965f-81775402c4a3","name":"Masa, peso, volumen y densidad"},{"id":"7f264f15-9a34-4d24-9b9f-f3c601d55f85","name":"Cambios de estado de la materia (evaporación y condensación)"},{"id":"c6f7d516-77c3-4e88-a7b1-4dc011371af6","name":"Mezclas en medios líquido, sólido y gaseoso"},{"id":"41588da5-51a0-4220-a8f4-5337b1960390","name":"Ondas (reflexión y refracción)"},{"id":"d946a615-3db8-43bb-bece-234ec65b4821","name":"Imanes"}]},{"id":"093ac3ec-53cf-4c74-bfbf-c53a52c2cdb0","name":"Interacción y movimiento","subthemes":[{"id":"cafde072-8dfa-4a2c-b081-b978d8b57ec8","name":"Fuerzas de contacto y a distancia"},{"id":"ba449d18-7e06-4ec0-996b-c54428e96d10","name":"Trayectoria, rapidez y dirección"}]},{"id":"b73355e9-1fd8-4c90-8c40-1643d764b89b","name":"Energía y conservación","subthemes":[{"id":"7c3d15f4-9668-41c3-9fab-b52f60e635fb","name":"Formas de energía (mecánica, lumínica, sonora, térmica, química)"},{"id":"04239c17-bf17-4daa-bef0-e047f2ca3d2c","name":"Eficiencias en algunas formas de energía"}]},{"id":"43d93dad-1110-456c-a522-4cfaf5632634","name":"Sistema y mecanismo","subthemes":[{"id":"c09a2df2-d9dd-428f-9410-2e7bb0fba800","name":"Máquinas manuales"},{"id":"682d27cd-43ae-4631-b721-d1a8bd7a801e","name":"Estructuras arquitectónicas (edificios públicos)"},{"id":"d9055549-cd24-41e6-af65-7e1696706783","name":"Tecnología de la comunicación (aparatos electrónicos)"},{"id":"a59ce329-6439-4eaf-9c97-73000a39978a","name":"Tecnología en la agricultura"}]}],"grade_levels":["3ro"],"subjectId":"naturales","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"bfabc49c-9ada-4efb-b770-2160faa768c5-block-1","themes":["Materia y sus propiedades","Interacción y movimiento","Energía y conservación","Sistema y mecanismo"],"conceptual":"\"Ciencias físicas\"\n \nConceptos\n\"Materia y sus propiedades\"\n-\tMasa, peso, volumen y densidad.\n-\tCambios de estado de la materia (evaporación y condensación).\n-\tMezclas en medios líquido, sólido y gaseoso.\n-\tOndas (reflexión y refracción).\n-\tImanes.\n \n\"Interacción y movimiento\"\n-\tFuerzas de contacto y a distancia.\n-\tTrayectoria, rapidez y dirección.\n \n\"Energía y conservación.\"\n-\tFormas de energía (mecánica, lumínica, sonora, térmica, química).\n-\tEficiencias en algunas formas de energía.\n \n\"Sistema y mecanismo - Máquinas manuales.\"\n-\tEstructuras arquitectónicas (edificios públicos).\n-\tTecnología de la comunicación (aparatos electrónicos).\n-\tTecnología en la agricultura.\n ","procedural":"\"Ciencias físicas\"\n \n-\tComunicación sobre la posición: ubicación de direcciones utilizando algún criterio de localización o un punto de referencia (una brújula, GPS, puntos cardinales). Procedimiento: observación, comparación, clasificación, evaluación, croquis, dibujos y comunicación en forma oral y escrita.\n \n-\tIdentificación de distintas formas de energía: mecánica, eléctrica, luminosa, sonora, térmica y química. Procedimiento: observación, recolección de información, comparación, descripción y registro de información en su cuaderno.\n \n-\tUtilización de máquinas manuales de uso común. Procedimiento: exploración, utilización de instrumentos, construcción de herramientas, registro de información en su cuaderno, dibujos y conclusiones.\n \n-\tUtilización de aparatos electrónicos: computadoras, tabletas, relojes, dispositivos inteligentes. Procedimiento: exploración, elaboración de preguntas, descripción, comunicación en forma oral y escrita.\n \n-\tDescripción de estructuras, ubicación y función de edificios públicos (escuelas, hospitales, iglesias, destacamentos policiales, alcaldía) Procedimiento: observación, comparación, clasificación, descripción, dibujo, modelos con masillas y croquis.\n \n-\tExploración acerca de la producción agrícola y la tecnología de algunos alimentos comunes y de la región. Procedimiento: identificación del problema (exploración, observación, preguntas), comparación, clasificación y descripción. Comunicación oral y escrita por medio de cuentos, anécdotas, registro en el cuaderno.\n \n \n\"Ciencias de la tierra y el universo\"\n \n-\tRecolección, observación y descripción de las características físicas de diferentes rocas, y vinculación de estas con su entorno.\n \n-\tDescripción del movimiento de la corteza terrestre (terremoto y maremoto). Exposición utilizando diferentes herramientas para registro de informaciones (diagramas, gráficos, notas).\n \n-\tObservación, descripción y comparación sobre el movimiento de rotación de la Tierra: el día y la noche. Exposición utilizando distintos medios.\n \n-\tObservación de la Luna y sus fases. Procedimiento: registro de observación, comparación entre las fases, comunicación y organización de su resultado a partir de observación de las fases de la luna durante algunos meses.\n \n-\tAnálisis, descripción y discusión sobre desastres naturales: inundaciones de agua y lodo, derrumbes (deslizamientos), aludes, aluviones, sequías. Relación con experiencias conocidas y exposición por medio de narraciones.\n \n-\tObservación, descripción y comparación sobre la relación entre el Sol, la Tierra y la Luna. Exposición por medio de narraciones y dibujos.\n \n-\tAnálisis y discusión usando diferentes herramientas para exponer las informaciones sobre cómo los océanos y las montañas afectan el clima.\n \n-\tAnálisis, discusión y organización de informaciones sobre el clima en los polos, el ecuador, las montañas y las costas.\n \n ","attitudinal":"-\tDemostración de interés por conocer sobre sí mismo; por experimentar y descubrir características y causas del movimiento; por utilizar herramientas,  construir y jugar con máquinas manuales y modelar estructuras.\n \n-\tMotivación por aprender cosas nuevas de objetos y fenómenos.\n \n-\tAdopción de medidas de cuidado, protección y prevención respecto \na objetos, materiales, fenómenos o acciones que puedan afectar sus órganos o salud.\n \n-\tMotivación en aplicar medidas de cuidado en el uso sostenible de los recursos tecnológicos.\n \n-\tMotivación e interés por conocer sobre los avances científicos y tecnológicos y su impacto en la sociedad y el medioambiente.\n \n-\tManifestación de interés por seguir instrucciones de seguridad y cuidado ante la manifestación de riesgos asociados a fenómenos naturales \n(terremoto y maremoto).\n \n-\tValoración del suelo y sus minerales.\n-\tMotivación e interés en buscar la \nexplicación científica de fenómenos naturales y de las implicaciones biológicas, físicas y sociales de su ocurrencia.\n \n-\tApreciación y disfrute del conocimiento que obtiene con respecto a las características del suelo y el clima de la República Dominicana.\n \n-\tConservación de rótulos, materiales e instrumentos dirigidos a la prevención y seguridad ante la ocurrencia de fenómenos y desastres naturales.\n "}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:20:36.184Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('f4a9175f-44d9-45db-9936-f7c64de6e56e', 'sociales', '3ro', '{"id":"f4a9175f-44d9-45db-9936-f7c64de6e56e","name":"El planeta Tierra y sus componentes","themes":[{"id":"69a9de83-afae-46ca-bc1c-550b4ac916d3","name":"Representación de la Tierra","subthemes":[{"id":"407c4665-45f4-409d-87ae-dec3e74479e8","name":"El globo terráqueo y sus partes"},{"id":"1ed2d310-d160-4f5a-a34d-e8ebb8212df8","name":"El globo terráqueo y sus partes"},{"id":"8e7d7974-8b53-499f-be26-d3d5e79fd7ec","name":"Los mapas y para qué sirven"}]},{"id":"79fce1f8-cca5-4f81-a510-ae5f9124a9d6","name":"Componentes de la superficie del Planeta: oceánicos y terrestres","subthemes":[{"id":"ffea6a3f-b02b-495c-9899-703dac9ce08f","name":"Superficie terrestre: continentes y tierras emergidas"},{"id":"143a4c71-c8f3-454a-9b89-29ab599aa3fc","name":"Superficie oceánica: mares y océanos"},{"id":"42213abb-2fd9-49b0-8dd1-4f4bb4a3358d","name":"Importancia del agua y la tierra para la vida"}]},{"id":"165413af-906c-4ede-82c9-f8f261fea6a4","name":"Las Antillas Mayores y Menores","subthemes":[{"id":"e0f51990-fe06-47cb-9cc5-3e8a9a43bf09","name":"Qué son las Antillas y dónde se ubican"},{"id":"6e360c62-1481-4e98-8045-77b9fab7e22e","name":"Las Antillas Mayores y sus países"},{"id":"9b9e37a5-5ad1-45f0-8fb4-70d0630bfb6b","name":"Las Antillas Menores y sus características"}]},{"id":"4e08767b-91af-447d-896f-dbb14bb899de","name":"Región, provincia, municipio, sección y paraje","subthemes":[{"id":"9e48b83c-020a-48cd-9ca6-7d6596d998e2","name":"División político-administrativa de la República Dominicana"},{"id":"6a01bd0d-9dfe-4d43-9124-4bb7537de574","name":"Sección y paraje como espacios cercanos a la comunidad"},{"id":"c1cfd528-fcb4-414c-a6f7-32119780b022","name":"Diferencias entre región, provincia y municipio"}]}],"grade_levels":["3ro"],"subjectId":"sociales","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"f4a9175f-44d9-45db-9936-f7c64de6e56e-block-1","themes":["Representación de la Tierra","Componentes de la superficie del Planeta: oceánicos y terrestres","Las Antillas Mayores y Menores","Región, provincia, municipio, sección y paraje"],"conceptual":"\"El planeta Tierra y sus componentes:\"\n \n-\tRepresentación de la Tierra.\n-\tComponentes de la superficie del Planeta: oceánicos y terrestres.\n-\tLas Antillas Mayores y Menores.\n-\tRegión, provincia, municipio, sección y paraje.\n ","procedural":"\"Observación de las diferentes formas de representar la Tierra (globo terráqueo, mapas, planos, fotografías satelitales).\"\n \n-\tComparación de los diferentes tipos de mapas y planos: físicos y políticos.\n-\tIdentificación de los componentes de la tierra: océanos, mares, continentes, islas y archipiélagos, en el globo terráqueo y/o mapamundi. Diferenciación entre estos elementos.\n-\tIndagación en diferentes fuentes y lectura del significado de los conceptos geográficos: bahía, península, río, lago, laguna, montaña, sierra, cordillera, valle y llanura.\n-\tUbicación de las Antillas Mayores y Menores en el mapa, conocimiento de sus nombres y posición relativa con respecto a la isla de Santo Domingo, en función de los puntos cardinales.\n-\tDibujo del mapa de la isla de Santo Domingo (la República Dominicana y Haití) y su localización en el conjunto de las Antillas y la región del Caribe.\n-\tIdentificación en el mapa de las principales regiones que tiene la República Dominicana.\n-\tIdentificación de las principales provincias de la región en que vive, señalando las más cercanas a la suya.\n-\tDescripción de cómo las actividades humanas en su región, comunidad y municipio han afectado el espacio geográfico natural.\n-\tUbicación de su municipio en el mapa, identificando a qué provincia y región pertenece.\n ","attitudinal":"-\tRespeto por las fuentes de información que utiliza.\n-\tValoración de la importancia de los mapas en la localización de fenómenos y hechos.\n-\tRespeto por sus raíces culturales.\n-\tInterés por conocer las festividades culturales de su comunidad.\n-\tReflexión sobre las influencias de otras culturas en su comunidad o región.\n-\tCompresión sobre la similitud y diferencia entre las transiciones culturales de los pueblos del Caribe como parte de su diversidad social.\n-\tValoración e identificación con diversos personajes destacados del país.\n-\tAprecio de los lugares naturales de su comunidad y procura su cuidado y conservación.\n "}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:20:36.184Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('65d53ffa-82fc-4916-b2ee-e841b68db4e2', 'sociales', '3ro', '{"id":"65d53ffa-82fc-4916-b2ee-e841b68db4e2","name":"Zona rural y urbana","themes":[{"id":"ba84eb0b-6726-4260-8d81-13da16c3ea86","name":"El campo, pueblo, ciudad y modos de vida de sus pobladores.","subthemes":[{"id":"e2892ef1-0862-460c-b76e-bffe086d4eaf","name":"Características del campo, el pueblo y la ciudad"},{"id":"b59fa45d-325e-442c-8701-73a9df9a5070","name":"Actividades y trabajos de sus pobladores"},{"id":"e01d9523-6fbb-4924-bd43-8c03f70d72e5","name":"Formas de vida y costumbres en cada lugar"},{"id":"6bb8bed2-5743-4f95-8e92-853a764c3d35","name":"Semejanzas y diferencias entre campo, pueblo y ciudad"}]}],"grade_levels":["3ro"],"subjectId":"sociales","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"65d53ffa-82fc-4916-b2ee-e841b68db4e2-block-1","themes":["El campo, pueblo, ciudad y modos de vida de sus pobladores."],"conceptual":"\"Zona rural y urbana\"\n \n- El campo, pueblo, ciudad y modos de vida de sus pobladores.\n ","procedural":"\"Indagación sobre el modo de vida en el campo y en la ciudad\"\n \n-\tIdentificación de las características de los campos, pueblos y ciudades, reconociendo las similitudes y diferencias entre ellos.\n-\tDescripción de las actividades productivas, costumbres alimenticias, medios de transporte y formas de recreación más comunes en su comunidad, enmarcadas en la provincia o región en que vive.\n-\tReflexión acerca del presupuesto familiar elaborado por sus padres.\n-\tIdentificación de problemáticas sociales y/o naturales de las regiones.\n-\tConversación sobre qué es una zona rural y cómo eran los campos del país, y por qué hoy hay más personas en las ciudades que en los campos.\n-\tIdentificación de algunas problemáticas de la zona urbana donde está ubicada la escuela.\n ","attitudinal":"-\tValoración de la importancia del campo, el pueblo, la ciudad y el país.\n-\tValoración y cuidado de la naturaleza.\n-\tSensibilidad ante las distintas problemáticas, sociales y naturales de su región.\n-\tColaboración activa en trabajos de equipo para la resolución problemas en la zona donde está ubicada la escuela.\n "}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:20:36.184Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('70eff0da-a3cc-42dc-962f-17028134915f', 'sociales', '3ro', '{"id":"70eff0da-a3cc-42dc-962f-17028134915f","name":"Procedencia familiar","themes":[{"id":"d2b7f475-d7af-40ab-a317-5dcea15f9ed9","name":"Migración","subthemes":[{"id":"d38c0065-711a-4cc5-a19d-7c78698be1a6","name":"Qué es la migración"},{"id":"ae5a84f5-a74f-472c-acba-62a8159b44c3","name":"Razones por las que las personas migran"},{"id":"0c6c9d33-ff10-4796-ad05-11c4eae305d8","name":"Migración interna y migración externa"},{"id":"41ba36ec-a090-48a3-8e95-e48c0ad28fa8","name":"Cambios que produce la migración en las personas y las comunidades"}]}],"grade_levels":["3ro"],"subjectId":"sociales","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"70eff0da-a3cc-42dc-962f-17028134915f-block-1","themes":["Migración"],"conceptual":"\"Procedencia familiar.\"\n Migración\n ","procedural":"\"Investigación acerca de la procedencia de su familia.\"\n \n-\tInvestigación sobre los lugares de procedencia de los y las integrantes de su familia y algunas costumbres de sus antepasados.\n-\tElaboración de historietas sobre su historia familiar, utilizando globos y otras formas. Teniendo en cuenta un inicio, desarrollo y cierre.\n-\tIdentificación en un mapa de las provincias y regiones de procedencia de algunos/as de sus familiares.\n-\tLectura y discusión en las que se argumente sobre los motivos por los que suceden las migraciones internas y externas.\n-\tLectura sobre el presupuesto familiar elaborado por la familia.\n ","attitudinal":"-\tValoración de los lugares de procedencia y costumbres de su familia.\n-\tAprecio por la historia de su familia.\n-\tSensibilidad ante los distintos motivos que llevan a las personas a migrar interna y externamente.\n "}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:20:36.184Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('a296f6bd-764b-4fba-819d-42462c09c54c', 'sociales', '3ro', '{"id":"a296f6bd-764b-4fba-819d-42462c09c54c","name":"Acontecimientos históricos que caracterizan su municipio, provincia, región y país","themes":[{"id":"8e6faa53-f797-4e01-9014-a4b001e0f348","name":"Hechos históricos importantes de su municipio","subthemes":[{"id":"03f2ff88-43c2-4fe3-87eb-a8594007093e","name":"Origen y fundación del municipio"},{"id":"21793acc-43d8-45c7-9af0-6fc976706dad","name":"Personajes históricos importantes del municipio"},{"id":"30be5c1e-3353-45df-bca9-20ea5e6fd711","name":"Hechos relevantes que marcaron su historia local"}]},{"id":"9e9109ee-097e-4b1b-afa9-b42724403364","name":"Acontecimientos relevantes de su provincia","subthemes":[{"id":"61f35b35-628a-44bc-b48c-b7f4225f4c8c","name":"Fundación y desarrollo de la provincia"},{"id":"99af847f-7771-40f2-b6aa-7f1dedd510ab","name":"Hechos históricos importantes ocurridos en la provincia"},{"id":"6e95951d-2880-4d43-a36e-761eebd70f14","name":"Aportes de la provincia a la historia nacional"}]},{"id":"dc713b73-9a0f-4b53-87fb-aacd03ceaaa8","name":"Sucesos históricos que marcaron su región","subthemes":[{"id":"99e89c68-90ad-4924-a061-598f5f157080","name":"Principales hechos históricos de la región"},{"id":"360aa974-280a-41e3-b216-81a25e2dc746","name":"Actividades económicas y sociales históricas de la región"},{"id":"483642ca-23ea-405c-b0b7-d910080edbc8","name":"Importancia histórica de la región para el país"}]},{"id":"20b5c960-405b-4548-904b-5721cbebc11d","name":"Acontecimientos históricos importantes de la República Dominicana","subthemes":[{"id":"87b58d02-04ee-42c5-9459-7f604278138f","name":"Hechos históricos más importantes de la República Dominicana"},{"id":"1f806a81-2be2-4fff-bf67-310bf5f78d29","name":"Personajes históricos nacionales destacados"},{"id":"9285313d-b84e-4f59-915a-6fdeefea6c88","name":"Importancia de los acontecimientos históricos para la identidad nacional"}]},{"id":"33a28f9b-9b48-4f80-a15e-58c372a8bd3b","name":"Héroes de la independencia","subthemes":[{"id":"d1b93026-289f-46f7-a986-71c3b8326563","name":"Matías Ramón Mella y su valentía"},{"id":"9bc0bdc7-0772-4ad9-9172-c49bb54c2361","name":"La bandera que representa nuestra libertad"},{"id":"f3c64c32-7f87-469d-886e-cc5d1adad994","name":"Juan Pablo Duarte, el líder"},{"id":"57c06b8b-f28c-4e9a-8261-6e93eef67cdb","name":"Francisco del Rosario Sánchez, el estratega"}]}],"grade_levels":["3ro"],"subjectId":"sociales","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"a296f6bd-764b-4fba-819d-42462c09c54c-block-1","themes":["Hechos históricos importantes de su municipio","Acontecimientos relevantes de su provincia","Sucesos históricos que marcaron su región","Acontecimientos históricos importantes de la República Dominicana","Héroes de la independencia"],"conceptual":"\"Acontecimientos históricos que caracterizan su municipio, provincia, región y país\"","procedural":"-\tIndagación en diversas fuentes sobre la historia de su municipio y provincia.\n \n\"Investigación sobre acontecimientos históricos que ocurrieron en su municipio, provincia, región y país.\n-\tElaboración de periódicos escolares y ¨panfletos¨ sobre la participación de su municipio en acontecimientos históricos del país.\"\n \n-\tElaboración de líneas de tiempo sobre acontecimientos históricos de su municipio, provincia y región.\n ","attitudinal":"-\tInterés por la historia de su municipio y su provincia.\n-\tValoración de los acontecimientos históricos de su región y el país.\n-\tCuriosidad por conocer sobre la participación de su municipio en acontecimientos históricos del país.\n "}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:20:36.184Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('c4ac44ab-4902-4845-bc90-5a27ab0b60af', 'educacion-fisica', '3ro', '{"id":"c4ac44ab-4902-4845-bc90-5a27ab0b60af","name":"Conceptos de unidad","themes":[{"id":"cb29d8d5-5b48-41e8-b73a-d4434f04bbfd","name":"Esquema corporal.","subthemes":[{"id":"46971b5e-9f9d-4e4a-922e-24a56149bce2","name":"Reconocimiento de las partes del cuerpo."},{"id":"da728e16-0355-4170-bfe0-e9e8e39bd985","name":"Control del cuerpo en movimiento y en reposo."},{"id":"9d2a958d-5fb6-4d10-b439-996f834bb0eb","name":"Conciencia y cuidado del propio cuerpo."}]},{"id":"73665f61-cbb8-40f8-89ff-cdb5d4a97f95","name":"Relaciones espaciales (dirección, orientación y simetrías), relaciones temporales (velocidad, ritmo, duración y secuencia).","subthemes":[{"id":"0a8ae201-4bcd-4df9-bab8-4f3ad2fef3c0","name":"Dirección y orientación del movimiento."},{"id":"fa0baec2-8b23-4d38-b9c3-9bae23c91400","name":"Ritmo, velocidad y duración de las acciones."},{"id":"edbcc5b4-347d-46d7-bcee-22ce6716ba82","name":"Ritmo, velocidad y duración de las acciones."}]},{"id":"4ae24e86-4512-45b8-a4e7-69b8d4b5edde","name":"El cuerpo como medio de comunicación y expresión","subthemes":[{"id":"a64e784d-f125-4d87-8c08-92b3de26ed0e","name":"Expresión de emociones con el cuerpo."},{"id":"d8850203-40b4-407c-9352-04cd5e648105","name":"Comunicación corporal sin palabras."},{"id":"0f696cdd-03fb-4c49-ad08-acaa010b5f93","name":"Representación de ideas mediante movimientos."}]},{"id":"6d7da281-6fc1-4475-8873-e224cdc896a6","name":"Gesto, movimiento, mímica, expresión corporal. Ritmo y movimiento (pulso, acento, compás).","subthemes":[{"id":"7fd6aa11-d5bd-4be3-8534-964fc96c7edd","name":"Uso del gesto y la mímica para expresarse."},{"id":"efd30687-df42-4333-bd50-cfa31aa9a675","name":"Movimiento corporal siguiendo el ritmo."},{"id":"af162405-5195-40c8-870c-d2738a379eeb","name":"Coordinación del cuerpo con pulso y compás."}]},{"id":"441ec254-9f53-4b5d-8159-1dedbd1c5936","name":"Juegos motores y sensoriales","subthemes":[{"id":"495e78cc-5403-47e0-ab7b-c1819ad5ed75","name":"Juegos que estimulan el movimiento corporal."},{"id":"6f103c8e-b672-4395-af16-5215d1d1d2e4","name":"Juegos para desarrollar los sentidos."},{"id":"df50eebf-5648-4416-a9c5-78895b850179","name":"Exploración del cuerpo a través del juego."}]},{"id":"287aaf52-0275-4114-b8a5-e54c36a04e29","name":"Juegos populares y tradicionales.","subthemes":[{"id":"336d23f6-9a60-43af-a86a-3ac37f187cf5","name":"Conocimiento de juegos tradicionales."},{"id":"e0863e43-8b9d-4b3c-9204-ee48e716304d","name":"Participación en juegos populares."},{"id":"b8b39bae-ab47-4039-83bc-a095efcf6f43","name":"Valor cultural y social de los juegos."}]},{"id":"f2d98403-274a-48e6-a8db-7ec6dd3b4ca4","name":"Habilidades motrices básicas (caminar, correr, saltar, rodar, esquivar, caer, trepar, subir, bajar, lanzar, golpear, atrapar, entre otras.","subthemes":[{"id":"870e21e1-f68b-4a3d-966d-9fde83872261","name":"Desplazamientos básicos (caminar, correr, saltar)."},{"id":"d88a2d1c-45f4-43b5-b0d3-b04ba253b43c","name":"Manipulación de objetos (lanzar, atrapar, golpear)."},{"id":"1eb62481-7e43-4e0f-837e-b98adad68755","name":"Movimientos de equilibrio y coordinación."}]},{"id":"43097844-4228-4ee1-a0dd-e8faa4271130","name":"Capacidades físicas (flexibilidad, velocidad de reacción).","subthemes":[{"id":"56c4ec2b-7cfd-4da8-956f-b6ccf218558e","name":"Ejercicios de flexibilidad corporal."},{"id":"5b405582-8ec8-4795-890a-4db277c7ba50","name":"Actividades para mejorar la velocidad de reacción."},{"id":"847ce202-d682-4c5c-b8c8-2aced72c4f14","name":"Importancia del ejercicio para el desarrollo físico."}]},{"id":"7a075920-a427-4b09-8814-2f46ab56ef50","name":"Ubicación espacio-temporal-objetual","subthemes":[{"id":"94710263-9ce4-4b2e-bde8-28fa1326d682","name":"Ubicación del cuerpo en el espacio."},{"id":"98898356-9457-488c-b65d-d7cabf9fde15","name":"Relación del cuerpo con objetos."},{"id":"d730889d-1a2d-4691-ada7-d8e4ac9c49d2","name":"Desplazamientos según consignas de tiempo."}]}],"grade_levels":["3ro"],"subjectId":"educacion-fisica","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"c4ac44ab-4902-4845-bc90-5a27ab0b60af-block-1","themes":["Esquema corporal.","Relaciones espaciales (dirección, orientación y simetrías), relaciones temporales (velocidad, ritmo, duración y secuencia).","El cuerpo como medio de comunicación y expresión","Gesto, movimiento, mímica, expresión corporal. Ritmo y movimiento (pulso, acento, compás).","Juegos motores y sensoriales","Juegos populares y tradicionales.","Habilidades motrices básicas (caminar, correr, saltar, rodar, esquivar, caer, trepar, subir, bajar, lanzar, golpear, atrapar, entre otras.","Capacidades físicas (flexibilidad, velocidad de reacción).","Ubicación espacio-temporal-objetual"],"conceptual":"-\tEsquema corporal.\n-\tUbicación espacio\n-\t- temporal objetar. \n-\tRelaciones espaciales (dirección, orientación y simetrías), relaciones temporales (velocidad, ritmo, duración y secuencia).\n-\tEl cuerpo como medio de comunicación y expresión.\n-\tGesto, movimiento, mímica, expresión corporal. Ritmo y movimiento (pulso, acento, compás).\n-\tJuegos motores y sensoriales.\n-\tJuegos populares y tradicionales.\n-\tHabilidades motrices básicas (caminar, correr, saltar, rodar, esquivar, caer, trepar, subir, bajar, lanzar, golpear, atrapar, entre otras).\n-\tCapacidades físicas (flexibilidad, velocidad de reacción).\n ","procedural":"-\tExperimentación y uso de las habilidades motrices básicas en distintas situaciones motrices.\n-\tParticipación en juegos populares, tradicionales y sensoriales.\n-\tRepresentación a través del movimiento de situaciones de la vida cotidiana.\n-\tExperimentación de diferentes formas de ejecución y control de las habilidades motrices básicas.\n-\tTensión y relajación con los segmentos corporales que integran su cuerpo.\n-\tDesplazamiento en diferentes posiciones, direcciones y ritmos.\n-\tRealización de movimientos con ritmo progresivamente acelerado y desacelerado.\n-\tMovimiento y exploración de objetos de diferentes tamaños, formas, texturas, pesos y consistencias.\n-\tEjecución de series y secuencias de ejercicios para la movilización de los diferentes segmentos corporales con y sin implementos.\n-\tExperimentación y uso de las habilidades motrices básicas en distintas situaciones motrices.\n-\tIdentificación y práctica de normas de higiene y salud.\n ","attitudinal":"-\tValoración y disfrute de participar en juegos con sus compañeros y compañeras.\n-\tAceptación de distintos roles en el juego.\n-\tCompresión y cumplimiento de las normas de juego.\n-\tConfianza en las propias posibilidades y el esfuerzo personal.\n-\tValoración del juego como medio de \ndisfrute y de relación con las demás personas.\n-\tDefensa y respeto por su derecho y el de los y las demás de jugar y realizar actividad física.\n-\tReconocimiento de la importancia de la realización de actividades físicas para su bienestar y la conservación de la salud.\n-\tValoración de los juegos tradicionales y populares como parte de su identidad.\n "}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:20:36.184Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('6bcf1d75-63fc-49c6-a42b-1f17257854f0', 'sociales', '3ro', '{"id":"6bcf1d75-63fc-49c6-a42b-1f17257854f0","name":"Diversidad cultural","themes":[{"id":"f2dafec9-cdbe-4bdc-a82c-f9f555ea027c","name":"Conceptos de democracia:  Libertad, respeto, colaboración.","subthemes":[{"id":"d4740dcd-fc8f-4d9b-bbd2-fba6363b9d3d","name":"Qué es la democracia y cómo la vivimos en la escuela"},{"id":"7aa60717-80a7-49cc-8cb0-68f7a5bdeda2","name":"La libertad con responsabilidad"},{"id":"e8494f3e-6987-46d9-9b8a-05cebd985362","name":"El respeto y la colaboración para convivir mejor"}]},{"id":"0155ead4-8c84-4487-8a47-3c1932806386","name":"Derechos y deberes","subthemes":[{"id":"fba65a92-d54c-43fa-84aa-5766facf1c7f","name":"Derechos de los niños y las niñas"},{"id":"4b168d9a-3a78-47ad-adf3-2c47a4036d45","name":"Deberes en la familia, la escuela y la comunidad"},{"id":"1008df3b-4783-4159-9985-32a43db2c8ba","name":"Importancia de cumplir derechos y deberes"}]},{"id":"1cd8d81b-f9fe-46b2-9b9b-416c41b988c0","name":"Las leyes como normas de convivencia.","subthemes":[{"id":"545fc34c-f1b0-48fe-9627-593174b497f9","name":"Qué son las leyes"},{"id":"fcd5b11e-e27e-4188-9b74-7196d0d6a132","name":"Las leyes y las normas en la vida diaria"},{"id":"5d93a69d-9821-4b2b-98a2-d8b1433dc640","name":"Importancia de respetar las leyes para convivir en paz"}]},{"id":"042ac156-dcf3-4fe4-b716-3a059be97cd2","name":"Constitución dominicana","subthemes":[{"id":"b28eab56-e43c-4e11-9e49-b486b9502b1b","name":"Qué es la Constitución Dominicana"},{"id":"32972e05-e7b8-4d76-8310-3a589d5a123a","name":"Derechos que protege la Constitución"},{"id":"4ef7891c-2361-4f04-aafb-49810900be16","name":"Importancia de la Constitución para el país"}]},{"id":"efa72b4e-184e-41ef-a8fe-23eb4df06a51","name":"Valores","subthemes":[{"id":"5393d52d-3969-4eb6-af49-60d31d9e218d","name":"Valores para la convivencia (respeto, solidaridad, honestidad)"},{"id":"18469713-d046-4cb7-85c0-1d3817840fed","name":"Práctica de los valores en la vida diaria"},{"id":"76c639fb-0cba-4b46-82dc-743a64ca145a","name":"Importancia de los valores para una buena convivencia"}]}],"grade_levels":["3ro"],"subjectId":"sociales","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"6bcf1d75-63fc-49c6-a42b-1f17257854f0-block-1","themes":["Conceptos de democracia:  Libertad, respeto, colaboración.","Derechos y deberes","Las leyes como normas de convivencia.","Constitución dominicana","Valores"],"conceptual":"\"Diversidad cultural\"\n \n-\tConceptos de democracia: \nLibertad, respeto, colaboración.\n-\tDerechos y deberes.\n-\tLas leyes como normas de convivencia.\n-\tConstitución dominicana.\n-\t- Valores \n ","procedural":"-\tIdentificación de situaciones comunitarias en las que estén implicadas las normas de tránsito. \n-\tElaboración de proyectos sobre educación vial y normas de tránsito que involucren la escuela, la comunidad.\n-\tRealización de campañas que promueva los valores de justicia, equidad, igualdad.\n-\tExploración a través de entrevistas a sus padres, abuelos/as, etc., sobre cómo han cambiado algunas prácticas democráticas en el país (libertad de participar y comunicar, derecho al voto, respeto, entre otras).\n-\tExploración en diversas fuentes (Constitución Dominicana Infantil, impresa, material audiovisual para niños y niñas, entre otras) sobre sus derechos y deberes.\n-\tEscucha atenta de una situación problemática de la convivencia familiar, en el salón de clases o en la trama de un cuento, expresando su punto de vista y respetando el de los demás.\n-\tElaboración de material visual con normas de convivencia que considera que deben cumplirse en su familia, en la escuela y en el país.\n-\tDramatizaciones sobre actuaciones democráticas y no democráticas en la casa, escuela, comunidad, país.\n \n\"Análisis de la democracia en su familia y en el país, realizando comparaciones con prácticas del pasado:\"\n \n-\tRealización de murales sobre los derechos humanos.\n-\tLectura y discusión de cuentos relacionados con el tema de derechos, deberes y valores en contextos democráticos y no democráticos.\n-\tPresentación oral, escrita y con dibujos de prácticas democráticas en su contexto familiar.\n ","attitudinal":"-\tRespeto por los valores y las normas de convivencia de su entorno social cercano.\n-\tValoración de la democracia, reconociendo la importancia de la convivencia.\n-\tDefensa de las costumbres y festividades de su comunidad, del país y algunos países de las Antillas.\n-\tValoración de la diversidad cultural de la República Dominicana.\n-\tRespeto de las normas de tránsito en cualquier espacio.\n-\tPromoción de valores como la justicia, la equidad y la igualdad.\n-\tIntegración en campañas sobre educación vial en su comunidad.\n-\tRespeto a las normas de convivencia en cualquier espacio. \n-\tToma posición sobre actuaciones democráticas y no democráticas.\n "}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:20:36.184Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('caf51d7d-e4be-4ab6-a23c-746ce3bd6b43', 'sociales', '3ro', '{"id":"caf51d7d-e4be-4ab6-a23c-746ce3bd6b43","name":"Patrimonio histórico y natural","themes":[{"id":"00a5b8e5-d27c-42d5-af76-5ffc06acc2bc","name":"Patrimonio histórico y natural","subthemes":[{"id":"aab44f05-54d0-4e9a-8e4b-af335aa8072b","name":"Qué es el patrimonio histórico y natural"},{"id":"c703edf7-c763-47cb-8898-e0e2ee86a3da","name":"Ejemplos de patrimonio histórico y natural de la República Dominicana"},{"id":"b615e535-a311-4b55-ab6e-a142b382ec94","name":"Importancia de cuidar y conservar el patrimonio"}]},{"id":"51a66c4f-6271-4ec8-be87-66278c74f3e7","name":"Padres de la Patria y heroínas","subthemes":[{"id":"5b8f925f-9ef1-458f-9fad-973178e43eb9","name":"Quiénes fueron los Padres de la Patria"},{"id":"1965c27d-6169-4d16-9f9d-98a6b5dc701b","name":"Heroínas dominicanas y su aporte a la historia"},{"id":"e87ac67f-164d-4c39-9b52-e5fc39806325","name":"Valores que representaron los Padres de la Patria y heroínas"}]},{"id":"987c8b16-1078-42c9-9415-936c94aef33c","name":"Independencia Nacional y Restauración","subthemes":[{"id":"46049bf4-dae5-47ca-8e0b-500591472ef1","name":"La Independencia Nacional y sus principales hechos"},{"id":"a6d17858-9a8e-48a9-a882-1fb043c40a79","name":"La Restauración y su importancia histórica"},{"id":"20210003-8917-4586-b9a0-1854817c72cf","name":"Significado de estos procesos para la identidad nacional"}]},{"id":"25d0ed02-6b6d-41bd-a2bf-cea70cc179b6","name":"Símbolos patrios y sus componentes","subthemes":[{"id":"36c4f60c-3677-4ff5-aa98-9966d8c818aa","name":"La Bandera Nacional y su origen"},{"id":"a46fc8ef-3779-4e23-943a-92f1f8219c3b","name":"El Escudo Nacional y sus elementos"},{"id":"914012c0-974e-4ce9-89e3-024d29d61d66","name":"El Himno Nacional y su significado"}]}],"grade_levels":["3ro"],"subjectId":"sociales","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"caf51d7d-e4be-4ab6-a23c-746ce3bd6b43-block-1","themes":["Patrimonio histórico y natural","Padres de la Patria y heroínas","Independencia Nacional y Restauración","Símbolos patrios y sus componentes"],"conceptual":"\"Patrimonio histórico y natural.\"\n \n-\tPadres de la Patria y heroínas.\n-\tIndependencia Nacional y Restauración.\n-\tSímbolos patrios y sus componentes: la Bandera, el Escudo Nacional, el Himno, y los orígenes de estos.\n ","procedural":"\"Levantamiento en fuentes confiables de información sobre las costumbres de su comunidad y su relación con la cultura dominicana:\"\n \n-\tIndagación sobre las costumbres festivas de su comunidad (carnaval, patrias y mágico-Religiosos).\n-\tIdentificación de la diversidad cultural de la República Dominicana (comida, música, bailes) producto de las distintas migraciones.\n-\tAnálisis sobre la similitud y diferencias entre las costumbres, expresiones, artes y tradiciones culturales de los pueblos de las Antillas Mayores y Menores.\n-\tLectura sobre personajes dominicanos que han trascendido la vida nacional: deportes, música, salud, entre otros.\n-\tPresentación a través de dramatización, afiches y escritos de los aportes y procedencia de algunos personajes de su comunidad.\nCuidado del patrimonio histórico y natural de su región como deber ciudadano:\n-\tIdentificación mediante la observación de imágenes físicas o digitales, elementos del patrimonio natural, histórico y cultural del municipio, provincial y región.\n-\tElaboración de murales sobre el patrimonio histórico y natural de la sociedad dominicana.\n-\tPresentación de propuestas sencillas sobre el cuidado del patrimonio cultural de la República Dominicana.\n-\tElaboración de murales sobre el patrimonio histórico, natural y cultural de la sociedad dominicana.\n-\tPresentación de propuestas sencillas sobre el cuidado del patrimonio cultural de la República Dominicana.\n-\tReconocimiento de las hazañas principales de los Padres de la patria y las heroínas.\n-\tElaboración de acrósticos sobre héroes y heroínas.\n-\tReconocimiento de heroínas que aportaron a los símbolos patrios.\n-\tAnálisis de los eventos más significativos de la Independencia Nacional y la Restauración de la República Dominicana.\n-\tAnálisis de la importancia de la Bandera, el Escudo y el Himno Nacional.\n ","attitudinal":"-\tActitud de cuidado del patrimonio histórico y natural de República Dominicana. \n-\tConocimiento y respeto por los Padres de la Patria y las mujeres que lucharon junto a ellos.\n-\tDemostración de respeto por los Símbolos de la Patria.\n-\tInterés por soluciones democráticas ante cualquier situación.\n-\tPromoción y respeto de los símbolos patrios.\n "}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:20:36.184Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('15553a93-6d5f-4776-8023-0c47286c922e', 'educacion-artistica', '6to', '{"id":"15553a93-6d5f-4776-8023-0c47286c922e","name":"Educación musical","themes":[{"id":"407eef12-b880-458e-ad82-8adeabc555ab","name":"Técnica vocal para hablar y cantar / formas de habla regional","subthemes":[{"id":"4a80b8f4-b25d-4aeb-8a6b-4c7db9d37fe1","name":"Respiración y cuidado de la voz."},{"id":"764930b5-efc8-46d4-a9b1-caa688889b04","name":"Proyección vocal al hablar y cantar."},{"id":"3b11877f-a358-454d-8e36-f9d05a77c265","name":"Acentos y formas de habla en RD."}]},{"id":"e765a8b0-9ab5-4782-b3c1-262fc7d868d8","name":"Música folklórica dominicana","subthemes":[{"id":"e7b93153-fce6-4fcc-a097-63060523a2ae","name":"Función cultural y social."},{"id":"bf0a2790-7b21-448b-b017-e130608ec0f7","name":"Géneros folklóricos: merengue típico, palos, salves."},{"id":"0726c267-3a54-4e1e-bb37-d6a156618ca6","name":"Instrumentos tradicionales."}]},{"id":"b0326736-4cbb-44fd-a37a-98a198d821a4","name":"Géneros musicales populares","subthemes":[{"id":"3c61c286-f94e-4e8b-9be5-6bf610af8660","name":"Características básicas de cada género."},{"id":"ea103477-25a9-4035-9b35-07723d794534","name":"Influencia cultural y juvenil."},{"id":"0f916e7f-ae9f-49cb-bbfd-1474cbdffead","name":"Ritmos populares dominicanos y actuales."}]}],"grade_levels":["6to"],"subjectId":"educacion-artistica","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"15553a93-6d5f-4776-8023-0c47286c922e-block-1","themes":["Técnica vocal para hablar y cantar / formas de habla regional","Música folklórica dominicana","Géneros musicales populares"],"conceptual":"\"Educación Musical\"\n-\tTécnica vocal para hablar y cantar. Formas de habla de las diferentes regiones del país.\n-\tMúsica folklórica dominicana. Géneros.\n-\tGéneros musicales populares.\n ","procedural":"-\tEducación Musical\n-\tRespiración y técnica vocal para el canto coral.\n-\tInventario y clasificación de ritmos folklóricos dominicanos.\n-\tPráctica de géneros musicales, populares y regionales (vocales, corporales e instrumentales).\n ","attitudinal":"-\tDesarrollo de la interacción grupal y fomento de la imaginación creadora en producciones artísticas.\n-\tApertura a la diversidad de expresiones artísticas populares nacionales.\n "}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:20:36.184Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('35501711-ed99-4939-99b9-4bb14ad46bcb', 'educacion-fisica', '1ro', '{"id":"35501711-ed99-4939-99b9-4bb14ad46bcb","name":"Conceptos de unidad","themes":[{"id":"e0d4d5b5-48f7-40d8-bf55-0e77c9e98abc","name":"Ubicación espacio- temporal- objetual.","subthemes":[{"id":"435afa3b-8368-4324-837b-3383a6760bfc","name":"Reconocimiento del cuerpo en el espacio y el tiempo."},{"id":"74504244-ac15-48ad-ac83-7191217a59bc","name":"Ubicación de objetos en relación al propio cuerpo."},{"id":"3a89774e-11b6-4371-8acd-f6657ba13ef1","name":"Desplazamientos según consignas espaciales y temporales."}]},{"id":"ca3bac97-a938-4113-95c6-fee6bee80be8","name":"Relaciones espaciales (dirección, orientación y simetrías), relaciones temporales (velocidad, ritmo, duración y secuencia).","subthemes":[{"id":"dad3c478-0106-4c44-8e50-2b1ac48a5371","name":"Dirección y orientación en el espacio."},{"id":"7b143d7b-2667-4316-87d8-857359894fdf","name":"Ritmo, velocidad y duración del movimiento."},{"id":"40205185-dbd4-4945-8b5d-62d650292023","name":"Secuencia de acciones motrices."}]},{"id":"6b2accb8-c1f5-41f7-b7ad-3c4fd238efae","name":"El cuerpo como medio de comunicación y expresión","subthemes":[{"id":"00b450bb-9a01-42cb-ae01-bc1b6d9f6d40","name":"El cuerpo para expresar emociones."},{"id":"68f900bf-feef-4418-8b84-788ceb1ca0b4","name":"Comunicación corporal sin palabras."},{"id":"82ccd46b-b9d9-4c7e-8bee-5db36b26bc9e","name":"Expresión de ideas mediante movimientos."}]},{"id":"093de293-2e0d-44c7-97f4-cea1acc8515f","name":"Gesto, movimiento, mímica, expresión corporal. Ritmo y movimiento (pulso, acento, compás).","subthemes":[{"id":"cf300561-1763-447b-b0b2-79447adbd20d","name":"Uso del gesto y la mímica para representar acciones."},{"id":"a44c10fb-615e-4608-bb04-0fe2255361ed","name":"Movimiento corporal siguiendo el pulso y el ritmo."},{"id":"74f9f919-1bf8-456a-9ca5-cbd708e6e928","name":"Coordinación del cuerpo con música y sonidos."}]},{"id":"7a8bc349-c703-4246-81dd-eb727d550c8c","name":"Esquema corporal. El cuerpo: imagen y percepción.","subthemes":[{"id":"ac8da2a8-723c-45e2-8d7f-39222879ce4e","name":"Reconocimiento del propio cuerpo y sus partes."},{"id":"5cc95922-57b4-48e2-8749-ab09cf03f589","name":"Imagen corporal y percepción del movimiento."},{"id":"c4b984cc-4787-4680-a37f-fc032d11afad","name":"Control del cuerpo en diferentes posiciones."}]},{"id":"95d364db-43b0-4656-9224-8f3a0052f909","name":"Segmentos corporales, independencia segmentaria","subthemes":[{"id":"4bae96f7-b7d0-4de9-ab34-dc4dffad22f1","name":"Movimientos de brazos, piernas y tronco."},{"id":"7d7256f1-adf4-4368-a6f0-f5f067ebc2d5","name":"Coordinación de segmentos corporales."},{"id":"4dcba4cb-bfbe-4db8-b109-9a7ef7c526a2","name":"Control independiente de partes del cuerpo."}]},{"id":"ef16268d-ad25-4b69-bab7-b4550856b13f","name":"Lateralidad. Movimientos simétricos y asimétricos","subthemes":[{"id":"16f046da-3b77-4770-b045-cd2f1db80afc","name":"Dominancia derecha e izquierda."},{"id":"4eaae777-e92b-4210-af48-78ffe1a028c9","name":"Movimientos simétricos del cuerpo."},{"id":"df584122-3546-43b2-90fc-e85116e80de4","name":"Movimientos asimétricos y combinados."}]},{"id":"27b47419-d39a-4519-a4d5-87ddd1159aee","name":"Equilibrio dinámico y estático. Control postural, tono muscular, respiración y relajación","subthemes":[{"id":"0184cd07-1f0d-4a9c-8f3c-0d09d031fb29","name":"Equilibrio en posiciones fijas."},{"id":"7d364091-60a8-4dae-a832-1d2ce5f431a0","name":"Equilibrio durante el desplazamiento."},{"id":"6e97fd67-7743-4393-89f8-25958ba7220e","name":"Control del tono muscular y la postura."}]},{"id":"26ae37fc-718f-4fb8-8e77-5828103666bd","name":"Coordinación motriz.","subthemes":[{"id":"783bf14c-e96c-46af-96b2-c4313d8e5d40","name":"Coordinación general del cuerpo."},{"id":"9c841fe7-7ba2-4a05-ac1e-dee853766077","name":"Coordinación en juegos y desplazamientos."},{"id":"b0c11caf-e2f7-4c3e-9d34-821686937e12","name":"Coordinación en actividades con objetos."}]},{"id":"3e6b12dc-756e-4681-a89c-5531e9e27aeb","name":"Visomotora, gruesa, fina.","subthemes":[{"id":"0be01794-542d-49d8-9146-2ed79795dc64","name":"Coordinación ojo-mano y ojo-pie."},{"id":"2b6ff55f-d833-40c1-838a-7d1054d63a84","name":"Movimientos amplios (coordinación gruesa)."},{"id":"2373e4ab-d705-41d8-92f0-85801d2ca6a2","name":"Movimientos precisos (coordinación fina)."}]},{"id":"a8d52557-0544-4bbf-b571-2e3b384aa064","name":"Reglas de juego.","subthemes":[{"id":"f903352d-002b-4f18-89e2-303607dbd397","name":"Importancia de las reglas en los juegos."},{"id":"f8c07c87-46a5-4a1d-b4f4-c7e86d6ac48e","name":"Respeto a turnos y normas."},{"id":"7550f66b-ed38-49a2-bc65-7d6932b32b49","name":"Juego limpio y trabajo en equipo."}]}],"grade_levels":["1ro"],"subjectId":"educacion-fisica","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"35501711-ed99-4939-99b9-4bb14ad46bcb-block-1","themes":["Ubicación espacio- temporal- objetual.","Relaciones espaciales (dirección, orientación y simetrías), relaciones temporales (velocidad, ritmo, duración y secuencia).","El cuerpo como medio de comunicación y expresión","Gesto, movimiento, mímica, expresión corporal. Ritmo y movimiento (pulso, acento, compás).","Esquema corporal. El cuerpo: imagen y percepción.","Segmentos corporales, independencia segmentaria","Lateralidad. Movimientos simétricos y asimétricos","Equilibrio dinámico y estático. Control postural, tono muscular, respiración y relajación","Coordinación motriz.","Visomotora, gruesa, fina.","Reglas de juego."],"conceptual":"-\tUbicación espacio- temporal- objetual.\n-\tRelaciones espaciales (dirección, orientación y simetrías), relaciones temporales (velocidad, ritmo, duración y secuencia).\n-\tEl cuerpo como medio de comunicación y expresión.\n-\tGesto, movimiento, mímica, expresión corporal. Ritmo y movimiento (pulso, acento, compás).\n-\tEsquema corporal. El cuerpo: imagen y percepción.\nSegmentos corporales, independencia segmentaria.\n-\tLateralidad. Movimientos simétricos y asimétricos.\n-\tEquilibrio dinámico y estático. Control postural, tono muscular, respiración y relajación.\n-\tCoordinación motriz.\n-\tVisomotora, gruesa, fina.\n-\tReglas de juego.\n ","procedural":"-\tIdentificación de diferentes partes y segmentos de su cuerpo y conocimiento de su funcionamiento básico.\n-\tRealización de movimientos con las diferentes partes y segmentos corporales.\n-\tRealización de tensión y relajación de los segmentos corporales.\n-\tExperimentación de posturas corporales diferentes en diversos planos y niveles.\n-\tExperimentación de situaciones de equilibrio y desequilibrio.\n-\tDesplazamiento en diferentes posiciones, direcciones y ritmos.\n-\tIdentificación y diferenciación de las relaciones temporales y espaciales.\n-\tIdentificación de las relaciones con su entorno a partir de las acciones de su propio cuerpo, en relación con objetos, formas, tamaños, texturas, peso, temperatura, color.\n-\tOrientación en el espacio a partir de la identificación de avisos y señales de tránsito.\n-\tUbicación en su entorno natural y social a partir del reconocimiento de relaciones de tipo espacial, tales como: cerca-lejos, dentro-fuera, arribaabajo, derecha-izquierda.\n-\tRealización de juegos de lanzar y patear.\n-\tRealización de juegos de roles. Dramatización de cuentos, situaciones, cantos.\n-\tEjercicios de organización y control. Formaciones en filas, hileras, columnas, círculos, entre otras)\n-\tIdentificación y práctica de normas de higiene y salud, tales como: lavado de manos y vuelta a la calma antes de retornar al aula.\n-\tReconocimiento del tipo de indumentaria apropiada para la práctica de actividades físicas.\n-\tReconocimiento crítico y respeto a instrucciones, reglas y normas en la realización de diversas actividades motrices.\n ","attitudinal":"-\tAutoconfianza es a partir de sus posibilidades de movimiento.\n-\tValoración de su cuerpo y de las posibilidades lúdicas y motrices.\n-\tValoración y disfrute de la participación en juegos con sus compañeros y compañeras.\n-\tValoración de sus propios desempeños motrices y los de otros compañeros y compañeras.\n-\tDefensa y respeto de su espacio personal y el de los demás.\n-\tDefensa y respeto por su derecho y el de los y las demás de jugar y realizar actividad física.\n-\tColaboración en tareas grupales.\n-\tValoración de la convivencia con sus pares en acciones motrices.\n "}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:20:36.184Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('132528dc-9573-4f22-9a80-2cb38d599987', 'educacion-fisica', '2do', '{"id":"132528dc-9573-4f22-9a80-2cb38d599987","name":"Conceptos de unidad","themes":[{"id":"56fd725b-edfd-4d96-8718-615a5f30837d","name":"Esquema corporal. El cuerpo: imagen y percepción","subthemes":[{"id":"a3a9c520-3aa6-4191-a065-0515cf79e2f4","name":"Reconocimiento de las partes del cuerpo."},{"id":"7aac61f9-bbdb-4bea-9571-bc86e30c3593","name":"Imagen corporal y cuidado del propio cuerpo."},{"id":"3e63716e-f282-4ae9-9d38-1c5c96855393","name":"Percepción del cuerpo en movimiento y en reposo."}]},{"id":"d8c6f726-19de-4b1b-b6f5-8b2a3f8180d1","name":"Segmentos corporales, independencia segmentaria. Ejes y planos corporales.","subthemes":[{"id":"d3120868-9fef-4edb-b062-3f240090ba2c","name":"Movimientos de brazos, piernas y tronco por separado."},{"id":"21a55d6d-a040-4f79-b0cd-042b307b2043","name":"Coordinación e independencia de segmentos corporales."},{"id":"7f2a049f-e386-4d30-931e-84d6aa62766a","name":"Reconocimiento de ejes y planos del cuerpo en el movimiento."}]},{"id":"f1012e4c-e2f5-48d3-9e3d-d5372e33fd01","name":"Relaciones espaciales (dirección, orientación y simetrías), relaciones temporales (velocidad, ritmo, duración y secuencia, anticipación).","subthemes":[{"id":"a907eb81-21d6-4673-9dd8-6d4150c7111f","name":"Dirección y orientación en el espacio."},{"id":"ea2031d8-c74a-4ba9-9929-5adf5b2af2a6","name":"Ritmo, velocidad y duración de los movimientos."},{"id":"9407c955-46bf-47a5-a1f6-0e8dc25e9b4e","name":"Secuencia y anticipación de acciones motrices."}]},{"id":"c8c2bcf1-ec54-4007-a826-197cecdc3da0","name":"Lateralidad Movimientos simétricos y asimétricos. Alterno y simultáneo","subthemes":[{"id":"52938e46-6f41-49c7-b345-065a1cb96360","name":"Dominancia lateral (derecha e izquierda)."},{"id":"4c869dc0-2290-4d1a-a564-b1ad3748170d","name":"Movimientos simétricos y asimétricos del cuerpo."},{"id":"423efe88-275c-49a3-a44c-a42458f28b9f","name":"Movimientos alternos y simultáneos en actividades físicas."}]},{"id":"c3b6b8ad-3e30-4270-a97b-9c7c865c2ccb","name":"Equilibrio dinámico y estático","subthemes":[{"id":"5a69893d-6599-41de-ba36-a4d4f414a373","name":"Equilibrio en posiciones fijas."},{"id":"8f2e49f7-06a0-45e4-bfb5-6cc22e2ce300","name":"Equilibrio durante el desplazamiento."},{"id":"6f53359f-a3a7-43f2-9fc4-14caf980fee4","name":"Control del cuerpo en diferentes situaciones de movimiento."}]},{"id":"7f7c5f7b-56b7-43fe-9cff-288592c879d1","name":"Control postural, tono muscular, respiración y relajación","subthemes":[{"id":"85d2631f-002a-44cd-a5a6-7019b50055d2","name":"Postura correcta del cuerpo en reposo y movimiento."},{"id":"34460089-0ecf-428f-9d59-bd9b375dd48b","name":"Respiración y relajación para el bienestar corporal."},{"id":"9aa01fff-634b-49d0-8d44-eeeb2a309320","name":"Control del tono muscular durante la actividad física."}]},{"id":"07932b6b-c2dd-4302-9099-e9721e58d61f","name":"Coordinación motriz","subthemes":[{"id":"765fb68f-058e-4f13-bf89-5a4a6e1fc765","name":"Coordinación en desplazamientos y juegos."},{"id":"907ed932-8f3b-4a55-999b-53ffa8f4adb4","name":"Coordinación general del cuerpo."},{"id":"dc042d99-e518-48a8-af3f-cf9e9a3d7a79","name":"Coordinación en actividades con objetos."}]},{"id":"7d50ed3f-9a7e-4d94-8db9-d95296018526","name":"Gesto, movimiento, mímica, expresión corporal.","subthemes":[{"id":"4ff47109-b444-408e-982c-cfc2a264eca1","name":"Uso del gesto para comunicar emociones e ideas."},{"id":"46df871f-852a-406e-a2fc-f3acef49fe38","name":"Expresión corporal en juegos y dramatizaciones."},{"id":"fb212478-7ad1-4b26-91fe-4fb9321714a5","name":"Mímica y representación corporal."}]},{"id":"0489ecba-d1ac-4436-b85b-4bebcb3c2a26","name":"Ritmo y movimiento (pulso, acento, compás).","subthemes":[{"id":"f8bdf12d-a447-46cd-9d8d-3faccd27a018","name":"Movimiento del cuerpo siguiendo música y sonidos."},{"id":"8eb46d61-32e4-43eb-bc56-37ea741d147e","name":"Reconocimiento del pulso y el ritmo corporal."},{"id":"3ab8fbc6-00cb-4b4d-afd5-3ab4af8365fd","name":"Coordinación del movimiento con el acento y el compás."}]},{"id":"f4563f1d-b5d4-42a3-bd2a-4bc3d8769d32","name":"La importancia del ejercicio","subthemes":[{"id":"9aaa8dcf-ea6a-4aea-b316-4282c2b94897","name":"Subir escaleras en la casa"},{"id":"e69d901b-7445-4a3f-bb65-9135cc895a87","name":"Jugar en el parque"},{"id":"9bfaa386-39aa-42da-a86b-ea724cb3cca7","name":"Bailar en familia"},{"id":"157cc2d7-d722-445c-b7b3-eb2b9355191c","name":"Correr con amigos"}]}],"grade_levels":["2do"],"subjectId":"educacion-fisica","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"132528dc-9573-4f22-9a80-2cb38d599987-block-1","themes":["Esquema corporal. El cuerpo: imagen y percepción","Segmentos corporales, independencia segmentaria. Ejes y planos corporales.","Relaciones espaciales (dirección, orientación y simetrías), relaciones temporales (velocidad, ritmo, duración y secuencia, anticipación).","Lateralidad Movimientos simétricos y asimétricos. Alterno y simultáneo","Equilibrio dinámico y estático","Control postural, tono muscular, respiración y relajación","Coordinación motriz","Gesto, movimiento, mímica, expresión corporal.","Ritmo y movimiento (pulso, acento, compás).","La importancia del ejercicio"],"conceptual":"-\tEsquema corporal. El cuerpo: imagen y percepción.\n-\tSegmentos corporales, independencia segmentaria. Ejes y planos corporales.\n-\tRelaciones espaciales (dirección, orientación y simetrías), relaciones temporales (velocidad, ritmo, duración y secuencia, anticipación).\n-\tLateralidad Movimientos simétricos y asimétricos. Alterno y simultáneo.\n-\tEquilibrio dinámico y estático\n-\tControl postural, tono muscular, respiración y relajación.\n-\tCoordinación motriz.\n-\tGesto, movimiento, mímica, expresión corporal.\n-\tRitmo y movimiento (pulso, acento, compás).\n ","procedural":"-\tDesplazamiento en diferentes posiciones, direcciones y ritmos (en diagonal, paralelo, alterno, simultáneo, zig-zag, entre otros).\n-\tAfirmación de la lateralidad. Identificación y reconocimiento del lado dominante.\n-\tIdentificación de diferentes partes y segmentos de su cuerpo y conocimiento de su funcionamiento básico. \n-\tReconocimiento de su expresión corporal como vehículo de comunicación e interacción personal.\n-\tRealización de tensión y relajación de los segmentos corporales.\n-\tIdentificación y diferenciación de las relaciones temporales y espaciales.\n-\tExperimentación, a través del juego, de diversas posibilidades de movimiento y de expresión.\n-\tExteriorización de sensaciones, emociones y sentimientos a través del cuerpo, el gesto y el movimiento, imitación de personajes, objetos, situaciones y actitudes.\n-\tIdentificación y práctica de normas de higiene y salud, tales como: lavado de manos, vuelta a la calma después de la actividad física, buenos hábitos posturales y respiratorios.\n-\tUtilización de las habilidades motrices básicas: correr, saltar, lanzar, golpear, rodar, reptar, entre otras, en diferentes situaciones ludo- motrices.\n-\tIdentificación, comprensión y resolución de situaciones problemáticas de carácter motor.\n-\tExploración de diferentes posturas y toma de conciencia de las correctas, en distintas acciones como: levantar objetos, desplazamientos, subir y bajar escaleras, entre otras.\n-\tIdentificación de avisos y señales de tránsito y reconocimiento de su importancia para la convivencia.\n-\tReconocimiento del tipo de indumentaria apropiada para la práctica de actividades físicas e importancia de su uso.\n-\tRealización de actividad física, siguiendo instrucciones, reglas y normas.\n-\tEjercicios de organización y control. Formaciones en filas, hileras, columnas, círculos, entre otras.\n ","attitudinal":"-\tParticipación entusiasta en las actividades, con un criterio de autovaloración y respeto hacia sus compañeros y compañeras.\n-\tManejo del error y el fracaso como forma de aprendizaje y superación personal.\n-\tValoración y disfrute de participar en juegos con sus compañeros y compañeras.\n-\tDefensa y respeto por su derecho y el de los y las demás de jugar y realizar actividad física.\n-\tAceptación de sí mismo, sí misma y participación en creaciones colectivas desde una perspectiva personal y de colaboración.\n "}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:20:36.184Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('6d0c6549-c35f-4da7-9f47-159c12826750', 'educacion-artistica', '6to', '{"id":"6d0c6549-c35f-4da7-9f47-159c12826750","name":"Artes aplicadas","themes":[{"id":"36cda1f7-d891-4c29-a927-33023f5c34b7","name":"Estampado y grabado","subthemes":[{"id":"d76b8d0e-db31-44e0-9f62-68b057571280","name":"Técnicas básicas de estampado."},{"id":"ace12dfa-02a7-4660-b4f9-ac847e2daeb3","name":"Instrumentos: cuchillas y gubias (uso seguro)."},{"id":"221f998b-457f-492e-b1ff-1fb901568d6a","name":"Matrices y soportes: linóleo, madera, tela y papel."}]}],"grade_levels":["6to"],"subjectId":"educacion-artistica","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"6d0c6549-c35f-4da7-9f47-159c12826750-block-1","themes":["Estampado y grabado"],"conceptual":"","procedural":"","attitudinal":""}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:20:36.184Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('274e2f4f-92c6-4594-8968-11c06e9556d2', 'sociales', '6to', '{"id":"274e2f4f-92c6-4594-8968-11c06e9556d2","name":"Historia Dominicana","themes":[{"id":"de25ab5a-cd8a-45af-afdb-b1b1cd227b74","name":"Primera intervención estadounidense de 1916","subthemes":[{"id":"81629f78-a100-4767-9d81-14faa4e9b124","name":"Cambios políticos y militares."},{"id":"d0f1c6ba-3095-46c3-9afe-eed3aa643b11","name":"Causas de la ocupación."},{"id":"ce8cbb63-9e07-45a3-9470-a6aba37230c6","name":"Consecuencias para el país."}]},{"id":"115dd5c4-372c-408d-89dc-810af3c4cb77","name":"Situación sociopolítica (1924–1930)","subthemes":[{"id":"6f58aa4c-fe2a-4ac3-8011-b86fd36ef1de","name":"Gobiernos y estabilidad política."},{"id":"75045c38-71cc-40cc-a597-e25f63934728","name":"Crisis económicas y sociales."},{"id":"3e498aec-0294-498a-b49a-02343daf48c3","name":"Retiro de tropas estadounidenses."}]},{"id":"76eaa70b-d591-4c1c-b86b-c2d1f27dee3b","name":"Dictadura de Rafael Leónidas Trujillo (1930–1961)","subthemes":[{"id":"0fd035dd-7275-4a7e-aa13-7bf48cfd18f5","name":"Violación de derechos humanos."},{"id":"a07134ac-e2aa-4af5-ba2f-983fdf83c544","name":"Control político y represión."},{"id":"1e1d2f3b-0047-43f0-834d-36753e19e44b","name":"Impacto económico y social."}]},{"id":"2abe680b-1223-4728-bd20-885955cbe953","name":"Situación política (1961–1963)","subthemes":[{"id":"beb72293-826b-48cb-8d4b-de70fa45755c","name":"Transición democrática."},{"id":"c3d83c30-faca-4b6e-a171-19d32f62a303","name":"Fin de la dictadura."},{"id":"a5a3bd87-879e-4041-8687-c1e165b827dd","name":"Conflictos políticos internos."}]},{"id":"5da6d780-613e-46d7-8994-8e2030d2863d","name":"Gobierno de Bosch y golpe de Estado","subthemes":[{"id":"f0197128-8597-4b6e-b0b5-bed29a9c77f1","name":"Nueva Constitución de 1963."},{"id":"a8b4d5cd-2018-456d-8b80-8ca3cee3ca6f","name":"Reformas del gobierno de Bosch."},{"id":"01a4854a-b29e-488d-bf01-e186cfd3996a","name":"Golpe militar y consecuencias."}]},{"id":"0a86a62c-b4bb-4cc6-aade-ccd8795e271e","name":"Revolución de Abril 1965","subthemes":[{"id":"e7e4a27e-848b-4de7-a2df-49858e06673a","name":"Grupo de San Isidro."},{"id":"e99fdcf3-e85c-4499-b669-15960e889beb","name":"Constitucionalistas y Caamaño."},{"id":"e320413b-8496-4193-a509-6a497fa98929","name":"Segunda intervención estadounidense."}]},{"id":"e9a67e1c-48a9-4ddc-8a59-082c4146aa1d","name":"Gobierno de Héctor García Godoy","subthemes":[{"id":"bf8eb606-ccdb-4fb4-9f9d-edc475a6979d","name":"Acuerdos políticos."},{"id":"dd60c0ac-e5ea-4782-8c92-7765a6f81c51","name":"Gobierno provisional."},{"id":"caf3620a-470c-4e49-8803-d69e47c5860c","name":"Preparación de elecciones.V"}]},{"id":"c6d74bf3-1a8a-4323-be3b-db8c00201559","name":"Los doce años de Joaquín Balaguer","subthemes":[{"id":"f26b434d-8413-4d42-891f-e13eab2470c9","name":"Obras públicas y economía."},{"id":"550480ee-079e-4014-924a-2f92c01a467a","name":"Control político y oposición."},{"id":"6b267052-1566-4100-b6b1-e1327836be74","name":"Situación social y derechos."}]},{"id":"3bb19fd2-03b1-4ab2-9070-651a7921cc54","name":"Cambios en la sociedad (1978–actualidad)","subthemes":[{"id":"83f79eef-2a1f-4306-b535-3ab473bbfe73","name":"Modernización económica."},{"id":"3fa1196c-3930-4026-9efb-b651d0826616","name":"Transición democrática."},{"id":"a2a155f4-74dc-4965-a510-3c660e398123","name":"Cambios sociales y tecnológicos."}]},{"id":"37874c33-7375-4ca6-b3db-a060c156dc8d","name":"Crisis y cambios en la sociedad","subthemes":[{"id":"2d569fb5-2453-4ba5-945b-390b3fc3bc54","name":"Migración y empleo."},{"id":"fcd011c9-2d2e-478d-8359-4ade37a15b06","name":"Crisis económicas."},{"id":"7a8ec6aa-0fc5-4a46-9433-d6a933808d92","name":"Reformas sociales."}]},{"id":"3dccb705-1790-4510-ae0e-cc7abe6805e0","name":"Gobiernos del PRD","subthemes":[{"id":"4303a985-1aea-441b-bca6-bba7c028de9f","name":"Políticas económicas y sociales."},{"id":"f7c63669-25f0-433d-b4da-59e7e21de307","name":"Principales presidentes."},{"id":"8dce5222-2983-43fa-adb8-c5bd222d2154","name":"Retos políticos."}]},{"id":"6a489bb7-8b0e-4fc6-8fc6-b2929000c99a","name":"Gobiernos del PLD","subthemes":[{"id":"29469aaa-45dc-4b4f-84f1-30879332dd9c","name":"Modernización e infraestructura."},{"id":"9046c39b-5650-46c3-8398-1cea80e5328b","name":"Desafíos sociales y políticos."},{"id":"a09c117f-1661-4c2b-9491-c84d2dd0c42c","name":"Crecimiento económico."}]}],"grade_levels":["6to"],"subjectId":"sociales","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"274e2f4f-92c6-4594-8968-11c06e9556d2-block-1","themes":["Primera intervención estadounidense de 1916","Situación sociopolítica (1924–1930)","Dictadura de Rafael Leónidas Trujillo (1930–1961)","Situación política (1961–1963)","Gobierno de Bosch y golpe de Estado","Revolución de Abril 1965","Gobierno de Héctor García Godoy","Los doce años de Joaquín Balaguer","Cambios en la sociedad (1978–actualidad)","Crisis y cambios en la sociedad","Gobiernos del PRD","Gobiernos del PLD"],"conceptual":"Historia Dominicana\n–\tPrimera Intervención estadounidense de 1916\n–\tSituación sociopolítica de la República Dominicana durante los años 1924-1930.\n–\tDictadura de Rafael \nLeónidas Trujillo Molina y la vulneración de los derechos humanos estatales durante los años 1930-1961. \n–\tSituación política de 19611963.\n–\tGobierno de Bosch y golpe de Estado.\n–\tRevolución de Abril (Caamaño y los constitucionalistas y el grupo de San Isidro).\n–\tGobierno de Héctor García Godoy.\n–\tLos doce años de Joaquín Balaguer.\n–\tCambios en la sociedad de \n1978 a la actualidad\n–\tCrisis y cambios en la sociedad.\n–\tLos gobiernos del PRD.\n–\tGobiernos del PLD.\n ","procedural":"–\tAnálisis de periodos de la historia dominicana, mediante comparaciones críticas 1916 y 1965.\n–\tComprensión de los principales acontecimientos históricos de América en el siglo XX.\n–\tAnálisis del impacto de los imperios coloniales en América.\n–\tAnálisis del merengue de Nico Lora “vienen los americanos” u otras canciones que se refieran al hecho histórico: Imágenes, caricaturas, poemas.\n–\t-Realización de comic, dibujos, pancartas, frases, u otras expresiones donde expresen sus opiniones sobre la ocupación por parte de Estados Unidos.\n–\tElaboración de líneas de tiempo de los acontecimientos históricos de 1960- 1965.\n–\tElaboración de líneas de tiempo sobre acontecimientos de 1916-1924. Formulación de hipótesis sobre los antecedentes de la Dictadura de Trujillo.\n–\tPlanteamiento de la hipótesis.\n–\tComprobación de la hipótesis.\n–\tCorrección de la hipótesis.\n–\tAnálisis del impacto social, político, económico y religioso de la Era de Trujillo.\n–\tLevantamiento de informaciones en museos y archivos sobre los movimientos opositores al régimen de Trujillo.\n–\tLevantamiento de informaciones sobre los acontecimientos que propiciaron la Dictadura de \nTrujillo.\n–\tAnálisis de documentales y videos: para determinar las características económicas, políticas y socioculturales de la de Dictadura Trujillo.\n–\tIdentificación de los factores que propiciaron la caída de Trujillo.\n–\tAnálisis de documentos y videos sobre los acontecimientos ocurridos de 1961 al 1966.\n–\tExplicación de las causas y consecuencias del Golpe de Estado a Juan Bosch.\n–\tElaboración de periódicos escolares sobre los sectores enfrentados en la Guerra de Abril.\n–\tAnálisis crítico del gobierno de García Godoy en 1966.\n–\tInvestigación en fuentes de investigación confiables sobre los doce años de Joaquín Balaguer.\n–\tIdentificación de las características principales que propiciaron su ascenso al poder.\n–\tAnálisis del impacto de los 12 años en la sociedad dominicana.\n–\tElaboración de monografías sobre los periodos históricos de 1978-1986; 1986-1994.\n–\tRealización de un informe de lectura sobre el papel de la sociedad civil de 1990 a la actualidad.\n–\tElaboración de textos argumentativos sobre la crisis electoral de 1990 y 1994.\n–\tRealización análisis comparativos sobre los aspectos sociales, políticos y económicos de los gobiernos del PRD, PRSC y los del PLD hasta el 2020.\n–\tPresentación de un resumen final sobre los procesos históricos estudiados de 1960 a la actualidad.\n \n ","attitudinal":"–\tPreocupación por comprender los periodos históricos de la República Dominicana de 1916-1924;1924-1930. \n–\tInterés por comprender los acontecimientos históricos principales en la Era de Trujillo.\n–\tReflexión crítica sobre el Golpe de Estado a Juan Bosch y la Guerra de Abril.\n–\tActitud crítica ante el papel de los constitucionalistas y el sector de San Isidro.\n–\tInterés por los acontecimientos históricos que propiciaron el gobierno de Héctor García Godoy.\n–\tAnálisis crítico de los 12 de Años de Joaquín Balaguer.\n–\tReflexión crítica sobre los gobiernos de 1978-1986: 1986-2000.\n–\tInterés por comprender los acontecimientos históricos de 2000 al 2020.\n– Interés por comprender la incidencia de los partidos políticos y la sociedad civil en la solución de problemas. \n "}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:20:36.184Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('a4da5316-442a-44bc-95e8-f6b9b4e3719c', 'educacion-artistica', '4to', '{"id":"a4da5316-442a-44bc-95e8-f6b9b4e3719c","name":"Conceptos de unidad","themes":[{"id":"a8df82a8-a486-42dd-b161-e6ba941b79f3","name":"El pensamiento divergente como generador de creatividad","subthemes":[{"id":"176dddd5-475c-448b-bf4a-ba135cd451ab","name":"Qué es el pensamiento divergente."},{"id":"60b2efce-a53c-4255-8cef-aafd4ada5223","name":"Generación de ideas creativas a partir de una misma situación."},{"id":"8f535dbb-611e-4842-9bb9-f4accbeabfa9","name":"Importancia de pensar diferente para crear."}]},{"id":"adfc087f-60d2-4ce4-a639-77d39a63a444","name":"El realismo y la ficción en diferentes manifestaciones artísticas","subthemes":[{"id":"4605a2aa-e02c-4694-9457-0f2efa8cffbe","name":"Ejemplos de realismo y ficción en dibujos, cuentos y teatro."},{"id":"557a2b22-319b-4aaf-b51f-89056371bef0","name":"Uso del realismo y la ficción para expresar ideas y emociones."},{"id":"d9887052-0c51-47f5-a5c4-7259a608f4d8","name":"Diferencia entre lo real y lo imaginario en el arte."}]},{"id":"82a887d6-606d-4fab-94d8-c6006ad2d5ef","name":"Música y danzas tradicionales dominicanas (merengue y mangulina)","subthemes":[{"id":"ba8465b6-700e-478d-b763-16f8c6d54f10","name":"Origen del merengue y la mangulina."},{"id":"1b073149-16d4-4efa-9f02-a18077269c29","name":"Características musicales y ritmos principales."},{"id":"e2dbaddc-ad3f-42f2-8ffe-f7ac4dafb96a","name":"Pasos básicos, vestuarios y expresiones visuales."}]},{"id":"6da659d1-20c2-4888-8324-73752ad0223e","name":"Identidad cultural. Patrimonio material e inmaterial. Bienes culturales","subthemes":[{"id":"7723966e-222b-418b-b145-82c2efa31716","name":"Qué es la identidad cultural."},{"id":"8bb74209-636b-4e23-ac40-a7032053ab98","name":"Patrimonio material e inmaterial dominicano."},{"id":"9e65116d-e525-47f0-8786-344fc10d8cce","name":"Importancia de cuidar y valorar los bienes culturales."}]},{"id":"2248b313-b854-4ba4-8107-af0e924c2b04","name":"La representación de objetos y personajes imaginarios","subthemes":[{"id":"b2a792f9-a632-41b5-9311-7845cb793dcd","name":"Creación de personajes imaginarios."},{"id":"594ba1e8-3c56-444e-b20a-a4ae446a83d8","name":"Representación de objetos fantásticos mediante el arte."},{"id":"9d4915a2-a31f-41b3-925b-376802443862","name":"Uso de la imaginación en producciones artísticas."}]},{"id":"5d6684dd-a304-431f-8662-e4456b802d0c","name":"Artes visuales","subthemes":[]}],"grade_levels":["4to"],"subjectId":"educacion-artistica","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"a4da5316-442a-44bc-95e8-f6b9b4e3719c-block-1","themes":["El pensamiento divergente como generador de creatividad","El realismo y la ficción en diferentes manifestaciones artísticas","Música y danzas tradicionales dominicanas (merengue y mangulina)","Identidad cultural. Patrimonio material e inmaterial. Bienes culturales","La representación de objetos y personajes imaginarios","Artes visuales"],"conceptual":"-\tEl realismo y la ficción en diferentes manifestaciones artísticas.\n-\tLa representación de objetos y personajes imaginarios.\n-\tEl pensamiento divergente como generador de creatividad.\n-\tMúsica y danzas tradicionales dominicanas (merengue y mangulina). \nCaracterísticas musicales, coreográficas y visuales fundamentales.\n-\tIdentidad cultural. Patrimonio material e inmaterial. Bienes culturales.\nArtes Visuales\n-\tEl dibujo (Líneas, luces y sombras como elementos    configuradores de la forma).\n-\tEl círculo cromático: combinaciones y tonalidades del color.\n-\tEl color en los lenguajes visuales: colores primarios, secundarios y complementarios.\n-\tLa narración visual con imágenes fijas o en movimiento.\n-\tTransformaciones reales e imaginarias del espacio (plástico-visual y escénico).\n \n-\tLa exposición de artes visuales y sus componentes básicos: espacio expositivo, iluminación, información del catálogo de participantes, ficha técnica de la obra, entre otros.\n-\tComposiciones visuales en objetos y producciones artísticas bidimensionales (pintura, serigrafía, fotografía, grabado, entre otros) y tridimensionales (cerámicas, maderas talladas, higüeros, pilones, entre otros.).\nArtes Escénicas\n-\tEl tiempo en el movimiento y el gesto corporal.\n-\tRecursos asociados al tiempo \n(velocidad, continuidad y energía), al espacio (niveles bajo, medio y alto) y direcciones, (arriba/abajo, derecha/ izquierda, amplitudes).\n-\tTíteres: figuras animadas para jugar y contar historias.\n-\tAcciones reales e imaginarias para la representación de cuentos breves, pequeñas historias, mitos y leyendas de su región o comunidad.\n-\tLa dramatización de cuentos, poesías y canciones. Personajes teatrales.\n-\tLa representación escénica: textos, personajes tradicionales y pregones.","procedural":"-\tExploración en diferentes manifestaciones artísticas, a partir de temas o formas del realismo y la ficción.\nArtes Visuales\n-\tLa fotografía con dispositivos móviles y sus posibilidades comunicativas.\n-\tCaracterísticas de la fotografía, considerando temáticas y tipos de encuadres.\n-\tLos medios audiovisuales y de las TIC como recursos de realización y análisis de producciones \nartísticas, articulando la percepción, la imaginación y la exploración.\n-\tFormas bidimensionales y tridimensionales pertenecientes a diferentes contextos, géneros y estilos. Técnicas y materiales en el lenguaje plástico-visual.\n-\tUtilización de los colores primarios y secundarios en producciones artísticas a partir de temas de la realidad y de la imaginación.\n-\tEl dibujo a lápiz, a carboncillo y a la témpera en la representación de objetos y personajes imaginarios.\n-\tDiseño y creación de objetos y personajes a partir de simbologías o referentes visuales propios de su región, utilizando materiales de su entorno inmediato.\n \n-\tCreación de dibujos para representar objetos, personas o ambientes rurales y urbanos, a partir del reconocimiento de sus  formas, colores u otras características estéticas.\n-\tAnimaciones sencillas creadas a partir del lenguaje audiovisual: guion, realización, montaje y sonido.\n-\tUtilización del círculo cromático para la representación de emociones y sentimientos en la ejecución de sus producciones visuales.\n-\tRealización de exposiciones de artes visuales y aplicadas. El plan de acción, paso a paso.\nArtes Escénicas\n-\tAcciones físicas y gestos expresivos en relación con los objetos, usos y costumbres de su realidad para comunicar sentimientos, emociones e ideas.\n-\tDramatización de cuentos, poesías y canciones. Interpretación de personajes teatrales.\n-\tModificación del espacio (escénico y plástico visual), utilizando elementos, gestos o movimientos a partir de un concepto real o imaginario.\n-\tEjecución de la mangulina y algunas formas danzadas del merengue dominicano.\n-\tManejo de títeres.\n-\tMontaje de piezas o cuentos breves, con títeres, como medio para conocer, interpretar y transformar la realidad.\n-\tMontaje de espectáculos escénicos integrando distintos elementos artísticos. El plan de acción, paso a paso.\n ","attitudinal":"-\tLa naturalidad en la expresión vocal (hablada o cantada) y corporal, individual y colectiva.\n-\tLa creatividad en el uso de diversos tipos de títeres y otras manifestaciones artísticas, valorando su utilidad a la hora de expresarse.\n-\tLa autoestima en la comunicación artística.\n-\tColaboración, solidaridad y respeto en actividades artísticas colectivas.\n-\tDisfrute de costumbres y prácticas artísticas tradicionales.\n-\tValoración de distintas manifestaciones artísticas, realistas o de ficción.\n-\tValoración y disfrute de los bienes culturales de su comunidad \n(materiales e inmateriales) haciendo conciencia sobre la necesidad de su preservación.\n-\tRespeto a las indicaciones de letreros y gráficos que regulan la convivencia y el orden en entornos rurales y urbanos (parques, monumentos, señalización de tránsito, pasos peatonales, rampas, aceras, depósitos clasificados para desechos, alumbrados).\n \n-\tValoración de los elementos técnicos que enriquecen distintas expresiones \nartísticas (iluminación, banda sonora, amplificación, decoración, maquillaje, vestuarios…).\n-\tValoración de los sentidos, la voz y el cuerpo como propiedades únicas e instrumentos de comunicación y percepción. Respeto a las diferencias.\n-\tValoración de las expresiones propias y ajenas, a partir del respeto y tolerancia con los desacuerdos.\n-\tDisposición a la terminación de la obra artística atendiendo a principios estéticos.\n "}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:20:36.184Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('3fe62187-8a32-4930-bce3-293c802f03c0', 'formacion-humana', '1ro', '{"id":"3fe62187-8a32-4930-bce3-293c802f03c0","name":"Conceptos de unidad","themes":[{"id":"44c4ec12-9862-4b63-a48d-8d721cb7f4d5","name":"Nacimiento de Jesús.","subthemes":[{"id":"5001c0a4-846c-4d74-947c-57105cff734d","name":"El anuncio del nacimiento de Jesús."},{"id":"b9e43d53-a5d5-4922-97bc-bca96815930e","name":"María, José y el Niño Jesús."},{"id":"33a1842a-bdfa-4a63-9c2d-0195f6196c57","name":"El lugar donde nació Jesús."},{"id":"e6a18139-af1c-4073-8a2d-f61a736a086f","name":"Importancia del nacimiento de Jesús para los cristianos."}]},{"id":"30fdc964-52d3-40cf-908e-6bfb5e8d5fe1","name":"Sentido religioso de la Navidad.","subthemes":[{"id":"52574884-5ca8-4313-a075-6b4162be97e0","name":"Qué celebramos en la Navidad."},{"id":"171c0dcc-912c-4224-a0ec-222a99a51116","name":"La Navidad como tiempo de amor y esperanza."},{"id":"2cddb8fe-66fc-4aca-8501-aed35dfea53f","name":"Mensaje de paz y solidaridad en la Navidad."},{"id":"39913ee0-6116-4eba-bf39-4641eb71c225","name":"La Navidad y la fe cristiana."}]},{"id":"3509f9ab-e028-46a7-aade-62fdd162a31f","name":"Celebraciones en la Navidad.","subthemes":[{"id":"01fe70fe-abed-4596-9e2e-5bf210b2584c","name":"La Nochebuena y el día de Navidad."},{"id":"a74ad057-1e1b-4fcb-96c6-c4f4e49ab061","name":"Actividades religiosas en Navidad."},{"id":"ab0910cf-21b4-4957-9e3e-07289594b531","name":"Celebraciones familiares en Navidad."},{"id":"dd932b57-03d2-4e4a-a9a0-5ab3d7dc475a","name":"La Navidad en la escuela y la comunidad."}]},{"id":"fc93fabb-60d6-4f76-b826-c1184b8bf811","name":"Costumbres en la época de navidad.","subthemes":[{"id":"dcc07d33-40bc-4197-a415-502a4bce524f","name":"Decoraciones navideñas."},{"id":"09787242-a9b4-498f-98b1-63f644937363","name":"Villancicos y canciones navideñas."},{"id":"0ef737f6-ec20-491b-867b-63a423b275e5","name":"Tradiciones familiares navideñas."},{"id":"f6fd76aa-55ff-4d95-9d90-01d5ecc06bbf","name":"Actitudes de compartir y ayudar en Navidad."}]},{"id":"bafcd524-7b47-4451-aa20-e7cd1e58444b","name":"Normas de convivencia.","subthemes":[{"id":"785cd4f1-820b-458c-808c-924e6e1b601e","name":"Importancia de las normas para vivir en armonía."},{"id":"5b711fe6-b307-481b-a1e8-16aa7e76c95d","name":"Consecuencias de cumplir o no las normas."},{"id":"5c060d2a-3f30-46ce-9db2-a4a2be5934f2","name":"Qué son las normas de convivencia."},{"id":"b3fc5efd-7191-4fbf-bc17-238774e0d4dc","name":"Normas básicas en la vida diaria."}]},{"id":"372d4539-5a89-4365-8ee3-c22de611887f","name":"Convivencia escolar y familiar.","subthemes":[{"id":"ad140d2d-07c5-40cb-8328-0503fb95b20d","name":"Normas de convivencia en la escuela."},{"id":"84f90de4-5cc5-4cd1-9e28-8687aea94d4e","name":"Resolución pacífica de conflictos."},{"id":"a7e71e23-6219-4b71-8230-f73c05f98108","name":"Normas de convivencia en la familia."},{"id":"901cd7aa-ad96-40d1-8be9-c35ec205e320","name":"Respeto y diálogo en la convivencia diaria."}]},{"id":"61ce292a-b468-441b-ae76-6381609a2e8a","name":"Las normas en el juego.","subthemes":[{"id":"b88f1703-254a-409a-bbf3-d0692e37bcb0","name":"Respeto a turnos y compañeros."},{"id":"686884de-4b5c-41f2-b147-653e603bba9d","name":"Aceptación de ganar y perder."},{"id":"f523375e-64ae-4616-9abb-e98f4ae2ca81","name":"Importancia de las reglas en los juegos."},{"id":"4c5b26be-2873-412c-97da-fdf41e56f4b5","name":"Juego limpio y trabajo en equipo."}]},{"id":"6209785c-209b-48ca-9186-146b2fa3d88b","name":"Normas en el uso de las tecnologías.","subthemes":[{"id":"18c7e6c2-3d36-40b1-b7bc-1e17d2efb0ee","name":"Normas para el uso de internet y redes."},{"id":"29233390-0f2c-4148-b533-d14ae271dcbb","name":"Respeto y seguridad en entornos digitales."},{"id":"60522186-18bb-4456-9d37-276fc37be8b5","name":"Uso responsable de dispositivos tecnológicos."},{"id":"8f718a58-9ce8-401a-b20c-f2a0fdd1cf32","name":"Cuidado del tiempo frente a pantallas."}]},{"id":"149abb03-89c3-4e34-9ac8-c4a5c4175e90","name":"Enseñanzas de Jesús de Nazaret sobre las normas de convivencia.","subthemes":[{"id":"a4f169ed-ee02-4079-ad53-f90b6015b5e2","name":"El respeto y la solidaridad en las enseñanzas de Jesús."},{"id":"f87fcec3-fc10-44ec-a2dc-51694bf2e41c","name":"Vivir las normas a ejemplo de Jesús."},{"id":"6637c9ed-fd8a-438a-99e3-ff753729d803","name":"El amor al prójimo."},{"id":"7ba3bef3-34b2-40bf-b0c7-dfd7f836a74a","name":"El perdón y la convivencia pacífica."}]},{"id":"91c9fa09-f0fa-436c-8167-7e6bfd9b67d7","name":"Dios es creador, todo lo hizo bueno","subthemes":[{"id":"a30e4274-bab6-4907-b43c-227ceb161f3b","name":"Dios como creador del mundo."},{"id":"5fd21c33-bb01-40c5-b4d5-f4a8e361d2ba","name":"La creación como obra buena de Dios."},{"id":"f0a103b1-e207-45e2-80ed-a079104e7d16","name":"Agradecimiento por lo que Dios creó."},{"id":"2428ac98-0591-4904-9129-3394fecc8664","name":"Cuidado de la creación como responsabilidad humana."}]},{"id":"003f3270-6992-47de-a0e6-62fb01b09124","name":"La naturaleza es creación de Dios","subthemes":[{"id":"a35aff68-3798-4018-94b4-560c00e491b5","name":"Elementos de la naturaleza creados por Dios."},{"id":"70b574c6-aefe-49e8-949b-34ae6dd5ac03","name":"La naturaleza como regalo de Dios."},{"id":"e1398700-5677-4a95-bd77-14398b21f53b","name":"Respeto y cuidado de la naturaleza."},{"id":"f56d67ad-1858-471e-b402-dff0fe3a0c8c","name":"Acciones para proteger la creación de Dios."}]},{"id":"faeef3ca-a273-430b-bf5f-7c2f74e0fa99","name":"Somos parte de la naturaleza","subthemes":[{"id":"a9914d46-d54b-4dfb-8bae-77ae9d3c346c","name":"Las personas como parte de la creación."},{"id":"297349f7-496b-422f-81e8-dd61bf7323d3","name":"Relación entre el ser humano y la naturaleza."},{"id":"cca41a5c-a5f9-4c48-8922-680e3163d998","name":"Importancia de cuidar nuestro entorno."},{"id":"d85a8223-8e97-4703-bf14-1264638f776a","name":"Vivir en armonía con la naturaleza."}]},{"id":"213c8baa-29e1-42ed-a7ec-6782d77db761","name":"Utilidad de las partes del cuerpo y su cuidado","subthemes":[{"id":"e5b94361-2cb5-4520-bcd8-f2632d128c9a","name":"Función de las partes del cuerpo."},{"id":"5bf3f8c6-4705-4b21-83fd-c5cacf1cf249","name":"Cuidado y respeto del propio cuerpo."},{"id":"85892056-f013-472a-a6ad-b5b602729724","name":"Hábitos saludables para el cuerpo."},{"id":"c45427bc-83bc-4598-9fda-cfea08ed2367","name":"Importancia del autocuidado."}]},{"id":"226618c5-8d6c-4da9-bead-cdfac6edf6eb","name":"El cuerpo humano: tesoro y regalo de Dios","subthemes":[{"id":"e546845f-cb4c-4436-b628-d878aabb8c8d","name":"El cuerpo como regalo de Dios."},{"id":"f5f112a7-2d32-48ab-be78-b24565ea6566","name":"Aceptación y valoración del propio cuerpo."},{"id":"a73bbc43-dfc9-458c-a26d-0cbc637f7b0a","name":"El cuerpo como medio para hacer el bien."},{"id":"7b192eb1-f8ee-46f8-b351-a3b2b7637cdd","name":"Agradecimiento a Dios por nuestro cuerpo."}]},{"id":"12efec52-2834-4d92-b15a-8788926996b0","name":"Situaciones de riesgo en la niñez","subthemes":[{"id":"68507455-83ca-4759-adf5-a789e3dafa3a","name":"Qué son las situaciones de riesgo."},{"id":"dd618cf1-d11b-4199-979d-7cdd09bcaa87","name":"Situaciones de riesgo en la vida diaria."},{"id":"e0d8d738-4bf4-4a4e-ab2b-2e62ad778248","name":"Cómo cuidarse y pedir ayuda."},{"id":"174f1543-34e9-40f1-81d0-9aa993209cd9","name":"Importancia de proteger la vida y la salud."}]}],"grade_levels":["1ro"],"subjectId":"formacion-humana","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"3fe62187-8a32-4930-bce3-293c802f03c0-block-1","themes":["Nacimiento de Jesús.","Sentido religioso de la Navidad.","Celebraciones en la Navidad.","Costumbres en la época de navidad.","Normas de convivencia.","Convivencia escolar y familiar.","Las normas en el juego.","Normas en el uso de las tecnologías.","Enseñanzas de Jesús de Nazaret sobre las normas de convivencia.","Dios es creador, todo lo hizo bueno","La naturaleza es creación de Dios","Somos parte de la naturaleza","Utilidad de las partes del cuerpo y su cuidado","El cuerpo humano: tesoro y regalo de Dios","Situaciones de riesgo en la niñez"],"conceptual":"-\tNacimiento de Jesús. \n-\tSentido religioso de la Navidad. - Celebraciones en la Navidad.\n-\tCostumbres en la época de navidad.\n \n- Normas de convivencia.\n- Convivencia escolar y familiar.\n- Las normas en el juego.\n- Normas en el uso de las tecnologías.\n- Enseñanzas de Jesús de Nazaret\nsobre las normas de convivencia.\n \n- Dios es creador, todo lo hizo bueno.\n- La naturaleza es creación de Dios.\n- Somos parte de la naturaleza.\n- Utilidad de las partes del cuerpo y su cuidado.\n- El cuerpo humano tesoro y regalo de Dios.\n- Situaciones de riesgo en la niñez\n- Dios es creador, todo lo hizo\nbueno.\n \n- La naturaleza es creación de Dios.\n- Somos parte de la naturaleza.\n- Utilidad de las partes del cuerpo y su cuidado.\n- El cuerpo humano tesoro y regalo de Dios.\n- Situaciones de riesgo en la niñez.\n \n ","procedural":"-\tRecreación por medio de dibujos, narración o gestos del texto bíblico del nacimiento de Jesús (Lucas 2: 1-20).\n-\tDescripción de diferentes momentos del relato del nacimiento de Jesús, visita de los pastores y adoración de los reyes (Mateo 2: 1-12). \n-\tConstrucción y exposición de un pesebre con recursos del medio. \n-\tConstrucción de un mural artístico donde se presenten las diferentes formas de celebrar la navidad desde el ámbito social y religioso.\n-\tIdentificación y dibujo de los diferentes símbolos de la Navidad.\n-\tPresentación de diferentes valores sobre el nacimiento de Jesús a partir de textos bíblicos.\n-\tSocialización sobre la manera en que su familia celebra la Navidad.\n-\tIdentificación de las costumbres y valores familiares, escolares y comunitarias en el tiempo de navidad.\n-\tConstrucción de manualidades religiosas alusivas a la navidad tomando como bases materiales reciclables.\n-\tOrganización de una fiesta navideña y exposición de las producciones artísticas. \n-\tParticipación en actividades de solidaridad organizadas por su maestro o maestra, para beneficiar a niños y niñas en tiempo de Navidad.\n \n- Socialización de normas que ayudan al bienestar personal, familiar y sociocultural.\n- Identificación de normas que favorecen el bien personal, familiar y social en relatos de textos bíblicos.\n- Dramatización de acciones que favorecen la buena convivencia en la escuela, la familia y otros ambientes socioculturales.\n- Realización de juegos individuales y grupales que necesitan el establecimiento de normas claras.\n- Elaboración de objetos tecnológicos sencillos con materiales reciclables del entorno.\n- Creación de proyecto para el fomento del uso respetuoso de las tecnologías en el juego, la escuela, la familia y la comunidad.\n- Socialización de normas de convivencia a partir de las enseñanzas de Jesús de Nazaret.\n- Comparación de las normas establecidas en la familia, la escuela y la comunidad con las enseñanzas de Jesús de Nazaret en relación a las relaciones armónicas entre las personas.\n- Organización de espacio festivo en que se expongan los aprendizajes desarrollados y se agradezca a Dios por las normas que favorecen las relaciones armoniosas en los diferentes contextos.\n- Organización de una celebración con sus juegos favoritos.\n \n- Identificación de las cosas presentes en su entorno natural creadas por Dios.\n- Dramatización de textos bíblicos y otros textos sobre la creación (Génesis 1, 31 y Génesis 2, 21-24).\n- Reconstrucción del relato de la creación a través de imágenes e ilustraciones.\n- Distinción de las cosas creadas por Dios y las hechas por las personas a través de observación de láminas, lectura de cuentos, relatos bíblicos y otros textos.\n- Dibujo e interpretación de canciones sobre elementos de la naturaleza que exigen respeto y protección.\n- Realización de proyectos para realizar acciones de cuidado de la creación.\n- Descripción de las partes del cuerpo humano, su utilidad y las formas de cuidarlo.\n- Identificación y descripción de posibles situaciones de violencia, abuso, peligro físico, sexual, psicológico y emocional en su familia, en la escuela y en su comunidad.\n- Interpretación de canciones, poesías y dramatizaciones sobre el valor del cuerpo humano como tesoro y regalo de Dios.\n- Realización de una feria en que se expongan los aprendizajes desarrollados sobre el valor del cuerpo humano, la naturaleza y de agradecimiento a Dios por el regalo del cuerpo humano.","attitudinal":"-\tReconocimiento de los valores del nacimiento de Jesús.\n-\tGratitud a Dios por enviar a su Hijo Jesús como regalo. \n-\tRespeto por las diferentes maneras en que las personas \ncelebran la Navidad. \n-\tAlegría y esperanza por las fiestas navideñas.\n-\tAdmiración del comportamiento de los personajes que están presentes en el nacimiento de Jesús. \n-\tAgradecimiento a Dios por la celebración de la navidad en familia.\n-\tSolidaridad con los demás.\n-\tDisfrute de las celebraciones navideñas.\n \n- Respeto por las normas de convivencia. \n- Admiración por las personas que son respetuosas en el trato hacia los demás.\n- Disfrute de juegos grupales respetando las normas establecidas. \n- Respeto de las normas establecidas en el uso de las tecnologías y en el juego.\n- Curiosidad por las enseñanzas de Jesús en relación a la convivencia armónica.\n- Agradecimiento a Dios por las normas que favorecen el bien personal, familiar y social.\n \n- Admiración y gratitud a Dios por todo lo bueno que recibe de la naturaleza.\n- Alegría al contemplar en la naturaleza la presencia amorosa y bondadosa de Dios.\n- Rechazo de acciones que agreden o contaminan la naturaleza creada por Dios.\n- Valoración y aceptación de su cuerpo.\n- Cuidado y defensa de su integridad física.\n- Agradecimiento a Dios por su cuerpo.\n "}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:20:36.184Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('f1eaa9f0-21ba-4c35-9b0f-4d07ff866019', 'educacion-artistica', '4to', '{"id":"f1eaa9f0-21ba-4c35-9b0f-4d07ff866019","name":"Artes visuales","themes":[{"id":"9606376a-9ec2-4c28-aee9-ccd07a2138d3","name":"El dibujo (líneas, luces y sombras como elementos configuradores de la forma)","subthemes":[{"id":"b23171c7-3bda-4cd9-a334-0b35dc7e3d0f","name":"Tipos de líneas en el dibujo."},{"id":"9d03483c-36e3-4a08-8aff-7d2475f5379f","name":"Uso de luces y sombras para crear formas."},{"id":"a593351e-791a-4e08-84ca-9f42d1908462","name":"Representación de objetos y figuras mediante el dibujo."}]},{"id":"5b433846-5ca5-4864-ab2a-b66d0ee1a58f","name":"La narración visual con imágenes fijas o en movimiento","subthemes":[{"id":"a91dbb7b-3d9b-4a4e-975b-e87c6a8a8ec3","name":"Secuencia de imágenes para contar historias."},{"id":"1db69b0c-5a41-4339-aa9f-e04fd4b1afdb","name":"Imágenes fijas en la narración visual."},{"id":"5882315c-cf1e-4cfa-81a2-24f9b02eb7bd","name":"Imágenes en movimiento y su función narrativa."}]},{"id":"45603bc5-bff2-4fcf-992f-ee113b522a63","name":"Composiciones visuales en objetos y producciones artísticas","subthemes":[{"id":"97dff99e-0909-4542-a971-9ca979e1bb72","name":"Producciones bidimensionales: pintura, fotografía y grabado."},{"id":"d7e72f92-1b2e-4f5e-bc6f-eb21fa786ed5","name":"Producciones tridimensionales: cerámica, madera tallada y objetos tradicionales."},{"id":"0c23bda3-6b88-442a-a035-3f2b2ba01c6a","name":"Valor artístico y cultural de las producciones visuales."}]},{"id":"386e09be-7839-4403-ac41-e7652f8e42da","name":"El círculo cromático: combinaciones y tonalidades del color","subthemes":[{"id":"2efa67dc-171c-49bc-ad73-30d101261aa3","name":"Colores primarios y secundarios en el círculo cromático."},{"id":"a874a9f6-6d4f-4f0f-9a35-f62362b2da13","name":"Combinación de colores."},{"id":"ae407df2-0f4a-4578-9208-0c22cf2b20cd","name":"Tonalidades claras y oscuras del color."}]},{"id":"40d727ed-5b42-4bde-afe6-d83018e0110b","name":"Transformaciones reales e imaginarias del espacio","subthemes":[{"id":"2a311f43-1d54-4780-b7f5-debffca3f92d","name":"Representación del espacio en el arte visual."},{"id":"e55cecf3-d34f-4337-aa91-85cc0410bfc1","name":"Espacios imaginarios en producciones artísticas."},{"id":"e988c387-5e38-4c46-bd8d-077f3c5c88ce","name":"Uso del espacio en representaciones escénicas."}]},{"id":"b528947f-7cd2-42c1-83ed-8108a7f649d2","name":"El color en los lenguajes visuales","subthemes":[{"id":"6354b9bc-7113-48db-ab74-3483135b7a19","name":"Colores primarios y secundarios."},{"id":"aa64a007-fe35-40ef-ae29-baf2d3591806","name":"Colores complementarios."},{"id":"9bbc769b-60ba-4c44-8eb6-767c3b78382d","name":"Uso del color para expresar ideas y emociones."}]},{"id":"6314732c-b645-4fef-b6ad-a0acbc13850f","name":"La exposición de artes visuales y sus componentes básicos","subthemes":[{"id":"4db909cd-e649-42be-8ddd-54995ee6f4d2","name":"El espacio expositivo y su organización."},{"id":"16435cdc-ba67-4e10-b16f-46ff30487bb9","name":"Iluminación y presentación de las obras."},{"id":"16351038-8de0-4853-be62-fea3f8d7cfda","name":"Información de la obra: ficha técnica y catálogo de participantes."}]}],"grade_levels":["4to"],"subjectId":"educacion-artistica","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"f1eaa9f0-21ba-4c35-9b0f-4d07ff866019-block-1","themes":["El dibujo (líneas, luces y sombras como elementos configuradores de la forma)","La narración visual con imágenes fijas o en movimiento","Composiciones visuales en objetos y producciones artísticas","El círculo cromático: combinaciones y tonalidades del color","Transformaciones reales e imaginarias del espacio","El color en los lenguajes visuales","La exposición de artes visuales y sus componentes básicos"],"conceptual":"-\tEl realismo y la ficción en diferentes manifestaciones artísticas.\n-\tLa representación de objetos y personajes imaginarios.\n-\tEl pensamiento divergente como generador de creatividad.\n-\tMúsica y danzas tradicionales dominicanas (merengue y mangulina). \nCaracterísticas musicales, coreográficas y visuales fundamentales.\n-\tIdentidad cultural. Patrimonio material e inmaterial. Bienes culturales.\nArtes Visuales\n-\tEl dibujo (Líneas, luces y sombras como elementos    configuradores de la forma).\n-\tEl círculo cromático: combinaciones y tonalidades del color.\n-\tEl color en los lenguajes visuales: colores primarios, secundarios y complementarios.\n-\tLa narración visual con imágenes fijas o en movimiento.\n-\tTransformaciones reales e imaginarias del espacio (plástico-visual y escénico).\n \n-\tLa exposición de artes visuales y sus componentes básicos: espacio expositivo, iluminación, información del catálogo de participantes, ficha técnica de la obra, entre otros.\n-\tComposiciones visuales en objetos y producciones artísticas bidimensionales (pintura, serigrafía, fotografía, grabado, entre otros) y tridimensionales (cerámicas, maderas talladas, higüeros, pilones, entre otros.).\nArtes Escénicas\n-\tEl tiempo en el movimiento y el gesto corporal.\n-\tRecursos asociados al tiempo \n(velocidad, continuidad y energía), al espacio (niveles bajo, medio y alto) y direcciones, (arriba/abajo, derecha/ izquierda, amplitudes).\n-\tTíteres: figuras animadas para jugar y contar historias.\n-\tAcciones reales e imaginarias para la representación de cuentos breves, pequeñas historias, mitos y leyendas de su región o comunidad.\n-\tLa dramatización de cuentos, poesías y canciones. Personajes teatrales.\n-\tLa representación escénica: textos, personajes tradicionales y pregones.","procedural":"-\tExploración en diferentes manifestaciones artísticas, a partir de temas o formas del realismo y la ficción.\nArtes Visuales\n-\tLa fotografía con dispositivos móviles y sus posibilidades comunicativas.\n-\tCaracterísticas de la fotografía, considerando temáticas y tipos de encuadres.\n-\tLos medios audiovisuales y de las TIC como recursos de realización y análisis de producciones \nartísticas, articulando la percepción, la imaginación y la exploración.\n-\tFormas bidimensionales y tridimensionales pertenecientes a diferentes contextos, géneros y estilos. Técnicas y materiales en el lenguaje plástico-visual.\n-\tUtilización de los colores primarios y secundarios en producciones artísticas a partir de temas de la realidad y de la imaginación.\n-\tEl dibujo a lápiz, a carboncillo y a la témpera en la representación de objetos y personajes imaginarios.\n-\tDiseño y creación de objetos y personajes a partir de simbologías o referentes visuales propios de su región, utilizando materiales de su entorno inmediato.\n \n-\tCreación de dibujos para representar objetos, personas o ambientes rurales y urbanos, a partir del reconocimiento de sus  formas, colores u otras características estéticas.\n-\tAnimaciones sencillas creadas a partir del lenguaje audiovisual: guion, realización, montaje y sonido.\n-\tUtilización del círculo cromático para la representación de emociones y sentimientos en la ejecución de sus producciones visuales.\n-\tRealización de exposiciones de artes visuales y aplicadas. El plan de acción, paso a paso.\nArtes Escénicas\n-\tAcciones físicas y gestos expresivos en relación con los objetos, usos y costumbres de su realidad para comunicar sentimientos, emociones e ideas.\n-\tDramatización de cuentos, poesías y canciones. Interpretación de personajes teatrales.\n-\tModificación del espacio (escénico y plástico visual), utilizando elementos, gestos o movimientos a partir de un concepto real o imaginario.\n-\tEjecución de la mangulina y algunas formas danzadas del merengue dominicano.\n-\tManejo de títeres.\n-\tMontaje de piezas o cuentos breves, con títeres, como medio para conocer, interpretar y transformar la realidad.\n-\tMontaje de espectáculos escénicos integrando distintos elementos artísticos. El plan de acción, paso a paso.\n ","attitudinal":"-\tLa naturalidad en la expresión vocal (hablada o cantada) y corporal, individual y colectiva.\n-\tLa creatividad en el uso de diversos tipos de títeres y otras manifestaciones artísticas, valorando su utilidad a la hora de expresarse.\n-\tLa autoestima en la comunicación artística.\n-\tColaboración, solidaridad y respeto en actividades artísticas colectivas.\n-\tDisfrute de costumbres y prácticas artísticas tradicionales.\n-\tValoración de distintas manifestaciones artísticas, realistas o de ficción.\n-\tValoración y disfrute de los bienes culturales de su comunidad \n(materiales e inmateriales) haciendo conciencia sobre la necesidad de su preservación.\n-\tRespeto a las indicaciones de letreros y gráficos que regulan la convivencia y el orden en entornos rurales y urbanos (parques, monumentos, señalización de tránsito, pasos peatonales, rampas, aceras, depósitos clasificados para desechos, alumbrados).\n \n-\tValoración de los elementos técnicos que enriquecen distintas expresiones \nartísticas (iluminación, banda sonora, amplificación, decoración, maquillaje, vestuarios…).\n-\tValoración de los sentidos, la voz y el cuerpo como propiedades únicas e instrumentos de comunicación y percepción. Respeto a las diferencias.\n-\tValoración de las expresiones propias y ajenas, a partir del respeto y tolerancia con los desacuerdos.\n-\tDisposición a la terminación de la obra artística atendiendo a principios estéticos.\n "}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:20:36.184Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('6590fb19-7fb3-4fe9-8cb2-363771e77580', 'sociales', '6to', '{"id":"6590fb19-7fb3-4fe9-8cb2-363771e77580","name":"Patrimonio natural, histórico y cultural del mundo.","themes":[{"id":"bf9188eb-1988-4969-ab6b-69e2458c822f","name":"Patrimonio natural, histórico y cultural del mundo","subthemes":[{"id":"9c25b126-b5a7-4004-b3c5-55c3398e5f1d","name":"Patrimonio natural y biodiversidad."},{"id":"69732a9c-5e69-4fc0-8946-532d246d1ace","name":"Tradiciones y diversidad cultural."},{"id":"126da653-5cba-4111-aff7-e750006a8fd1","name":"Monumentos y sitios históricos."}]},{"id":"250878eb-2277-4a16-91fc-9922f0f99c18","name":"Organización de la sociedad","subthemes":[{"id":"654bb0c3-063d-453e-bf9b-2c741d9b2c71","name":"Grupos sociales e instituciones."},{"id":"80f4750a-d892-4e15-b9fe-5d496a82d97b","name":"Roles y responsabilidades ciudadanas."},{"id":"18fb1ebf-baa1-46ff-9a42-9219e09e7572","name":"Normas y convivencia social."}]},{"id":"84bfde28-01bd-43df-9815-9e75b8d73efb","name":"Atribuciones del Poder Judicial","subthemes":[{"id":"d1ae407a-a56c-42e6-a083-3e7df9cc9cd8","name":"Función de impartir justicia."},{"id":"31396a44-2ed7-400a-bf91-a52d3a925d81","name":"Cumplimiento de leyes."},{"id":"347ea590-e9b0-4eef-a2e0-99f4ac7d991b","name":"Tribunales y jueces."}]},{"id":"57373a1b-8dab-482e-8a22-06eb3a831b0c","name":"Símbolos patrios","subthemes":[{"id":"8582dec0-bb9b-4346-9176-cc2cbcf23e10","name":"Bandera, escudo e himno nacional."},{"id":"914fa3e0-efd1-4aeb-abbf-c4fa50adf103","name":"Uso en actos cívicos."},{"id":"a7a3a8f5-d771-48d8-b321-3e1c01d288f5","name":"Significado y respeto."}]},{"id":"5144145e-340b-4ed9-b448-96bf20d14879","name":"Deberes fundamentales","subthemes":[{"id":"0ef33913-0681-41cb-8147-1cadc19ef0ae","name":"Respeto a la ley."},{"id":"1b481cfe-8fee-403a-9ad5-d1941442c344","name":"Participación social."},{"id":"3dc7fac7-4558-4599-910e-f0358332fabd","name":"Responsabilidad ciudadana."}]},{"id":"7219fa5b-3c88-4c9c-9f57-14780ca8e080","name":"Organización municipal","subthemes":[{"id":"cc4a3410-ad6d-4075-addc-ad6ff2baf003","name":"Qué es un municipio."},{"id":"9e43bd49-8659-458f-938f-39d63e536e8e","name":"Servicios comunitarios."},{"id":"4a5dd4f5-c12b-4d6c-acea-4f21f912f0b3","name":"Autoridades locales."}]},{"id":"a24b26e2-6f65-470a-aeff-d774f7aec6de","name":"Participación de sectores sociales y sociedad civil","subthemes":[{"id":"d6f0a54f-0849-4c2b-b83d-4a66977995c9","name":"Participación estudiantil y comunitaria."},{"id":"199e88c2-5d70-4fa7-9a3a-1f4392fb745e","name":"Trabajo colaborativo en la nación."},{"id":"2fce473a-4b41-43a7-9578-7eb2073ebf6d","name":"Organizaciones sociales y políticas."}]},{"id":"55ff6090-b740-48c0-8d5d-a9967e55cec5","name":"Deberes y derechos tributarios / Convivencia humana","subthemes":[{"id":"5370e172-23de-4828-adc2-72a1e684db97","name":"Qué son impuestos y para qué sirven."},{"id":"25db8f24-0194-4a1b-855e-b38a8108363b","name":"Convivencia basada en normas."},{"id":"b3757deb-cdc8-4267-aac1-19b679f84da3","name":"Responsabilidad ciudadana tributaria."}]},{"id":"b846cec7-ea63-4e8b-a046-86822a2687e0","name":"Cumplimiento de deberes y derechos","subthemes":[{"id":"8b04a12a-4403-446a-b55c-1b2e14664237","name":"Derechos ciudadanos básicos."},{"id":"08a33b0a-9ae4-44e9-8c7d-a4a4f748efef","name":"Respeto a leyes y normas."},{"id":"2a989442-9407-455c-bfe7-259a0fb08b3c","name":"Responsabilidades individuales."}]},{"id":"b36d8e90-b7fc-42bc-af89-104236c8e278","name":"Valores importantes para la convivencia","subthemes":[{"id":"7fabd1b1-c842-49d0-b896-3e7798b6d8d9","name":"Respeto y tolerancia."},{"id":"aeaf3881-d17d-4b63-8e59-8bbfc6d5ca81","name":"Honestidad y responsabilidad."},{"id":"935e2179-8b34-4744-adf6-2420ff14ecbf","name":"Solidaridad y empatía."}]},{"id":"d6bdcd81-7d68-4da6-ad40-78d96b9ee221","name":"Problemáticas viales y educación tributaria","subthemes":[{"id":"421f3cf6-ac9f-42ae-b597-1d6f2fe49f80","name":"Normas 