}]},{"id":"5941b68a-0882-4d4c-ac3c-6249e50c053b","name":"Diversidad, amistad y fraternidad","subthemes":[{"id":"b33aaff0-65d0-4e37-89a2-f9ff22ab11c5","name":"Respeto a la diversidad."},{"id":"ae8b7f98-6a1b-47c3-a4cc-b281bbf87a23","name":"La amistad como valor."},{"id":"3d901291-b1af-416c-9649-ef90c52f47d0","name":"La fraternidad y el compañerismo."}]},{"id":"ef7c9db4-6756-4761-b6f4-945b496cd8d5","name":"El valor de la vida humana","subthemes":[{"id":"89dfc7be-5000-4ea5-8eb1-b6e3af52160c","name":"Importancia de la vida humana."},{"id":"b6e8e81a-73fa-4a7b-a933-880d1a6b6328","name":"Respeto por la vida propia y ajena."},{"id":"f3c28ac7-d703-4dec-a4b4-2f142fa597f6","name":"Cuidado de la vida en todas sus etapas."}]},{"id":"bf8d09aa-1579-417c-9d0c-a2c77862816c","name":"El entorno natural como espacio creado por Dios para todos","subthemes":[{"id":"28050c4d-67bc-4a88-9ec5-8bd36ae66fc3","name":"La naturaleza como regalo de Dios."},{"id":"27a8ea0a-93eb-40f3-ad66-8858c001cbc2","name":"Uso responsable del entorno natural."},{"id":"a3e47198-e251-4126-872a-89c3d49350af","name":"Convivencia armoniosa con la creación."}]},{"id":"e00b1150-883c-471a-a1bc-7ba9efbd4294","name":"Jesús hace el bien a las personas","subthemes":[{"id":"4edf61ec-cd2b-4ebf-8ffb-993dead276d4","name":"Milagros y acciones buenas de Jesús."},{"id":"7e168f0f-b97f-4789-b1ce-95dd153b2e1c","name":"Jesús ayuda y sana a las personas."},{"id":"bf06fb78-ab68-47b8-b31b-83924a25d477","name":"Imitar a Jesús haciendo el bien."}]},{"id":"74952071-f627-43c1-aede-6586744b0419","name":"Normas de convivencia","subthemes":[{"id":"d23f1c13-0646-414d-98b3-9b0f08f65583","name":"Qué son las normas de convivencia."},{"id":"420872a1-48d2-4c27-bf92-3411e676e419","name":"Importancia de respetar las normas."},{"id":"02b8b13f-1a5f-481b-bdcd-19b06f13006e","name":"Consecuencias de cumplir o no las normas."}]},{"id":"57ff5317-641a-4539-bd1f-feaacc4b57a5","name":"La familia da y protege vida","subthemes":[{"id":"1a4ea1e0-ccf0-4b9e-89a4-e9bebba764cb","name":"La familia como espacio de cuidado."},{"id":"b338d69a-057c-4cd8-846c-5f5e62a15251","name":"La familia como espacio de cuidado."},{"id":"3bfcd8b4-70d2-4e46-bb1f-b45cdb2503ec","name":"Responsabilidad familiar con la vida."}]},{"id":"64a31a3d-f246-4607-85be-e79aa8195afb","name":"Jesús muere y resucita","subthemes":[{"id":"6064a489-2f65-466f-809b-2855a5abe4f9","name":"La muerte de Jesús en la cruz."},{"id":"c3ebbb1c-fdab-45e2-af75-c313dc55cb83","name":"La resurrección de Jesús."},{"id":"4f01a102-fe18-4493-a2b7-dca012948d51","name":"Significado de la Pascua cristiana."}]},{"id":"6a77787e-c0f1-4547-8650-b2e0815efeda","name":"Juego y diversión","subthemes":[{"id":"a5feb479-fbad-4a40-be5c-0363f4af7807","name":"El juego como forma de diversión sana."},{"id":"094a599b-4b61-4b43-903b-626e6ed00cee","name":"Compartir y respetar al jugar."},{"id":"b511f407-3ea3-4583-a7d8-10325fa6471d","name":"Equilibrio entre juego y responsabilidades."}]},{"id":"8611cf0f-28fe-45c4-9415-b14daab8ccbf","name":"Beneficios de la tecnología","subthemes":[{"id":"b16b6636-1bb2-4e88-bdc1-5acea5ef8a22","name":"Tecnología para aprender y comunicarse."},{"id":"e292d491-2c42-4ac5-aaa1-7968113aac19","name":"Tecnología en la vida diaria."},{"id":"95bfe1a9-df57-4269-8efd-23dbf6b07dee","name":"Uso responsable de la tecnología."}]},{"id":"38c78d45-f07b-4700-b962-6ba87c3f8baf","name":"Peligros contra la vida","subthemes":[{"id":"d65a9812-6002-47e9-b475-dc1b967af1c1","name":"Situaciones que ponen en riesgo la vida."},{"id":"7b5392c7-0b7e-4525-9149-bb22ee869188","name":"Cómo cuidarse y pedir ayuda."},{"id":"2ff3ae17-f835-4b99-826a-07ff643ff705","name":"Importancia de proteger la vida."}]}],"grade_levels":["3ro"],"subjectId":"formacion-humana","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"93c0c80f-e26a-49db-a555-ec30f3ac4103-block-1","themes":["Valores culturales y valores cristianos","Etapas de la vida de Jesús de Nazaret","Familia y valores cristianos","Ventajas y desventajas de los juegos electrónicos","La vida viene de Dios","Cuidado, respeto y protección de la creación","Las enseñanzas de Jesús","Buenas relaciones interpersonales en la familia y la escuela","Vivir como Jesús enseñó.","Familia y convivencia","Diversidad, amistad y fraternidad","El valor de la vida humana","El entorno natural como espacio creado por Dios para todos","Jesús hace el bien a las personas","Normas de convivencia","La familia da y protege vida","Jesús muere y resucita","Juego y diversión","Beneficios de la tecnología","Peligros contra la vida"],"conceptual":"-\tValores culturales y valores cristianos\n-\tEtapas de la vida de Jesús de Nazaret.\n-\tLas enseñanzas de Jesús. \n-\tEl nacimiento de Jesús. \n-\tJesús hace el bien a las personas. \n-\tJesús muere y resucita.\n-\tFamilia y valores cristianos.\n \n-\tBuenas relaciones interpersonales en la familia y la escuela. \n-\tFamilia y Convivencia.\n-\tNormas de convivencia.\n-\tJuego y diversión. \n-\tVentajas y desventajas de los juegos electrónicos\n-\tDiversidad, amistad y fraternidad.\n-\tBeneficios de la tecnología\n \n-\tLa vida viene de Dios. \n-\tEl valor de la vida humana. \n-\tLa familia da y protege vida.\n-\tPeligros contra la vida.\n-\tCuidado, respeto y protección por la creación.\n-\tEl entorno natural como espacio creado por Dios para todos.\n \n \n ","procedural":"-\tEscenificación del nacimiento de Jesús de Nazaret tomando como referencia textos bíblicos. \n-\tSocialización sobre las fiestas y tradiciones que vivió Jesús de Nazaret y su parecido con las locales apoyándose en el texto bíblico de Lucas 2,22 ss; 2,41ss. \n-\tExposición acerca de la manera en que su familia festeja la fiesta de la Navidad y otras fiestas y tradiciones. \n-\tDramatización de acciones de Jesús de Nazaret haciendo el bien a las personas apoyándose en textos bíblicos. \n-\tInvestigación acerca de qué se celebra durante la Semana Santa y cuáles actividades se realizan en su familia, su comunidad y en la sociedad dominicana. \n-\tPresentación de acontecimientos relacionados con la pasión, muerte y resurrección de Jesús de Nazaret de forma cronológica y usando diversas técnicas y recursos\n \n-\tIdentificación de valores culturales y cristianos presentes en su familia, escuela y en su entorno sociocultural a partir de textos bíblicos y otros textos.\n-\tIndagación de situaciones de violencia física, verbal y sexual que sufren personas en la familia, en la escuela o en la comunidad. \n-\tExplicación del cuidado, respeto y valoración de su cuerpo en su medio familiar, escolar, comunitario y social. \n-\tRepresentación sobre las características de la buena convivencia familiar.\n-\tExposición acerca de cómo las normas favorecen la convivencia entre las personas en los ambientes familiares, escolares, sociales y culturales.\n-\tOrganización de un espacio celebrativo en que se representen los aprendizajes desarrollados y se agradezca a Dios por la importancia de las normas para la convivencia armónica en la casa, la escuela y el entorno sociocultural.\n-\tDramatización donde se presenten juegos cooperativos e inclusivos que muestren la importancia del cumplimiento de normas. \n-\tIdentificación de elementos o situaciones que provocan desacuerdos y discusiones en el juego y la manera de resolver las situaciones de conflictos. \n-\tIdentificación del uso adecuado de los juegos electrónicos indicando sus ventajas y desventajas. \n-\tInvestigación sobre los beneficios que proporciona la tecnología a las personas.\n-\tDescripción de situaciones en las que puede mostrar su amistad sin distinción de personas, color, religión, raza, sexo, género o discapacidad. \n-\tSocialización de por qué debemos amarnos y respetarnos unos a otros como Dios manda, apoyándose en el texto bíblico Juan 13: 34.\n ","attitudinal":"-\tGratitud a Jesús de Nazaret por haber entregado su vida por amor a todas las personas. \n-\tAdmiracón hacia Jesús de Nazaret por perdonar a los que lo crucificaron. \n-\tDisposición para excusar y perdonar. \n-\tCultivo de valores cristianos y culturales en su vínculo con los demás en los diferentes entornos.\n-\tSensibilidad al escuchar el relato de la pasión, muerte y resurrección de Jesús de Nazaret. \n-\tSolidaridad, perdón y amor en las relaciones\n \n-\tRespeto y cariño por sus padres, madres, tutores/as y familiares.\n-\tDisfrute de los momentos festivos que realiza en su familia, escuela y comunidad.\n-\tAmabilidad en su relación con las demás personas.\n-\tRespeto, cortesía y buen trato a los demás\n-\tRespeto por las diferencias de sus compañeros\n-\tDisfrute y alegría por el juego, la amistad y el compartir. \n-\tAcogida y respeto a todo tipo de diversidad: prácticas religiosas, color, nacionalidad, limitaciones físicas, habilidades, sexo y género.\n-\tReconocimientos de sus errores y aprendizaje de éstos. \n \n-\tExposición acerca de la vida como regalo de Dios a través de diversos recursos (láminas, canciones, videos, dibujos, pinturas, murales). \n-\tSocialización sobre situaciones y acciones que dañan o ponen en peligro la vida. \n-\tExposición acerca de cómo Dios da la vida a las personas a partir del texto bíblico Génesis 2 y otros textos. \n-\tExposición acerca de las bondades del agua, los animales y las plantas para las personas y el equilibrio del entorno natural y cómo podemos cuidarlos y protegerlos. \n-\tExposición acerca de sus sentimientos al observar y explorar la naturaleza a través de sus sentidos (ver, sentir, oler, tocar, gustar, escuchar).\n-\tElaboración de dibujos, anuncios, frases, canciones, poesías, caricaturas, acrósticos, láminas que muestren el entorno natural como espacio creado por Dios para el disfrute de todos.\n-\tIdentificación de acciones humanas que benefician o dañan el entorno natural creado por Dios.\n-\tIdentificación de instituciones que realizan acciones de protección y cuidado de la naturaleza en su comunidad, provincia y el país.\n-\tRepresentación y realización de acciones de cuidado y protección del entorno natural creado por Dios para todos.\n-\tOrganización de un espacio en que se expongan los aprendizajes desarrollados sobre el cuidado y la protección del entorno natural y se agradece a Dios por las acciones que se pueden realizar para cuidarlo y protegerlo.\n \n "}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:20:36.185Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('86c66d21-ffd9-4d1a-bfa9-d18643432aa2', 'educacion-artistica', '1ro', '{"id":"86c66d21-ffd9-4d1a-bfa9-d18643432aa2","name":"Conceptos de unidad","themes":[{"id":"8b559298-bafe-4f90-95a2-6f0b2fc24fd0","name":"Juego de roles","subthemes":[{"id":"68e72d6a-e002-467f-9669-f69482e81ac6","name":"Representación de personajes."},{"id":"5379a31a-138f-4e8e-a6d6-0199a8f9a1e0","name":"Dramatización de situaciones cotidianas."},{"id":"82dfd3f0-148a-4b41-b315-53121b7d44ab","name":"Desarrollo de la imaginación y la creatividad."}]},{"id":"3b7a20d0-76ff-4bb8-badb-358ebd5e09d9","name":"Elementos del ritmo: pulso y acento","subthemes":[{"id":"a30b0c25-762a-4a66-9473-07b03be6c4cd","name":"Identificación del pulso musical."},{"id":"332b9acd-7863-419c-9ab5-c9453eb3f047","name":"Reconocimiento del acento en la música."},{"id":"e81b290a-e039-49ea-82df-c559537bc17d","name":"Movimiento corporal siguiendo el ritmo."}]},{"id":"e3d9db05-4806-4184-aad8-87d06ccacd30","name":"Canciones escolares y folklóricas","subthemes":[{"id":"14ab2191-8786-49e1-a5d1-a6238785c6c7","name":"Interpretación de canciones escolares."},{"id":"367e9fd5-224a-4124-9300-e00744485b21","name":"Canciones folklóricas dominicanas."},{"id":"6f6d8a51-0676-4359-b934-310ed0c842a7","name":"Valor cultural de las canciones."}]},{"id":"11ff6089-0881-4818-b8b2-31f668b287c6","name":"Figuras musicales y lectoescritura musical","subthemes":[{"id":"6301e8dc-ae20-4294-8766-f5676c47f4c0","name":"Reconocimiento de figuras musicales básicas."},{"id":"06def4e3-e8c6-46d2-9f9f-2f88b09810e2","name":"Lectura sencilla de ritmos."},{"id":"edafb781-e636-4bd4-b8f9-a2d1bd9433b8","name":"Escritura básica de símbolos musicales."}]},{"id":"028dd84c-8c74-425a-8057-e4fea2668478","name":"Percepción auditiva","subthemes":[{"id":"588ad73b-f60b-4ebd-a816-9c23cd4e58af","name":"Reconocimiento de sonidos del entorno."},{"id":"b3708187-5e7e-4f19-a417-95fa02104be2","name":"Diferenciación de sonidos fuertes y suaves."},{"id":"5fedc3a0-64c4-4d6f-a3b9-eee14b443663","name":"Atención y escucha activa."}]},{"id":"c5205721-a958-4442-8c53-6769e55abd3e","name":"Ilustración","subthemes":[{"id":"da0d1dec-47b5-4eda-8ca2-bc202b681322","name":"Ilustración de cuentos y canciones."},{"id":"2597bae3-4e81-4570-b59c-3c06b7d71276","name":"Uso de colores y formas en ilustraciones."},{"id":"782f1144-833b-4053-81a6-7e0d3f763d6a","name":"Expresión artística a través del dibujo."}]},{"id":"729ee93c-63e7-40c0-aa78-dd3b46e79cf5","name":"Cuerpo y movimiento","subthemes":[{"id":"df5b3849-75cf-4e09-aef2-3b60473da297","name":"Movimientos básicos del cuerpo."},{"id":"571c7192-fe85-4067-8918-89814c058891","name":"Coordinación corporal en el espacio."},{"id":"5fb6ba8b-5496-44f9-b674-056b9ad70931","name":"Control del cuerpo en actividades expresivas."}]},{"id":"98923871-df9b-4693-ab33-25d0291617ac","name":"Auto-representación con imágenes y objetos","subthemes":[{"id":"1c196b95-7049-42a3-9ad5-c4ec423a44d8","name":"Representación de sí mismo con dibujos."},{"id":"72f0e32f-f5d6-4f2d-8b1b-7c9757ae0a15","name":"Uso de objetos para expresarse."},{"id":"e9422dfb-ad69-412d-acb8-95770b76277d","name":"Identidad y expresión personal."}]},{"id":"08af390d-33a0-4b5f-a2ef-88cbb0de4dd5","name":"Representación gráfica de espacios","subthemes":[{"id":"7f5c7071-7ff0-40ae-bf60-429e8011cf37","name":"Dibujo de espacios interiores."},{"id":"7fb1d30b-28b6-47e3-a1de-4aa54af17357","name":"Dibujo de espacios exteriores."},{"id":"e4add7e1-24ed-4ebc-b293-2694f68f7f82","name":"Representación de espacios virtuales."}]},{"id":"c529cddb-c659-4b84-bae2-1b27969ed463","name":"Formas, figuras y colores en juegos tradicionales","subthemes":[{"id":"a5da51b5-d751-4846-a1f1-04349a3246e1","name":"Identificación de formas y figuras."},{"id":"6b083418-626b-4988-8a2d-94db7efb2507","name":"Uso de colores en juegos tradicionales."},{"id":"8ad84bd4-d998-4e7f-8b4e-f86524c15481","name":"Relación entre juego y expresión visual."}]},{"id":"af25e795-3b12-44a8-86fa-11cfa3e4d594","name":"Expresión corporal–gestual","subthemes":[{"id":"76ebf4b9-7dee-4df0-a95f-805f0b3898c6","name":"Gestos para expresar emociones."},{"id":"ff1d8276-6be5-4913-a439-6a4ba7c89e26","name":"Uso del cuerpo para comunicar ideas."},{"id":"b83e42ae-998f-4e3e-98b3-fca87e143eab","name":"Expresión corporal en juegos y dramatizaciones."}]},{"id":"937464ba-3dbb-4ce9-883d-e4895b9b061d","name":"Teatro de títeres","subthemes":[{"id":"be82c764-76eb-4f43-baef-7131888597c5","name":"Creación de títeres."},{"id":"296f116d-29e5-4993-ad18-c559e9763c1a","name":"Representación de historias con títeres."},{"id":"1f6ac4cd-46ff-4da4-8a3a-811cdeb01f48","name":"Expresión oral y corporal a través del títere."}]},{"id":"653c8e5e-0e5f-4549-bd0e-bcf12424c80b","name":"Juegos de ronda","subthemes":[{"id":"db94a836-9e59-44d9-a800-19e8716c5f83","name":"Participación en juegos de ronda tradicionales."},{"id":"9c7f56c7-3f85-437c-a7ad-4d84432050b5","name":"Coordinación y ritmo en juegos colectivos."},{"id":"6679893f-f8e6-4798-8f05-af6048620641","name":"Respeto de reglas en juegos grupales."}]},{"id":"b410ebb7-b339-420d-a01e-622db59a6d62","name":"El juego dramático","subthemes":[{"id":"4f7f0a20-d6da-401d-8c50-3f7e22e9b46b","name":"Representación libre de historias."},{"id":"7d2ebc8c-8a44-44c5-a9c6-36395b3feb92","name":"Expresión de emociones mediante el drama."},{"id":"ae491462-b265-4d11-9885-85810c3c6cf9","name":"Creatividad en la actuación."}]},{"id":"ddc45138-b9d9-4aee-bd5d-7d744b1692d6","name":"La música nos mueve","subthemes":[{"id":"1e84f5b3-46a6-4adf-8284-6cb4c3d0e4c7","name":"Creando pasos nuevos con la música"}]}],"grade_levels":["1ro"],"subjectId":"educacion-artistica","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"86c66d21-ffd9-4d1a-bfa9-d18643432aa2-block-1","themes":["Juego de roles","Elementos del ritmo: pulso y acento","Canciones escolares y folklóricas","Figuras musicales y lectoescritura musical","Percepción auditiva","Ilustración","Cuerpo y movimiento","Auto-representación con imágenes y objetos","Representación gráfica de espacios","Formas, figuras y colores en juegos tradicionales","Expresión corporal–gestual","Teatro de títeres","Juegos de ronda","El juego dramático","La música nos mueve"],"conceptual":"-\tCuerpo y movimiento.\n-\tExpresión corporal- gestual.\n-\tJuego de roles.\n-\tPercepción auditiva.\n-\tAuto- representación con imágenes y objetos.\n-\tTeatro de títeres.\n-\tElementos del ritmo: pulso y acento.\n-\tRepresentación gráfica de espacios: interiores, exteriores y virtuales.\n-\tJuegos de ronda («Las cortinas del palacio», «El gato y el ratón», «La cinta»).\n-\tCanciones escolares y folklóricas.\n-\tFormas, figuras y colores presentes en juegos tradicionales.\n-\tEl juego dramático.\n-\tFiguras musicales y lectoescritura musical.\n-\tIlustración.\n ","procedural":"-\tRealización de juegos de roles, utilizando expresiones faciales, gestos corporales y su relación con distintos estados de ánimo.\n-\tExploración de sonidos vocales, corporales y del entorno.\n-\tIdentificación de imágenes y situaciones presentes en cuentos, canciones, películas, espectáculos diversos y objetos, representándolas creativamente.\n-\tElaboración y manipulación de títeres (con materiales de fácil acceso).\n-\tExploración del ritmo en el cuerpo, la naturaleza, el habla y la música.\n-\tUtilización del cuerpo para la reproducción o creación de patrones rítmicos, sonoros o de movimientos.\n-\tReconocimiento de elementos en espacios interiores, exteriores y virtuales, representándolos a través de distintas técnicas como el dibujo, pintura y modelado.\n-\tRealización de juegos de ronda.\n-\tReproducción de sonidos musicales y ecos melódicos.\n-\tInterpretación de canciones escolares y folklóricas a través de juegos musicales.\n-\tCreación de juegos diseñados para espacios exteriores o interiores.\n-\tDiseño y elaboración de utilerías y accesorios presentes en juegos propios y tradicionales usando diversos materiales del entorno y de fácil acceso.\n \n-\tRealización de juegos dramáticos integrando juegos de ronda, juegos de roles y títeres, siguiendo instrucciones del uso del ritmo y el espacio.\n-\tReconocimiento de la figura «negra» como valor rítmico de un pulso.\n-\tReconocimiento, lectura y entonación de las notas Sol -Mi en el bigrama (de dos líneas horizontales).\n-\tIlustración gráfica de informaciones tomadas de distintas fuentes (textos, ideas, sonidos y vivencias). \n ","attitudinal":"-\tAutovaloración de sus capacidades cognitivas y sensoriales.\n-\tExpresión libre de las ideas, sentimientos y emociones.\n-\tFortalecimiento de la autoestima y de la identidad personal y social.\n-\tValoración y respeto de su cuerpo y su voz.\n-\tInterés cognitivo por el ritmo propio de su cuerpo, la naturaleza, el lenguaje hablado y la música.\n-\tConciencia del uso racional del espacio individual y colectivo.\n-\tDisposición para hacer acuerdos y respetar las reglas de juego.\n-\tConfianza al cantar de manera individual o grupal, en público.\n "}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:20:36.185Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('3607bdcf-b1b3-43b8-9a63-d0ef181f301a', 'educacion-artistica', '2do', '{"id":"3607bdcf-b1b3-43b8-9a63-d0ef181f301a","name":"Conceptos de unidad","themes":[{"id":"b4c48745-7595-4991-b66f-f3144a21b25c","name":"Movimiento rítmico corporal","subthemes":[{"id":"6607ec66-130d-4d5a-8f30-defd6d6f9e00","name":"Movimiento del cuerpo siguiendo el ritmo."},{"id":"9d50caf0-c7ff-4ff8-9f78-e27c6e7f0dce","name":"Coordinación corporal con música."},{"id":"cff370c3-0933-46b1-b5d4-fc4b737020a3","name":"Expresión corporal a través del movimiento."}]},{"id":"32b54f17-2d0b-44ad-92ed-046a60fb48b2","name":"Cualidades del sonido: timbre e intensidad","subthemes":[{"id":"e97774c1-5b8f-4386-8537-db64496e5b37","name":"Sonidos fuertes y suaves."},{"id":"7464dd5b-391b-4678-a3d2-dfb86ec58011","name":"Diferentes timbres de sonido."},{"id":"d81761a9-a075-4731-88e5-234319519a15","name":"Reconocimiento de sonidos del entorno."}]},{"id":"2e61a778-77dd-4486-887c-1b01f541742b","name":"Imágenes visuales fijas y en movimiento","subthemes":[{"id":"0ad7757e-c897-471c-bcc2-6f69129ad7a3","name":"Imágenes fijas y su significado."},{"id":"80f1d942-6680-4ad1-a443-ac9724b929d1","name":"Imágenes en movimiento."},{"id":"d943274c-c3bb-4fd7-a5b7-a1cedc466bc7","name":"Uso de imágenes para comunicar ideas."}]},{"id":"2bcdb6db-2da3-4e4c-8044-1216b700f642","name":"El carnaval dominicano","subthemes":[{"id":"d0b16a1d-c732-40d9-8503-22314e9f783a","name":"Origen del carnaval dominicano."},{"id":"025ba92e-e122-40f5-b1c0-a1be0d8b5051","name":"Personajes y tradiciones del carnaval."},{"id":"d624e0c4-b687-48ee-a62e-4eaaa94361b5","name":"Importancia cultural del carnaval."}]},{"id":"288f7522-9945-48b2-9d00-839c42eb71a1","name":"Elementos fundamentales del ritmo","subthemes":[{"id":"ac323f98-ff1e-4f06-bfc5-33a052d3611c","name":"Pulso y acento."},{"id":"203bf808-cc6d-4762-93b5-571d99b5bee1","name":"Repetición de patrones rítmicos."},{"id":"33c101d1-83f9-44ef-9658-2719102c0037","name":"Ritmo rápido y lento."}]},{"id":"c01c954b-887d-465a-a165-fe979b87c345","name":"Collage y modelado","subthemes":[{"id":"a8c22d18-01b5-4cd2-b8e9-8fb0f6b3f2c3","name":"Uso de materiales para collage."},{"id":"1a220076-296f-4646-b943-1bf7ab882e8a","name":"Expresión creativa a través del collage y el modelado."},{"id":"f9ca211e-9ab9-40c6-b5f1-bb25dbc6e3fd","name":"Modelado con diferentes materiales."}]},{"id":"a94d8a37-030a-4af6-ae46-241577c0e779","name":"Pregones dominicanos y sus personajes","subthemes":[{"id":"a96b4fc4-8239-45c4-89a1-aef23a92b6d4","name":"Qué son los pregones."},{"id":"2432dcd3-00a1-48f7-9c02-bcb2f463bb5a","name":"Valor cultural de los pregones."},{"id":"7a8788b4-e76c-4cca-8ac6-22e6d66ff7fa","name":"Personajes de los pregones dominicanos."}]},{"id":"5c21cf65-bf88-4ee9-bf7d-79ca668012bd","name":"Instrumentos musicales: percusión menor y folklórica","subthemes":[{"id":"2f265df3-e5e1-4cae-814a-7eb2ef18924a","name":"Instrumentos de percusión menor."},{"id":"38dbf548-81d3-4953-a7c1-e514300637c7","name":"Uso de instrumentos para acompañar ritmos."},{"id":"bd6e3383-9857-41b1-8fe4-66e29c535893","name":"Instrumentos folklóricos dominicanos."}]},{"id":"8e5be8aa-a8fd-4777-813c-e3768b70cba1","name":"Máscaras y vestuarios","subthemes":[{"id":"b3d065d3-4bdf-4cd7-9d46-5d1ce02bf764","name":"Elaboración de máscaras."},{"id":"1465b52a-721e-4ec4-b36a-05508252c836","name":"Uso de máscaras y vestuarios en celebraciones."},{"id":"f74ef9ec-eeb7-4b91-b09e-250aef95bdb0","name":"Diseño de vestuarios."}]},{"id":"58ca32ea-ebfd-4ef6-b509-b02eb84e06f3","name":"La comparsa carnavalesca","subthemes":[{"id":"c13d84ee-e184-45ce-a696-82f40643d9b5","name":"Qué es una comparsa."},{"id":"1092405d-8d14-4e52-a385-60d0dabb2670","name":"Participación en desfiles carnavalescos."},{"id":"f80271ab-8619-4347-9864-43d441d08a44","name":"Organización de una comparsa."}]},{"id":"c52b10ac-3eae-4d97-b153-8ccde85fe25d","name":"Banda rítmica","subthemes":[{"id":"9558c72b-e4cc-4fe5-88e7-a2b896d8ab54","name":"Instrumentos de una banda rítmica."},{"id":"daa593f0-9fa5-4c4c-b5d3-4d42cb88aa56","name":"Presentación de una banda rítmica."},{"id":"d96acd25-64f0-4fa5-9023-8010f331d720","name":"Coordinación rítmica en grupo."}]},{"id":"b6d87d70-9b49-491a-b3fa-24b049aed719","name":"Cartel","subthemes":[{"id":"925568c6-d9a3-4564-a235-05b821a4265e","name":"Función del cartel."},{"id":"54c9cf7d-dd78-4386-be7d-3b66eb9ec1b3","name":"Elaboración de carteles creativos."},{"id":"2c0dc333-fb0e-4702-a48e-e11be4ec13f6","name":"Elementos del cartel (imagen y texto)."}]}],"grade_levels":["2do"],"subjectId":"educacion-artistica","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"3607bdcf-b1b3-43b8-9a63-d0ef181f301a-block-1","themes":["Movimiento rítmico corporal","Cualidades del sonido: timbre e intensidad","Imágenes visuales fijas y en movimiento","El carnaval dominicano","Elementos fundamentales del ritmo","Collage y modelado","Pregones dominicanos y sus personajes","Instrumentos musicales: percusión menor y folklórica","Máscaras y vestuarios","La comparsa carnavalesca","Banda rítmica","Cartel"],"conceptual":"-\tMovimiento rítmico corporal.\n-\tCualidades del sonido: timbre e intensidad.\n-\tImágenes visuales fijas y en movimiento.\n-\tEl carnaval dominicano.\n-\tElementos fundamentales del ritmo\n-\tCollage y modelado.\n-\tPregones dominicanos y sus personajes.\n-\tInstrumentos musicales: percusión menor y folklórica.\n-\tMáscaras y vestuarios.\n-\tLa comparsa carnavalesca.\n-\tBanda rítmica.\n-\tCartel.\n \n-\tMovimiento rítmico corporal.\n-\tCualidades del sonido: timbre e intensidad.\n-\tImágenes visuales fijas y en movimiento.\n-\tEl carnaval dominicano.\n-\tElementos fundamentales del ritmo\n-\tCollage y modelado.\n-\tPregones dominicanos y sus personajes.\n-\tInstrumentos musicales: percusión menor y folklórica.\n-\tMáscaras y vestuarios.\n-\tLa comparsa carnavalesca.\n-\tBanda rítmica.\n-\tCartel.\n \n ","procedural":"-\tRepresentaciones rítmicas corporales a partir de textos, imágenes y sonoridades.\n-\tProducción de sonidos con diferentes timbres e intensidad o volumen.\n-\tDecodificación de mensajes a partir de imágenes visuales fijas (fotografía, historietas, gráficas) y en movimiento (video, animación, película).\n-\tConstrucción de un mensaje utilizando imágenes fijas y en movimiento con recursos disponibles (gráficos y/o tecnológicos).\n-\tConstrucción de instrumentos de percusión menor.\n-\tRepresentaciones carnavalescas de teatro y danza.\n-\tReconocimiento y expresión del pulso, el acento y la línea rítmica en un trozo musical utilizando la voz, el cuerpo e instrumentos musicales de percusión.\n-\tCreación de ensambles utilizando collage y/o modelado para generar nuevas formas.\n-\tRepresentación de personajes de pregones dominicanos, utilizando algunos elementos de vestuario, utilería, títeres y máscaras.\n-\tExploración y producción de sonidos percutiendo o sacudiendo cuerpos de metal, de madera y membrana y diversos materiales del ambiente.\n-\tIdentificación de instrumentos de percusión menor en diferentes géneros musicales.\n-\tCreación de comparsas de carnaval.\n-\tEjecución instrumental en la banda rítmica escolar.\n-\tPresentación en público de la banda rítmica.\n-\tIdentificación de una situación (necesidad o problema) a partir de la cual diseña un cartel persuasivo que haga uso del texto y la imagen de manera efectiva. ","attitudinal":"-\tAprecio por las posibilidades expresivas de su cuerpo.\n-\tLibertad de expresar sus emociones y sentimientos a través del arte.\n-\tSensibilidad auditiva.\n-\tPensamiento \ncrítico y creativo al discernir mensajes y comunicarlos.\n-\tEntusiasmo al participar en trabajos colaborativos.\n-\tDisfrute de actividades rítmicas individuales o colectivas.\n-\tCreatividad al construir un ensamble y satisfacción al transferir el concepto a otros aspectos de la vida.\n-\tDisfrute al participar en juegos y actividades artísticas individuales y grupales.\n-\tValoración de su entorno y de las expresiones culturales dominicanas.\n "}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:20:36.185Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('ddc997c5-c604-40be-a4cc-03838da53a27', 'educacion-artistica', '3ro', '{"id":"ddc997c5-c604-40be-a4cc-03838da53a27","name":"Conceptos de unidad","themes":[{"id":"1065fb65-3543-402f-80a2-d576e2bdca6f","name":"La voz: proyección y dicción","subthemes":[{"id":"6f204e96-81e8-4a7f-a25b-ded8e20065e0","name":"Uso adecuado de la voz al hablar y cantar."},{"id":"9ffac70c-c9a7-4ed2-b500-6fe84f6d97fa","name":"Pronunciación clara de palabras (dicción)."},{"id":"25cb45d9-4eb0-4a49-9d8d-99ea641ea663","name":"Pronunciación clara de palabras (dicción)."}]},{"id":"655abacf-70f0-4558-a9a9-a41fe63a0151","name":"Instrumentos musicales: cuerdas frotadas, punteadas y percutidas","subthemes":[{"id":"8b9d128b-fe0d-4080-b04e-8fd0fa19961c","name":"Instrumentos de cuerdas frotadas."},{"id":"786f7b0c-e10f-406a-bbc2-5cdac3c4b983","name":"Instrumentos de cuerdas punteadas."},{"id":"6153beaf-d23e-4868-b14a-5d8fea11a11d","name":"Instrumentos percutidos."}]},{"id":"d0926ee8-0031-4da8-a4bc-922a939fbdd7","name":"La trama en las artes escénicas","subthemes":[{"id":"5deccb32-cd93-44ab-9712-30922a75637f","name":"Inicio, desarrollo y final de una historia."},{"id":"144cc175-b4f9-4324-8934-a70a47420ac5","name":"Organización de la trama teatral."},{"id":"f0add3ae-0151-44f1-a414-1674bcac4617","name":"Representación escénica de la trama."}]},{"id":"07e2a37f-bc2c-4c6e-b151-20b12eac5ec1","name":"Conjunto vocal e instrumental: el coro y la banda rítmica","subthemes":[{"id":"4dc64a03-fdb6-4a61-bb07-14b7c956caa7","name":"El coro y el canto en grupo."},{"id":"049731a3-1036-4a7f-b72f-ccea81d2548f","name":"La banda rítmica y sus instrumentos."},{"id":"7b9b39fc-4418-4667-97b6-df82970e3db8","name":"Coordinación y trabajo en conjunto."}]},{"id":"c27b723f-cacb-4138-b152-7859001208cf","name":"Colores fríos y calientes","subthemes":[{"id":"4b574dd9-0218-4ada-a1ed-721ada2d4319","name":"Identificación de colores calientes."},{"id":"78164d18-39da-40b2-ad29-f7a6a363201c","name":"Uso de colores fríos y calientes en el arte."},{"id":"a2f3b35c-4343-4736-b1bb-03e63c004094","name":"Identificación de colores fríos."}]},{"id":"2f07eb38-55f9-4198-aeec-ccb9b4cc1158","name":"El conflicto en textos, danzas y dramatizaciones","subthemes":[{"id":"5a90a53f-0df1-4e5d-bd4c-f2d149048441","name":"Qué es el conflicto en una historia."},{"id":"71d076aa-9cc5-4cc9-a8a0-2722ce79e729","name":"Representación del conflicto mediante el cuerpo y la danza."},{"id":"a3177d8e-6576-4a5b-85e5-487dd66c2ebc","name":"Representación del conflicto mediante el cuerpo y la danza."}]},{"id":"58974295-54a1-45fd-be1e-21ea20a12aa6","name":"Cualidades del sonido: duración y altura o tono","subthemes":[{"id":"52c77fc1-f2ad-42a2-a6bd-f5fb71cb05b1","name":"Sonidos largos y cortos."},{"id":"16278e98-6551-4192-97f8-03dbdeef8e46","name":"Sonidos agudos y graves."},{"id":"12852e07-36e8-4729-9c93-f36c2e1cd473","name":"Reconocimiento del tono en la música."}]},{"id":"2d5f3135-8815-41a0-9f70-c9d8cfed1b73","name":"Artesanía y reciclaje","subthemes":[{"id":"2a8284f3-cc1a-49eb-b426-ba25db956df8","name":"Elaboración de artesanías con materiales reciclados."},{"id":"f24a324d-c521-4a12-ac25-8f4b00d3c812","name":"Importancia del reciclaje en el arte."},{"id":"af6f7695-0827-417e-80bc-5e2d0b5d409b","name":"Creatividad y cuidado del medio ambiente."}]},{"id":"e14ccded-34b2-474e-bd2f-5a745c317774","name":"La comedia en las artes escénicas","subthemes":[{"id":"cb751939-42ca-4df1-b1ee-1ddb73567487","name":"Características de la comedia."},{"id":"224718ce-ceaf-44ea-af1d-b7d436f96172","name":"Expresión del humor en el teatro."},{"id":"84aea4b4-2ed8-430f-8986-6879bc9d3433","name":"La risa como forma de comunicación."}]},{"id":"0b89f829-b00a-47a1-babe-4489071683bc","name":"Paisaje rural y urbano","subthemes":[{"id":"235d8218-c782-4444-96b3-45a0b6737a14","name":"Características del paisaje rural."},{"id":"c1edfc87-bb94-4a1f-97c4-50ae32c22fc2","name":"Características del paisaje urbano."},{"id":"c5cec0a1-d631-4da6-a231-7f1fdd72142d","name":"Características del paisaje urbano."}]},{"id":"2d13bcee-0ea6-4359-be24-585528dd93a2","name":"Danzas populares del mundo","subthemes":[{"id":"3ea5e87f-6059-456e-b6ec-187b9bfd2a27","name":"Danzas populares del mundo"},{"id":"5317cb54-3fc2-4419-aab9-adb4799962a7","name":"Danzas populares de África."},{"id":"abd9a166-9213-455c-8088-b4b8ee4e721e","name":"Danzas populares de las Antillas."}]},{"id":"ecae9b12-0638-4c38-9982-5e02bb24e658","name":"Elementos fundamentales del ritmo","subthemes":[{"id":"867da28a-8105-4a50-af8d-89a0b8a892d4","name":"Pulso y acento rítmico."},{"id":"a5e7b800-c3e8-47ab-8a81-4d0e38b02696","name":"Línea rítmica y ostinato."},{"id":"20c4aae8-8c73-40fd-9d1b-a2e019e9681d","name":"Repetición de patrones rítmicos."}]},{"id":"18b278ed-e54b-4a87-ae35-2c1414b65f4b","name":"El cuerpo expresivo","subthemes":[{"id":"b4a80185-d53e-4494-bf1e-3cb497208ecb","name":"El cuerpo como medio de expresión artística."},{"id":"a49755af-eb29-422a-a8a9-352cd4edef1b","name":"Expresión de emociones a través del movimiento."},{"id":"4279da05-726a-49c0-b7aa-2b2697c8e82c","name":"Uso del cuerpo en dramatizaciones y danzas."}]},{"id":"c3611958-a6f6-408b-88d4-d68029e2ba6f","name":"La técnica del clown (payaso)","subthemes":[{"id":"27e4ed0b-a7cb-4247-9318-4ee91112dcf8","name":"Características del clown."},{"id":"dd4f6cad-9e95-400f-8f72-18ea5fc2dc78","name":"Expresión corporal y gestual del payaso."},{"id":"01ee39b9-593d-4dac-b016-acbee3c349c3","name":"Uso del humor y la exageración."}]},{"id":"2e7700e3-d922-4909-b5af-9c0a9e5a4857","name":"Cultura dominicana y foránea","subthemes":[{"id":"c5b99f04-7c26-4f49-be4a-9a3d80f32c37","name":"Manifestaciones culturales dominicanas."},{"id":"147e19e4-f1f5-4108-8330-8c377b15be64","name":"Manifestaciones culturales de otros países."},{"id":"ee6cae0b-478c-40f1-8c89-6bc2fa468680","name":"Respeto y valoración de la diversidad cultural."}]}],"grade_levels":["3ro"],"subjectId":"educacion-artistica","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"ddc997c5-c604-40be-a4cc-03838da53a27-block-1","themes":["La voz: proyección y dicción","Instrumentos musicales: cuerdas frotadas, punteadas y percutidas","La trama en las artes escénicas","Conjunto vocal e instrumental: el coro y la banda rítmica","Colores fríos y calientes","El conflicto en textos, danzas y dramatizaciones","Cualidades del sonido: duración y altura o tono","Artesanía y reciclaje","La comedia en las artes escénicas","Paisaje rural y urbano","Danzas populares del mundo","Elementos fundamentales del ritmo","El cuerpo expresivo","La técnica del clown (payaso)","Cultura dominicana y foránea"],"conceptual":"-\tEl cuerpo expresivo.\n-\tLa voz: proyección y dicción.\n-\tEl conflicto en textos, danzas y dramatizaciones.\n-\tCualidades del sonido: duración y altura o tono.\n-\tArtesanía y reciclaje\n-\tLa comedia en las artes escénicas.\n-\tLa técnica del clown (payaso).\n-\tInstrumentos musicales: cuerdas frotadas, punteadas y percutidas. - Paisaje rural y urbano.\n-\tDanzas populares del mundo (al menos una de Europa, una africana y otra de las Antillas).\n-\tElementos fundamentales del ritmo: pulso, acento, línea y ostinato rítmico.\n-\tCultura dominicana y foránea.\n \n-\tLa trama en las artes escénicas.\n-\tConjunto vocal e instrumental: el coro y la banda rítmica.\n-\tColores fríos y calientes\n \n ","procedural":"-\tRepresentación de movimientos corporales creando imágenes con sentido.\n-\tCreación y escenificación de obras breves, inspiradas en relatos de su entorno y sucesos históricos.\n-\tJuegos y ejercicios de vocalización y dicción.\n-\tExploración de sonidos de diferente duración y altura.\n-\tUso del reciclaje en la solución de necesidades expresivas (arte- objetos, accesorios, murales, entre otros).\n-\tRepresentación de personajes y escenas de comedias dominicanas.\n-\tClasificación de los instrumentos de cuerda.\n-\tElaboración de instrumentos con materiales reciclados del ambiente para utilizarlos en bandas rítmicas.\n-\tInterpretación de paisajes rurales y urbanos, integrando características culturales por medio de distintas técnicas (collage, maqueta, dibujo, pintura, entre otros).\n-\tEjecución de coreografías sencillas, aprendiendo la manera de bailar algunos ritmos populares del mundo (polka, baile de la cinta, entre otros).\n-\tReproducción de líneas rítmicas y ostinatos.\n-\tInvestigación sobre diversas manifestaciones culturales foráneas, relacionándolas con características culturales dominicanas. \n \n-\tCreación colectiva de teatro, títeres, canto y danza.\n-\tPráctica vocal e instrumental: el coro y la banda rítmica.\n-\tUtilización de los colores fríos y calientes en sus obras (dibujos, pinturas, collage, fotografía, entre otros) asociándolos a distintos referentes (emocionales, sociales, culturales).\n-\tDifusión de sus investigaciones artísticas.\n ","attitudinal":"-\tDisfrute de las posibilidades expresivas del cuerpo y la voz.\n-\tValoración de la capacidad de percepción de sonoridades.\n-\tConciencia ambiental en la creación artística.\n-\tTrabajo cooperativo en actividades y proyectos artísticos grupales.\n-\tTolerancia y respeto por la diversidad en la expresión personal y artística.\n-\tCuriosidad y apertura por conocer diversas culturas.\n-\tObjetividad al argumentar sus elecciones y asociaciones con criticidad y al emitir opiniones artísticas.\n "}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:20:36.185Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('1e20c530-40d3-42c3-99a0-15b1fa59bb92', 'educacion-artistica', '4to', '{"id":"1e20c530-40d3-42c3-99a0-15b1fa59bb92","name":"Educación Musical","themes":[{"id":"fbaf828c-881b-4826-a156-9d9997711660","name":"El tiempo en la música: el ritmo y sus elementos: pulso, acento y velocidad (lento y rápido).","subthemes":[{"id":"585c2c72-4251-4f20-a8ae-37f14e4efbc9","name":"El ritmo como organización del tiempo en la música."},{"id":"c9107b6a-715a-4bc9-b62f-77dee296e5ea","name":"El pulso musical y su reconocimiento corporal."},{"id":"2ea2fc96-719a-4229-b64a-83822f287916","name":"El acento en el ritmo musical."},{"id":"168b906c-2159-4ce3-a036-e09c00e2e917","name":"La velocidad del ritmo: lento y rápido."},{"id":"bb29209a-8591-4ab8-93cb-177ac0df9e4f","name":"Coordinación del movimiento corporal con el ritmo musical."}]}],"grade_levels":["4to"],"subjectId":"educacion-artistica","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"1e20c530-40d3-42c3-99a0-15b1fa59bb92-block-1","themes":["El tiempo en la música: el ritmo y sus elementos: pulso, acento y velocidad (lento y rápido)."],"conceptual":"\"Educación Musical\"\n- El tiempo en la música: el ritmo y sus elementos: pulso, acento y velocidad (lento y rápido).\n ","procedural":"\"Educación Musical\"\n-\tRespiración diafragmática como elemento para una adecuada emisión de la voz.\n-\tArticulación y dicción en la voz cantada o hablada.\n ","attitudinal":" "}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:20:36.185Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('93024824-0340-441e-999b-7901d291b52d', 'educacion-fisica', '4to', '{"id":"93024824-0340-441e-999b-7901d291b52d","name":"Conceptos de unidad","themes":[{"id":"a58dd6cb-1ed5-4970-be67-458ad6b20d7b","name":"El cuerpo como medio de expresión y comunicación","subthemes":[{"id":"36877766-88bf-4592-ba6c-f10056f2f1ba","name":"El gesto y la mímica para expresar emociones e ideas."},{"id":"f45cdb31-671c-4112-b528-e7372f80ef45","name":"El movimiento corporal como forma de comunicación."},{"id":"bd02f9f6-9e78-4216-973d-810a81f01d33","name":"La expresión corporal en juegos y dramatizaciones."},{"id":"dcefc3a9-1a5a-4875-9170-678330fb3ce6","name":"El ritmo corporal: pulso, acento y compás."},{"id":"f7a12a01-a0bd-464a-80d2-302dfd043d09","name":"Coordinación del cuerpo con la música y el movimiento."}]},{"id":"6ed060a9-4d70-4424-bd06-55a35a65a172","name":"Capacidades condicionales","subthemes":[{"id":"007bdf55-ed07-4c7f-973e-ff5b95ab5909","name":"Velocidad del movimiento: gestual, de reacción y de desplazamiento."},{"id":"e13b6bf3-72eb-46e1-a850-434092ff3e0c","name":"Flexibilidad y movilidad corporal."},{"id":"7a2b1853-543b-4888-a4d5-29cea9a8cefd","name":"Resistencia aeróbica y cuidado de la condición física."}]},{"id":"6799d041-1358-4397-9979-6c133b1f8acb","name":"Habilidades motrices básicas","subthemes":[{"id":"3ea53a9d-35da-407d-a9a4-c3cd5aa2842d","name":"Desplazamientos básicos: caminar, correr y marchar."},{"id":"ef979801-e4ec-4ee5-8cc3-53a4a6a38a27","name":"Saltos y desplazamientos variados: saltar en horizontal, vertical y en profundidad, reptar y rodar."},{"id":"ac7c5b00-0d6b-4a25-b556-3ef4e9f59884","name":"Movimientos de exploración del espacio: trepar y desplazarse en diferentes direcciones."}]},{"id":"bd5c0b49-11a1-42d9-85b6-3b91c977ab8c","name":"Gimnasia general","subthemes":[{"id":"80e08e3e-2542-42a4-94e5-881897d876e2","name":"Ejercicios básicos de calentamiento y estiramiento."},{"id":"5f1f4c04-70fc-4d01-839b-9ee8acb01122","name":"Movimientos gimnásticos simples (saltos, giros y equilibrios)."},{"id":"f2132f80-e879-482d-afb2-920723a785d1","name":"Coordinación y control corporal en la gimnasia."}]},{"id":"9e906920-60d9-44bf-a5cf-a42ee1f2bf1d","name":"Habilidades manipulativas","subthemes":[{"id":"a1219cd0-1013-43f5-950a-63dcdaef4e25","name":"Lanzar, atrapar y rodar objetos con las manos."},{"id":"3bcb8226-cc78-4335-ab0b-a9b158c61458","name":"Golpear, patear y controlar objetos con diferentes partes del cuerpo."},{"id":"cda9b80e-7f8e-4fdc-95f8-d394045b47dc","name":"Manipulación de objetos usando implementos: halar, empujar, picar y mover."}]},{"id":"1779edae-4b57-40ea-b1a6-7c4eee0fc50e","name":"Habilidades de control corporal","subthemes":[{"id":"81b0d291-31cc-4b2d-801f-fc044b956368","name":"Flexión y extensión en diferentes posiciones."},{"id":"937aa98e-9ad0-412d-83cc-caf13560d568","name":"Giros y rotaciones del cuerpo."},{"id":"b40aba01-176a-4adf-a85d-7bfb003844cd","name":"Balanceo y control del cuerpo en movimiento y en reposo."}]},{"id":"7424bcfc-4da3-47eb-9d61-bb189d87a172","name":"Capacidades físicas","subthemes":[{"id":"b69ac15f-207e-436f-931c-f6fe0d0dfaca","name":"Coordinación y control del movimiento (equilibrio, acoplamiento y orientación)."},{"id":"5062d146-70d1-463e-8ebb-846002ba6d77","name":"Diferenciación y adaptación del movimiento en distintas situaciones."},{"id":"2593afac-311d-4182-a173-a4d6af38abe2","name":"Reacción y ritmo en actividades motrices."}]},{"id":"92814fc6-f3c9-42ce-a6e4-d28d13819d40","name":"Juegos cooperativos y de oposición","subthemes":[{"id":"731e8803-0d30-4a0a-b86a-3d0b8d157455","name":"Juegos de cooperación y trabajo en equipo."},{"id":"aba6f31a-c420-4e78-822f-7ff809f96457","name":"Juegos de oposición con respeto a las reglas."},{"id":"8311e7d5-74f9-40d0-9a7f-fdea0648d42f","name":"Juego limpio, respeto y autocontrol."}]},{"id":"4b4eba75-b9be-4f9e-92b7-1f88acd89bfb","name":"Juegos tradicionales y populares","subthemes":[{"id":"3c55e69e-6e57-4ad9-b342-709885b66b5f","name":"Juegos tradicionales de la comunidad."},{"id":"d1e83ac9-11b2-4317-9abb-799673260cad","name":"Valor cultural de los juegos populares."},{"id":"483d45b2-5bd3-42c5-90f6-675b4038ce44","name":"Participación y convivencia a través del juego."}]},{"id":"eff1d341-bbb1-4914-8860-2cf1a1918d58","name":"Ajedrez (el tablero y las piezas)","subthemes":[{"id":"ce47dea1-a351-446e-9fac-b063ac882b47","name":"Conocimiento del tablero de ajedrez."},{"id":"de9ee4e6-2cef-4e8c-b429-8656691db672","name":"Identificación y función de las piezas."},{"id":"44e8fdb8-582a-49ce-9b5c-b73f5dbbe638","name":"Normas básicas del juego de ajedrez."}]}],"grade_levels":["4to"],"subjectId":"educacion-fisica","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"93024824-0340-441e-999b-7901d291b52d-block-1","themes":["El cuerpo como medio de expresión y comunicación","Capacidades condicionales","Habilidades motrices básicas","Gimnasia general","Habilidades manipulativas","Habilidades de control corporal","Capacidades físicas","Juegos cooperativos y de oposición","Juegos tradicionales y populares","Ajedrez (el tablero y las piezas)"],"conceptual":"El cuerpo como medio de expresión y comunicación: gesto, movimiento, mímica, expresión corporal. Ritmo y movimiento (pulso, acento, compás).\nHabilidades motrices básicas: \n-\tLocomotoras (caminar, rodar, reptar, correr, saltar -horizontal, vertical y en profundidad- marchar, “saltar”, trepar). \n-\tManipulativas (lanzar, atrapar, picar, rodar, halar, empujar, mover y golpear objetos con ayuda de otros implementos, golpear, patear, atrapar, controlar objetos con diferentes partes del cuerpo). De control corporal (girar, flexionar, balancear).\nCapacidades físicas:\n-\tCoordinativas (equilibrio, acoplamiento, orientación, diferenciación, reacción, adaptación, ritmo).\n-\tCondicionales (velocidad -gestual, de reacción, de desplazamiento-, flexibilidad, resistencia aeróbica).\n-Gimnasia general.\n-\tJuegos cooperativos y de oposición.\n-\tJuegos tradicionales y populares.\n-\tAjedrez (el tablero, las piezas).\n ","procedural":"-\tCreación y realización de series de movimientos utilizando diversos implementos: aros, cuerdas, bastones, pañuelos, globos, pelotas, entre otros.\n-\tRealización de combinaciones de movimientos (saltos, equilibrios y giros).\n-\tEjecución de carreras con y sin obstáculos, con y sin control del tiempo, en forma individual y en grupo.\n-\tExperimentación de diferentes formas de saltar en forma vertical y horizontal, con y sin desplazamiento, aplicando técnicas básicas.\n-\tRealización de diversas formas de lanzamientos utilizando diferentes implementos, aplicando técnicas y reglas sencillas.\n-\tRealización, creación y reproducción de juegos de persecución, colaboración, relevos, saltos y lanzamientos, tradicionales y no tradicionales.\n-\tExperimentación a través del juego de diversas posibilidades de movimiento y expresión.\n-\tEjercicios de organización y control. Formaciones en filas, hileras, columnas, círculos, entre otras.\n-\tEjecución de juegos de conducción de implementos.\n \n-\tUtilización de secuencias rítmicas relacionándolas con movimientos corporales, utilizando herramientas y/o recursos físicos y audiovisuales.\n-\tEjecución de rodadas corporales en diferentes planos y direcciones.\n-\tEjecución de posiciones elementales de relajación corporal, después de la actividad física.\n-\tPráctica de hábitos de higiene y normas de comportamiento durante la realización de las actividades físicas.\n-\tRealización de juegos de correr utilizando las técnicas básicas en la carrera de relevos (carrera, pase y recepción del testigo y llegada).\n-\tRealización de juegos para el reconocimiento de las casillas, filas, columnas y diagonales del tablero de ajedrez, en medio físico, digital o virtual.\n-\tRealización de juegos para el aprendizaje del nombre, disposición en el tablero y movimiento de las piezas.\n-\tExploración de diferentes posturas y toma de conciencia de las correctas, en diferentes acciones como: \nlevantar objetos, desplazamientos, subir y bajar escaleras, entre otros.\n ","attitudinal":"-\tValoración y disfrute de participar en juegos con sus compañeros y compañeras.\n-\tDefensa y respeto por su derecho y el de los y las demás de jugar y realizar actividad física, sin discriminación por género, origen, edad u otra condición.\n-\tReconocimiento de la importancia de la realización de actividades físicas para su desarrollo, bienestar y conservación de la salud.\n-\tValoración de los juegos tradicionales y populares como parte de su identidad.\n-\tCuidado y protección de los ambientes físicos y naturales en donde practica la actividad física.\n-\tMotivación por el respecto a las normas y reglas establecidas y del juego limpio.\n-\tDisfrute de la relación y comunicación corporal con los y las demás.\n-\tCuidado y protección de su integridad física y la de sus compañeros y compañeras durante la práctica de actividades físicas.\n \n-\tValoración del orden y la limpieza de los espacios en donde se practica la actividad física.\n-\tValoración y respeto por las destrezas y habilidades de cada compañero y compañera al realizar las diversas actividades físicas.\n-\tUtilización de un lenguaje respetuoso y asertivo durante la práctica de las actividades físicas.\n "}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:20:36.185Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('596f61ed-0f0a-49df-866a-c8b7db214dff', 'sociales', '4to', '{"id":"596f61ed-0f0a-49df-866a-c8b7db214dff","name":"Educación Ciudadana, patrimonio natural y cultural de Rep. Dom.","themes":[{"id":"9a3cc4b2-fb2a-4a39-bb7f-55b82454eac3","name":"Educación ciudadana, patrimonio natural y cultural RD.","subthemes":[{"id":"bd09a630-646d-4c4d-b4d4-2799be09238a","name":"Concepto de ciudadanía y convivencia social."},{"id":"bb860481-9ada-4c7d-808c-7ca994534e4d","name":"Patrimonio natural y cultural dominicano."},{"id":"83677ab4-86af-4143-8115-6dbc9fd77da8","name":"Importancia de cuidar y valorar el patrimonio nacional."}]},{"id":"73cbde11-e5b0-48c2-955c-6b506f93abdd","name":"Organización de la sociedad","subthemes":[{"id":"af21732d-68bf-43ad-a6bf-2f22f8567c0e","name":"Grupos sociales y su función."},{"id":"b45ad0f8-b449-4126-ab03-30c24804ca97","name":"Normas de convivencia en la sociedad."},{"id":"14750d0c-ff29-4ea9-b077-2de75f72dd9a","name":"Participación ciudadana en la comunidad."}]},{"id":"ae51e292-51db-4350-a5fa-431360e9c959","name":"Conceptos de nación, Estado y gobierno","subthemes":[{"id":"ddbf1aca-c06a-43ee-b05f-d0b5d26cd28a","name":"Qué es la nación."},{"id":"39c14692-e129-4783-a012-d8b056cebaa9","name":"Qué es el Estado."},{"id":"4b0f1c7f-fa33-4ab8-9888-39fa8fd67180","name":"Qué es el gobierno y su función."}]},{"id":"df2d834f-4d6e-4a83-a6bb-48ae4965f179","name":"Estado social, democrático y de derechos","subthemes":[{"id":"296eb232-0551-4e1d-8795-f153037770fc","name":"Características del Estado social y democrático."},{"id":"7c521a06-1404-442b-a762-440df5ed5d84","name":"Derechos y deberes de los ciudadanos."},{"id":"a7eabe55-e475-444c-84da-526b5a3e0f83","name":"Importancia del respeto a los derechos humanos."}]},{"id":"9d1db583-4bac-49da-938c-a3a27a0d1d41","name":"Territorio nacional","subthemes":[{"id":"4d3134b9-4faa-42aa-afb9-6fb0a6c66d31","name":"Componentes del territorio nacional."},{"id":"2ae853fc-8383-4c5b-9857-598dbbd23e08","name":"Importancia del territorio para la identidad nacional."},{"id":"4dba1c50-fa28-4b9e-b421-ec877adb9885","name":"Límites y extensión del territorio dominicano."}]},{"id":"af43eea5-5eda-43a5-9235-8d140c9f8a06","name":"Los poderes del Estado","subthemes":[{"id":"ab6342da-8a0b-4f60-bd66-37a88f4e4403","name":"Poder Ejecutivo y sus funciones."},{"id":"e7f4b43f-41e1-439e-a64a-9e507ce18b18","name":"Poder Legislativo y sus funciones."},{"id":"adaea1c1-7834-4e5f-b40f-9ee3cb7cf2cf","name":"Poder Judicial y sus funciones."}]},{"id":"6d42f433-d431-40d3-9c4b-b5caa3527224","name":"Estado y Constitución","subthemes":[{"id":"0a1a144b-a064-4ce4-9ca4-525c3cbcee5a","name":"Relación entre Estado, Constitución y ciudadanía."},{"id":"5c46b9a5-83c7-4920-823e-03fe4fc4a66f","name":"Qué es la Constitución dominicana."},{"id":"ae808411-be48-4c44-b08f-74f03f85dcb5","name":"Importancia de la Constitución como ley suprema."}]},{"id":"21f78074-7a53-47e0-919d-927df2b42be0","name":"Símbolos patrios","subthemes":[{"id":"bdace461-937c-4934-96ac-b5005c6ac7e6","name":"El Escudo Nacional y su significado."},{"id":"6e7cdd4d-8468-4279-a6a5-cd04247e1902","name":"El Himno Nacional y su valor patriótico."},{"id":"1064f8c6-ff03-4aaa-aac9-2f0035065b07","name":"La Bandera Nacional y su significado."}]}],"grade_levels":["4to"],"subjectId":"sociales","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"596f61ed-0f0a-49df-866a-c8b7db214dff-block-1","themes":["Educación ciudadana, patrimonio natural y cultural RD.","Organización de la sociedad","Conceptos de nación, Estado y gobierno","Estado social, democrático y de derechos","Territorio nacional","Los poderes del Estado","Estado y Constitución","Símbolos patrios"],"conceptual":"Educación Ciudadana, patrimonio natural y cultural de la República Dominicana. – Organización de la sociedad\n–\tConceptos de nación, estado y gobierno.\n–\tEstado social, democrático y de derechos.\n–\tTerritorio nacional.\n–\tLos poderes del Estado.\n–\tEstado y Constitución.\n–\tSímbolos patrios.\n ","procedural":"–\tAnálisis de los conceptos de nación, Estado y gobierno y Constitución, planteando su punto de vista.\n–\tElaboración de informes de lectura y monografía sobre la importancia de los Poderes del Estado en el equilibrio democrático.\n–\tLectura y comentario de texto relacionados al himno nacional y sobre el origen de la bandera dominicana y evaluación del contexto en que se crearon.\n ","attitudinal":"–\tRespeto y tolerancia hacia los diferentes grupos humanos que conforman la población de la República Dominicana.\n–\tInterés por conocer sobre el Estado democrático y los poderes del Estado. \n–\tValoración de su vida y la de las demás personas.\n–\tPlantea soluciones a conflictos mediante el diálogo y el consenso.\n–\tValoración del diálogo, la cultura de paz para la prevención y solución de conflictos.\n "}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:20:36.185Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('b4250e10-34ce-4125-869c-782e395effeb', 'sociales', '4to', '{"id":"b4250e10-34ce-4125-869c-782e395effeb","name":"Geografía del Caribe y las Antillas","themes":[{"id":"36356f67-b7eb-49c0-a0df-38231e365b57","name":"El Caribe, Antillas Mayores y Menores","subthemes":[{"id":"75c36d45-54dd-4f88-9d3f-716256cce43a","name":"Ubicación del Caribe y de las Antillas Mayores y Menores."},{"id":"6c043eba-5b09-45dd-9aa2-3578c4342dcf","name":"Características físicas y sociales del Caribe."},{"id":"9ed8badb-7932-4d24-a16c-ea2cb66ba06a","name":"Diversidad cultural de los pueblos caribeños."}]},{"id":"77d55385-c2dc-45bf-9f06-d22132e4ee3e","name":"El Caribe, las Antillas e Isla de Santo Domingo","subthemes":[{"id":"6fd3e355-ce4c-4483-bdb9-d45b2c831837","name":"Posición geográfica del Caribe y la isla de Santo Domingo."},{"id":"46b294b9-30b4-47cf-bd61-78a84c13579b","name":"Relieve y clima de la región caribeña."},{"id":"5030ec0b-9bf1-441a-a3ec-4cae32009280","name":"Población y formas de vida en el Caribe y la isla de Santo Domingo."}]}],"grade_levels":["4to"],"subjectId":"sociales","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"b4250e10-34ce-4125-869c-782e395effeb-block-1","themes":["El Caribe, Antillas Mayores y Menores","El Caribe, las Antillas e Isla de Santo Domingo"],"conceptual":"Geografía del Caribe y las Antillas.\n–\tEl Caribe, Antillas Mayores y Menores: características físicas, sociales y culturales.\n–\tEl Caribe, las Antillas e Isla de Santo Domingo: posición, relieve, clima y población.\n ","procedural":"Ubicación en mapas de las Antillas mayores y menores:\n–\tSelección de fuentes sobre el Caribe y las Antillas (mapas y publicaciones).\n–\tIdentificación de las Antillas mayores en un mapa del Caribe.\n–\tIdentificación de la isla de Santo Domingo en un mapa del Caribe.\n–\tUso de la rosa de los vientos para identificar las Antillas que están al norte, sur, este y oeste.\n–\tUtilización de escala y leyendas en la lectura del mapa del Caribe.\n–\tElaboración de leyendas sencillas con colores que representan las Antillas que están al norte, sur, este y oeste.\n–\tElaboración de infografía sobre las Antillas y la isla de Santo Domingo.\n–\tElaboración de cuadros sencillos sobre la cantidad de Antillas mayores y menores y la población de algunas de ellas.\n–\tElaboración de cuadros sinópticos sobre el clima en las Antillas mayores y menores.\n–\tElaboración de proyectos de investigación sencillos sobre el relieve y el clima de las Antillas.\n–\tIdentificación, con la ayuda del docente, de mapas de población de las Antillas y la República Dominicana.\n ","attitudinal":"–\tValoración del Caribe y las Antillas.\n–\tRespeto por la autoría de las fuentes de información consultadas\n–\tUso adecuado de las informaciones que utiliza en sus producciones.\n–\tValoración del uso de fuentes confiables sobre temas históricos y geográficos.\n–\tParticipación en proyectos grupales, escuchando y respetando las ideas de los/las demás y demostrando espíritu emprendedor. \n–\tApreciación por los elementos de la cultura indígena, africana y española.\n–\tValoración positiva de las formas de defensa de los derechos humanos de indígenas y africanos.\n "}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:20:36.185Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('7244e219-15e4-4194-85ac-7715454eddfa', 'sociales', '4to', '{"id":"7244e219-15e4-4194-85ac-7715454eddfa","name":"Origen y formación del pueblo dominicano","themes":[{"id":"36366936-4a5f-4672-accc-5b644302b4cc","name":"Primeros pobladores de la isla: ciguayos, macorixes y taínos","subthemes":[{"id":"153e0dac-1123-4074-bf68-18e52b720f2c","name":"Quiénes fueron los ciguayos, macorixes y taínos."},{"id":"2ef34e5d-0b84-4f10-bda5-825983efd6fd","name":"Formas de vida, organización y costumbres."},{"id":"c5b5c50b-b42a-4d91-a28e-9f5f2853a657","name":"Aportes culturales de los primeros pobladores."}]},{"id":"d48fb8a1-a130-43d8-b17d-759f61f4aed0","name":"Conquista de la Española: colonizadores españoles","subthemes":[{"id":"eb55802c-4d8a-4a18-95c8-df227874e420","name":"Llegada de los españoles a la isla."},{"id":"21a969c7-eff7-4838-bb86-3bd6e2826183","name":"Cambios sociales, económicos y culturales durante la conquista."},{"id":"d85e5a45-0ed5-47dd-b516-572b40a013ca","name":"Consecuencias de la colonización para los pueblos originarios."}]},{"id":"2d0065c2-9400-42e4-a62c-aa4d5f70da13","name":"Defensa de los indígenas y formas de resistencia indígena y africana","subthemes":[{"id":"2d6a373a-67e0-4f24-94ef-d3b035d3a9b9","name":"Alzamientos y rebeliones indígenas."},{"id":"7c914fa3-e6f5-498c-a108-75a18cf4d6df","name":"Cimarronadas, manieles y palenques."},{"id":"392799ce-6c2f-492a-a59b-b52bbb178789","name":"Importancia histórica de la resistencia indígena y africana."}]}],"grade_levels":["4to"],"subjectId":"sociales","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"7244e219-15e4-4194-85ac-7715454eddfa-block-1","themes":["Primeros pobladores de la isla: ciguayos, macorixes y taínos","Conquista de la Española: colonizadores españoles","Defensa de los indígenas y formas de resistencia indígena y africana"],"conceptual":"Origen y formación del pueblo dominicano:\n–\tPrimeros pobladores de la isla: ciguayos, macorixes y taínos.\n–\tConquista de la Española: \ncolonizadores españoles.\n–\tDefensa de los indígenas y formas de resistencia indígena y africana: \nalzamiento, cimarronadas, manieles y palenques.\n ","procedural":"Análisis de acontecimientos históricos que incidieron en la formación del pueblo dominicano.\n–\tIdentificación de los lugares de procedencia de los aborígenes que poblaron la isla de Santo Domingo en un mapa del Caribe.\n–\tIdentificación de los elementos que caracterizan la cultura dominicana.\n–\tReconocimiento de las comunidades indígenas que habitaban la isla (ciguayos, macorixes y taínos), estableciendo algunas diferencias entre ellos.\n–\tExplicación de los aportes que dejaron los taínos a la cultura dominicana.\n \n–\tComparación de mapas de los cacicazgos con el actual, identificando similitudes y diferencias.\n–\tIdentificación de las causas que motivaron a los españoles a traer africanos como esclavos a nuestra isla.\n–\tReflexión acerca de las luchas de los taínos en contra de los conquistadores.\n–\tReflexión sobre la importancia del Sermón de Montesinos y las leyes de Burgos.\n–\tAnálisis de clasificación de conceptos relacionados con el periodo estudiado.\n–\tPresentación en línea de tiempo de los grupos aborígenes que poblaron la isla.\n–\tAnálisis de términos como: conquista, colonización, encomiendas, factoría colombina, cimarronadas, manieles, palenques.\n–\tElaboración de línea de tiempo sobre los gobernadores de la isla de 1500 a 1520.\n–\tLectura, comentario de texto y discusión sobre las causas y consec uencias de la llegada de los esclavos africanos a la isla de Santo Domingo.\n–\tComparación de rasgos culturales de los distintos grupos humanos que poblaron la isla de Santo Domingo antes y después de la colonia.\n–\tIdentificación y explicación de las causas de la resistencia contra la esclavitud de indígenas y africanos: alzamientos y cimarronadas en la isla de Santo Domingo.\n \n ","attitudinal":"–\tAprecio por los elementos de la cultura indígena, africana y española. \n–\tValoración positiva de las formas de defensa de los derechos humanos de indígenas y africanos. \n–\tRespeto y tolerancia hacia los diferentes grupos humanos que conforman la población de la República Dominicana.\n–\tValoración de luchas y acontecimientos históricos que incidieron en la formación de la sociedad dominicana. \n "}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:20:36.185Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('46160d3b-f9bd-4ce7-b632-a7a37fa11878', 'sociales', '4to', '{"id":"46160d3b-f9bd-4ce7-b632-a7a37fa11878","name":"Características de la Isla de  Santo Domingo XVII y XVIII","themes":[{"id":"47238b8a-c63a-49bf-bbc8-d60c2890c3c1","name":"Características de la Isla de Santo Domingo en los siglos XVII y XVIII","subthemes":[{"id":"c6f1265e-8207-40db-83a8-672d763524c3","name":"Organización social y económica de la isla en los siglos XVII y XVIII."},{"id":"33090ea2-cc12-4d95-8578-7603ceb5d514","name":"Cambios políticos y territoriales de la época."},{"id":"14b06362-9cb1-4308-95d3-115a0e66cbc2","name":"Vida cotidiana y actividades productivas."}]},{"id":"689dfe51-ad4e-44e2-b88c-93c8bb19ff50","name":"Monopolio, contrabando y piratería","subthemes":[{"id":"01c42946-cabf-484c-aed1-4a58ac022b4b","name":"El monopolio comercial impuesto por España."},{"id":"7a14c1d9-351b-4c5b-bee7-ef3337711b38","name":"El contrabando y la piratería en el Caribe."},{"id":"b6e767cd-f9aa-4e8e-908f-74d74ac14b39","name":"Consecuencias del contrabando y la piratería en la isla."}]},{"id":"c7acdb92-00a1-4f93-ba35-e877aa3ae273","name":"Devastaciones de Osorio","subthemes":[{"id":"79f14155-523b-4ff3-b450-482b3e6aef4e","name":"Qué fueron las Devastaciones de Osorio."},{"id":"bd4bc842-539d-4234-9b29-a0ef2a49a5b7","name":"Motivos y desarrollo de las devastaciones."},{"id":"a0146fee-a29c-4b84-ae1e-ffbc584a3571","name":"Consecuencias para la población y la economía."}]},{"id":"2157fc4f-38e9-4690-bf1c-fc6f56d3aa74","name":"Ocupación francesa y división de la isla","subthemes":[{"id":"4cf35fe5-db5c-4029-b3cb-51938c9c4b7f","name":"Llegada y establecimiento de los franceses en la isla."},{"id":"bffcc094-8cee-4cd7-94f1-b77516523786","name":"División territorial de la isla de Santo Domingo."},{"id":"1a271f7b-146c-4fed-aa60-e12aa9599b4a","name":"Cambios sociales y culturales tras la ocupación francesa."}]},{"id":"87eeae3f-86a9-4da8-9f4b-120bddb78588","name":"Independencia de Haití","subthemes":[{"id":"b9fe21c7-85c6-426c-8026-10c6589824ea","name":"Causas de la independencia de Haití."},{"id":"346ce5ec-0020-437d-86e7-868d0fdc6368","name":"Proceso independentista haitiano."},{"id":"7a200097-cb80-4702-885d-a5945e8acbd2","name":"Consecuencias para la isla de Santo Domingo."}]}],"grade_levels":["4to"],"subjectId":"sociales","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"46160d3b-f9bd-4ce7-b632-a7a37fa11878-block-1","themes":["Características de la Isla de Santo Domingo en los siglos XVII y XVIII","Monopolio, contrabando y piratería","Devastaciones de Osorio","Ocupación francesa y división de la isla","Independencia de Haití"],"conceptual":"Características de la Isla de \nSanto Domingo en los siglos XVII y XVIII\n–\tMonopolio, contrabando y piratería.\n–\tDevastaciones de Osorio.\n–\tOcupación francesa y división de la isla.\n–\tIndependencia de Haití.\n ","procedural":"–\tIdentificación de los factores que posibilitaron el surgimiento de las dos colonias.\n–\tExplicaciones sencillas sobre las razones por que hubo crisis en la isla de Santo Domingo durante el siglo XVI\n–\tExplicación de los términos: monopolio comercial, pirata, corsarios, piratería y su relación con la crisis vivida en la isla durante el siglo XVI\n–\tExpresión de su opinión sobre las soluciones que los habitantes de la isla dieron a la crisis vivida durante el siglo XVI.\n–\tExpresión de su opinión sobre las soluciones que los habitantes de la isla dieron a la crisis vivida durante el siglo XVI.\n–\tComparación y análisis de textos cortos de fuentes confiables sobre:\n•\tEl contrabando o comercio de rescate.\n•\tLas despoblaciones de Osorio.\n•\tLa piratería y la formación de las colonias francesas y españolas.\n–\tElaboración de infografías, esquemas, u otros medios para establecer por qué España nos entregó a Francia en 1795 mediante el Tratado de Basilea.\n–\tAnálisis de las causas y consecuencias de la revolución haitiana.\n ","attitudinal":"–\tInterés por el conocimiento de los acontecimientos históricos que dieron origen a las colonias de Santo Domingo y Saint Domingue. \n–\tReflexión crítica sobre la situación económica de la isla de Santo Domingo durante los siglos XVII y XVIII.\n–\tActitud crítica sobre el contrabando, la piratería y las Devastaciones de Osorio.\n–\tInterés por analizar la importancia de los tratados sobre las colonias.\n–\tActitud crítica ante la Independencia de Haití.\n "}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:20:36.185Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('953af061-82b4-4b9b-b7f4-2ef058b81d93', 'sociales', '4to', '{"id":"953af061-82b4-4b9b-b7f4-2ef058b81d93","name":"Siglo XIX: primera mitad","themes":[{"id":"0d39c507-4418-4fa2-80fa-5aa6827b8c29","name":"Siglo XIX: primera mitad","subthemes":[{"id":"9b64f301-d594-4003-bf56-b183319e4e9b","name":"Situación política y social de la isla en el siglo XIX."},{"id":"c0bab14d-44d3-48db-998d-5f2034b15c09","name":"Cambios económicos y sociales del período."},{"id":"4f134440-e5cd-4100-9343-a6bc3fc2cc25","name":"Importancia histórica de esta etapa."}]},{"id":"d5be5d28-2ce4-4033-a098-15ed73a5aad4","name":"Ocupaciones ","subthemes":[{"id":"6e8e2385-f458-474f-935b-33b657f5afdb","name":"Entrega a Francia"},{"id":"8bfe9c07-3129-48d6-a186-97d3d3f29fe2","name":"Vuelta a la colonia española"},{"id":"b3226b68-4b22-496f-84b8-d0b1c45166d7","name":"Reconquista e independencia efímera"},{"id":"9aba55c3-7a5d-46bc-9ca8-4d25987c896f","name":"La entrega de Santo Domingo a Francia."},{"id":"bf386bea-6527-4dab-811a-4ff162e064fd","name":"La reconquista y la independencia efímera."},{"id":"908fae97-ff55-4a03-b687-116d1d3ed435","name":"Consecuencias de estos procesos históricos."}]},{"id":"9d13df73-302e-4d5f-950b-1050f203e7ef","name":"Período de la unificación haitiana","subthemes":[{"id":"0379a14c-e516-489a-a9ae-048ba67e69d8","name":"Inicio de la unificación haitiana."},{"id":"e5255e26-ce20-4103-b386-37a9d8a5a0ed","name":"Cambios políticos y sociales durante la unificación."},{"id":"0d1a71e5-9bd0-433d-85af-9123a216741e","name":"Reacciones de la población dominicana."}]},{"id":"b7a7435c-f538-4be1-ad3c-78151dceb1af","name":"La Sociedad Secreta La Trinitaria","subthemes":[{"id":"2aea1457-b385-497a-b444-57fcc3457d7e","name":"Origen y objetivos de La Trinitaria."},{"id":"14089baa-2d99-4333-ba82-ac6bdf971a1f","name":"Principales miembros y acciones."},{"id":"77d43292-f95c-44eb-844c-5a24c40f1973","name":"Importancia de La Trinitaria en la independencia."}]},{"id":"cb91b33d-a5b6-4b83-b066-31c391f869e6","name":"Nacimiento de la República Dominicana","subthemes":[{"id":"3e3a081c-02ca-4410-a689-45ca2f7aa9d4","name":"Hechos que dieron origen a la República Dominicana."},{"id":"7707af38-8bdd-4bd4-941b-86b88de8c9f0","name":"Proclamación de la independencia nacional."},{"id":"dcf730ce-96f1-4c6e-bec4-fe60cc1a9643","name":"Significado del nacimiento de la República Dominicana."}]},{"id":"dd45dde9-fd69-463c-9ff4-4440b2975c5c","name":"Aportes de las mujeres en la fundación de la República Dominicana","subthemes":[{"id":"0a2679d5-2927-4b2a-acca-d4aeb471cddd","name":"Participación de las mujeres en la lucha independentista."},{"id":"593e716f-0377-49d7-8ea3-06af9e1432ed","name":"Aportes de heroínas dominicanas."},{"id":"c9fe58cc-ba55-4a0d-976e-2d9e937db91b","name":"Importancia del rol femenino en la historia nacional."}]},{"id":"9f4caa27-84be-4b34-a196-39fa9286fc50","name":"Los Héroes de la Independencia","subthemes":[{"id":"07327bed-290d-414d-8082-b1dd0ca35f96","name":"Juan Pablo Duarte: El Padre de la Patria"},{"id":"6668ba1c-0695-4339-ad6e-15233c4ffc51","name":"Símbolos patrios y los héroes"}]}],"grade_levels":["4to"],"subjectId":"sociales","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"953af061-82b4-4b9b-b7f4-2ef058b81d93-block-1","themes":["Siglo XIX: primera mitad","Ocupaciones ","Período de la unificación haitiana","La Sociedad Secreta La Trinitaria","Nacimiento de la República Dominicana","Aportes de las mujeres en la fundación de la República Dominicana","Los Héroes de la Independencia"],"conceptual":"Siglo XIX: Primera mitad.\n–\tEntrega a Francia, vuelta a la colonia española, reconquista e independencia efímera.\n–\tPeríodo de la unificación haitiana.\n–\tLa Sociedad Secreta la Trinitaria\n–\tNacimiento de la República Dominicana.\n–\tAportes de las mujeres en la fundación de la República Dominicana.\n ","procedural":"–\tRealización de diálogo problematizado sobre las acciones que tomó el gobernador francés durante la ocupación de Francia.\n–\tRealización de debates en torno al papel jugado por Juan Sánchez Ramírez en la guerra contra Francia y su decisión de volver al dominio de España.\n–\tRedacción de ensayos sobre la Independencia Efímera y el papel de José Núñez de Cáceres en la proclamación de la primera Independencia llamada Independencia Efímera, siguiendo procedimientos:\n•\tSelección de los pasos del ensayo.\n•\tSelección de fuentes confiables con la ayuda del profesor o profesora. \n•\tCorrección con el docente de dos borradores antes de la presentación del texto final.\nIdentificación de los aspectos principales que causaron la unificación de la isla bajo el gobierno de Boyer en 1822.\n–\tIdentificación de los antecedentes.\n–\tIdentificación de mapas alusivos al periodo histórico.\n–\tElaboración de línea de tiempo de los acontecimientos principales.\n–\tDramatización del proceso.\n–\tElaboración de murales con ilustraciones alusivas al proceso histórico.\n–\tAnálisis de los principales acontecimientos históricos de 1822-1844.\nIndagación en diversas fuentes y tratamiento de la información sobre la formación de la nación dominicana y las causas que dieron lugar a la fundación de la República Dominicana.\n–\tAnálisis del papel de la Trinitaria en el nacimiento de la República Dominicana.\n–\tIdentificación de los aportes de las mujeres en la fundación de la República Dominicana. \n–\tRealización de murales sobre el patrimonio natural y cultural de la República Dominicana, siguiendo un esquema establecido.\n ","attitudinal":"–\tActitud crítica en el análisis de acontecimientos de 1800-1921.\n–\tValoración de las luchas de pueblo dominicano por mantener su soberanía. \n–\tReflexión crítica sobre el dominio haitiano de 1822-1844.\n–\tInterés por levantar informaciones sobre el nacimiento de la Primera República. \n "}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:20:36.185Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('5f1875ca-4634-4806-acfd-b986402d5303', 'educacion-fisica', '6to', '{"id":"5f1875ca-4634-4806-acfd-b986402d5303","name":"Conceptos de unidad","themes":[{"id":"ddf99ebc-9df2-4afe-9989-ffb9f0ef0dcb","name":"Habilidades motrices básicas locomotoras","subthemes":[{"id":"c0b8e78a-5791-433a-b4d3-d4545ebd4b34","name":"Desplazamientos: caminar, correr y marchar."},{"id":"117c8ffd-3e04-4ae1-bb94-d9e795251fd5","name":"Saltos y trepas básicas."},{"id":"d2ed66de-d51a-44ff-9a8b-876c068e482c","name":"Cambios de dirección y velocidad."}]},{"id":"985c3dfb-c20b-422c-8b41-0d556956c72f","name":"Habilidades motrices manipulativas","subthemes":[{"id":"dc785087-b545-4e4e-8d60-5fc228b624c0","name":"Lanzar, atrapar y patear."},{"id":"7f7dbc07-d14e-4f86-a4fc-19aaeb119f13","name":"Control de objetos con manos y pies."},{"id":"b9f65c19-12cc-4c76-96a4-9123b2122ed0","name":"Empujar, halar y golpear con precisión."}]},{"id":"965420bb-266e-4258-87e4-156a6b8331c6","name":"Habilidades de control corporal","subthemes":[{"id":"e3519874-371f-486f-8856-38ffda1187dd","name":"Giros y balanceos."},{"id":"be9783a9-1392-4790-8522-0fa03cb00556","name":"Flexiones y posturas corporales."},{"id":"b80aab86-cd25-483f-9821-4356bbbd4fec","name":"Coordinación y equilibrio corporal."}]},{"id":"4a0dff63-d5f4-4637-b479-aa639add4d53","name":"Capacidades físicas coordinativas","subthemes":[{"id":"794c349b-6342-417a-b977-bdaff5c77d46","name":"Equilibrio y coordinación."},{"id":"6394c73d-f862-4e6e-8996-f8279c6c73e7","name":"Orientación espacial y ritmo."},{"id":"17a4b93e-5ccf-4278-8bfb-3c63803c7bb3","name":"Reacción y adaptación al movimiento."}]},{"id":"8696c12d-13a6-42e5-b7fe-7e450b1b2d32","name":"Capacidades físicas condicionales","subthemes":[{"id":"6e5e9575-c0cb-4f0f-a4f7-d5cf0aa294bb","name":"Fuerza explosiva básica."},{"id":"31a53d90-115c-4d11-ac8d-adc1ef249cec","name":"Velocidad de reacción."},{"id":"e949b45c-577e-4353-b2bb-5a8a8518ce21","name":"Flexibilidad y resistencia aeróbica."}]},{"id":"79a681d1-4e07-41f2-a56b-50ed5cd1aa2b","name":"Juegos predeportivos y juegos adaptados","subthemes":[{"id":"919b4cf8-6e98-447f-bb37-e039933010f9","name":"Reglas básicas y adaptación de juegos."},{"id":"5ab16117-8ac8-4a09-9d34-b6b6cea2e153","name":"Trabajo en equipo y cooperación."},{"id":"3628c8c0-a6b8-4c52-9020-246d16994180","name":"Desarrollo de habilidades deportivas básicas."}]},{"id":"c258a751-40ea-4a00-bdad-f2b5515b310e","name":"Voleibol","subthemes":[{"id":"25e209a6-7ae6-4a8e-b47b-70a3ceaabaf4","name":"Voleo y golpe bajo."},{"id":"8aff3d84-41ac-43ff-9d8b-70b9de19d10e","name":"Saque básico."},{"id":"492f8a99-4e4a-40a6-9228-a668a7681b93","name":"Ataque y ubicación en cancha."}]},{"id":"a562e719-ca2a-4b05-9506-0b7e1810e52b","name":"Fútbol","subthemes":[{"id":"840cd969-9989-403a-baf0-ed31658d7faa","name":"Conducción del balón."},{"id":"c08bb7aa-564e-4d4f-95d3-464286cfef51","name":"Pase y control."},{"id":"25e63725-0308-4735-93f8-17c8669952b0","name":"Tiro a portería."}]},{"id":"253e9a2f-7967-4472-80ab-2cb8e331e65a","name":"Béisbol","subthemes":[{"id":"83ef8775-a2aa-4cfb-b969-4fed5295e17f","name":"Fildeo y bateo básico."},{"id":"70a73d3f-5f14-49a4-8a6f-efcf67cfa67f","name":"Corrido de bases."},{"id":"3cb336c3-7089-493c-9bcc-6ce4ada96722","name":"Reglas e importancia del juego."}]},{"id":"e84e6038-157a-4f38-9f44-4b57f42975ac","name":"Ajedrez","subthemes":[{"id":"e4a69b00-e03b-4893-bba5-b48adbea0f80","name":"Normas básicas de apertura."},{"id":"68ff9e3c-c6fe-418b-8d33-659478418ebd","name":"Anotación algebraica."},{"id":"382b2411-d4ee-48c7-a356-2956a9d4fef0","name":"Estrategias iniciales simples."}]}],"grade_levels":["6to"],"subjectId":"educacion-fisica","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"5f1875ca-4634-4806-acfd-b986402d5303-block-1","themes":["Habilidades motrices básicas locomotoras","Habilidades motrices manipulativas","Habilidades de control corporal","Capacidades físicas coordinativas","Capacidades físicas condicionales","Juegos predeportivos y juegos adaptados","Voleibol","Fútbol","Béisbol","Ajedrez"],"conceptual":"\"Habilidades motrices básicas:\"\n-\tLocomotoras (caminar, rodar, reptar, correr, saltar, marchar, “saltar”, trepar).\n-\tManipulativas (lanzar, picar, rodar, halar, empujar, golpear, patear, atrapar, controlar objetos con diferentes partes del cuerpo). De control corporal (girar, flexionar, balancear).\n \n\"Capacidades físicas:\"\n-\tCoordinativas (equilibrio, coordinación, orientación, diferenciación, reacción, adaptación, ritmo). Condicionales (fuerza explosiva, velocidad de reacción, flexibilidad, resistencia aeróbica).\n \nJuegos predeportivos, \n- \"juegos adaptados.\"\nVoleibol (voleo, golpe bajo, saque, ataque).\nFútbol (conducción del balón, pase, tiro). Béisbol (fildeo, bateo, corrido de bases, características, importancia, reglamento para su ejecución).\nAjedrez (normas generales de la apertura, anotación algebraica).\n ","procedural":"-\tParticipación de los niños y las niñas en las distintas actividades físicas con equidad e igualdad de género.\n-\tDistribución consciente del movimiento en el espacio.\n-\tCombinación de movimientos, formas, formaciones, direcciones y trayectorias de forma creativa.\n-\tAplicación de las habilidades motrices básicas y capacidades físicas en la resolución de situaciones motrices cotidianas, deportivas y recreativas.\n-\tAplicación de las habilidades motrices básicas y capacidades físicas en el manejo y utilización de diversos implementos y aparatos gimnásticos, recreativos y deportivos.\n-\tElaboración y descripción de las utilerías e implementos manipulados en fútbol, voleibol, béisbol y ajedrez y su utilización, con apoyo de recursos del medio.\n-\tRealización de juegos de coordinación viso-motora.\n-\tRealización de actividades y juegos recreativos, en los que se efectúen saltos y lanzamientos de objetos con peso moderado.\n-\tRealización de carreras continuas a ritmo moderado.\n \n-\tParticipación en juegos recreativos y deportivos adaptados, en los que se ponga de manifiesto su resistencia aeróbica.\n-\tEjercicios de organización y control. Formaciones en filas, hileras, columnas, círculos, entre otras.\n-\tEjecución de juegos en los que se apliquen técnicas básicas para la conducción del balón.\n-\tEjecución de juegos en los que se apliquen técnicas básicas para los pases y tiros con las extremidades inferiores y la cabeza.\n-\tEjecución de juegos en los que se apliquen técnicas básicas para el bateo.\n-\tEjecución de juegos en los que se apliquen técnicas básicas para atrapadas de aire y de ¨rolling¨.\n-\tEjecución de pequeños juegos de voleibol de cooperación y oposición en los que se apliquen técnicas básicas para el saque, golpe bajo, voleo y ataque.\n-\tParticipación en juegos predeportivos en los que se fildean diferentes móviles y pelotas tanto de rolling como de aire.\n-\tGolpeo de diferentes tipos de pelotas y otros implementos con manos, pies, bates y materiales adaptados para tal uso.\n-\tPráctica de correr entre puntos o bases.\n-\tRealización de ejercicios de relajación corporal, después de la actividad física.\n-\tRealización de juegos con mates elementales (dos torres y rey contra rey, dos alfiles y rey contra rey), en medios físicos, digitales o virtuales.\n-\tRealización de juegos aplicando las normas generales de la apertura.\n-\tJuego de partidas con sus compañeros con anotación algebraica.\n \n ","attitudinal":"-\tPráctica el juego limpio, respetando las reglas de los juegos que realiza.\n-\tValoración y práctica de hábitos de higiene y normas de comportamiento.\n-\tValoración y disfrute de participar en juegos con sus compañeros y compañeras.\n-\tDefensa y respeto por su derecho y el de los y las demás de jugar y realizar actividades físicas.\n-\tReconocimiento de la importancia de la realización de actividades físicas para su desarrollo, bienestar y conservación de la salud.\n-\tCuidado y protección de los ambientes físicos y naturales en donde practica actividades físicas.\n-\tValoración del béisbol como deporte nacional.\n "}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:20:36.185Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('1fa7ba0a-18cb-45ec-93fb-34c3a03a7631', 'sociales', '4to', '{"id":"1fa7ba0a-18cb-45ec-93fb-34c3a03a7631","name":"Convivencia humana","themes":[{"id":"c1cc2be5-95c4-4366-b83c-a8e5779f7313","name":"Deberes y derechos civiles y políticos","subthemes":[{"id":"842e8bed-8e41-484c-a5e1-ec818e6efa9e","name":"Derechos civiles de niños y ciudadanos."},{"id":"9d23f138-3b8c-4ae1-bf8d-6b4d55058db1","name":"Deberes y responsabilidades ciudadanas."},{"id":"d369dff0-85d2-4abb-8079-b5d9929c66be","name":"Importancia de participar en la vida democrática."}]},{"id":"1b193eab-91d3-4e97-a997-84fab2b0ad16","name":"Aspectos principales de la educación vial","subthemes":[{"id":"3a4dd7f3-6113-4155-bf59-b2270f50b80e","name":"Comportamiento seguro como peatón y pasajero."},{"id":"938a7c75-2479-49bb-b483-22abbdd6d983","name":"Normas básicas de tránsito."},{"id":"e471ebe2-b041-419c-972a-1023131f5a1e","name":"Señales de tránsito y su significado."}]},{"id":"348bfd35-5a84-42c3-b69d-d5b1ddb67e8e","name":"Cultura de paz y manejo de conflictos","subthemes":[{"id":"4068ce29-ef0f-4d72-ba86-558b67a6d799","name":"Qué es la cultura de paz."},{"id":"51e22c43-520a-40e3-a029-f261362fc18e","name":"Diálogo y respeto para resolver conflictos."},{"id":"ac386228-a783-4f0d-b44e-abb46bfdbf94","name":"Soluciones pacíficas ante desacuerdos."}]},{"id":"bb29a289-9279-4311-b72b-6e37bb4f1c43","name":"Valores importantes para la convivencia","subthemes":[{"id":"3d4cb98a-2de4-44e4-98fb-cd0d6f0bbe5a","name":"Honestidad y justicia en la vida diaria."},{"id":"68783d91-d21a-41cb-92b5-c933c86bf602","name":"Respeto y responsabilidad en la convivencia."},{"id":"5169e607-4078-4df6-ba18-2decca09b378","name":"Solidaridad y cooperación."}]},{"id":"1c8175b9-109c-437d-9656-be10af49a9a9","name":"Participación, justicia, respeto, responsabilidad, libertad y tolerancia","subthemes":[{"id":"63eb09d9-a412-46c6-9267-2ed2cab614ad","name":"Justicia y respeto a los derechos de los demás."},{"id":"143744d5-24e3-469f-a344-ce6f2150e534","name":"Libertad y tolerancia en la convivencia social."},{"id":"965615c3-8bbd-4b6a-89c7-f73e6d8e8a9d","name":"Participación activa en la escuela y la comunidad."}]},{"id":"23ac0cb6-1b0d-4929-9cb2-7ece3274627a","name":"Convivencia vial","subthemes":[{"id":"2f2af245-22b9-41b4-9578-52d16c6c37fa","name":"Respeto a las normas de tránsito."},{"id":"89b82326-a870-4ffb-9001-65b4deca1e6d","name":"Convivencia entre peatones y conductores."},{"id":"91896f14-2eef-45bb-91df-3003757834fb","name":"Prevención de accidentes de tránsito."}]},{"id":"0a876630-361d-41ac-90b3-a37ad2af49e1","name":"Cultura de ahorro","subthemes":[{"id":"ce49a965-5470-4ae6-a1f8-8799c6002d1c","name":"Ahorro en la familia y la comunidad."},{"id":"22ff2199-d9b0-4806-9264-d78b273a7375","name":"Importancia del ahorro."},{"id":"dc5da796-7ca3-402a-8e1d-3ff1d5d06baa","name":"Uso responsable del dinero."}]},{"id":"cd5183a9-9ff5-4a93-a387-167b204c3158","name":"Situaciones de violencia y corrupción","subthemes":[{"id":"b2e1ccad-2363-45b0-9c43-732863a7b2ac","name":"Consecuencias de la corrupción."},{"id":"3ddd5fe9-f1a8-4939-98d7-5122a0023106","name":"Rechazo a la violencia y a la corrupción."},{"id":"0dc2289f-7062-49e0-9e8c-fda4dbe21129","name":"Identificación de situaciones de violencia."}]},{"id":"e5490575-9ca9-44e0-a720-e8c448855bf8","name":"Respeto a las demás personas","subthemes":[{"id":"e5a3fe81-7654-4df0-90f3-f199d51b42b1","name":"Respeto a la diversidad."},{"id":"8eeff705-b252-4e16-8fac-d928900e001c","name":"Trato digno hacia los demás."},{"id":"b401496c-58c1-4ba4-8321-340bdeea8903","name":"Empatía y consideración en la convivencia."}]},{"id":"75548f04-46ea-4b46-9451-19280ec5edc0","name":"Relaciones armoniosas","subthemes":[{"id":"cf79df0e-faed-40f3-819e-8f2e8202aab6","name":"Convivencia pacífica en la familia, escuela y comunidad."},{"id":"939614fc-6ded-48f9-bc8c-af559bcd798d","name":"Comunicación respetuosa."},{"id":"235f497f-8bee-4cd2-8565-bce2b3c6062d","name":"Cooperación y trabajo en equipo."}]}],"grade_levels":["4to"],"subjectId":"sociales","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"1fa7ba0a-18cb-45ec-93fb-34c3a03a7631-block-1","themes":["Deberes y derechos civiles y políticos","Aspectos principales de la educación vial","Cultura de paz y manejo de conflictos","Valores importantes para la convivencia","Participación, justicia, respeto, responsabilidad, libertad y tolerancia","Convivencia vial","Cultura de ahorro","Situaciones de violencia y corrupción","Respeto a las demás personas","Relaciones armoniosas"],"conceptual":"Convivencia humana\n–\tDeberes y derechos civiles y políticos.\n–\tAspectos principales de la educación vial.\n–\tCultura de paz y manejo de conflictos.\n–\tValores importantes para la convivencia.\n–\tParticipación, justicia, respeto, responsabilidad, libertad y tolerancia.\n–\tConvivencia vial.\n–\tCultura de ahorro.\n–\tSituaciones de violencia y corrupción.\n–\tRespeto a las demás personas.\n–\tRelaciones armoniosas.\n ","procedural":"–\tRealización de actividades creando símbolos patrios originales vinculados al contexto actual.\n–\tElaboración de periódicos escolares sobre los derechos fundamentales y los deberes en la Constitución dominicana.\n–\tIdentificación de situaciones que inciden en los accidentes de tránsito, aportando posibles soluciones.\n–\tLevantamiento de estadísticas sobre los accidentes de tránsito en periodos determinados y elaboración de proyecto sobre las posibles medidas para evitarlos, fomentando una cultura de convivencia pacífica en la circulación terrestre.\n–\tExploración y lectura de diversas fuentes sobre la convivencia de los primeros habitantes de nuestra isla.\n–\tAnálisis de los valores sociales y espirituales que favorecen la convivencia armoniosa en la familia, la escuela y otros entornos sociales; su apropiación mediante estrategias y técnicas como: debates, dramatizaciones, otras.\n–\tPlanteamiento y discusión de normas para la convivencia armoniosa en el aula, promoviendo la cultura de paz en el centro educativo.\n–\tElaboración de acciones en el aula que induzcan a la construcción de la cultura del ahorro de los recursos naturales, materiales y económicos\n ","attitudinal":"–\tValoración de la vida y su integridad. \n–\tRespeto por las normas de convivencia y las relaciones armoniosas.\n–\tInterés por la solución de conflictos de forma pacífica.\n–\tRespeto de los símbolos patrios en cualquier espacio.\n–\tPosición crítica ante el incumplimiento de los valores.\n "}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:20:36.185Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('32556908-8127-4713-ab62-f080d0422071', 'naturales', '4to', '{"id":"32556908-8127-4713-ab62-f080d0422071","name":"Ciencias de la vida ","themes":[{"id":"0157729b-979d-4d40-b050-0f3e4056dfa9","name":"Materia y sus propiedades","subthemes":[{"id":"22ede522-b714-4bcd-8568-477b84bc2aa4","name":"Qué es la materia y dónde la encontramos."},{"id":"ef46d249-3512-428f-8421-553e1277ebf4","name":"Propiedades de la materia (forma, tamaño, color, estado)."},{"id":"0b771a80-d481-4280-961b-7d0e973ed3ad","name":"Cambios simples en la materia."}]},{"id":"2b739b78-04eb-4442-a503-0dd6a011da65","name":"La biodiversidad de los seres vivos y su organización celular","subthemes":[{"id":"5c640ee8-e654-488c-b331-22dde132c566","name":"La célula como unidad básica de los seres vivos."},{"id":"1f399709-cedc-4a8f-b892-d829e5a07dd4","name":"Diversidad de seres vivos en el planeta."},{"id":"56360a8a-d11f-4315-9db4-938ee070df12","name":"Importancia de la biodiversidad para la vida."}]},{"id":"f1151be2-8128-4dec-8963-9f9566582ac9","name":"Las plantas: endémicas y nativas","subthemes":[{"id":"a60b788a-3526-4c7d-bf26-b5f83b1e4de9","name":"Qué son plantas endémicas y nativas."},{"id":"a0c423ac-6b80-4cfd-a131-a67f83c88b21","name":"Ejemplos de plantas endémicas y nativas de Rep. Dom."},{"id":"bb7c8011-264b-485d-807e-853b189565ac","name":"Importancia de las plantas para el ambiente y la vida."}]},{"id":"ed924ac2-2160-4922-b27c-2e4a0c8b8a93","name":"Los animales: endémicos y nativos","subthemes":[{"id":"456420ae-5c78-4859-a3d2-f142191cf992","name":"Importancia de la fauna para el equilibrio natural."},{"id":"7edd33fd-6ee5-41e9-8e80-06a72b8d8e4b","name":"Qué son animales endémicos y nativos."},{"id":"ef5351c4-ffc9-463a-94ba-cd814af0fa5b","name":"Ejemplos de animales endémicos y nativos del país."}]},{"id":"83a2a2c4-6585-479d-aaa0-27a79a57f4d8","name":"Reproducción: asexual y sexual","subthemes":[{"id":"b9763b42-0685-43b0-beed-70aaf4d28342","name":"Reproducción sexual en los seres vivos."},{"id":"23759a98-ae8e-4551-8a78-190d9bb49039","name":"Importancia de la reproducción para la continuidad de la vida."},{"id":"7023c275-e6f0-40b5-b17d-890045aa5a7c","name":"Reproducción asexual en plantas y animales."}]},{"id":"0f6920d3-db00-43b2-9bf4-ed7b6df6b213","name":"Caracteres hereditarios","subthemes":[{"id":"1411a1ae-dc90-490c-9641-25eaf8bf7918","name":"Qué son los caracteres hereditarios."},{"id":"06fe451d-7cdf-44ef-bf05-d758acf84ad5","name":"Características que se heredan de padres a hijos."},{"id":"a8f65795-3ffb-4456-9742-6f204cab3ba0","name":"Importancia de la herencia en los seres vivos."}]},{"id":"38265599-c146-44e0-a058-0d40e3f8d4d1","name":"Energía y conservación","subthemes":[{"id":"a1b8a6c9-c0a9-434b-8ce7-faa657b9f813","name":"Nutrición en plantas y animales"},{"id":"e479040c-6c6b-4f83-a56f-1a7fe9542b1a","name":"La fotosíntesis"},{"id":"0942a418-5357-4d2c-956e-442f3191e7a4","name":"Flujo de energía en ecosistemas."}]},{"id":"d0b1283c-6694-41da-aeb1-fff7b418409d","name":"Interacción y movimiento","subthemes":[{"id":"7becbeb5-dfe9-4e99-8ca1-936e9c717717","name":"Movimiento en planta"}]},{"id":"67a579c7-e714-4ac1-9318-b888a02beb7c","name":"Sistema y mecanismo","subthemes":[{"id":"7c2963f3-e080-448a-a33b-ff49b7fd71be","name":"Los ecosistemas"},{"id":"ea597f42-f60f-43e8-b78c-3308404aa5dc","name":"Los recursos naturales"},{"id":"08af1a32-3603-4336-a7e2-7029f25ca804","name":"La agricultura: cultivos y huertos escolares"}]},{"id":"f0cea955-ec1b-4674-89ea-afed5361d138","name":"Salud y ser humano","subthemes":[{"id":"e02030e1-91f6-4b2a-ace4-5e7007939b45","name":"Desarrollo y cambio en el ser humano"},{"id":"f77bdb90-ee4e-493c-a623-aabc9ea3d12b","name":"Cuidado del cuerpo humano"},{"id":"48daa4d6-a398-4cf1-b51a-b07464728753","name":"Enfermedades tropicales y virales (transmitidas por vectores)"}]}],"grade_levels":["4to"],"subjectId":"naturales","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"32556908-8127-4713-ab62-f080d0422071-block-1","themes":["Materia y sus propiedades","La biodiversidad de los seres vivos y su organización celular","Las plantas: endémicas y nativas","Los animales: endémicos y nativos","Reproducción: asexual y sexual","Caracteres hereditarios","Energía y conservación","Interacción y movimiento","Sistema y mecanismo","Salud y ser humano"],"conceptual":"Ciencias de la Vida \nMateria y sus propiedades\n–\tLa biodiversidad de los seres vivos y su organización celular.\n–\tLas plantas: endémicas y nativas.\n–\tLos animales: endémicos y nativos.\n–\tReproducción: asexual y sexual.\n–\tCaracteres hereditarios.\nEnergía y conservación\n–\tNutrición en plantas y animales.\n–\tLa fotosíntesis.\n–\tFlujo de energía en ecosistemas.\nInteracción y movimiento – Movimiento en plantas.\nSistema y mecanismo\n–\tLos ecosistemas y los recursos naturales.\n–\tLa agricultura: cultivos y huertos escolares.\nSalud y ser humano\n–\tDesarrollo y cambio en el ser humano.\n–\tCuidado del cuerpo humano.\n–\tEnfermedades tropicales y virales (transmitidas por vectores).\n ","procedural":"Ciencias de la Vida\n–\tDescripción e interpretación de las células vegetal y animal. \nProcedimiento: uso de modelos, material audiovisual (video educativo, película, documental, atlas, lámina), utilización de instrumentos (microscopio, estereoscopio), observación, dibujos, comparación, conclusión, exposición de resultados.\n–\tIndagación: seres vivos unicelulares y multicelulares. Procedimiento: formulación de preguntas, búsqueda de información, planteamiento de hipótesis, experimentación, interpretación, selección de la información, comparación, inferencia, argumentación, dibujos, reporte en diario de laboratorio.\n–\tObservación de las partes de las plantas: raíz, tallo, hoja, flor, fruto, semilla. Procedimiento: exploración de plantas de su entorno y construcción de modelos.\n–\tObservación de raíces, hojas y flores de su entorno. Procedimiento: utilización de recursos del medio, materiales didácticos y audiovisuales, recolección de información, comparación, clasificación, descripción, dibujos, comunicación de los resultados y reporte diario de laboratorio.\n–\tExploración del cuerpo de los animales de su entorno. Procedimiento: uso de material didáctico (atlas, láminas), instrumentos (microscopio, estereoscopio), audiovisuales (videos, películas, documentales), construcción de modelos, comparación, clasificación, descripción, comunicación oral y escrita, dibujos.\n–\tCaracterización del cuerpo, órganos y sistemas de la especie humana (digestivo, circulatorio, respiratorio, excretor, nervioso y reproductor). Procedimiento: uso de material didáctico (láminas, atlas, modelos), audiovisual (videos, películas, documentales) y aparatos (microscopio, estereoscopio), construcción de modelos, comparación, clasificación, descripción, inferencia, comunicación oral y escrita, dibujos.\n \n–\tIndagación sobre los cambios biológicos que ocurren durante la pubertad. Procedimiento: exploración, utilización de material didáctico (láminas, libros, atlas), audiovisuales (videos, películas, documentales), recolección de información, comparación, descripción, inferencia, comunicación de resultados.\n–\tIndagación sobre la reproducción sexual y asexual en los seres vivos. Procedimiento: formulación de preguntas, búsqueda de información, utilización de material didáctico (láminas, libros, atlas) y audiovisual (videos, películas, documentales), recolección de información, comparación, descripción, inferencia, comunicación de resultados.\n–\tIndagación sobre la reproducción sexual y asexual en los seres vivos. Procedimiento: formulación de preguntas, búsqueda de información, utilización de material didáctico (láminas, libros, atlas) y audiovisual (videos, películas, documentales), recolección de información, comparación, descripción, inferencia, comunicación de resultados.\n–\tExperimentación (guiada) sobre el proceso de fotosíntesis en las plantas. Procedimiento: recolección de información, formulación de preguntas, planteamiento de hipótesis, experimentación, registro de información, comparación, inferencia, argumentación, discusión, comunicación de resultados, redacción y exposición.\n–\tExploración de componentes del entorno: bióticos y abióticos, y su interacción en el entorno. Procedimiento: \nobservación, preguntas, planteamiento de hipótesis, búsqueda de información, descripción, medición, tabulación, comparación, inferencia, argumentación, contrastación de las hipótesis, discusión, conclusión, exposición.\n–\tIndagación sobre los recursos naturales de la isla de Santo Domingo. Procedimiento: observación, interpretación de mapas temáticos, recolección de información, clasificación, comparación, construcción de modelos, dibujos, comunicación oral y escrita.\n–\tIndagación sobre la biodiversidad autóctona, flora y fauna (nativa y endémica), de la isla de Santo Domingo. Procedimientos: observación, recolección de información, construcción de modelos, clasificación, descripción, elaboración e interpretación de mapas temáticos, interpretación, comentarios, exposición.\n–\tIndagación sobre las enfermedades de las plantas y animales que habitan en su entorno inmediato o localidad. Procedimiento: preguntas de investigación, planificación, búsqueda de información, diseño, planteamiento de hipótesis, entrevistas, experimentación, toma de datos, interpretación, selección de información, inferencia, redacción y exposición.\n ","attitudinal":"–\tMotivación e interés en el uso sostenible de los recursos, asumiendo una actitud de ahorro e integrándose al reúso, reducción y reciclaje de materiales.\n–\tValoración y protección de la biodiversidad, así como de los entornos local, regional y global.\n–\tManifestación de cooperación e interés ante la situación de salubridad de su entorno, contribuyendo al mantenimiento de un espacio adecuado para una vida de calidad.\n–\tDemostración de interés por aprender sobre el funcionamiento y la salud de los sistemas del cuerpo humano.\n–\tParticipación en los proyectos, en la toma de decisiones y en la búsqueda de soluciones a situaciones problemáticas.\n "}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:20:36.185Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('478b0a16-3c48-40a8-87fa-f6343d784ab9', 'naturales', '4to', '{"id":"478b0a16-3c48-40a8-87fa-f6343d784ab9","name":"Ciencias físicas","themes":[{"id":"cbe528a0-4922-43e4-9fdc-510219ffa4c7","name":"Materia y sus propiedades ","subthemes":[{"id":"59bdcdda-436b-47ae-833b-a89d2bafcc35","name":"La luz"},{"id":"d9d453bb-1ece-4049-82eb-0e8eb11edfff","name":"Los colores"},{"id":"e6d9a4bb-5f33-48c5-a69d-b6798d66424c","name":"Reflexión, refracción y difracción"},{"id":"39f6ea36-9a44-4697-8c5c-22f8785720fd","name":"Sustancias, combinaciones y mezclas (homogéneas y heterogéneas)."}]},{"id":"43d51cf0-a0e3-41bb-a825-8ddf3d7a327f","name":"Energía y conservación","subthemes":[{"id":"4d620a9a-a2dd-455a-a7df-4b70ee9d75de","name":"Energía química"},{"id":"3c8cd789-2517-44b6-98a2-d5452756dc6a","name":"Energía"},{"id":"fef950f7-ed3a-4fed-99e8-8babd170d96f","name":"Transformación"},{"id":"5b4d1dcb-eedd-44bd-8fc0-f12a239b9dd6","name":"Transmisión "},{"id":"af65e5b7-cc44-4aab-8fbb-c6dcd518fb62","name":"Energía solar"}]},{"id":"6fb1ba42-8cb8-4873-b8ac-103078ea072c","name":"Interacción y movimiento","subthemes":[{"id":"9373b1a2-a693-4d42-a492-5e701166459d","name":"Movimiento en línea recta  (luz). "},{"id":"9b2f03a9-ff05-44be-bde5-90d5d4396316","name":"Interacción de la luz con líquido y sólido."}]},{"id":"caf8bb7a-97be-4c29-8a9f-c123555e8d3a","name":"Sistema y mecanismo","subthemes":[{"id":"e2690819-3a75-4d03-9d82-51168296a6f7","name":"Prismas, espejos y lentes. "},{"id":"4705ce50-74e4-44bc-9b25-8e206f2febae","name":"Instrumentos ópticos."},{"id":"1775ad44-ce83-401e-a906-3cb3229f1171","name":"Mecanismos de transmisión de movimiento (palancas, poleas simples y distintas ruedas, tornillos sin fin)"},{"id":"90949e9a-e9ad-4f31-9fc9-43418c45295e","name":"Tecnología en la medicina"},{"id":"2f18fe34-859a-4d30-8b92-511de57ed12d","name":"Placa de rayos X, sonografía, análisis médicos e instrumentos ópticos."}]},{"id":"4ad32745-1141-4309-ac5a-80c332f17692","name":"El Poder de las Ondas: Aplicaciones y Descubrimientos","subthemes":[]}],"grade_levels":["4to"],"subjectId":"naturales","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"478b0a16-3c48-40a8-87fa-f6343d784ab9-block-1","themes":["Materia y sus propiedades ","Energía y conservación","Interacción y movimiento","Sistema y mecanismo","El Poder de las Ondas: Aplicaciones y Descubrimientos"],"conceptual":"\"Ciencias físicas\"\nMateria y sus propiedades – La luz.\n–\tLos colores.\n–\tReflexión, refracción y difracción.\n–\tSustancias, combinaciones y mezclas (homogéneas y heterogéneas).\nEnergía y conservación\n–\tEnergía, transmisión y transformación: solar y química. \nInteracción y movimiento\n–\tInteracción de la luz con líquido y sólido.\n–\tMovimiento en línea recta \n(luz). \nSistema y mecanismo\n–\tPrismas, espejos y lentes. Instrumentos ópticos.\n–\tMecanismos de transmisión de movimiento (palancas, poleas simples y distintas ruedas, tornillos sin fin).\n–\tTecnología en la medicina (placa de rayos X, sonografía, análisis médicos e instrumentos ópticos).\n ","procedural":"Ciencias físicas\n–\tClasificación de materiales transparentes, opacos y traslúcidos. Procedimiento: exploración, comparación, clasificación, descripción, conclusión de hallazgos.\n–\tExperimentación de la refracción de la luz en líquidos. Procedimiento: observación, utilización de instrumentos, medición, descripción, inferencia, dibujos y registro de información en diario de laboratorio.\n–\tObservación de la difracción de la luz a través de una o dos rendijas. Procedimiento: Exploración, construcción de modelos, descripción, esquemas o gráficos, comunicación en forma oral y escrita.\n–\tExploración sobre el comportamiento de la luz a través de distintas sustancias. Procedimiento: utilización de instrumentos, recolección y registro de informaciones, análisis y discusión.\n–\tExperimentación sobre la reflexión de la luz: ángulo de incidencia y ángulo de reflexión. Procedimiento: observación, uso de instrumentos, recolección de información, comparación, dibujo de esquema y registros en diario de laboratorio.\n–\tExperimentación sobre la descomposición de la luz blanca con un prisma. Procedimiento: exploración, utilización de instrumentos, descripción, comunicación de resultados mediante el uso de esquemas y dibujos a colores.\n–\tDescripción de la transmisión de energía (radiación de la luz). Procedimiento: formulación de preguntas, recolección de información, utilización de instrumentos, planificación de experimentos, puesta en común de resultados.\n–\tExperimentación sobre la transformación de la energía: solar y química. Procedimiento: observación, utilización de instrumentos, construcción de modelos, comparación, descripción, esquemas, gráficos y diario de laboratorio.\n–\tObservación de cámara oscura, caleidoscopio, microscopio sencillo. Procedimiento: exploración, formulación de preguntas, construcción de modelos, planificación de experimentos, presentación de resultados.\n–\tIndagación a partir de la observación y comparación entre sustancias, combinaciones y mezclas.\n–\tExperimentación(guiada) con distintos materiales que constituyen las mezclas homogéneas y heterogéneas. Procedimiento: recolección de información, utilización de materiales de uso cotidiano, planificación de experimentos, comparación, clasificación, comunicación oral y escrita, registro de información en el diario de laboratorio.\n–\tExperimentación (guiada) sobre técnicas de separación de mezclas. Procedimiento: exploración, formulación de preguntas, recolección de información, descripción, utilización o construcción de instrumentos y equipos sencillos, registro de información, comunicación escrita.\n–\tDiseño y elaboración equipos utilizando materiales reciclables para la realización de las separaciones de mezclas. Procedimiento: planificación, diseño, recolección de materiales, elaboración de equipos, experimentación.\n ","attitudinal":"–\tManifestación de curiosidad, creatividad, objetividad.\n–\tComunicación de sus ideas, seguimiento de procedimiento, trabajo individual y colaborativo. Respeto a las ideas y diferencias de las demás personas, solidaridad. Utilización sostenible de los recursos tecnológicos de que dispone.\n–\tDemostración de interés por conocer las propiedades y características de la luz y la materia; por utilizar herramientas, construir máquinas y modelar estructuras e instrumentos, así como por la preparación y separación de mezclas.\n–\tMotivación por aprender cosas nuevas de su entorno material y tecnológico.\n–\tAdopción de medidas de cuidado, protección y prevención con respecto a la luz, sustancias y mezclas que puedan afectar sus órganos o su salud.\n–\tEvaluación y prevención de los riesgos de la interacción de la radiación con la materia. Asume la importancia de las informaciones médicas acerca de su salud.\n–\tValoración de los aportes y avances científicos y tecnológicos en los aparatos electrónicos médicos y su impacto en la sociedad y el Medioambiente.\n "}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:20:36.185Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('a381f5fc-38bf-4bb1-9235-9bc53ab48d00', 'naturales', '4to', '{"id":"a381f5fc-38bf-4bb1-9235-9bc53ab48d00","name":"Ciencias de la tierra y el universo ","themes":[{"id":"0edbb88d-7847-4db4-a6cc-1289d1ab543c","name":"Materia y sus propiedades","subthemes":[{"id":"156c8ae3-8804-419a-82ee-da83599ad2c9","name":"Composición física del planeta Tierra"},{"id":"d9ae73b5-8fd9-47ed-bf38-24b387ce772b","name":"Fenómenos naturales. Sismos."}]},{"id":"e7f6bbfb-3e8d-4d07-87b5-95b7859ddf19","name":"Energía y conservación ","subthemes":[{"id":"f7813f8f-fe4f-4323-88ff-35e2bce21f42","name":"El Sol: fuente de energía."},{"id":"934e41c0-60d2-4e95-a679-cad99db81bfd","name":"Eficiencia energética."}]},{"id":"c51cc27e-a330-4bb5-ac9b-91ad9f2be251","name":"Sistema y mecanismo","subthemes":[{"id":"f369b322-a238-4278-9b82-cda942dde35a","name":"–\tSistema Solar: Sol, planetas, satélites, luna, cometas."}]},{"id":"12717e60-62ec-4f38-8759-ef1f2e0a0987","name":"Interacción y movimiento","subthemes":[{"id":"555d6138-ffd2-455e-8d43-d1f7b07fb2bb","name":"Eclipse."},{"id":"851276f8-b11c-4184-9802-77a2da8f8b8b","name":"Movimiento y trayectoria de los planetas del Sistema Solar."}]}],"grade_levels":["4to"],"subjectId":"naturales","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"a381f5fc-38bf-4bb1-9235-9bc53ab48d00-block-1","themes":["Materia y sus propiedades","Energía y conservación ","Sistema y mecanismo","Interacción y movimiento"],"conceptual":"\"Ciencias de la tierra y el universo\"\n \nMateria y sus propiedades\n–\tComposición física del planeta Tierra.\n–\tFenómenos naturales. Sismos.\nEnergía y conservación \n–\tEl Sol: fuente de energía.\n–\tEficiencia energética.\nSistema y mecanismo\n–\tSistema Solar: Sol, planetas, satélites, luna, cometas.\nInteracción y movimiento\n–\tMovimiento y trayectoria de los planetas del Sistema Solar.\n–\tEclipse.\n ","procedural":"\"Ciencias de la tierra y el universo\"\n \n–\tDescripción y comparación entre el manto y la corteza del planeta Tierra. Comunicación por medio de dibujos y esquemas.\n–\tObservación, descripción y comparación entre rocas y minerales, clasificándolos de acuerdo a sus propiedades y características físicas.\n–\tAnálisis y discusión sobre sismos y energía, reconociendo que los sismos liberan grandes cantidades de energía capaces de hacer daño a estructuras y seres vivos.\n–\tExperimentación guiada sobre el Sol como fuente de energía. Análisis a través de fuentes tecnológicas diferentes, y comunicación de resultados.\n–\tObservación, descripción y comparación entre la Luna, el Sol, planetas, estrellas y cometas. Comunicación por medio de dibujos y esquemas.\n–\tAnálisis y discusión (comparación, clasificación, descripción) sobre los planetas, la Luna y otros cuerpos del Sistema Solar, y sus movimientos y trayectorias alrededor del Sol. Comunicación por medio de dibujos, esquemas, observación de videos.\n–\tDescripción y experimentación guiada sobre los eclipses, comunicando sus observaciones por medio de dibujos, o por el análisis de lecturas y noticias.\n ","attitudinal":"–\tMotivación e interés por aprender sobre sí mismo, sobre su entorno y por mantener una convivencia sana, mostrando solidaridad, respeto y colaboración con los demás.\n–\tAdopción de medidas de cuidado y utilización sostenible de los recursos naturales.\n–\tDemostración de interés por seguir instrucciones de seguridad y cuidado ante la manifestación de riesgos asociados a fenómenos naturales (sismos)\n–\tValoración de la Luna y el Sol y los beneficios para la vida en el planeta Tierra.\n "}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:20:36.186Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('5f15ca19-5f8d-4d0e-8332-92604c7384a4', 'formacion-humana', '5to', '{"id":"5f15ca19-5f8d-4d0e-8332-92604c7384a4","name":"Conceptos de unidad","themes":[{"id":"48902533-8d39-41d9-9d7e-e687081bcc16","name":"La maravilla del cuerpo","subthemes":[{"id":"d62d7ba4-9f51-489d-b449-82cb5b12796d","name":"Partes del cuerpo y sus funciones principales."},{"id":"898ccf7e-86ec-422d-a517-9701d60fadf9","name":"Cómo el cuerpo trabaja como un sistema (órganos y cuidado)."},{"id":"a3fedf39-e438-49a1-85f0-5cb2b7fad3ea","name":"El cuerpo como regalo valioso: autoestima y aceptación."}]},{"id":"742f738f-4860-4caf-bc32-409f574dc164","name":"Cambios y desarrollo del cuerpo","subthemes":[{"id":"0bd6e5da-fd0e-4fb6-810c-90b8e73186f5","name":"Crecimiento saludable: hábitos que apoyan el desarrollo."},{"id":"1cb81507-8b45-456a-bdab-94cd57039d92","name":"Cambios físicos en la niñez hacia la preadolescencia."},{"id":"ba193c5f-1c08-49b0-9206-52719631d94f","name":"Cambios emocionales: estado de ánimo y sensibilidad."}]},{"id":"9dd9a555-befa-4fc3-8dfd-836361ae1de5","name":"Cuidado y respeto por el cuerpo / Importancia del cuerpo","subthemes":[{"id":"6ef90b4e-090b-4212-a70b-cb595877d9ed","name":"Respeto al propio cuerpo y límites personales."},{"id":"f66a0859-414e-4ead-b50b-80e6c411e8e0","name":"Alimentación, descanso y actividad física como cuidado del cuerpo."},{"id":"47ef9f8d-663e-4534-a99d-8f6b6caa4191","name":"Higiene personal diaria y prevención de enfermedades."}]},{"id":"6b29045b-1be5-4d26-a46e-97b02b88be93","name":"Desarrollo afectivo sexual","subthemes":[{"id":"17178d79-f266-48b7-8bdc-09f28992b336","name":"Afectos y emociones: cómo expresar cariño con respeto."},{"id":"842c49cb-f2ef-4cce-bbd3-779d1bdb3abe","name":"Diferencia entre amistad, cariño y enamoramiento (según la edad)."},{"id":"e162b662-18e2-4816-bcdf-5663100a7d00","name":"Prevención del abuso: partes privadas y pedir ayuda."}]},{"id":"dd87be8e-cef3-4af1-876c-b09710cb4539","name":"Deberes y derechos de la niñez","subthemes":[{"id":"8a9e3499-6d0c-4f4c-a7db-55898f85cd5e","name":"Derechos fundamentales: educación, salud y protección."},{"id":"724713e2-877d-46a4-bd56-df21a5d2b7fd","name":"Instituciones que protegen a la niñez (familia, escuela, comunidad)."},{"id":"7b7f0062-5aaf-4e76-b2a6-9a30f0fd593a","name":"Deberes en casa y escuela: responsabilidad y disciplina."}]},{"id":"94f1fe19-1e7f-4843-a75b-e5f6d0663f38","name":"Normas de convivencia","subthemes":[{"id":"ad590513-1666-4405-accd-bfa89f0a2c30","name":"Respeto, cortesía y tolerancia con los demás."},{"id":"ae39ed0f-21dd-45e0-a006-a8ff274c8343","name":"Respeto, cortesía y tolerancia con los demás."},{"id":"50d01e6d-d6ae-43b2-8165-c120f0c5b4e4","name":"Normas en el aula y en el hogar: para qué sirven."}]},{"id":"4d7138ae-649c-4c19-9576-7a7a59f5af1b","name":"Conflictos interpersonales","subthemes":[{"id":"77c111b8-16ac-4841-96fd-ae099cce5290","name":"Técnicas de solución pacífica: acuerdos y mediación."},{"id":"2ecdd4fc-7a08-4344-9884-4ae74032cd09","name":"Manejo del enojo: autocontrol y comunicación."},{"id":"b0eb3f07-e39f-4325-a1e2-b3d9462ff945","name":"Causas comunes de conflictos entre niños/as."}]},{"id":"6b04d69e-503d-40b3-8216-c474055578cd","name":"Relaciones interpersonales en la familia y escuela","subthemes":[{"id":"7d2e48b9-7368-4dfe-9b0d-9424cadda752","name":"Respeto a la diversidad: aceptar diferencias."},{"id":"cc2f2633-b9e6-4edd-b045-29f4ddfd7543","name":"Comunicación asertiva con padres, docentes y compañeros."},{"id":"98e70bc3-e94d-4f3a-81b2-b0fa41e8acc2","name":"Cooperación y trabajo en equipo."}]},{"id":"3f30ccc7-7aa5-4fe9-91b4-91a09ff63ae5","name":"Familia y crecimiento integral","subthemes":[{"id":"d1e1bc7c-c08f-45e9-ab05-36fc055b6862","name":"La familia como base emocional y formadora de valores."},{"id":"af02d761-4fd1-4abf-81a9-81f022be236f","name":"Influencia de la familia en hábitos y comportamiento."},{"id":"2eb8ac06-aeaa-40b1-b3d5-3a880d68970f","name":"Apoyo familiar en lo académico y personal."}]},{"id":"d4f70abf-59e1-4cd6-a42f-8792048b671f","name":"Tipos de familia","subthemes":[{"id":"30d7ad0a-f753-4495-8f06-22d027104f5b","name":"Familias reconstituidas y familias adoptivas."},{"id":"78d24605-a2f5-4d78-9556-acb82c101851","name":"Familias nucleares, extendidas y monoparentales."},{"id":"9302e80d-d822-497d-9e23-f751be6a380d","name":"Respeto y valoración de todos los tipos de familia."}]},{"id":"8becd174-78d9-42ca-ba24-8c38f2de4cc5","name":"Derechos y deberes en la familia","subthemes":[{"id":"22bd431c-b99d-4245-ba4f-fe895831d99d","name":"Deberes en casa: colaboración y obediencia responsable."},{"id":"7b803ed2-5993-456e-b319-968f31c03156","name":"Respeto mutuo: trato digno entre todos los miembros."},{"id":"8e914d87-9281-42f4-8c65-5ce7b62eec22","name":"Derecho a ser cuidado/a, escuchado/a y respetado/a."}]},{"id":"8b9e6164-3561-4d8c-9c3c-56d710c64ee8","name":"Roles en la familia","subthemes":[{"id":"b56199eb-d7d6-42ca-95ff-63d080742773","name":"Roles de padres/madres o tutores: cuidado y orientación."},{"id":"0b9ad60e-2cd9-4f54-a6ee-465827aa0c63","name":"Roles de hijos/as: estudio, respeto y colaboración."},{"id":"b2a1ac4a-28c1-4552-b244-6e45450421b5","name":"Igualdad y equidad: roles sin discriminación."}]},{"id":"ccf60d4c-194a-4c1b-9348-50ac4553455c","name":"Corresponsabilidad y diálogo en la familia","subthemes":[{"id":"7429580d-e1b6-4337-bcc8-0fc1d302fd64","name":"Corresponsabilidad: tareas del hogar compartidas."},{"id":"218efca7-0240-44ef-b41b-1de1557f2a42","name":"Importancia del diálogo para resolver problemas."},{"id":"8d012a14-1108-4683-8866-8bac93381bba","name":"Escucha activa y acuerdos familiares."}]},{"id":"c63d0e1b-338f-400c-8d32-2e47039e1060","name":"Familia, regalo de Dios","subthemes":[{"id":"9331946e-2c02-424e-bd8c-16ed002ec6f7","name":"Gratitud: reconocer el amor y cuidado familiar."},{"id":"c5c6ad13-3dbf-4d44-8647-fabb51a4fbfa","name":"La familia como comunidad de amor y fe."},{"id":"c96c644e-ddf7-4042-9856-6ce3f0e277a7","name":"Valores cristianos en la familia: respeto, perdón y solidaridad."}]},{"id":"df59f0a8-eaeb-4e77-b43a-4c7ec8af407f","name":"Entorno natural como casa común","subthemes":[{"id":"149123db-4524-4ea0-b939-278caa6f536c","name":"La naturaleza como hogar compartido: por qué debemos cuidarla."},{"id":"4e17027b-f26f-4e84-9827-53ae9120a720","name":"Relación entre seres humanos, animales, plantas y agua."},{"id":"23032aa7-e2aa-4785-aa70-9325279670d9","name":"Problemas ambientales cercanos: basura, contaminación y deforestación."}]},{"id":"a52b5f30-be18-4d01-937c-5c33073a41b7","name":"Acciones ecológicas en el cuidado de las personas y del entorno natural","subthemes":[{"id":"cb9f1087-312c-4154-99dc-612936a03271","name":"Jornadas ecológicas: limpieza, siembra y protección de áreas verdes."},{"id":"e95408b5-650c-47c6-8ca6-a4abf8e0ce8f","name":"Acciones ecológicas diarias: reducir, reutilizar y reciclar."},{"id":"7003177b-a07d-4a94-b642-b312ccfb09a5","name":"Cuidado del agua y la energía en casa y escuela."}]},{"id":"ac555a3e-a3b6-427c-a009-0d119c06f524","name":"El país donde nació Jesús de Nazaret","subthemes":[{"id":"187f34f7-abf0-44f7-abdd-4b27acfb249f","name":"Ciudades importantes relacionadas con Jesús: Belén y Nazaret."},{"id":"ee7b6b0b-0874-4168-b5f0-da820ff329d6","name":"Cómo era el ambiente (clima, vida cotidiana) en ese territorio."},{"id":"88392cbb-ff41-445e-9552-bd53ba894b7c","name":"Ubicación geográfica: Palestina / Israel (contexto histórico)."}]},{"id":"14608053-aaa2-40db-948c-672d61fa42ee","name":"Costumbres y prácticas religiosas en la época de Jesús de Nazaret","subthemes":[{"id":"8b143d2d-41db-4632-92c8-cabf3cd0407d","name":"Oración, lectura de las Escrituras y normas religiosas de la época."},{"id":"c1e207b2-2c05-4220-886a-88641a6909ea","name":"Lugares religiosos: sinagogas y el Templo de Jerusalén."},{"id":"d2d48c66-72bf-4460-9010-17cf452653fb","name":"Celebraciones importantes: Pascua y otras fiestas judías."}]}],"grade_levels":["5to"],"subjectId":"formacion-humana","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"5f15ca19-5f8d-4d0e-8332-92604c7384a4-block-1","themes":["La maravilla del cuerpo","Cambios y desarrollo del cuerpo","Cuidado y respeto por el cuerpo / Importancia del cuerpo","Desarrollo afectivo sexual","Deberes y derechos de la niñez","Normas de convivencia","Conflictos interpersonales","Relaciones interpersonales en la familia y escuela","Familia y crecimiento integral","Tipos de familia","Derechos y deberes en la familia","Roles en la familia","Corresponsabilidad y diálogo en la familia","Familia, regalo de Dios","Entorno natural como casa común","Acciones ecológicas en el cuidado de las personas y del entorno natural","El país donde nació Jesús de Nazaret","Costumbres y prácticas religiosas en la época de Jesús de Nazaret"],"conceptual":"-\tLa maravilla del cuerpo. \n-\tCambios y desarrollo del cuerpoCuidado y respeto por el cuerpo. Importancia del cuerpo.\n-\tDesarrollo afectivo sexual - Deberes y derechos de la niñez.\n-\tNormas de convivencia.\n-\tConflictos interpersonales. \n-\tRelaciones interpersonales en la familia y escuela.\n-\tFamilia y crecimiento integral.\n-\tTipos de familia.\n-\tDerechos y deberes en la familia.\n-\tRoles en la familia.\n-\tCorresponsabilidad y diálogo en la familia.\n-\tFamilia, regalo de Dios.\n ","procedural":"-\tElaboración de un cuadro comparativo sobre los cambios ocurridos desde su nacimiento en los aspectos físico, emocional y social.\n-\tIdentificación y exposición de situaciones de la vida cotidiana que permiten el desarrollo físico, espiritual y emocional de los niños, niñas y adolescentes.\n-\tInteracción acerca de su desarrollo afectivo sexual.\n-\tAnálisis de noticias, sucesos y situaciones que dañan o maltratan y violentan el cuerpo. \n-\tFormulación y aplicación de medidas para el respeto y cuidado del cuerpo a partir del texto bíblico de 1 Corintios 6, 19- 20.\n-\tElaboración de distintas técnicas y recursos (murales, exposiciones, conversaciones, redacciones…) en los que se destaquen las acciones realizadas con el cuerpo que ayudan a la comunicación con las personas. \n-\tOrganización de una celebración donde se exponga todo lo maravilloso que puede hacer con su cuerpo y agradezca a Dios por el regalo del cuerpo y sus capacidades.\n \n-\tSocialización de las normas y leyes que se practican en la convivencia cotidiana, en la familia, la escuela y la comunidad. \n-\tInvestigación sobre las principales normas de convivencia para una relación armónica con las demás personas.\n-\tOrganización de una mesa redonda donde se construya en equipo las normas para mejorar el comportamiento en el aula.\n-\tExposición de los aspectos que hay que fomentar para una convivencia armónica en las relaciones con las demás personas.\n-\tRealización de actividades (sociodramas, exposiciones, conversatorios) donde se presenten situaciones conflictivas en las relaciones interpersonales y la forma de resolverlas.\n-\tExploración sobre la convivencia familiar, destacando los roles y la corresponsabilidad en la familia. \n-\tConstrucción de la historia familiar consultando padres, hermanos, abuelos, bisabuelos tíos, y otras personas de su familia. \n-\tComposición sobre la familia como espacio de crecimiento físico, moral y espiritual.\n-\tInvestigación sobre los derechos y deberes que les corresponden a la familia.\n-\tAnálisis de roles y relaciones entre padres, madres, tutores, hijos e hijas a partir del texto de Efesios 6,1-4\n-\tInvestigación sobre las características de los diferentes tipos de familia en la sociedad dominicana.\n-\tOrganización de una celebración en la que se exponen las producciones, se destaque el amor, el cuidado, la colaboración entre familiares y agradecimiento a Dios por el regalo de su familia.\n-\tInvestigación sobre las características de los diferentes tipos de familia en la sociedad dominicana.\n-\tOrganización de una celebración en la que se exponen las producciones, se destaque el amor, el cuidado, la colaboración entre familiares y agradecimiento a Dios por el regalo de su familia.\n \n-\tArgumentación sobre cómo el trabajo de las personas adultas y la tecnología contribuyen al desarrollo humano y espiritual de los niños, niñas y adolescentes.\n-\tAnálisis sobre la obligatoriedad del trabajo según el texto bíblico de 2 Tesalonicenses 3,10-13.\n-\tInvestigación de los diferentes aportes y beneficios del trabajo de las personas adultas y la tecnología al desarrollo de la obra creadora de Dios.\n-\tSocialización acerca de la necesidad de las ciencias y las tecnologías para el desarrollo social, cultural y espiritual de las personas.\n-\tDramatización de situaciones reales sobre el uso adecuado e inadecuado de las tecnologías en la familia, la escuela y la sociedad.\n-\tRealización de entrevistas a familiares, maestros y vecinos acerca de la importancia de la inclusión de principios éticos en la realización de los trabajos escolares.\n-\tElaboración de murales informativos sobre la importancia del implementar valores éticos en el uso y manejo de las ciencias y las tecnologías en actividades personales, familiares y escolares.\n-\tCelebración festiva donde se expongan las producciones, se reconozcan los beneficios del trabajo de las personas adultas y de las tecnologías en el desarrollo humano y espiritual de los niños, y niñas y adolescentes.\n- Realización de una mesa redonda donde se plantee los principales problemas medio ambientales, identificando sus causas, consecuencias y planteando medidas de soluciones para mejorar nuestra casa común.\n \n-\tInvestigación sobre las principales normas, leyes ecológicas y \nmandamientos ambientales que existen para la protección y cuidado del entorno natural.\n-\tRealización de una campaña de implementación de acciones en nuestra vida cotidiana que contribuyan al cuidado y protección del entorno natural.\n-\tElaboración de un proyecto donde se implementen acciones y cuidado del entorno natural como nuestra casa común, en su contexto familiar, comunitario, escolar y social. \n-\tOrganización de una “creatividad ecológica”, donde los estudiantes elaboren dibujos, fotos, poesías, composiciones, afiches en torno a las soluciones ecológicas y medio ambientales. \n-\tSocialización sobre el sentido de la Navidad y los sentimientos que produce esta celebración en la familia, la escuela, la comunidad y el país.\n-\tPresentación y contemplación del nacimiento de Jesús donde se agradezca a Dios por el nacimiento de su Hijo y por tenerlo como ejemplo de vida.\n-\tPresentación de los siguientes aspectos sobre Palestina: Características geográficas, gastronomía, producción agrícola, costumbres religiosas, forma de gobiernos, lugares turísticos. \n-\tIdentificación y presentación de costumbres religiosas en su familia y comunidad a partir del texto bíblico de Lucas 2, 21-24 y 41-42.\n-\tComparación ente las costumbres y prácticas religiosas de su familia y comunidad a con las del país de Jesús de Nazaret. \n-\tExposición sobre los valores que Jesús predicó y practico al relacionarse con las personas de su tiempo. \n \n-\tRealización de síntesis del mensaje de Jesús sobre el amor y el perdón apoyándose en los textos de Juan 13,3436 y Mateo 18,21-22.\n-\tOrganización de un teatro bíblico sobre la pasión, muerte y resurrección de Jesús a partir de los textos de Lucas 24, 1- 12; 24, 13- 35; Marcos 16, 1- 8 y Juan 20, 1- 19 y otros recursos audiovisuales. \n-\tOrganización de una celebración donde los estudiantes presenten gestos que expresen amor y perdón entre ellos. \n \n ","attitudinal":"-\tAdmiración ante lo que puede hacer con su cuerpo. \n-\tAceptación y alegría de los cambios experimentados en su cuerpo y su persona. \n-\tRechazo al maltrato de su cuerpo y el de otras personas. \n-\tDenuncia de todo tipo de acoso o abuso sexual. \n-\tReclamación de  los derechos de la niñez y cumple con sus deberes.\n-\tPráctica del diálogo y la negociación como forma de solucionar los conflictos interpersonales.\n-\tAprecio por la actitud de amar y perdonar a los demás.\n-\tDisposición para dar y recibir amor y perdón.\n-\tCuriosidad por conocer su ascendencia familiar.\n-\tComunicación y colaboración en su familia.\n-\tAgradecimiento a Dios por el regalo de su familia.\n \n-\tGratitud a Dios por lo que las personas pueden hacer con su trabajo para mejorar la sociedad.\n-\tReconocimiento del esfuerzo y sacrificio de las personas que trabajan. \n-\tAdmiración por los beneficios que el trabajo digno trae a la persona, a la sociedad y al entorno natural.\n-\tAgradecimiento a Dios por las capacidades personales en el manejo y buen uso de las ciencias y las tecnologías.\n-\tRespeto de los principios y valores éticos en el uso de las tecnologías.\n-\tGratitud a Dios por lo que las personas pueden hacer con su trabajo para mejorar la sociedad.\n-\tReconocimiento del esfuerzo y sacrificio de las personas que trabajan. \n-\tAdmiración por los beneficios que el trabajo digno trae a la persona, a la sociedad y al entorno natural.\n-\tAgradecimiento a Dios por las capacidades personales en el manejo y buen uso de las ciencias y las tecnologías.\n-\tRespeto de los principios y valores éticos en el uso de las tecnologías.\n "}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:20:36.186Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('ec3997b2-d8d9-479b-999f-72e27ad4ecfd', 'educacion-artistica', '5to', '{"id":"ec3997b2-d8d9-479b-999f-72e27ad4ecfd","name":"Artes visuales","themes":[{"id":"c35fc2ba-08f0-4a32-87b9-b72576b83537","name":"Escultura en alambre dulce","subthemes":[{"id":"0afdd14d-2deb-402b-8f66-98b3d4540ce3","name":"Creación de figuras (animales, personas, objetos) y acabado final."},{"id":"c21d90ea-2f73-4e83-b748-f40cfc63d590","name":"Materiales y herramientas básicas para trabajar el alambre dulce."},{"id":"d059eac2-8808-4792-996b-662cdfa70541","name":"Técnicas de doblado, enrollado y unión (estructuras simples)."}]},{"id":"43b7d755-6c8e-45cd-be45-03f0c51efb39","name":"La técnica del collage","subthemes":[{"id":"faccf053-e529-47e5-b683-889351620d25","name":"Composición visual en collage: equilibrio, contraste y armonía."},{"id":"d66c1eb5-3e2c-42cf-859c-674aad815f31","name":"Collage con materiales reciclados: papel, tela, revistas, cartón."},{"id":"880fcc13-ebc2-4174-af98-145f968d9fa6","name":"Tipos de collage: recorte, superposición, textura y relieve."}]},{"id":"affc4b33-cd89-4ef7-80ed-ba8139b2ffb7","name":"La imagen audiovisual","subthemes":[{"id":"7999fbad-01dc-4f6f-b6b1-799569e9395a","name":"Elementos del audiovisual: imagen, sonido, texto y movimiento."},{"id":"352eb214-d2b2-4e26-8d77-c884dc3e6ad8","name":"Tipos de producciones: videos cortos, animaciones, documentales."},{"id":"c3bb5dd7-2fcf-4c8e-8ee0-cc89e51fd7f7","name":"Lectura crítica: mensaje, intención y valores en lo audiovisual."}]},{"id":"8db3fc6a-3145-45c9-9b88-f186b71846ad","name":"Arquitectura vernácula: regional y nacional","subthemes":[{"id":"30a5eb4d-ab1a-4e02-9089-7c73c127a3c9","name":"Viviendas y estilos por regiones: campo, costa, montaña."},{"id":"15a8ae87-8b04-40e8-b8aa-f11298598198","name":"Qué es arquitectura vernácula: construcciones tradicionales."},{"id":"8a673102-8298-4cb9-a13c-5d5ae1e762d8","name":"Materiales típicos dominicanos: madera, palma, zinc, barro."}]},{"id":"f9f1bc54-6615-4dd2-b8c6-e019f2fe2222","name":"Estilos en obras artísticas (lenguaje visual)","subthemes":[{"id":"3fe1536a-dac6-4cf7-88e6-22de8365712a","name":"Materiales y técnicas: pintura, escultura, grabado, mixtas."},{"id":"aacf66e7-feea-43e9-8bba-278925342bac","name":"Expresividad: emociones, símbolos y estilo personal del artista."},{"id":"0d244764-8eb1-44ce-9532-10309c996b98","name":"Temas y contextos en el arte: qué representa la obra y por qué."}]},{"id":"b2d42e8b-aa76-4c5d-b29b-801b43c3e039","name":"Costumbrismo en la plástica dominicana: temáticas y estilos","subthemes":[{"id":"08218626-680b-40a7-96df-ce63647cd9a4","name":"Qué es el costumbrismo: vida cotidiana como tema artístico."},{"id":"428d4cab-4aa7-406a-b18e-b112be584104","name":"Temas dominicanos: campo, mercado, carnaval, familia, trabajo."},{"id":"a22f4883-0a41-4c8d-9a5f-79484a9eefcf","name":"Estilo y colores en la plástica dominicana: identidad cultural."}]},{"id":"f77a940c-6af0-43b9-a233-f0e36c99b3c1","name":"Diseño gráfico como comunicación visual","subthemes":[{"id":"ed036d1b-1796-4033-a5d1-42e616d86018","name":"Creación de mensajes visuales: tipografía, color e iconos."},{"id":"87ec9da7-818e-4c08-9622-068a3a020017","name":"El diseño gráfico y su función: informar y orientar."},{"id":"dd763002-8e66-4f39-b2dd-5032d21ee751","name":"Tipos de diseño: señales, etiquetas, afiches, vallas y manuales."}]}],"grade_levels":["5to"],"subjectId":"educacion-artistica","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"ec3997b2-d8d9-479b-999f-72e27ad4ecfd-block-1","themes":["Escultura en alambre dulce","La técnica del collage","La imagen audiovisual","Arquitectura vernácula: regional y nacional","Estilos en obras artísticas (lenguaje visual)","Costumbrismo en la plástica dominicana: temáticas y estilos","Diseño gráfico como comunicación visual"],"conceptual":"\"Artes Visuales\"\n-\tEscultura en alambre dulce - La técnica del collage.\n-\tLa imagen audiovisual.\n-\tArquitectura vernácula: regional y nacional.\n-\tEstilos en obras artísticas en relación con la aplicación del lenguaje visual: temas, contextos, materiales y expresividad.\n-\tCostumbrismo en la plástica dominicana: temáticas y estilos.\n-\tEl diseño gráfico como elemento de comunicación visual: señales, etiquetas, manuales, carteles, vallas, entre otros.\n ","procedural":"Artes Visuales\n-\tDiseño artesanal utilizando las técnicas del papel maché.\n-\tUso del collage como técnica para la realización de obras (procedimientos y posibilidades expresivas).\n-\tLectura e interpretación de imágenes en obras audiovisuales: videos, películas, spots, entre otros, a través de la TV, cine, web, etc.\n-\tClasificación y representación de elementos característicos de la arquitectura vernácula y monumentos de su región. En Montecristi, Santiago, San Cristóbal y Puerto Plata: las casas victorianas; en el Sur y la Línea Noroeste: las casas de tejamaní, entre otras, valorando las construcciones de su entorno.\n-\tAplicación de técnicas y procedimientos para la creación plástica individual (pintura, escultura y otros tipos de representaciones), utilizando materiales de su entorno.\n-\tElaboración de obras pictóricas, incorporando elementos técnicos y contextuales nacionales.\n-\tDiseño de carteles con textos, señales, símbolos y signos que contribuyan a la orientación de temas relacionados con la salud y preservación del medioambiente.\n ","attitudinal":"-\tSeguridad al expresarse con la voz y el cuerpo tanto a nivel individual como colectivo.\n-\tValoración de las expresiones artísticas propias y las de otras personas.\n-\tValoración crítica de las imágenes presentes en obras audiovisuales.\n-\tApreciación de la arquitectura vernácula regional.\n-\tValoración de formas folklóricas musicales, cantadas, bailadas y teatralizadas, como expresión de su identidad y del patrimonio intangible de la humanidad.\n "}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:20:36.186Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('1b3e07cd-f354-4bc5-b17b-54de620309ac', 'educacion-artistica', '5to', '{"id":"1b3e07cd-f354-4bc5-b17b-54de620309ac","name":"Artes escénicas","themes":[{"id":"71274029-c9db-4438-9521-22f2317b5419","name":"El títere de guante","subthemes":[{"id":"cbed2cba-5734-4382-b85b-ca67bac7e88e","name":"Partes del títere de guante y materiales para construirlo."},{"id":"e72cba1d-415d-4d89-b7eb-435bfad7f17e","name":"Técnicas básicas de manipulación: movimientos, gestos y voz."},{"id":"7f5d45bd-d928-47d1-b0b6-94619dabe97d","name":"Creación de personajes y diálogos para pequeñas obras."}]},{"id":"fcc41957-64f0-444c-a0eb-2a1b7327711b","name":"Formas folklóricas musicales, cantadas, bailadas y teatralizadas","subthemes":[{"id":"1dbe67cb-4139-4a21-b3e2-a1fef085ecba","name":"Representaciones teatralizadas: personajes, vestuario y expresividad."},{"id":"f00be73a-8d29-45ee-9768-442ab8eb9e30","name":"Manifestaciones folklóricas dominicanas: merengue, mangulina, palos, salves."},{"id":"6f8d3ba4-fe4e-44c7-93c8-ec4c677b79f5","name":"Canciones y rondas tradicionales: ritmo, letra y propósito cultural."}]},{"id":"94d37a29-834d-4d11-ace8-57471dbef393","name":"Juegos infantiles tradicionales","subthemes":[{"id":"ff331af1-d2c3-42b9-8699-e2ca465a0e53","name":"Juegos con canciones y rondas: coordinación y ritmo."},{"id":"6a8e9522-164a-4ad6-b672-c1d65dc187f3","name":"Valores en el juego: respeto, trabajo en equipo y cooperación."},{"id":"367db641-7be5-4976-afdb-4a354a768799","name":"Juegos dominicanos: reglas, roles y convivencia (ej. pañuelo, topao, vitilla)."}]},{"id":"31bb5515-6197-4284-876c-1b85ad036bdb","name":"La pantomima como técnica escénica","subthemes":[{"id":"d4493abd-8942-4585-b444-43e7b48494fb","name":"Qué es pantomima: comunicar sin hablar (gestos y movimientos)."},{"id":"dab779ce-4c07-4182-a24b-0f19c02d6626","name":"Expresión corporal: emociones, acciones y posturas."},{"id":"95487e26-4ac7-46b2-b0c0-1aebc5417f42","name":"Creación de escenas cortas y secuencias (inicio, nudo, cierre)."}]},{"id":"5ced2fd9-b98d-4d59-ae37-a77080511ede","name":"Escenificaciones folklóricas con títeres y pantomima","subthemes":[{"id":"84be15c2-bb3a-4585-8cd6-c7663bcf1044","name":"Elementos escénicos: escenario, música, sonidos, utilería y vestuario."},{"id":"0ab9c7dd-462e-443f-8394-8f3f8b86b707","name":"Leyendas y cuentos dominicanos: selección y adaptación a escena."},{"id":"d384fa65-508b-4acc-8d48-6f8cca69e04e","name":"Uso de títeres y pantomima para narrar rimas y textos culturales."}]}],"grade_levels":["5to"],"subjectId":"educacion-artistica","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"1b3e07cd-f354-4bc5-b17b-54de620309ac-block-1","themes":["El títere de guante","Formas folklóricas musicales, cantadas, bailadas y teatralizadas","Juegos infantiles tradicionales","La pantomima como técnica escénica","Escenificaciones folklóricas con títeres y pantomima"],"conceptual":"\"Artes Escénicas\"\n \n-\tEl títere de guante.\n-\tFormas folklóricas musicales, cantadas, bailadas y teatralizadas.\n-\tJuegos infantiles tradicionales.\n-\tLa pantomima como técnica escénica.\n-\tEscenificaciones folklóricas con títeres y con pantomima de leyendas, rimas y textos del legado cultural dominicano.\n ","procedural":"\"Artes Escénicas\"\n-\tUso del cuerpo y la voz en el manejo de títeres de guante y la pantomima.\n-\tCoordinación, equilibrio y percepción del espacio en la pantomima.\n-\tAplicación de técnicas de manejo de subidas y bajadas de escaleras y manejo de objetos en la pantomima.\n-\tDramatización en teatro de títeres y pantomima: uso de textos con derecho de autor y la adaptación de cuentos, poesías, experiencias personales, sentimientos, recuerdos y canciones.\n-\tUso de máscaras para la representación de personajes.\n-\tInterpretación de formas folklóricas musicales, cantadas, bailadas y teatralizadas como legado cultural dominicano e incorporarlas a producciones artísticas.\n-\tIdentificación de los rasgos de la cultura regional presentes en la obra de artistas escénicos. (incluye lo gastronómico, uso del lenguaje, hábitat, mitos y leyendas).\n-\tEscenificaciones folklóricas y costumbristas (danza, títeres y pantomima): gestualidad y expresión corporal propias.\n ","attitudinal":"-\tValoración y disfrute de las características de las obras pictóricas producidas por artistas nacionales.\n-\tApreciación de instrumentos musicales de uso popular y folklórico (tambora, güira, guitarra, balsié y marimba de cajón).\n-\tValoración de las creaciones de artistas escénicos y su vinculación con las culturas regionales.\n-\tEsmero en la realización de gráficos promoviendo soluciones a problemáticas sociales.\n-\tValoración de la difusión de obras artísticas criollas en montajes, representaciones, exposiciones y muestras artísticas.\n-\tDisfrute de la realización de actividades colectivas que propicien la interacción grupal.\n-\tValoración del trabajo cooperativo en provecho de la armonía grupal en su participación en bandas rítmicas y conjuntos de flauta dulce.\n "}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:20:36.186Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('1bf6af0e-2d55-4aec-a32b-ebb9d3e4e396', 'educacion-artistica', '5to', '{"id":"1bf6af0e-2d55-4aec-a32b-ebb9d3e4e396","name":"Educación musical","themes":[{"id":"7982db8c-fe13-4624-ac0e-55ee5453f06a","name":"Elementos del ritmo (pulso, acento, línea rítmica y ostinato rítmico)","subthemes":[{"id":"1e8e7537-fd71-4ff1-a454-a2b9be1e7b92","name":"Diferencia entre pulso y ritmo (mantener el tiempo con palmas o pasos)."},{"id":"b28e8f8d-8db0-4fa1-97a1-f638d9b2660f","name":"Acento rítmico: sonidos fuertes y débiles dentro de una secuencia."},{"id":"7de29cce-2144-4bae-bf6b-72e617d3754c","name":"Ostinato rítmico: patrones que se repiten para acompañar canciones."}]},{"id":"f15eba32-f274-462e-a4e9-aede2fb95f89","name":"Instrumentos musicales populares y folklóricos","subthemes":[{"id":"21b3b8f2-897b-45f3-b58d-c20882fa240e","name":"Uso en la música dominicana: merengue típico, perico ripiao y expresiones folklóricas."},{"id":"bebbb9f8-0425-40c6-8667-e1dc6d6c9903","name":"Características y sonidos de cada instrumento (forma y función)."},{"id":"a164ddec-da52-4372-b3c3-15b647964f57","name":"Clasificación: percusión, cuerda y melódicos (según el instrumento)."}]},{"id":"8e99e5af-77c2-4126-8b34-b06df7c64373","name":"Bandas rítmicas y conjuntos de flautas dulces","subthemes":[{"id":"e75f9fb2-9d41-464c-afbd-17392383a3bf","name":"Práctica de patrones rítmicos con instrumentos escolares (maracas, claves, triángulo, etc.)."},{"id":"ed61411b-7b81-4372-adf8-a0f1221b0bac","name":"Interpretación con flauta dulce: respiración, digitación y melodías sencillas."},{"id":"66d72fdb-ba76-4516-b075-8462551b9433","name":"Organización de una banda rítmica: roles y coordinación en grupo."}]}],"grade_levels":["5to"],"subjectId":"educacion-artistica","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"1bf6af0e-2d55-4aec-a32b-ebb9d3e4e396-block-1","themes":["Elementos del ritmo (pulso, acento, línea rítmica y ostinato rítmico)","Instrumentos musicales populares y folklóricos","Bandas rítmicas y conjuntos de flautas dulces"],"conceptual":"Educación Musical\n-\tElementos del ritmo (pulso, acento, línea rítmica y ostinato rítmico).\n-\tInstrumentos musicales populares y folklóricos (tambora, güira, guitarra, balsié y marimba de cajón).\n-\tBandas rítmicas y conjuntos de flautas dulces.\n ","procedural":"Educación Musical\n-\tOstinatos rítmicos:\n-\tReproducción y creación de ostinatos rítmicos. Acompañamiento de canciones y melodías.\n-\tClasificación de instrumentos musicales de uso popular y folklórico.\n-\tEjecución de instrumentos musicales de uso popular y folklórico.\n-\tInterpretación de distintos géneros musicales dominicanos utilizando bandas rítmicas.\n-\tCreación de conjuntos de flauta dulce para la interpretación.\n-\tEmisión de los sonidos SOL, LA, SOL, DO y RE, emitidos con la flauta dulce.\n \n ","attitudinal":"-\tValoración y disfrute de las características de las obras pictóricas producidas por artistas nacionales.\n-\tApreciación de instrumentos musicales de uso popular y folklórico (tambora, güira, guitarra, balsié y marimba de cajón).\n-\tValoración de las creaciones de artistas escénicos y su vinculación con las culturas regionales.\n-\tEsmero en la realización de gráficos promoviendo soluciones a problemáticas sociales.\n-\tValoración de la difusión de obras artísticas criollas en montajes, representaciones, exposiciones y muestras artísticas.\n-\tDisfrute de la realización de actividades colectivas que propicien la interacción grupal.\n-\tValoración del trabajo cooperativo en provecho de la armonía grupal en su participación en bandas rítmicas y conjuntos de flauta dulce.\n "}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:20:36.186Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('86aad18c-b90a-4493-adfb-7f7d659a83b2', 'educacion-fisica', '5to', '{"id":"86aad18c-b90a-4493-adfb-7f7d659a83b2","name":"Conceptos de unidad","themes":[{"id":"b98fb630-2730-4322-b2ab-5c78b337be71","name":"Habilidades motrices básicas: locomotoras","subthemes":[{"id":"bc2f0cf4-3538-400f-b829-98865846180a","name":"Tipos de desplazamientos: rápidos, lentos y con cambios de dirección."},{"id":"f2d8133f-2da1-4d0e-bae9-875754c1eb3f","name":"Coordinación locomotora: combinar correr-saltar-trepar en circuitos."},{"id":"55339e28-77e0-4079-94b5-8bca2564f300","name":"Seguridad y control del cuerpo durante desplazamientos y saltos."}]},{"id":"b5e7cd8c-7bf6-495b-a0cd-901572813535","name":"Habilidades motrices básicas: manipulativas","subthemes":[{"id":"9e3124a7-5d06-45c1-8d95-733286cf07d3","name":"Juegos motores con implementos: pelotas, aros, cuerdas y conos."},{"id":"c7db529b-9b33-498d-83f0-cc6a2a385f61","name":"Control de objetos con manos, pies y otras partes del cuerpo."},{"id":"1b8dca60-81ab-4780-9907-9c91b4442f0d","name":"Lanzamientos y recepciones: precisión y fuerza controlada."}]},{"id":"d6b33286-4d77-4651-8652-5b3a66274507","name":"Habilidades motrices básicas: control corporal","subthemes":[{"id":"cd527566-4c8d-4858-8f8b-66489b4f1d8e","name":"Movimientos corporales: giros, flexiones y balanceos coordinados."},{"id":"332278c5-df4a-4cbd-b9d3-e1e27abf5a83","name":"Control postural: equilibrio y alineación del cuerpo."},{"id":"96884b59-0a1f-4e25-a282-13899c3c8b88","name":"Secuencias motrices: unir control corporal con desplazamientos."}]},{"id":"d23f9924-dbd5-4bfd-b518-d93763d96531","name":"Capacidades físicas: coordinativas","subthemes":[{"id":"298f7add-276f-4c61-9bda-f22d55695dbf","name":"Ritmo y coordinación: movimientos al compás con palmadas/música."},{"id":"d9fabc61-99fa-482a-b072-334baf2af8e0","name":"Reacción y adaptación: responder a señales, cambios y estímulos."},{"id":"17b1d4f6-a1d9-43ea-a0f7-0fd0af64f39d","name":"Equilibrio estático y dinámico en recorridos y juegos."}]},{"id":"cb8f01f2-622e-4383-886b-d733ca743fb0","name":"Capacidades físicas: condicionales","subthemes":[{"id":"d45bb67f-6aa9-473a-9731-c98bfa671716","name":"Resistencia aeróbica: juegos prolongados y carreras moderadas."},{"id":"63216d97-7fcf-4b37-89a3-00c73d16a655","name":"Velocidad: carreras cortas y cambios de ritmo."},{"id":"022c5aab-1006-45df-94ed-b549655cbfb0","name":"Flexibilidad y fuerza: estiramientos y ejercicios básicos con el peso corporal."}]},{"id":"79ee306c-33d3-4182-843d-0ae7e18a3936","name":"Gimnasia general / composiciones gimnásticas","subthemes":[{"id":"2cffe4f8-e321-4dae-bde1-95e9b95c9978","name":"Elementos gimnásticos básicos: roles, apoyos, saltos simples."},{"id":"3b7d7654-530a-4884-83c6-4719b09e68f0","name":"Composición gimnástica: crear rutinas cortas en grupo (inicio-desarrollo-cierre)."},{"id":"5898c120-439d-4979-941a-11803117a24f","name":"Gimnasia rítmica: uso de cintas, aros o pelotas con coordinación."}]},{"id":"a8f346d7-e34a-4544-accc-f4cac6df53af","name":"Juegos cooperativos y de oposición","subthemes":[{"id":"f4583093-d91b-4fb7-9aca-d2d46c050c46","name":"Resolución de conflictos y juego limpio (fair play)."},{"id":"b8b7f6ce-6783-4be8-9a81-7ce830d18739","name":"Juegos de oposición: reglas, respeto y autocontrol."},{"id":"2372b98f-62a3-4b23-b666-ba172d559dac","name":"Juegos cooperativos: metas comunes y trabajo en equipo."}]},{"id":"d1b24aed-6679-4e1f-af46-210944bf61ad","name":"Juegos predeportivos","subthemes":[{"id":"d6339993-e2f9-4c73-b105-5b839d2f1814","name":"Habilidades técnicas iniciales: pases, tiros, control del balón."},{"id":"41970899-33ae-4eeb-a8c2-ea184ed525a2","name":"Reglas básicas de juegos predeportivos (mini fútbol, mini baloncesto, etc.)."},{"id":"73d4c621-0b20-4a58-9ac7-d952e10b40be","name":"Trabajo táctico básico: ubicarse, colaborar y defender."}]},{"id":"ae6e27c1-0b43-4f66-8eee-2dea755959d8","name":"Atletismo","subthemes":[{"id":"681be50d-89a8-470b-9ff3-8936f2a01c6c","name":"Conceptos del atletismo: velocidad, resistencia, saltos y lanzamientos."},{"id":"cb71fb61-d23e-4d72-8dbd-db7d1cfe6722","name":"Prácticas: saltos (largo/alto adaptado) y lanzamientos (pelota/vortex)."},{"id":"7a043c53-222f-4ac7-a25b-5b4e18cb3527","name":"Reglas básicas en carreras: salida, llegada y respeto del carril."}]},{"id":"cf223ed1-0a17-4891-bdb2-8f4890b487c8","name":"Baloncesto (dribbles, pases, tiros y defensa)","subthemes":[{"id":"09edbe79-41a0-4f1d-ac70-97ab1ed74a9f","name":"Drible: control y avance."},{"id":"324de461-7ab2-4ec0-8856-2e15a53c2055","name":"Pases y tiros básicos."},{"id":"0410f41a-27b6-416c-8394-f49921556e3d","name":"Defensa y reglas principales."}]},{"id":"317275fe-0e84-400f-be0e-9088c387bd5c","name":"Ajedrez","subthemes":[{"id":"16e373a1-3a75-4e7d-91c9-8836d2b39957","name":"Valor de piezas y estrategia simple."},{"id":"69bb93cc-eebd-4e61-b680-ef9f98329d1d","name":"Jaque y jaque mate."},{"id":"88f1a373-309c-4cb9-8b7a-9416c521534b","name":"Enroque, coronación y peón al paso."}]},{"id":"91fb0ae2-7d80-4cc8-832a-dfcafac46c71","name":"Fuerza y Mantenimiento: ¡Manteniéndonos fuertes como un león!","subthemes":[{"id":"34ecd565-251c-44b5-9990-f42e7c9295a9","name":"Ejercicios de empuje: ¡Como empujar un carro varado!"},{"id":"e1cac8df-a9ba-406e-80ae-ad1a37c49754","name":"Importancia del descanso y la alimentación: ¡Como recargar energías después de jugar!"}]}],"grade_levels":["5to"],"subjectId":"educacion-fisica","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"86aad18c-b90a-4493-adfb-7f7d659a83b2-block-1","themes":["Habilidades motrices básicas: locomotoras","Habilidades motrices básicas: manipulativas","Habilidades motrices básicas: control corporal","Capacidades físicas: coordinativas","Capacidades físicas: condicionales","Gimnasia general / composiciones gimnásticas","Juegos cooperativos y de oposición","Juegos predeportivos","Atletismo","Baloncesto (dribbles, pases, tiros y defensa)","Ajedrez","Fuerza y Mantenimiento: ¡Manteniéndonos fuertes como un león!"],"conceptual":"-\tHabilidades motrices básicas: Locomotoras (caminar, rodar, reptar, correr, saltar, marchar, “salticar”, trepar).\n-\tManipulativas (lanzar, atrapar, picar, rodar, halar, empujar, golpear, patear, atrapar, controlar objetos con diferentes partes del cuerpo).\n-\tDe control corporal (girar, flexionar, balancear).\n-\tCapacidades físicas: Coordinativas \n(equilibrio, coordinación, \norientación, diferenciación, reacción, adaptación, ritmo).\n-\tCondicionales (fuerza explosiva, velocidad, flexibilidad, resistencia aeróbica).\n-\tGimnasia general. Composiciones gimnasticas. Elementos básicos de gimnasia artística, rítmica y acrobática.\n-\tJuegos cooperativos y de oposición.\n-\tJuegos predeportivos.\n-\tAtletismo (reglas básicas, conceptos básicos, saltos y lanzamientos).\n-\tBaloncesto (dribbles, pases, tiros y defensa, clasificación, importancia, reglamento para su ejecución).\n-\tAjedrez (el jaque, el jaque mate, la coronación del peón, el enroque, peón al paso, valor absoluto de las piezas).\n ","procedural":"-\tRealización de elementos de elevación, equilibrio, fuerza y mantenimiento.\n-\tAplicación de las habilidades motrices básicas y capacidades físicas en la resolución de situaciones motrices cotidianas, deportivas y recreativas.\n-\tAplicación de las habilidades motrices básicas y capacidades físicas en el manejo y utilización de diversos implementos gimnásticos, recreativos y deportivos.\n-\tRealización de ejercicios de relajación corporal, después de la actividad física.\n-\tRealización de juegos utilizando las técnicas básicas de saltar en distancia y altura.\n-\tRealización de juegos en donde se apliquen las técnicas básicas de lanzamiento, con pelotas de diferentes pesos y tamaños.\n-\tRealización de juegos recreativos o predeportivos de baloncesto, donde se apliquen las técnicas de los pases, dribbling y tiro, evadiendo la oposición a través de la cooperación del compañero o la compañera.\n \n-\tRealización de juegos con mates elementales (torre y rey contra rey, dama y rey contra rey)\n-\tRealización de juegos con coronación de peones en diferentes situaciones.\n-\tParticipación en actividades físicas y juegos recreativos en los que se realicen saltos y lanzamientos de objetos con pesos moderados.\n-\tRealiza carreras continuas a ritmo moderado, juegos predeportivos y adaptados en los que se pone de manifiesto su resistencia aeróbica.\n-\tParticipación en juegos adaptados partiendo de situaciones de aprendizaje que promuevan el pensamiento táctico.\n-\tParticipación en juegos predeportivos relacionados con el dribble, pases, tiros y aspectos generales de la defensa.\n-\tDescripción y elaboración de las utilerías e implementos manipulados en baloncesto, atletismo, gimnasia, ajedrez y su utilización, con apoyo de recursos tecnológicos.\n-\tValoración de hábitos de higiene, aseo personal y alimentación saludable en la práctica diaria de actividades físicas.\n ","attitudinal":"-\tExperimentación de diferentes sensaciones, descubrimiento, percepción y mejor entendimiento de sus movimientos y los de los y las demás.\n-\tPráctica del juego limpio, respetando las reglas de los juegos que realiza.\n-\tValoración y práctica de hábitos de higiene y normas de comportamiento.\n-\tValoración y disfrute de participar en juegos con sus compañeros y compañeras.\n-\tDefensa y respeto por su derecho y el de los y las demás de jugar realizar actividades físicas.\n-\tReconocimiento de la importancia de la realización de actividades físicas para su desarrollo, bienestar y conservación de la salud.\n-\tCuidado y protección de los ambientes físicos y naturales en donde practica actividades físicas.\n-\tRespeto por la creación de los y las demás.\n-\tValoración del movimiento corporal del compañero y la compañera.\n-\tActitud de aceptación de sí mismo, sí misma y de los y las demás sin discriminación de sexo o nivel de habilidades.\n-\tDemostración de disfrute al participar en las diferentes actividades deportivas y recreativas.\n-\tActitud de cooperación con sus compañeros y compañeras, y de respeto por las reglas y por el/la adversario/a.\n "}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:20:36.186Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('d3f82489-10f3-41de-985a-1b5955ee522f', 'sociales', '5to', '{"id":"d3f82489-10f3-41de-985a-1b5955ee522f","name":"Historia como ciencia","themes":[{"id":"473c0f01-3a96-4a40-be5c-8cc7d809f9b6","name":"Fuentes históricas y sus periodos","subthemes":[{"id":"cba8ea2d-d59e-4fb7-a181-72447afaad39","name":"Fuentes materiales, escritas y orales."},{"id":"a2f50a27-d195-494d-ba72-e2b4a2f72808","name":"Tipos de fuentes: primarias y secundarias."},{"id":"728f90b3-d7bb-43c8-91a1-cebc907a4d03","name":"Uso de fuentes para estudiar épocas."}]},{"id":"4997b2e9-7708-4e79-93a7-5e0b9b2cd3be","name":"Estudio del pasado (Prehistoria e Historia)","subthemes":[{"id":"0a2d768b-fe39-42e9-baba-6f750f199a14","name":"Edad Antigua y Edad Media."},{"id":"4ce4f9b5-bb26-487e-ab35-446e8ace232f","name":"Prehistoria: etapas y características."},{"id":"bb609e69-0dd2-475f-b4be-77d53e8c797d","name":"Edad Moderna y Contemporánea."}]},{"id":"41f6549b-14c1-40d1-b371-17b56a8982f1","name":"Períodos de la historia de América","subthemes":[{"id":"d9230705-cc82-4805-bb55-e7db4f73e98e","name":"América precolombina."},{"id":"3413df37-73cd-4d7e-a500-01786797a453","name":"Conquista y colonización."},{"id":"a210ec7f-3a98-4e54-ac11-cc90cb26d4ed","name":"Independencias y época republicana."}]},{"id":"6d1ef35f-1c73-4bb5-a1ef-707735575e3c","name":"Períodos de la historia dominicana","subthemes":[{"id":"aca812ea-f164-45e8-b9a4-5589b608c30e","name":"República Dominicana contemporánea."},{"id":"582153ca-0dbd-47b0-bddf-fd0aad68f32c","name":"Período prehispánico y colonia."},{"id":"b1556da5-ed4a-4689-9c32-7918a9ed9295","name":"Independencia y Restauración."}]}],"grade_levels":["5to"],"subjectId":"sociales","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"d3f82489-10f3-41de-985a-1b5955ee522f-block-1","themes":["Fuentes históricas y sus periodos","Estudio del pasado (Prehistoria e Historia)","Períodos de la historia de América","Períodos de la historia dominicana"],"conceptual":"","procedural":"","attitudinal":""}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:20:36.186Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('723ff6c2-f729-4bb9-a547-44065c94c7a4', 'sociales', '5to', '{"id":"723ff6c2-f729-4bb9-a547-44065c94c7a4","name":"Historia de América","themes":[{"id":"e22ea7a3-1945-4250-bfd4-d6bf0629814a","name":"Poblamiento de América / Civilizaciones precolombinas","subthemes":[{"id":"5c045f7f-5123-4965-9eb0-064b8ff96362","name":"Teorías del poblamiento de América."},{"id":"49f68bea-794b-4a61-a002-7e745a74ddb0","name":"Mayas, Aztecas e Incas: características."},{"id":"e86f7701-26dc-49d9-8618-631ece22fcaf","name":"Aportes: ciencia, agricultura y arquitectura."}]},{"id":"48ae5a46-f08d-4764-a8c8-df3df195de2c","name":"Expansión europea (siglos XV–XVIII) en América","subthemes":[{"id":"1e2a3637-2232-4424-9ebd-67552328397c","name":"Otras potencias: Francia y Holanda en el Caribe."},{"id":"4bc495df-bd76-4654-9d5b-1b602b9167a9","name":"Conquista y colonización europea."},{"id":"d693587f-75a4-43a3-9ff5-067fcfb39471","name":"España y Portugal: control territorial."}]},{"id":"052f34e1-9bcf-4cd6-b039-1bb5e83350b0","name":"Comercio triangular / esclavitud y rebeliones","subthemes":[{"id":"13a5001d-ed0f-4e6f-9539-42444435d720","name":"Esclavitud en América y el Caribe."},{"id":"bdd01811-2510-438a-b699-ba22f189ff59","name":"Rebeliones y resistencias de esclavizados."},{"id":"5dc2b5b3-dec3-45de-a8f7-14acd10a6d35","name":"Comercio triangular: rutas y productos."}]},{"id":"77c8cbc2-691a-4e64-b1f8-348b7be5914f","name":"Revolución y restauraciones / Liberales y conservadores EE.UU.","subthemes":[{"id":"839092d3-d404-4823-80af-a199303bd4aa","name":"Restauración de poderes y cambios de gobierno."},{"id":"8fa624e4-bcd3-4fa7-b916-39172a55895a","name":"Expansión territorial de Estados Unidos."},{"id":"cc96c09e-9178-4e71-a6aa-9acb963a4404","name":"Conflictos entre liberales y conservadores."}]},{"id":"670cedac-25c0-456a-9d2d-121496009c4b","name":"Piratería y contrabando en Santo Domingo","subthemes":[{"id":"f986bec