INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('5876a518-d95a-4fb2-9345-5ed86bd1731f', 'sociales', '5to', '{"id":"5876a518-d95a-4fb2-9345-5ed86bd1731f","name":"Educación ciudadana y convivencia humana","themes":[{"id":"8c88a55c-ded0-4de1-98e0-a667660801b9","name":"Nacionalidad y ciudadanía","subthemes":[{"id":"f41d2f5f-0c4d-4548-882d-66c4f13a93c5","name":"Concepto de nacionalidad y ciudadanía."},{"id":"354cac15-01a4-4d77-abd6-9730c87b1745","name":"Formas de adquirir la nacionalidad."},{"id":"c8f43b7d-7e1e-408c-81c6-b9c374f65cd2","name":"Derechos y deberes del ciudadano."}]},{"id":"3ef211a7-3f1d-43db-a16e-d8b17b6dae7c","name":"Derechos fundamentales (Constitución)","subthemes":[{"id":"dba1aa05-ebe1-490d-98e7-c602681eb3ae","name":"Respeto y cumplimiento de los derechos."},{"id":"dde9341a-b2b7-444f-8f1e-1f085b7dcb98","name":"Derechos civiles y políticos básicos."},{"id":"be70ee9d-fa3c-4e18-a31b-2a6aeec5c63d","name":"Derechos sociales: educación, salud y protección."}]},{"id":"074cb737-3b1c-493b-88ce-cef41196be8c","name":"Símbolos patrios","subthemes":[{"id":"b35d8ea4-64c0-4cfe-a93a-1ccd84e14734","name":"Bandera, escudo e himno nacional."},{"id":"fd1c9814-4722-4eff-99f0-04b4e3d5adfa","name":"Significado y respeto a los símbolos."},{"id":"549c247a-af7f-49a6-8fe8-c28361d80947","name":"Efemérides y actos patrios."}]},{"id":"c7d88601-3e3f-4a71-8b5e-e849bec2a336","name":"Atribuciones del Poder Legislativo","subthemes":[{"id":"ce99bfe5-d163-40ce-b7b8-37cc012c5048","name":"Creación y aprobación de leyes."},{"id":"53100712-4df9-46b2-a507-fddc007834ff","name":"Control y representación ciudadana."},{"id":"d2618fe2-7993-49b0-93f0-f200f7225ed0","name":"Función del Congreso Nacional."}]},{"id":"d41b8aad-041d-49e2-b0f6-17395b8c7a1d","name":"Ley 136-03 y protección de niños/as","subthemes":[{"id":"e5efc03d-9177-414d-b777-f393418b3ad6","name":"Qué es la Ley 136-03 (Código de Niños, Niñas y Adolescentes)."},{"id":"f6cc26fa-04d8-465f-8454-948ee8cfd5a9","name":"Responsabilidades de familia, escuela y Estado."},{"id":"4550a704-d55c-4eed-81e0-c6a20c8928ea","name":"Derechos que protege y situaciones de riesgo."}]},{"id":"bca130e4-cb4d-4663-ab50-9d7f9e618778","name":"Cultura de paz y solución pacífica de conflictos","subthemes":[{"id":"cb992415-4e4f-4aa3-8435-9754c8e59028","name":"Qué es cultura de paz."},{"id":"47490b67-162b-4811-8900-21619be5039b","name":"Diálogo, mediación y acuerdos."},{"id":"c6d3e6fb-0e14-42d6-b607-637cc6b9a6d3","name":"Respeto y tolerancia en convivencia."}]},{"id":"f982ece1-ec2a-4a70-9a1f-3c8d354f3a13","name":"Soluciones democráticas y participativas","subthemes":[{"id":"9c81db8a-b038-4c1d-ad68-f4f4fe055b89","name":"Toma de decisiones en grupo."},{"id":"8ac8bb41-780c-4336-b9e2-8c772cfb0db4","name":"Respeto a reglas y mayoría."},{"id":"7c870ff4-d1df-4d01-b00f-ba4837a00faf","name":"Participación: votar, opinar y colaborar."}]},{"id":"8727f4af-24cf-45e9-a19b-de9ebb985d55","name":"Educación vial y tributaria","subthemes":[{"id":"ae6c7923-fac2-4548-bfc1-eb8fa5d10d10","name":"Impuestos: para qué sirven."},{"id":"71c1d981-22b0-48d3-b2c6-171ad6f211cd","name":"Responsabilidad del peatón y conductor."},{"id":"7d3ad6fc-e11b-463f-96bd-fc492401d230","name":"Normas básicas de tránsito."}]},{"id":"7daf62c4-fce2-49c8-8499-06d954917cc5","name":"Gobierno","subthemes":[{"id":"724dc33f-8bd9-4f92-badb-59a961db80d6","name":"Qué es el gobierno y su función."},{"id":"cb955a8a-7db5-4d60-aab7-36afd859ee1c","name":"Autoridades y organización del país."},{"id":"051aa880-b67b-41e6-8ced-59a7e6fbf7fa","name":"Poderes del Estado (básico)."}]},{"id":"a509b757-5e66-4bed-9af6-16b1a0b4646c","name":"Accidentes de tránsito e impacto económico","subthemes":[{"id":"0ba864c5-ec6e-4a69-a043-d462d46763e1","name":"Costos en salud y servicios públicos."},{"id":"d07533f1-fb04-4b15-ab32-9b1d950218fd","name":"Daños materiales e infraestructura."},{"id":"f8e8cbb9-5331-4fc4-b38f-ebd7149abb4d","name":"Prevención como ahorro para el Estado."}]},{"id":"14379b70-c9e5-4352-a9b4-c3bae38ecd81","name":"Situaciones de violencia social e intrafamiliar","subthemes":[{"id":"8346df13-e4c8-4b6b-aade-14136c79795d","name":"Tipos de violencia: física, verbal y psicológica."},{"id":"c0b82a5b-7678-4bf8-b396-f3044ea346d5","name":"Consecuencias en la familia y comunidad."},{"id":"c965d4a8-ec07-48b5-b616-50473adaba82","name":"Prevención y búsqueda de ayuda."}]},{"id":"17ec7153-e4fd-4954-af33-e2f2d741d1bb","name":"Violencia juvenil (análisis)","subthemes":[{"id":"48d262be-463c-444a-97a0-82fcbb97a690","name":"Consecuencias: escuela, familia y ley."},{"id":"88746ec0-2e09-4ab3-8ee8-f58eda0ec3cd","name":"Alternativas: valores, deporte y apoyo."},{"id":"147229e1-e985-47a5-b3f8-792e97b2b803","name":"Causas: presión social, entorno y bullying."}]},{"id":"07f52769-17bf-4915-8514-d1e765e3ebe2","name":"Patrimonio natural, histórico y cultural de Latinoamérica","subthemes":[{"id":"40c334a7-4bbf-4636-865e-e0f3e7dffda8","name":"Patrimonio natural: parques, ríos y biodiversidad."},{"id":"dcf1a813-f7ab-44cd-8c58-245dc92b85dd","name":"Patrimonio histórico: culturas y monumentos."},{"id":"154442a3-60ac-4209-b153-31cb47a9e9f2","name":"Patrimonio cultural: tradiciones, música y gastronomía."}]},{"id":"bab53e7f-6833-4d8e-a11d-74135d88ee9a","name":"Impacto de la contaminación","subthemes":[{"id":"e87b56c7-78ad-4479-811e-e1169341fdce","name":"Tipos de contaminación: aire, agua y suelo."},{"id":"06035f6b-7a5c-46d9-b16a-482c7af00cba","name":"Consecuencias en salud y ambiente."},{"id":"40c96a36-82b4-4ccb-af08-72405d42eb89","name":"Acciones para prevenir y reducir."}]},{"id":"fdb520c2-99f2-4fcf-9de2-c74b3a3959ed","name":"Situaciones cotidianas que ponen en riesgo seguridad y salud","subthemes":[{"id":"a8528795-ce1a-4095-a302-c3524c44feed","name":"Prevención de accidentes y autocuidado."},{"id":"8973e10c-f9a3-4385-b056-7537aadb7534","name":"Riesgos en casa, escuela y calle."},{"id":"d3a4ef05-a935-4b2f-a6ea-bc120ee1a778","name":"Decisiones responsables: hábitos saludables."}]},{"id":"b2986967-b843-42bb-941d-4a4188227ff1","name":"Participación ciudadana en mi comunidad","subthemes":[]}],"grade_levels":["5to"],"subjectId":"sociales","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"5876a518-d95a-4fb2-9345-5ed86bd1731f-block-1","themes":["Nacionalidad y ciudadanía","Derechos fundamentales (Constitución)","Símbolos patrios","Atribuciones del Poder Legislativo","Ley 136-03 y protección de niños/as","Cultura de paz y solución pacífica de conflictos","Soluciones democráticas y participativas","Educación vial y tributaria","Gobierno","Accidentes de tránsito e impacto económico","Situaciones de violencia social e intrafamiliar","Violencia juvenil (análisis)","Patrimonio natural, histórico y cultural de Latinoamérica","Impacto de la contaminación","Situaciones cotidianas que ponen en riesgo seguridad y salud","Participación ciudadana en mi comunidad"],"conceptual":"\"Educación Ciudadana:\"\n–\tNacionalidad y ciudadanía.\n–\tDerechos Fundamentales según la Constitución.\n–\tSímbolos patrios.\n–\tAtribuciones del Poder Legislativo.\n \n\"Convivencia humana\"\n–\tLey 136-03 y su incidencia en la protección de niños y niñas.\n–\tCultura de paz y solución pacífica a los conflictos.\n–\tSoluciones democráticas y participativas.\n–\tEducación vial y Tributaria.\n–\tGobierno.\n–\tImplicaciones de los accidentes de tránsito en la economía del Estado.\n–\tSituaciones de violencia social e intrafamiliar.\n–\tAnálisis de situaciones de violencia juvenil.\n–\tSituaciones de violencia social e intrafamiliar.\nPatrimonio natural, histórico y cultural de Latinoamérica\n–\tImpacto de la contaminación.\n–\tSituaciones cotidianas que ponen en riesgo su seguridad y su salud.\n \n \n ","procedural":"\"Análisis de los conceptos de nacionalidad, ciudadanía y Derechos Fundamentales:\"\n \n–\tBúsqueda de información en la Constitución sobre estos conceptos y expresión de sus experiencias de aprendizaje en reflexiones, comentarios, argumentación, ejemplificación, otros.\n–\tElaboración de collage sobre los símbolos patrios, destacando aspectos históricos. Exposición explicando sus significados para los ciudadanos y la Patria dominicana.\n–\tRealización de exposiciones y mesas redondas sobre las atribuciones del Poder Legislativo.\n \n–\tAnálisis de la protección que otorga la Ley 136-03 a la población infantil dominicana. Reflexiones sobre experiencias en la comunidad.\n–\tRealización de debates con sus compañeros y compañeras sobre las condiciones de la democracia en la República Dominicana.\n–\tAporte de opinión sobre la participación democrática en el país.\n–\tArgumentación sobre el cumplimiento de leyes para el bienestar común y para vivir en democracia.\n–\tAnálisis de sus derechos y deberes en la Ley 136-03.\n–\tAnálisis de las fuentes del erario público y su distribución.\n–\tRepresentación en gráficos de la distribución del erario público.\n–\tElaboración de campañas sobre la convivencia armoniosa y la cultura de paz en la escuela y la comunidad.\n–\tRealización de simulaciones de consulta y votaciones en la escuela, en la solución de problemas de su comunidad.\n–\tPresentación de propuestas para solucionar los problemas de tránsito en su comunidad, mediante el análisis de la Ley No. 63- 17, de Movilidad, Transporte Terrestre, Tránsito y Seguridad Vial.\n–\tRealización de campañas preventivas de violencia juvenil, intrafamiliar y social.\n–\tRealización de campañas escolares de concientización de educación vial y tributaria.\n–\tInvitación de especialistas en los temas en educación vial.\n–\tOrganización de la campaña en la escuela.\n–\tElaboración de las propagandas.\n–\tPresentación de los resultados de la campaña en gráficos.\n–\tElaboración de panfleto o ”brochure” sobre el patrimonio histórico y cultural de Latinoamérica.\n–\tProducción de proyectos de investigación sobre la contaminación ambiental y situaciones que ponen en riesgo la salud.\n \n ","attitudinal":"–\tRespeto a los derechos, la cultura de paz y la tolerancia como bases de una sociedad justa.\n–\tActitud positiva del diálogo como herramienta para solucionar los conflictos.\n–\tRespeto por los símbolos patrios.\n–\tInterés por preservar la vida en vías públicas.\n–\tValoración del ahorro como forma de garantizar la calidad de vida.\n–\tValoración del diálogo para resolver situaciones cotidianas.\n–\tValoración de la vida y su integridad.\n–\tRespeto y cuidado del medioambiente.\n–\tValoración de acciones que fomenten relaciones democráticas.\n "}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:20:36.186Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('11f3ca25-6970-4197-a066-8913a0175832', 'naturales', '5to', '{"id":"11f3ca25-6970-4197-a066-8913a0175832","name":"Ciencias de la vida ","themes":[{"id":"b77b2edc-0756-40d6-9324-6f595592b6d3","name":"Materia y sus propiedades ","subthemes":[{"id":"efaaae7f-35cd-4f8f-983c-818515172605","name":"Los fósiles."},{"id":"99412102-c570-4704-b231-4c7eaa58ca5f","name":"Evolución de las especies."},{"id":"08153278-a264-42fd-9319-2840a25d145d","name":"La Española y su historia fósil."}]},{"id":"b645d81f-fc32-4418-91c0-aa4f9c7d8016","name":"Interacción y movimiento ","subthemes":[{"id":"ba6889c6-22be-42f7-9ba0-384ecd6f912a","name":"Impulso nervioso."}]},{"id":"67df82e6-213d-4a8b-807f-8d93c3190777","name":"Sistema y mecanismo","subthemes":[{"id":"81571afd-a452-4847-be04-613726bf3a2b","name":"Medioambiente: Áreas protegidas."},{"id":"77223591-48a2-43aa-b05f-98085d94842a","name":"Qué son áreas protegidas y por qué existen."},{"id":"e09e3bc7-fb56-4632-9530-abbb423dfdd3","name":"Tipos de áreas protegidas (parques, reservas, etc)"},{"id":"c8366eb3-960b-4ab2-9c21-f0f0f857d2ca","name":"Importancia: biodiversidad y cuidado del agua/suelos."}]},{"id":"117d65a8-513f-4253-b770-8ec7b29e8ee5","name":"Salud y ser humano","subthemes":[{"id":"c3ec24c7-2ca6-4b55-80ac-9b63cc1a1a5c","name":"Enfermedades: bacterias infectocontagiosas"},{"id":"e8b730e1-524a-488d-baa4-5d5378e5389e","name":"Función principal de cada sistema."},{"id":"42aebf70-5593-4f9f-99fd-29e3c93efc3e","name":"Fecundación: unión de células reproductoras."},{"id":"f43b850e-eb0e-4c7f-9e24-8937a3313448","name":"Qué son bacterias y cómo se transmiten."},{"id":"e3f7435e-03d4-49d0-8611-a9b72707f981","name":"Órganos/partes principales de cada sistema."},{"id":"6a9c7a67-fd47-471a-b1de-49d9fbee4bc7","name":"Fecundación: unión de células reproductoras."},{"id":"30be0433-6dd2-4891-8857-b97b8bd8bc9a","name":"Enfermedades comunes y síntomas básicos."},{"id":"f8b23c21-6609-4f0c-8d59-898fd864bd90","name":"Hábitos para cuidarlos (alimentación, ejercicio, higiene)."},{"id":"29d1b56d-43df-4505-a8a5-ed9834b38167","name":"Prevención: higiene, vacunas y cuidado."},{"id":"f98d3bfa-5449-4488-80fb-38afecc631f6","name":"Reproducción y fecundación"},{"id":"4c19165b-2d06-4cb7-9966-25e417eb72af","name":"Sistemas: muscular, óseo, nervioso y reproductor"},{"id":"81999a47-fa5d-439a-a069-8ed52ab7d163","name":"Reproducción humana: concepto general."}]}],"grade_levels":["5to"],"subjectId":"naturales","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"11f3ca25-6970-4197-a066-8913a0175832-block-1","themes":["Materia y sus propiedades ","Interacción y movimiento ","Sistema y mecanismo","Salud y ser humano"],"conceptual":"“Ciencias de la Vida “\n“Materia y sus propiedades”\n– Los fósiles.\n–\tEvolución de las especies.\n–\tLa Española y su historia fósil.\n“Interacción y movimiento”\n– Impulso nervioso.\n“Sistema y mecanismo”\n–\tMedioambiente: Áreas protegidas.\n“Salud y ser humano”\n–\tEnfermedades: bacterias infectocontagiosas.\n–\tSistemas: muscular, óseo, nervioso y reproductor.\n–\tReproducción y fecundación.\n ","procedural":"\"Ciencias de la Vida\"\n \n–\tIndagación sobre los tipos de fósiles y sus características. Procedimiento: observación, descripción, comparación, verificación de fuentes de información, experimentación, análisis, discusión y comunicación.\n–\tIndagación acerca de científicos que han hecho aportes sobre la teoría de la evolución. Búsqueda de información, lectura y comentario, conclusión y exposición de los resultados.\n–\tObservación, descripción, comparación y discusión acerca de fósiles de la República Dominicana y sus características.\n–\tIndagación sobre la evolución de la vida. Procedimiento: observación, descripción, comparación, verificación de fuentes de información, análisis, discusión y comunicación.\n–\tObservación, análisis y discusión de la biogeografía de los seres vivos en el planeta.\n–\tExperimentación (guiada) con rocas o resinas con fósiles. Procedimiento: descripción, comparación, análisis, discusión y comunicación.\n–\tIndagación sobre las estructuras y funciones de los sistemas y aparatos en animales y en el ser humano. Procedimiento: observación, descripción, comparación, verificación de fuentes de información, experimentación (guiada), análisis, discusión y comunicación.\n–\tAnálisis de características de la transmisión del impulso nervioso.\n–\tEnfermedades de los sistemas muscular, óseo y nervioso. Procedimiento: formulación de preguntas, búsqueda de información, ejecución y exposición.\n–\tInvestigación sobre los cambios morfológicos y fisiológicos que ocurren en la pubertad. Procedimiento: formulación de preguntas, búsqueda de información, ejecución y exposición.\n–\tIndagación sobre la situación de las Áreas protegidas de la República Dominicana. Planteamiento de preguntas, búsqueda de información, lectura y comentarios, uso de mapas, planificación y diseño, ejecución, conclusión y exposición.\n \n–\tElaboración de un listado de vacunas contra enfermedades infecciosas. Planteamiento de preguntas, búsqueda de información, lectura y comentarios, planificación y diseño, ejecución, conclusión y exposición.\n–\tEnfermedades infecciosas causadas por bacterias y hongos. Procedimiento: observación, descripción, comparación, verificación de fuentes de información, experimentación, análisis, discusión y comunicación.\n \n ","attitudinal":"–\tMotivación de seguir los procedimientos propios de la investigación sistemática para dar respuesta científica a sus preguntas y comprobar sus ideas.\n–\tValoración y cuidado de su salud, su bienestar y los de las demás personas.\n–\tAdopción de responsabilidad, solidaridad, curiosidad y creatividad en la búsqueda de soluciones a problemas.\n–\tValoración de los recursos naturales y de su uso sostenible.\n–\tManifestación de interés en la obtención de informaciones sobre eventos naturales, medidas de prevención, recomendaciones y rutas de seguridad.\n–\tMotivación respecto a la colaboración y trabajo en equipo en las actividades del ámbito escolar, familiar y comunitario.\n–\tManifestación de curiosidad, creatividad, objetividad.\n–\tComunicación de sus ideas, seguimiento de procedimientos, trabajo individual y colaborativo.\n–\tRespeto a las ideas y diferencias de los demás, solidaridad.\n–\tUtilización sostenible de los recursos materiales y tecnológicos de que dispone.\n–\tDemostración de interés por conocer sobre las propiedades y características de la materia y la energía, así como por utilizar herramientas y construir máquinas comprendiendo sus mecanismos y funcionamiento.\n "}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:20:36.186Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('4e9cc3a0-037b-42eb-b90e-54c0190f5569', 'naturales', '5to', '{"id":"4e9cc3a0-037b-42eb-b90e-54c0190f5569","name":"Ciencias físicas","themes":[{"id":"5a0dba23-7172-4d2f-838e-f043f0e3c606","name":"Materia y sus propiedades","subthemes":[{"id":"3467522c-7cce-4ba1-83ca-c10c98a4568b","name":"Elementos y compuestos químicos."},{"id":"66911a78-93b1-4185-af86-295d2fdf496c","name":"Átomos y moléculas."},{"id":"b0b9328c-afd2-4020-96f7-b4f73e54d2bd","name":"Cambios en la materia"},{"id":"7b0d64b2-f2c0-431d-8b0c-89b5bfcb5745","name":"cambios físicos, cambios de estado, cambios químicos."},{"id":"55a73282-331c-4dc8-999c-8632300e4897","name":"Carga eléctrica."}]},{"id":"5b4856d3-999f-4ace-af60-8be5ced4bc2e","name":"Energía y conservación","subthemes":[{"id":"54c86c74-d9f4-4b73-934d-9143311d7818","name":"Tipos de energía: mecánica, química, eléctrica y magnética."},{"id":"a0fa7d48-df92-4ca2-b6d4-e024611e5fd4","name":"Materiales conductores comunes (metales, agua, etc.)."},{"id":"e8dc1ddf-897e-43a3-876b-86e89926c820","name":"Circuito en serie y paralelo (básico)."},{"id":"b6584fc5-fca5-455e-af71-42f377ecc040","name":"Conservación de la masa y energía"},{"id":"ab707400-2c82-411f-8afb-ec0e6c20d509","name":"Fuentes de energía: renovables y no renovables."},{"id":"2f004748-b07f-4cb3-9cf9-bef27a4d0af8","name":"Riesgos y normas de seguridad eléctrica."},{"id":"cd69fdae-c39e-4c2f-9891-61334af5e176","name":"Transformación de energía"},{"id":"c912aaed-18c4-45f8-ba37-8a60cf7957dc","name":"La masa no se crea ni se destruye (en cambios simples)."},{"id":"604c0a27-956a-4ef0-9cda-59b1ef345300","name":"Usos cotidianos y cuidado/ahorro de energía."},{"id":"bd4e0a82-2e30-438c-8058-d17ae3daa780","name":"Circuitos eléctricos"},{"id":"6b9e099e-313c-44d8-acbc-731c5bb3f9c6","name":"Energía eléctrica a térmica y luminosa."},{"id":"427ece82-b512-4128-9145-9e1ada678bca","name":"Energía: se transforma, no desaparece."},{"id":"3f89eeed-530f-4843-833d-8bdf6c0ac9f0","name":"Transmisión: conductividad eléctrica"},{"id":"26e43d18-e266-4ba7-a21e-187964e3dd6b","name":"Partes del circuito: fuente, cables, interruptor y carga."},{"id":"9531801c-504a-4822-bd35-5b8125f437eb","name":"Energía mecánica a eléctrica (ejemplos simples)."},{"id":"6c4d4b6b-48b3-4397-a031-1655192af930","name":"Ejemplos de conservación en experimentos sencillos."},{"id":"7023491a-e697-42c4-ac99-2935c147f149","name":"Conductores y aislantes eléctricos."},{"id":"092a3187-85b2-489d-8c01-b6a01eb79205","name":"Circuito abierto y circuito cerrado."},{"id":"15b2ce91-2ffb-433b-ada5-e8cb32b5244e","name":"Ejemplos cotidianos de transformación (bombillo, licuadora, radio)."},{"id":"ca824eb6-1003-4831-ba8d-25511ad2a28d","name":"Formas y fuentes de energía (mecánica, química, eléctrica, magnética)."}]},{"id":"c64f4ffd-6446-44d0-9c09-d02eaef7ff45","name":"Interacción y movimiento","subthemes":[{"id":"173f7095-5f6d-4a06-8508-187fabd5fc82","name":"Interacción y movimiento / Fuerzas y sus efectos"},{"id":"651d3da3-e64b-46c8-a44a-58b1c81c7883","name":"Qué es una fuerza: empujar, halar y cambiar el movimiento."},{"id":"f4b99439-f1e0-452e-ab47-c7260f88348c","name":"Energía cinética: objetos en movimiento."},{"id":"715223d5-7245-42c0-b239-82e90a197190","name":"Efectos de la fuerza: mover, detener, deformar o cambiar dirección."},{"id":"899eede8-cc95-4f48-8b92-cbaf48a60d39","name":"Ejemplos cotidianos: correr, rodar, caer, empujar."},{"id":"56cab14e-9223-4664-bf8c-018128295997","name":"Fuerzas mecánicas, eléctricas y magnéticas en la vida diaria."},{"id":"f0b59f6d-b859-4a96-bbce-1e80b6f6b409","name":"El movimiento como una forma de energía. "},{"id":"e79414b7-c263-4ce6-90f4-0c9e5b248793","name":"Relación entre energía y movimiento."}]},{"id":"7884e12a-6107-4ba5-ac36-46b6010d5ad8","name":"Sistema y mecanismo","subthemes":[{"id":"7122490c-7011-484b-aeb9-7aadd3e3b5e0","name":"Mecanismo de transformación y acoplamiento de movimiento"},{"id":"983c4f38-15bd-41b4-9799-41dcef889824","name":"Motores de combustión: cómo funcionan (básico)."},{"id":"c35d1bd2-0b66-4a9b-b5fc-9c738b8c59aa","name":"Qué es un motor eléctrico: convierte electricidad en movimiento."},{"id":"83075471-8caf-4e59-8c29-305dc4e95a50","name":"Mecanismos: palancas, poleas y engranajes."},{"id":"17e1eea1-8ad0-499c-a690-1d0986e31fa9","name":"Motores eléctricos: ventajas y uso actual."},{"id":"874c1b65-332d-4152-8f70-853d345ea92b","name":"Ejemplos: ventilador, licuadora, alternador."},{"id":"28382c38-9e5b-4b32-9aa6-765c313e1e10","name":"Cambio de movimiento: circular y lineal."},{"id":"df5aa6d0-9971-48f0-9257-63e344df6833","name":"Comparación: impacto ambiental y eficiencia."},{"id":"741d2185-1802-476d-a550-174098b0abef","name":"Transmisión de fuerza y velocidad en máquinas simples."},{"id":"3e4cc11f-c37f-465f-aa56-adcd23d04b8b","name":"Generadores y motores eléctricos"},{"id":"0ecf69b1-c64a-4289-9eb9-0c21a9d8eec9","name":"Tecnología en la transportación (motores de explosión y eléctricos)"},{"id":"d2e82018-9b96-4a90-8dcc-1ce33e3a7e64","name":"Qué es un generador: produce electricidad."}]}],"grade_levels":["5to"],"subjectId":"naturales","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"4e9cc3a0-037b-42eb-b90e-54c0190f5569-block-1","themes":["Materia y sus propiedades","Energía y conservación","Interacción y movimiento","Sistema y mecanismo"],"conceptual":"\"Ciencias físicas\"\n\"Materia y sus propiedades\"\n–\tElementos y compuestos químicos.\n–\tÁtomos y moléculas.\n–\tCambios en la materia: \ncambios físicos, cambios de estado, cambios químicos.\n–\tCarga eléctrica.\n \n\"Energía y conservación\"\n–\tFormas y fuentes de energía (mecánica, química, eléctrica, magnética).\n–\tTransmisión: conductividad eléctrica.\n–\tCircuitos eléctricos.\n–\tTransformación de energía de una forma a otra.\n–\tConservación de la masa y energía.\n \n\"Interacción y movimiento\"\n–\tFuerzas y sus efectos (mecánica, eléctrica, magnética).\n–\tEl movimiento como una manifestación de energía. \n \n\"Sistema y mecanismo\"\n ","procedural":"\"Ciencias físicas\"\n \n–\tIdentificación de elementos y compuestos químicos esenciales en la vida. Procedimiento: observación, formulación de preguntas, construcción de modelos, recolección de información, dibujos o esquemas, comunicación de resultados por diferentes vías.\n–\tExperimentación (guiada): cambios de estado de la materia: sublimación (cristalización). Procedimiento: observación, descripción, clasificación, uso de instrumentos y materiales, inferencia, elaboración de gráficos, esquemas, reportes en el diario de laboratorio y puesta en común.\n–\tExperimentación con los cambios físicos y químicos de la materia. Procedimiento: formulación del problema, observación, comparación, inferencias, comunicación oral y escrita en dibujos, diagramas en el diario de laboratorio. \n–\tDiseño e identificación de reacciones químicas (ácidobase). Procedimiento: observación, experimentación, utilización de instrumentos y materiales de uso cotidiano, comparación, evidencias, reporte en el diario de laboratorio.\n–\tExperimentación con circuitos eléctricos simples (cable, bombillas, interruptor, pila y multímetro). Procedimiento: exploración, utilización de instrumentos, planificación, comparación, inferencia, dibujo, esquema y reporte en el diario de laboratorio.\n–\tExperimentación sobre la conservación de la masa y energía. Procedimiento: exploración, formulación de preguntas, recolección de información, utilización de instrumentos, análisis, inferencia, dibujos, reporte en el diario de laboratorio.\n–\tObservación de las líneas de fuerzas magnéticas con limaduras de hierro. Procedimiento: exploración, formulación de preguntas, experimentación, comparación, descripción, dibujos o esquemas, reporte en el diario de laboratorio.\n–\tConstrucción, utilización y presentación de electroimanes, brújulas y dinamómetros. Procedimiento: observación, experimentación (guiada), diseño, análisis, comparación, modelos, reporte en el diario de laboratorio.\n–\tConstrucción de generadores y motores eléctricos. Procedimiento: observación, experimentación (guiada), diseño, análisis, comparación, modelos, reporte en el diario de laboratorio.\n–\tExperimentación con mecanismo de transformación de movimiento de lineal a circular o viceversa (poleas, correas transportadoras, cadenas, piñones). Procedimiento: \nobservación, formulación de preguntas, recolección de información, comparación, clasificación, dibujo, esquemas, gráficos y reporte en el diario de laboratorio.\n–\tObservación de sistemas con acoplamiento de movimiento: embragues y juntas. Procedimiento: exploración, formulación de preguntas, utilización de instrumentos, comparación, clasificación, descripción, evaluación.\n–\tConstrucción de celdas electroquímicas y pilas. \nProcedimiento: observación, experimentación (guiada), diseño, análisis, comparación, modelos, reporte en el diario de laboratorio.\n–\tObservación de fuentes y formas de energías. \nProcedimiento: exploración, formulación de preguntas, recolección de información, comparación, clasificación, descripción.\n–\tExperimento de cambios de energía (conversión entre distintas formas de energía: eléctrica, térmica, eólica, solar, biomasa, hidráulica). Procedimiento: observación, formulación de preguntas, elaboración de modelos, recolección de información, comunicación escrita.\n–\tReconocimiento de los efectos de fuerzas electrostáticas al frotar cuerpos. Procedimiento: experimentación, formulación de preguntas, recolección de información, comunicación escrita.\n–\tExperimento de generación, transmisión y almacenamiento de energía. Procedimiento: exploración, formulación de preguntas, comparación y clasificación, construcción de modelos, reporte en el diario de laboratorio.\n–\tExploración y formulación de preguntas acerca de la relación entre las unidades de medida Celsius y Joules.\n–\tExperimento de la fuerza con deformación. Procedimiento: \nobservación, formulación de preguntas, recolección de información, medición, inferencia.\n ","attitudinal":"–\tParticipación con los demás de sus experiencias, observaciones, ideas, inquietudes, aspiraciones y preguntas sobre su entorno natural.\n–\tMotivación por aprender cosas nuevas sobre la estructura y composición de la materia.\n–\tAdopción de medidas de cuidado, protección y prevención con respecto a la luz, el ruido, los olores, líquidos y sustancias peligrosas, así como objetos que puedan afectar sus órganos o su salud.\n–\tAsume con responsabilidad el uso sostenible de la energía y su impacto en el ambiente.\n–\tApropiación de hábitos de seguridad personal y ambiental al realizar experimentos.\n–\tMotivación e interés por aprender sobre su entorno material y mantener una convivencia sana, demostrando solidaridad, respeto y colaboración con las demás personas.\n–\tValoración acerca del desarrollo científico y tecnológico y su impacto en la sociedad.\n–\tEvaluación y prevención de riesgos de seguridad en el uso de la energía.\n–\tValoración de las actividades que realizan los profesionales de la Química, la Física, la Biología y la Ingeniería Eléctrica en la producción energética.\nDemostración de:\n–\tObjetividad en la comunicación y en los procesos científicos.\n–\tCuriosidad, creatividad y perseverancia en la búsqueda de respuestas y comprensión de su entorno natural.\n–\tInterés por la comunicación de sus ideas.\n–\tSistematicidad en los procesos de la ciencia.\n–\tTrabajo individual y colaborativo.\n–\tCuidado de su salud y el Medioambiente, y la utilización sostenible de los recursos disponibles.\n "}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:20:36.186Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('61d88484-5058-44e1-b9cf-64b9cbd81be9', 'naturales', '5to', '{"id":"61d88484-5058-44e1-b9cf-64b9cbd81be9","name":"Ciencias de la tierra y el universo ","themes":[{"id":"6689e127-f085-43c0-a411-7efb27ace44c","name":"Materia y sus propiedades","subthemes":[{"id":"7070383e-07ce-478b-8ece-5798b79727b1","name":"Manto, volcanes y corteza terrestre"},{"id":"92a795e9-8d42-4a73-a432-452415e45db8","name":"Qué es la deriva continental (movimiento de placas)."},{"id":"58e6a01c-650f-4dda-aaa0-679f7986abf5","name":"Función: aire y protección del planeta."},{"id":"ff37aad3-4689-431c-b48a-b7b635be6071","name":"Importancia del agua para la vida."},{"id":"e2f9be54-3293-4aa9-9afa-90f2833778c1","name":"Capas de la Tierra: corteza, manto y núcleo."},{"id":"80126f3b-c968-4b60-b88c-4659dc155b14","name":"Pangea y separación de continentes."},{"id":"f6ca794a-7c38-4ecb-8c6b-a4d50fff1bec","name":"Clima y fenómenos atmosféricos."},{"id":"f2c49780-2526-4170-b05c-16835fc12202","name":"Volcanes: partes y erupciones."},{"id":"d4e58440-dff5-41a8-8e2f-6eb703e064a5","name":"Consecuencias: sismos, montañas y volcanes."},{"id":"723d2ed5-87c3-4527-b6d4-cf3364b366ab","name":"Hidrósfera"},{"id":"e856f6ba-6f63-46e3-98f4-ed2b98db7b76","name":"Importancia de la corteza y relieve terrestre."},{"id":"af16e32c-97b4-4b62-9f1a-1ffc4a9bbebc","name":"Atmósfera"},{"id":"dc7bd4ba-045a-440a-ae29-bf70dca749fd","name":"Aguas del planeta: ríos, mares, lagos y océanos."},{"id":"2985ca62-20ec-4385-83c7-16649e640d60","name":"Deriva continental"},{"id":"2f6fd24f-83db-4d8f-a12d-165c08ae4291","name":"Capas de la atmósfera (básico)."},{"id":"a07490f3-8a4a-46cd-ab37-06b5750097f6","name":"Ciclo del agua."}]},{"id":"aad799c6-460e-4c5f-ad44-1b882447385c","name":"Energía y conservación","subthemes":[{"id":"8896300a-9aa7-4495-994d-b7461b25f97c","name":"Energía y conservación "},{"id":"21f9f40c-90b9-4512-8f9c-b1ac169d610e","name":"Fuentes de energía renovable y no renovable"},{"id":"990b481c-96f8-4891-9dae-e52a22c9216b","name":"Energías renovables: solar, eólica e hidráulica."},{"id":"349a5df8-ac16-4a16-8728-bdb1b4d5aae3","name":"Energías no renovables: petróleo, gas y carbón."},{"id":"a220b687-2038-4e44-a341-79e9c714d6f3","name":"Uso responsable: ahorro y conservación de energía."}]},{"id":"758583f0-2334-4ac4-906b-7648f3f8f20e","name":"Sistema y mecanismo","subthemes":[{"id":"ad02a589-2ed4-402a-bb19-1251f101adfe","name":"Ciclo del agua"},{"id":"7530d82e-d216-43f4-9bfe-868e558d126f","name":"Etapas: evaporación, condensación y precipitación."},{"id":"fc9f3dae-47ac-498a-b0c8-9ac82240ebd8","name":"Causas de contaminación del agua."},{"id":"9055215c-e10b-4a0b-8345-71dfaab3ae10","name":"Prevención y seguridad ante eventos."},{"id":"10e9d03d-d41f-49bb-b9cc-4b6d0e64925a","name":"Escorrentía e infiltración (agua en suelo y ríos)."},{"id":"aad418d7-e9d2-4786-89d7-c49c08d3cae1","name":"Medidas para cuidar el agua."},{"id":"6e2718f6-7771-4d78-9e91-c9a647927bd1","name":"Eras geológicas"},{"id":"2c79b137-cd5f-485c-ace9-c2fa5feff563","name":"Importancia del ciclo para la vida."},{"id":"076c7f8a-a6f0-42a9-8537-f901bb016287","name":"Fenómenos atmosféricos (tormentas y tornados)"},{"id":"bb6e7dbf-348b-4aa1-8a02-d84ad145e491","name":"Qué son eras geológicas."},{"id":"7aa8a9ef-8468-4b06-87f0-46653b21d364","name":"Agua potable y contaminación hídrica"},{"id":"f23289e3-41f0-46fd-af2d-29583a323b5b","name":"Qué son tormentas y tornados."},{"id":"de776c5e-e2c1-40d7-8d6e-1e53258f9266","name":"Principales eras: Paleozoica, Mesozoica y Cenozoica."},{"id":"a30c4788-d1dc-45ab-be59-e27673b4e62f","name":"Qué es agua potable y cómo se obtiene."},{"id":"557721bc-93aa-4b48-b178-25220de5acc5","name":"Cómo se forman (explicación simple)."},{"id":"51e29627-bd96-4e41-87c8-7d87c635c829","name":"Cambios en la Tierra y seres vivos en cada era."}]}],"grade_levels":["5to"],"subjectId":"naturales","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"61d88484-5058-44e1-b9cf-64b9cbd81be9-block-1","themes":["Materia y sus propiedades","Energía y conservación","Sistema y mecanismo"],"conceptual":"\"Ciencias de la tierra y el universo\"\n \n\"Materia y sus propiedades\"\n–\tManto, volcanes y corteza terrestre.\n–\tDeriva continental.\n–\tAtmósfera. \n– Hidrósfera.\n \n\"Energía y conservación\"\n–\tFormas y fuentes de energía renovable y no-renovable. \n \n\"Sistema y mecanismo\"\n–\tCiclo del agua\n–\tAgua potable y contaminación hídrica.\n–\tFenómenos atmosféricos (tormentas y tornados).\n–\tEras geológicas.\n ","procedural":"\"Ciencias de la tierra y el universo\"\n–\tDiscusión y comparación entre la composición física del manto y la corteza terrestre. Comunicación por medio de dibujos, fotografías.\n–\tAnálisis y discusión sobre cambios en la morfología de la Tierra a través del tiempo, comprendiendo que los procesos geológicos son lentos.\n–\tAnálisis, comparación, descripción y discusión sobre las diferentes capas que forman la atmósfera terrestre, comunicando su aprendizaje por medio de dibujos, mapas, exposiciones.\n–\tAnálisis, descripción y discusión sobre fenómenos naturales asociados a la atmósfera. Comunicación por medio de narraciones, dramatizaciones, murales, dibujos.\n–\tAnálisis y discusión sobre la hidrósfera y el ciclo del agua, identificando las aguas oceánicas, aguas continentales (aguas subterráneas, aguas superficiales ríos, lagos, lagunas), olas, corrientes marinas, mareas.\n–\tAnálisis, descripción y discusión sobre fenómenos naturales relacionados al agua. Comunicación por medio de narraciones, esquemas, gráficos y dibujos.\n–\tDescripción y discusión sobre el arcoíris en las que se describe el mismo a partir de la reflexión y refracción de la luz. Comunicación por medio de narraciones y dibujos.\n–\tExperimentación guiada sobre energía renovable y no renovable. Procedimiento: discusión, descripción y comparación entre energías renovables y no-renovables.\n–\tExperimentación guiada sobre extracción de residuos sólidos y contaminantes en el agua.\n–\tExperimentación guiada sobre el uso y construcción de instrumentos meteorológicos sencillos, tales como: termómetro, veleta, anemómetro, pluviómetro y caseta meteorológica.\n–\tDiscusión y clasificación de las diferentes eras geológicas. \nComunicación por medio de dibujos.\n ","attitudinal":"–\tRespeto a las ideas y diferencias de las demás personas.\n–\tCriticidad y cuestionamiento en la búsqueda de información.\n–\tMotivación e interés en conocer la situación del recurso suelo de la\n–\tRepública Dominicana, participando en proyectos colectivos.\n–\tValoración del aprendizaje científico respecto a los recursos naturales, su situación actual, y las acciones para su conservación.\n–\tMotivación por la información sobre los desastres naturales, las medidas de prevención, las recomendaciones y las rutas de seguridad.\n "}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:20:36.186Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('162f0997-f235-4d3d-bc59-ff5b1545aa63', 'sociales', '6to', '{"id":"162f0997-f235-4d3d-bc59-ff5b1545aa63","name":"Continentes","themes":[{"id":"356900a5-4308-4a1c-ba1d-5d36783aa820","name":"Europa","subthemes":[{"id":"2fe309ba-aedc-49ed-b2d4-9c99fe894f8e","name":"Ubicación y límites geográficos."},{"id":"fd7423df-a5ae-404f-a3f5-014eb36c7eae","name":"Población, economía y cultura."},{"id":"9e7fdaab-18f2-4b02-a93a-b7eabd513b3c","name":"Relieve, clima y recursos naturales."}]},{"id":"fb17ef61-93c1-4913-94c9-d184c14091ca","name":"Asia","subthemes":[{"id":"7c147690-d4ef-4b14-b005-806edcb66aeb","name":"Relieve y diversidad climática."},{"id":"007edf9c-06b2-475f-9b56-7802ebbd890d","name":"Ubicación y extensión territorial."},{"id":"bb3b2d40-6fd7-4a43-abab-6c2cd7eafe27","name":"Población y desarrollo económico."}]},{"id":"c27a47a3-104d-4433-8eff-63db527ba850","name":"África","subthemes":[{"id":"cdf1b312-b16c-4e67-b4ab-7cc20c92e665","name":"Clima y recursos naturales."},{"id":"5806f975-9e20-4c49-a842-0a7eaf9bb960","name":"Regiones y características físicas."},{"id":"33d9a689-e1ac-449a-bfb3-59a4d81046a4","name":"Población y actividades económicas."}]},{"id":"ec0a15d2-03f1-4290-8800-5015c59a1e77","name":"Oceanía","subthemes":[{"id":"df80a448-10e4-4d7a-b980-31b74bf5dca2","name":"Relieve, clima y biodiversidad."},{"id":"19afd078-a1d1-4691-bfae-e518b1500e57","name":"Cultura y economía regional."},{"id":"f58b2a51-f63f-442f-96bb-a6741bf4ab8e","name":"Países y ubicación insular."}]}],"grade_levels":["6to"],"subjectId":"sociales","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"162f0997-f235-4d3d-bc59-ff5b1545aa63-block-1","themes":["Europa","Asia","África","Oceanía"],"conceptual":"\"Continentes:\"\nEuropa Asia África Oceanía\n– Límites, países, relieve, clima, recursos naturales, población, economía de Europa.\n ","procedural":"\"Localización de los continentes en mapas y planisferio\".\n–\tUbicación de los continentes (Asia, África, Europa y Oceanía) en un mapamundi utilizando sistema de referencia de coordenadas (Latitud norte o sur y longitud este u oeste).\n–\tUtilización de la rosa del viento en un mapamundi para la ubicación de los continentes.\n ","attitudinal":"–\tValoración de la diversidad geográfica y cultural del mundo.\n–\tValoración del continente americano.\n–\tValoración de los aportes hechos a la humanidad por las distintas civilizaciones de África, Asia, Europa y América.\n–\tInterés por conocer procesos. \n "}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:20:36.186Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('432a2657-b130-4f9d-883d-619cc285d66a', 'naturales', '6to', '{"id":"432a2657-b130-4f9d-883d-619cc285d66a","name":"Ciencias de la vida","themes":[{"id":"f9797a34-d0c1-4a5e-93e5-f2aa6014a173","name":"Materia y sus propiedades","subthemes":[{"id":"ea423509-262c-487a-97ab-db14fb9755da","name":"La célula"},{"id":"4e381f6e-03f6-4ffd-8f80-760879be2996","name":"Características de las células"},{"id":"229054a9-016f-4de8-947d-20f5ad8520a9","name":"División celular."},{"id":"1dee1bc6-075a-46da-9171-fff8ba071528","name":"Los tejidos"}]},{"id":"00cf5eda-6a52-4ae8-96a1-74e28ccb97cd","name":"Energía y conservación","subthemes":[{"id":"f71ac676-5c69-42b4-a8ac-e5d32f60b76e","name":"Nutrición"},{"id":"268b2096-694e-46a6-8128-bbc7066a9fef","name":"Digestiónv"},{"id":"69780668-3dd2-4c1c-beaa-2b0027aa8d75","name":"Homeostasis (equilibrio térmico)"},{"id":"3a02ffbc-abe7-45d0-8609-c2981216d830","name":"Respiración"}]},{"id":"4e867f7b-8a47-4446-b3a3-1cc3a167f7a1","name":"Sistema y mecanismo","subthemes":[{"id":"e9617b3d-ead3-4a48-9620-942f14978ab1","name":"Concepto de tejido."},{"id":"7d24de00-1844-4781-b6bc-61d61a9f6a71","name":"Tipos de tejidos."},{"id":"1e810955-7ded-4b0d-994c-96031dd6a2e2","name":"Órganos"},{"id":"4171f2e7-a250-4221-8432-9d12a83bf4fa","name":"Relación entre tejidos y órganos."},{"id":"443b5732-a5f5-4a35-bc5d-ff585cd2788d","name":"Sistema endocrino"},{"id":"8175d590-3811-4c2d-8f99-98e38e69a56d","name":"Sistema respiratorio"},{"id":"f9d20745-81c6-4e8b-b9d3-8968cc1c16cb","name":"Ecosistema"},{"id":"63b32c8e-2312-4010-9cca-914a3c702480","name":"Relaciones entre organismos"},{"id":"12a5c179-1ce0-48a0-b74c-373873cca5fb","name":"Funciones principales de los tejidos"},{"id":"e89e3d1b-c707-4c19-b916-375f776d2f1e","name":"Relación entre células y tejidos."},{"id":"d719196a-d834-4492-8cdf-c81882254136","name":"Ejemplos de órganos en el cuerpo humano."},{"id":"a744b0cd-5c2b-4b59-8a75-e60f7e5a2ae5","name":"Componentes: corazón, vasos sanguíneos y sangre."},{"id":"e1db0ec1-d167-4cf7-a46a-777e73923448","name":"Sistema inmunológico"},{"id":"d90fcb11-9924-4e6e-8f3d-2b757dea6351","name":"Medioambiente"},{"id":"777a09b6-a9d8-482f-aeeb-b44c40732199","name":"Ciclo de los elementos"},{"id":"63fd0636-4e70-4bbf-95cd-b22728a25e1f","name":"Definición de órgano."},{"id":"9ef366f4-643f-4baf-a149-4eb1346d28fd","name":"Sistema excretor"},{"id":"63606b0f-86a7-47ea-ae49-7fde569a619c","name":"Biodiversidad"},{"id":"afb4d203-5c42-4323-8ea9-003dab7706d7","name":"Función específica de cada órgano."},{"id":"c6b585f8-d0bb-4088-a40f-2033e8be1c09","name":"Sistema circulatorio"},{"id":"672aef32-052a-44af-a2d8-702f8f95c453","name":"Función: transporte de nutrientes y oxígeno."},{"id":"360fd7bd-9d27-405c-9708-98dd8162d784","name":"Sistema digestivo"},{"id":"6560be0b-277d-4662-bfbf-392ed96cc907","name":"Relaciones simbióticas"},{"id":"580c3497-0d1c-4582-a8df-5f55f99c9332","name":"Relaciones no simbióticas"}]},{"id":"16c75f33-1eed-4f38-b5e9-7e596a2505b6","name":"Salud y ser humano","subthemes":[{"id":"6207ee99-60f6-4164-9012-1d1742059765","name":"Aparato reproductor"},{"id":"019f5870-09a5-4d57-a7c6-77c6266dd197","name":"Fecundación"},{"id":"4ee1a2a8-b7e7-448b-969b-79b48e243d23","name":"Pubertad"},{"id":"39aa15ea-0f75-419c-aedf-abcf0dea8a18","name":"Interacción patógeno–huésped"},{"id":"43412570-c44b-42a8-b6e8-5a95c71311bc","name":"Hormonas reproductivas"},{"id":"fe67abe6-251d-4e80-8024-ec8b7d87bbf7","name":"Embarazo y desarrollo"},{"id":"f1e3abdc-0891-4789-81a0-1f27d6663e20","name":"ETS principales"},{"id":"14f6e9c6-1bb1-4125-87ac-65ff7c9494b1","name":"Sistema inmune"},{"id":"dcb05894-3cf1-42eb-9152-56fc5474e705","name":"Cambios biológicos"},{"id":"58991b74-307f-40d1-ba1c-5181b19c97ce","name":"Enfermedades de transmisión sexual (ETS)"},{"id":"e72022cc-2a27-4199-81f5-b048519df1b5","name":"Reproducción humana"},{"id":"6bbc10ad-28ed-4eff-a2dc-bc1d5d357612","name":"Enfermedades gastrointestinales"}]}],"grade_levels":["6to"],"subjectId":"naturales","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"432a2657-b130-4f9d-883d-619cc285d66a-block-1","themes":["Materia y sus propiedades","Energía y conservación","Sistema y mecanismo","Salud y ser humano"],"conceptual":"\"Ciencias de la Vida\"\n \n\"Materia y sus propiedades\"\n– La célula y sus características.\n– División celular.\n– Los tejidos.\n \n\"Energía y conservación\"\n– Nutrición. Digestión.\n– Homeostasis (equilibrio térmico).\n– Respiración.\n \n\"Sistema y mecanismo\"\n– Tejidos, órganos y sistemas de órganos (sistema circulatorio, endocrino, inmunológico, excretor, respiratorio, digestivo).\n– Medioambiente: ecosistema, biodiversidad, ciclo de los elementos. Relaciones simbióticas y no simbióticas.\n \n\"Salud y ser humano\"\n– Reproducción humana: aparato reproductor, órganos, hormonas, fecundación, embarazo y desarrollo.\n– Pubertad: procesos de cambios biológicos.\n– Enfermedades de transmisión sexual (ETS), VIH-SIDA, papiloma humano.\n– Sistema inmune.\n– Interacción patógeno-huésped.\n– Enfermedades gastrointestinales.","procedural":"\"Ciencias de la Vida\"\n \n– Características y componentes de la célula. Procedimiento: observación, descripción, comparación, experimentación, análisis, discusión y comunicación.\n– Observación, descripción y comparación de la división celular.\n– Indagación sobre las células y la formación de tejidos en vegetales y animales. Procedimiento: observación, formulación de preguntas, comparación, experimentación, análisis, discusión y comunicación.\n \n– Investigación sobre los tejidos, órganos y sistemas de órganos. Procedimiento: observación, formulación de preguntas, comparación, análisis, discusión y comunicación.\n– Realización de preparaciones biológicas de células vegetales y animales.\n– Identificación de personajes de la ciencia que aportaron a la comprensión de la célula.\n– Descripción y análisis sobre la relación entre la nutrición y energía.\n– Clasificación de los nutrientes de acuerdo a los tipos de alimentos.\n– Observación, descripción y análisis de características, estructura y función de los sistemas de órganos.\n– Observación, formulación de preguntas y análisis de enfermedades de los sistemas digestivo, circulatorio y excretor.\n– Descripción, análisis, discusión y comunicación sobre enfermedades de transmisión sexual (ETS), VIH-SIDA que afectan el sistema reproductor, e investigación sobre medidas de prevención.\n– Descripción y discusión del esquema anatómico del sistema reproductor masculino y femenino en los seres humanos.\n– Discusión y análisis de los cambios biológicos que ocurren en la pubertad.\n– Descripción, análisis, discusión y comunicación sobre el sistema reproductor: procesos de fecundación, embarazo y parto.\n– Investigación sobre el desarrollo embrionario a través de experimentos sencillos (huevo, semillas de habichuela, maíz). Procedimiento: observación, formulación de preguntas, comparación, experimentación, análisis, evaluación y distinción entre fuentes de información, discusión y comunicación.\n– Análisis y discusión sobre enfermedades infecciosas comunes de los sistemas digestivo, circulatorio, respiratorio y excretor.\n– Indagación sobre los ecosistemas, componentes bióticos y no bióticos, a la vez que consideración de las medidas para su protección y el desarrollo sostenible.\n– Observación, comparación, análisis y comunicación sobre relaciones (simbióticas y no simbióticas) entre seres vivos.\n– Indagación sobre manifestaciones de la crisis medioambiental (cambio climático, situación actual de la capa de ozono, contaminación del medioambiente marino, deterioro de los bosques, pérdida de la biodiversidad).\n \n– Indagación sobre problemas ambientales ocasionados por residuos sólidos, líquidos, gases y ruidos que afectan al medioambiente local y global. Procedimiento: observación, formulación de preguntas, experimentación, comparación, análisis, inferencia, evaluación y distinción entre fuentes de información, discusión y comunicación.\n \n– Descripción, análisis y comunicación sobre la nutrición, homeostasis y respiración. Procedimiento: búsqueda de información general, lectura y comentarios, distribución de temas, planteamiento de preguntas, búsqueda de información específica, análisis, inferencia, elaboración de documento, presentación, discusión, conclusiones y resumen.","attitudinal":"– Demostración de objetividad, creatividad, curiosidad en el uso del lenguaje científico en sus intervenciones orales y en sus trabajos escritos.\n– Demostración de tolerancia frente a las ideas de las demás personas en los diálogos, foros y debates, a la vez que se expresa con argumentos que sostienen sus ideas.\n– Demostración de respeto y cuidado por los recursos naturales, asumiendo un rol activo en la protección de los ecosistemas y la biodiversidad del entorno.\n– Adopción de medidas de cuidado respecto a las enfermedades de transmisión sexual y sus consecuencias.\n– Reconocimiento de los aportes científicos y tecnológicos que han fortalecido el conocimiento sobre la naturaleza, la sociedad y la solución a las problemáticas originadas.\n– Manifestación de curiosidad, creatividad, objetividad.\n– Comunicación de sus ideas, seguimiento de procedimientos, trabajo individual y colaborativo.\n– Respeto a las ideas y diferencias de las demás personas, solidaridad.\n– Utilización sostenible de los recursos materiales y tecnológicos de que dispone."}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:20:36.187Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('e5c225dd-965e-44a2-88fa-513c4d58f2dd', 'naturales', '6to', '{"id":"e5c225dd-965e-44a2-88fa-513c4d58f2dd","name":"Ciencias de la tierra y el universo","themes":[{"id":"225b5150-7007-4d88-ad4e-c880e254712b","name":"Materia y sus propiedades","subthemes":[{"id":"9a35630e-ffcf-4844-bef1-2092e57e112f","name":"Satélites artificiales."},{"id":"e50c5a42-38d3-499d-af78-5677394eb1e2","name":"El Big Bang."},{"id":"37adf279-aa56-4f08-94db-38edba852889","name":"El Universo"},{"id":"36912189-b20e-401e-8518-d0238f55aa14","name":"Origen del universo."}]},{"id":"b51aca7e-da7b-4339-9242-634ee7cf2400","name":"Energía y conservación","subthemes":[{"id":"26f7831a-16ea-4687-b7eb-e5bb761609f1","name":"Qué es la energía."},{"id":"811ca8c4-e8dd-461c-9822-7bb398e5f434","name":"Recursos naturales"},{"id":"89035a41-f12d-420c-b0a7-eb7ee510c92f","name":"Energía en fenómenos cósmicos"},{"id":"02a77c89-72ef-49a3-bf75-56010d211e20","name":"Transformación y conservación de la energía."},{"id":"16936ac9-cd95-40dd-b1d7-cfd48ed84cee","name":"Formas y fuentes de energía en el Universo"},{"id":"4c1060fb-590a-4960-a4b9-1aa08f175717","name":"Formas de energía"},{"id":"a5def71b-1c3c-4111-9918-07a45c7ad25d","name":"Concepto de energía"}]},{"id":"5bf71994-b75c-4423-b28d-661afc2d669e","name":"Interacción y movimiento","subthemes":[{"id":"78ea0ec7-4eb0-4d46-8b8f-c82755aba36d","name":"Fuerzas en el Universo."},{"id":"a944b3a9-0a65-43f8-a417-3f664fb7be64","name":"Dinámica del Sistema Solar."}]},{"id":"a5d31380-a994-4289-8205-a3faa7364a25","name":"Sistema y mecanismo","subthemes":[{"id":"75ee3dda-8c70-454d-9287-81bfd2545c2f","name":"La Vía Láctea"},{"id":"ae7430d1-c650-4f1e-88e9-5528e4335902","name":"Galaxias y constelaciones"},{"id":"16730d4b-07b3-4d3d-9fe0-bd17b72e987b","name":"Origen de nuestro Sistema Solar."},{"id":"3ba01875-791c-46a5-93a2-8737256d93a5","name":"Atmósfera del Sol"},{"id":"be235aa0-ae2e-48b4-b1d1-84bdeb0c9c3e","name":"El Sistema Solar"},{"id":"acd61fb7-60ba-4c2f-b7c3-6c8ec1c19409","name":"Ciclo de vida de las estrellas"}]}],"grade_levels":["6to"],"subjectId":"naturales","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"e5c225dd-965e-44a2-88fa-513c4d58f2dd-block-1","themes":["Materia y sus propiedades","Energía y conservación","Interacción y movimiento","Sistema y mecanismo"],"conceptual":"\"Ciencias de la Tierra y el Universo\"\n \n\"Materia y sus propiedades\"\n– El Universo y su origen. El Big Bang.\n– Satélites artificiales.\n \n\"Energía y conservación\"\n– Formas y fuentes de energía en el Universo.\n \n\"Interacción y movimiento\"\n– Dinámica del Sistema Solar.\n– Fuerzas en el Universo.\n \n\"Sistema y mecanismo\"\n– El Sistema Solar.\n– Origen de nuestro Sistema Solar.\n– La Vía Láctea.\n– Galaxias y constelaciones.\n– Ciclo de vida de las estrellas.\n– Atmósfera del Sol.","procedural":"– Discusión sobre el origen, composición y la evolución de nuestro Sistema Solar.\n \n– Análisis y discusión sobre los planetas del Sistema Solar (y otros fuera del Sistema Solar) y sus características. Expresión por medio de dibujos.\n \n– Análisis, discusión (comparación, clasificación, descripción) sobre la composición y estructura de la atmósfera del Sol, así como el ciclo de las estrellas. Expresión por medio de dibujos.\n \n– Observación y utilización guiada sobre el uso del telescopio para la observación de cuerpos celestes.\n \n– Discusión y utilización de modelos para explicar las capas de la atmósfera del Sol.\n \nSi quieres, te hago algo que te va a ahorrar mucho trabajo (especialmente si estás armando contenidos para Planix):","attitudinal":"– Valoración de los aportes científicos y tecnológicos que han fortalecido el conocimiento sobre la naturaleza, la sociedad y la solución de las problemáticas originadas de su interacción.\n \n– Valoración y respeto por el impacto en la sociedad de los avances tecnológicos y expresa los beneficios del uso razonable de los recursos naturales.\n \n– Valoración de los riesgos que podrían presentar eventos que afecten a la Tierra."}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:20:36.187Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('301', 'naturales', '2do', '{"id":"301","name":"Ciencias de la Vida","themes":[{"id":"f639af4d-df41-4230-84d3-1c5b2cf426d9","name":"La materia","subthemes":[{"id":"282196ef-d2ae-47d9-a311-1f412f06242a","name":"¿Qué es la materia?"},{"id":"411f8976-3792-4dce-8642-4391159ba101","name":"Objetos que nos rodean y de qué están hechos"},{"id":"29df4008-6327-4590-9647-ae52f7fba089","name":"Propiedades de la materia (forma, tamaño, color y textura)"},{"id":"a3046bf6-6882-40fe-8407-18245927d142","name":"Uso y cuidado de los materiales en la vida diaria"}]},{"id":"54e17f9e-7c4f-4fb6-b7b4-cc032e6b51e2","name":"Sistemas digestivo, circulatorio y respiratorio de los seres vivos","subthemes":[{"id":"2c898667-c893-4d8f-b21f-adcc78639692","name":"Los órganos internos del cuerpo humano"},{"id":"a0166d5b-aef4-42d0-81d4-d6193a20fbf9","name":"El sistema digestivo y su función"},{"id":"893da960-281d-4b3e-8239-bb67f4dc558d","name":"El sistema circulatorio y el corazón"},{"id":"80355701-f185-4627-b9a8-fd2370b6be87","name":"El sistema respiratorio y la respiración"},{"id":"62bda8a3-1e9b-45d2-8b82-2750ae777afa","name":"Importancia de los sistemas para la vida"}]},{"id":"872075c2-b0ad-4853-a875-b2a6301893bf","name":"Relación con plantas y animales","subthemes":[{"id":"894364d7-d24b-40d3-96ab-49ede6d1b098","name":"Las plantas como seres vivos"},{"id":"f021761a-7a4d-4180-8da8-57b13de87d05","name":"Los animales como seres vivos"},{"id":"2119e152-6051-42f5-aa8b-1e0da95d83e6","name":"Relación entre plantas, animales y seres humanos"},{"id":"679ba6ea-8525-4a19-88c2-3e06cba05141","name":"Importancia del cuidado de plantas y animales"}]},{"id":"82b2e562-7f90-41bf-be83-d07e5b478c5d","name":"Nutrición: alimentos y nutrientes","subthemes":[{"id":"cf300afb-52a1-4216-acf4-e7e2fd9a2529","name":"¿Qué son los alimentos?"},{"id":"959ccc1f-679f-48d3-8566-50d59e4adadc","name":"Tipos de alimentos (origen animal y vegetal)"},{"id":"56dada73-7234-44d0-9c9c-471809e1301e","name":"Nutrientes que aportan los alimentos"},{"id":"b573933d-13ef-48d7-95e0-0c5a328c0012","name":"Importancia de una alimentación saludable"}]},{"id":"a154c7f1-0ef9-4282-86d1-1c81ab3c7e48","name":"Ecosistemas: hábitat, ambiente","subthemes":[{"id":"1a671a33-585b-4ef5-9851-4df2103fea52","name":"¿Qué es un ecosistema?"},{"id":"d3854f43-7eab-4fd0-92e9-7e1a4c7f7cb8","name":"El hábitat de plantas y animales"},{"id":"6012d0e2-f4de-49fa-a27b-8ef4fa231109","name":"Relación entre los seres vivos y su ambiente"},{"id":"f57e61d7-f4b1-4a52-bedc-939d7b52d23b","name":"Cuidado del ambiente y los ecosistemas"}]},{"id":"f6c0172b-5ae3-47e3-9787-828ffee6e240","name":"Enfermedades infecciosas y síntomas (fiebre, tos, vómito y diarrea)","subthemes":[{"id":"c3c272f5-1abe-4125-88f6-53a0ae760daf","name":"¿Qué son las enfermedades infecciosas?"},{"id":"dd6eebe0-a0c0-4ad6-9095-6bf949d83f49","name":"Síntomas comunes de enfermedades"},{"id":"61512323-2db4-417b-8838-d374ae3de3ae","name":"Cómo se transmiten las enfermedades"},{"id":"3cb2529a-0534-495f-a31e-051c24585aa7","name":"Importancia de la prevención y las vacunas"}]},{"id":"6be3fa33-d3f2-49bc-b8ed-09d2c6886a6e","name":"Cuidados a personas, plantas y animales","subthemes":[{"id":"63dc6723-e197-44f4-9b02-28b10983fc18","name":"Hábitos de higiene personal"},{"id":"480fbc37-7a22-4d76-866d-ceec867cca96","name":"Cuidados para mantener el cuerpo sano"},{"id":"fdfae76b-ef77-41ad-aa6c-6ec2e63119eb","name":"Cuidados de las plantas"},{"id":"db5844f6-0e0c-4b39-b4cf-131afc00187c","name":"Cuidados de los animales"},{"id":"149216f4-5831-4a8a-9cb3-abb4d95590fa","name":"Acciones para prevenir enfermedades en la comunidad"}]}],"grade_levels":["2do"],"subjectId":"naturales","week_duration":4,"description":"Identifica en los seres vivos de su entorno y el ser humano, órganos internos de los sistemas con modelo o simulación: digestivo, circulatorio y respiratorio.\nIdentifica y describe propiedades utilizando el lenguaje apropiado que caracterizan los estados del agua y a las mezclas.\nUsa diferentes vías de comunicación para explicar o dar soluciones de forma abierta y creativa a su manera de percibir las propiedades y características de la materia.\nEjecuta experimentos guiados en colaboración, observando, describiendo, utilizando herramientas o equipos siguiendo características observables.\nAsocia y construye modelos, estructuras y funciones de elementos mecánicos de máquinas, objetos, juegos, herramientas.\nComunica los registros de sus ideas, observaciones, exploraciones y experimentos, usando y cuidando los sentidos e instrumentos.\nExpresa prácticas y hábitos saludables de alimentación, cuidado y protección de sus órganos.\nAplica medidas de cuidado al Medioambiente, acciones sencillas concretas de sostenibilidad.\nIdentifica actitudes y valores proactivos en su desarrollo personal, en el cuidado de su salud y bienestar personal y comunitario.","achievementIndicators":["Identifica en los seres vivos de su entorno y el ser humano, órganos internos de los sistemas con modelo o simulación: digestivo, circulatorio y respiratorio.","Identifica y describe propiedades utilizando el lenguaje apropiado que caracterizan los estados del agua y a las mezclas.","Usa diferentes vías de comunicación para explicar o dar soluciones de forma abierta y creativa a su manera de percibir las propiedades y características de la materia.","Ejecuta experimentos guiados en colaboración, observando, describiendo, utilizando herramientas o equipos siguiendo características observables.","Asocia y construye modelos, estructuras y funciones de elementos mecánicos de máquinas, objetos, juegos, herramientas.","Comunica los registros de sus ideas, observaciones, exploraciones y experimentos, usando y cuidando los sentidos e instrumentos.","Expresa prácticas y hábitos saludables de alimentación, cuidado y protección de sus órganos.","Aplica medidas de cuidado al Medioambiente, acciones sencillas concretas de sostenibilidad.","Identifica actitudes y valores proactivos en su desarrollo personal, en el cuidado de su salud y bienestar personal y comunitario."],"conceptual_content":[{"id":"57e7889a-a7af-4c65-8ac2-73c2cde04313","themes":[],"conceptual":"Ciencias de la Vida\nConceptos Materia y sus propiedades\nSistemas digestivo, circulatorio y respiratorio de los seres vivos.\nRelación con plantas y animales.\nEnergía y conservación.\nNutrición: alimentos y nutrientes.\nSistema y mecanismo\nEcosistemas: hábitat, ambiente.\nSalud\nEnfermedades infecciosas y síntomas (!ebre, tos, vómito y diarrea).\nCuidados a personas, plantas y animales.","procedural":"Identificación, discusión, descripción y comparación de órganos internos\nConstrucción de modelos de sistemas del cuerpo humano y animal\nObservación de latidos del corazón y movimientos respiratorios (inspiración/espiración)\nAnálisis del proceso digestivo en animales\nIndagación y análisis sobre nutrientes en alimentos (huevo, leche, vegetales, frutas, carnes)\nConstrucción de modelos de plantas (raíz, tallo, hoja, flor, fruto)\nExperimentación guiada: crecimiento de plantas según nutrientes\nIndagación sobre medidas higiénicas y prevención de enfermedades\nArgumentación sobre la importancia de las vacunas\nDiscusión sobre eliminación de criaderos de mosquitos","attitudinal":"Curiosidad, creatividad, objetividad y responsabilidad\nParticipación en acciones preventivas para la salud y el medio ambiente\nValoración de la ingesta de alimentos ricos en nutrientes\nUtilización de diferentes vías de comunicación para explicar hábitos saludables\nAdopción de medidas de seguridad ante sustancias tóxicas"}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:20:36.187Z');